def _fold_source_text(value: object) -> str:
    text = str(value or "").replace("\\", "/").casefold()
    text = unicodedata.normalize("NFKD", text)
    return "".join(char for char in text if not unicodedata.combining(char))


def _iter_source_text_values(value: object) -> Iterable[str]:
    if value is None:
        return
    try:
        if bool(pd.isna(value)):
            return
    except Exception:
        pass
    if isinstance(value, Mapping):
        for item in value.values():
            yield from _iter_source_text_values(item)
        return
    if isinstance(value, (list, tuple, set)):
        for item in value:
            yield from _iter_source_text_values(item)
        return
    text = str(value).strip()
    if text:
        yield text


def _source_label_from_text(value: object) -> Optional[str]:
    folded = _fold_source_text(value)
    if not folded:
        return None
    if "kosice" in folded or "košice" in folded:
        return "Ko\u0161ice"
    if "praha" in folded:
        return "Praha"
    if "imported" in folded:
        return "Imported"
    if folded in {"manual", "manual entry", "manual_entry"}:
        return "Manual"
    if ":/" in folded or folded.startswith("//"):
        return "Other"
    return None


def _microscope_expected_suffix_from_path(path: Path) -> Optional[str]:
    """Return only suffixes that are meaningful microscope row identities."""

    parsed_key = _microscope_key(path)
    if parsed_key is None:
        return None
    suffix = str(parsed_key[3] or "").strip()
    if suffix.casefold() == "oe":
        return "oe"
    return None


def _source_labels_from_row(row: Mapping[str, Any] | pd.Series) -> List[str]:
    labels: List[str] = []

    def add(label: Optional[str]) -> None:
        if label and label not in labels:
            labels.append(label)

    try:
        existing = row.get(SOURCE_LABEL_COLUMN)  # type: ignore[arg-type]
    except Exception:
        existing = None
    for value in _iter_source_text_values(existing):
        add(str(value).strip())
    for column in _SOURCE_PROVENANCE_COLUMNS:
        try:
            value = row.get(column)  # type: ignore[arg-type]
        except Exception:
            value = None
        for item in _iter_source_text_values(value):
            add(_source_label_from_text(item))
    return labels


def _source_label_for_row(row: Mapping[str, Any] | pd.Series) -> str:
    return ", ".join(_source_labels_from_row(row))


def _with_source_label_column(frame: pd.DataFrame | None) -> pd.DataFrame:
    if frame is None or not isinstance(frame, pd.DataFrame) or frame.empty:
        return frame if isinstance(frame, pd.DataFrame) else pd.DataFrame()
    if not any(str(column) in _SOURCE_PROVENANCE_COLUMNS or str(column) == SOURCE_LABEL_COLUMN for column in frame.columns):
        return frame
    updated = frame.copy()
    labels = [_source_label_for_row(row) for _, row in updated.iterrows()]
    if not any(label for label in labels):
        return updated
    updated[SOURCE_LABEL_COLUMN] = labels
    columns = [column for column in updated.columns if str(column) != SOURCE_LABEL_COLUMN]
    insert_after = None
    for preferred in ("Data source", "Sources", "Source files"):
        if preferred in columns:
            insert_after = columns.index(preferred) + 1
            break
    if insert_after is None:
        first_internal = next(
            (idx for idx, column in enumerate(columns) if str(column).startswith("_")),
            len(columns),
        )
        insert_after = first_internal
    columns.insert(insert_after, SOURCE_LABEL_COLUMN)
    return updated.loc[:, columns]


def _builder_settings() -> QtCore.QSettings:
    custom_file = os.environ.get("MICROWIRE_BUILDER_SETTINGS_FILE", "").strip()
    if custom_file:
        return QtCore.QSettings(custom_file, QtCore.QSettings.Format.IniFormat)
    platform = os.environ.get("QT_QPA_PLATFORM", "").strip().lower()
    if os.environ.get("PYTEST_CURRENT_TEST") or platform == "offscreen":
        settings_file = (
            Path(gettempdir()) / f"microwire_data_builder_offscreen_{os.getpid()}.ini"
        )
        return QtCore.QSettings(str(settings_file), QtCore.QSettings.Format.IniFormat)
    return QtCore.QSettings("MicrowireLab", "MicrowireDataBuilder")


def _parse_vsm_hysteresis_preview_range_oe(value: Any) -> Optional[float]:
    if value is None:
        return VSM_HYSTERESIS_DEFAULT_PREVIEW_RANGE_OE
    text = str(value).strip().lower()
    if not text:
        return VSM_HYSTERESIS_DEFAULT_PREVIEW_RANGE_OE
    if text in {"auto", "full", "none", "0"}:
        return None
    try:
        limit = float(text)
    except (TypeError, ValueError):
        return VSM_HYSTERESIS_DEFAULT_PREVIEW_RANGE_OE
    if not math.isfinite(limit) or limit <= 0:
        return VSM_HYSTERESIS_DEFAULT_PREVIEW_RANGE_OE
    return limit


def _load_vsm_hysteresis_preview_range_oe(
    settings: Optional[QtCore.QSettings] = None,
) -> Optional[float]:
    resolved = settings or _builder_settings()
    try:
        stored = resolved.value(
            VSM_HYSTERESIS_PREVIEW_RANGE_SETTING,
            str(int(VSM_HYSTERESIS_DEFAULT_PREVIEW_RANGE_OE)),
        )
    except Exception:
        stored = str(int(VSM_HYSTERESIS_DEFAULT_PREVIEW_RANGE_OE))
    return _parse_vsm_hysteresis_preview_range_oe(stored)


def _parse_vsm_hysteresis_angle_filter_mode(value: Any) -> str:
    text = str(value).strip().lower() if value is not None else ""
    if text in {"0_90", "0-90", "focused"}:
        return "0_90"
    return VSM_HYSTERESIS_DEFAULT_ANGLE_FILTER_MODE


def _load_vsm_hysteresis_angle_filter_mode(
    settings: Optional[QtCore.QSettings] = None,
) -> str:
    resolved = settings or _builder_settings()
    try:
        stored = resolved.value(
            VSM_HYSTERESIS_ANGLE_FILTER_SETTING,
            VSM_HYSTERESIS_DEFAULT_ANGLE_FILTER_MODE,
        )
    except Exception:
        stored = VSM_HYSTERESIS_DEFAULT_ANGLE_FILTER_MODE
    return _parse_vsm_hysteresis_angle_filter_mode(stored)


def _parse_vsm_temperature_preview_mode(value: Any) -> str:
    text = str(value).strip().lower() if value is not None else ""
    if text == "smoothed":
        return "smoothed"
    return VSM_TEMPERATURE_DEFAULT_PREVIEW_MODE


def _load_vsm_temperature_preview_mode(
    settings: Optional[QtCore.QSettings] = None,
) -> str:
    resolved = settings or _builder_settings()
    try:
        stored = resolved.value(
            VSM_TEMPERATURE_PREVIEW_MODE_SETTING,
            VSM_TEMPERATURE_DEFAULT_PREVIEW_MODE,
        )
    except Exception:
        stored = VSM_TEMPERATURE_DEFAULT_PREVIEW_MODE
    return _parse_vsm_temperature_preview_mode(stored)


def _shape_memory_has_value(value: Any) -> bool:
    if value is None:
        return False
    if isinstance(value, str):
        return bool(value.strip())
    try:
        if bool(pd.isna(value)):
            return False
    except Exception:
        pass
    return True


def _shape_memory_payload_has_values(
    payload: Mapping[str, Any], columns: Sequence[str]
) -> bool:
    return any(_shape_memory_has_value(payload.get(column)) for column in columns)


def _shape_memory_graph_item_count(value: Any) -> int:
    if value is None:
        return 0
    if isinstance(value, str):
        return 1 if value.strip() else 0
    if isinstance(value, (list, tuple, set)):
        return sum(_shape_memory_graph_item_count(item) for item in value)
    return 1


