class AnnealingPlotPanel(QtWidgets.QWidget):
    """Display anchor and follow-up annealing plots for the selected microwire."""

    def __init__(
        self,
        logger: logging.Logger,
        parent: QtWidgets.QWidget | None = None,
    ) -> None:
        super().__init__(parent)

        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(8)

        self.header_label = QtWidgets.QLabel("Select a row to preview annealing plots.")
        self.header_label.setAlignment(
            QtCore.Qt.AlignmentFlag.AlignLeft | QtCore.Qt.AlignmentFlag.AlignVCenter
        )
        layout.addWidget(self.header_label)

        splitter = QtWidgets.QSplitter(QtCore.Qt.Orientation.Horizontal, self)
        self._high_display = _AnnealingPlotDisplay(ANNEALING_HIGH_GRAPH_DISPLAY_TITLE, logger, splitter)
        self._other_display = _AnnealingPlotGallery(ANNEALING_OTHER_GRAPH_COLUMN, logger, splitter)
        splitter.addWidget(self._high_display)
        splitter.addWidget(self._other_display)
        splitter.setStretchFactor(0, 1)
        splitter.setStretchFactor(1, 1)
        splitter.setSizes([1, 1])
        layout.addWidget(splitter, 1)

    def update_selection(
        self,
        key: Optional[MicrowireKey],
        high: Optional[MeasurementRecord],
        other_records: Sequence[MeasurementRecord],
    ) -> None:
        if key is None:
            self.header_label.setText("Select a row to preview annealing plots.")
            self._high_display.clear("Select a row to view the exact 1000 mA measurement.")
            self._other_display.clear("Select a row to view the other annealing measurements.")
            return

        composition, draw, piece, suffix = key
        try:
            microwire = _microwire_label(draw, piece, suffix)
        except Exception:
            microwire = f"{draw}/{piece}"
        self.header_label.setText(f"{composition} — {microwire}")

        self._high_display.set_record(
            high,
            setpoint=_extract_setpoint(high),
            description=_missing_high_measurement_message(other_records),
        )
        self._other_display.set_records(
            other_records,
            description="No other annealing measurements available for this microwire.",
        )



class _TransitionPickerDialog(QtWidgets.QDialog):
    def __init__(
        self,
        parent: QtWidgets.QWidget,
        record_pairs: List[Tuple[str, MeasurementRecord]],
        existing: Dict[str, float],
    ) -> None:
        super().__init__(parent)
        self.setWindowTitle("Interactive annealing plot")
        self.resize(960, 640)
        self._points: Dict[str, Optional[float]] = {
            "As": float(existing.get("As")) if isinstance(existing.get("As"), (int, float)) else None,
            "Ms": float(existing.get("Ms")) if isinstance(existing.get("Ms"), (int, float)) else None,
        }
        self._plots: Dict[str, Dict[str, Any]] = {}
        self._lines: Dict[str, Dict[str, Optional[Any]]] = {}
        self.cursor_value_label = QtWidgets.QLabel("—")
        self.cursor_value_label.setMinimumWidth(80)

        layout = QtWidgets.QVBoxLayout(self)
        self._tab_widget = QtWidgets.QTabWidget(self)
        layout.addWidget(self._tab_widget, 1)

        for label, record in record_pairs:
            frame = record.dataframe if isinstance(record.dataframe, pd.DataFrame) else pd.DataFrame()
            metadata = getattr(record, "metadata", None)
            if metadata is not None:
                title = format_annealing_title(metadata)
            else:
                path_attr = getattr(record, "path", None)
                title = Path(path_attr).name if path_attr else "Current annealing"
            figure, _ = plot_annealing_curve(frame, title, target_px=(1280, 640))
            canvas = FigureCanvasQTAgg(figure)
            toolbar = NavigationToolbar2QT(canvas, self)
            page = QtWidgets.QWidget(self)
            page_layout = QtWidgets.QVBoxLayout(page)
            page_layout.setContentsMargins(0, 0, 0, 0)
            page_layout.addWidget(toolbar)
            page_layout.addWidget(canvas, 1)
            self._tab_widget.addTab(page, label)
            axes = figure.axes[0] if figure.axes else figure.add_subplot(111)
            cid = canvas.mpl_connect("button_press_event", lambda event, lbl=label: self._handle_click(lbl, event))
            motion_cid = canvas.mpl_connect("motion_notify_event", lambda event, lbl=label: self._handle_motion(lbl, event))
            self._plots[label] = {"canvas": canvas, "figure": figure, "axes": axes, "cid": cid, "motion_cid": motion_cid}
            self._lines[label] = {"As": None, "Ms": None}

        controls = QtWidgets.QHBoxLayout()
        controls.addWidget(QtWidgets.QLabel("Cursor:"))
        controls.addWidget(self.cursor_value_label)
        controls.addSpacing(20)
        self.as_radio = QtWidgets.QRadioButton("Set As (mA)")
        self.ms_radio = QtWidgets.QRadioButton("Set Ms (mA)")
        self.as_radio.setChecked(True)
        controls.addWidget(self.as_radio)
        controls.addWidget(self.ms_radio)
        controls.addSpacing(20)
        self.as_value_label = QtWidgets.QLabel(self._format_value(self._points["As"]))
        self.ms_value_label = QtWidgets.QLabel(self._format_value(self._points["Ms"]))
        controls.addWidget(QtWidgets.QLabel("As:"))
        controls.addWidget(self.as_value_label)
        clear_as = QtWidgets.QPushButton("Clear As")
        clear_as.clicked.connect(lambda: self._clear_point("As"))
        controls.addWidget(clear_as)
        controls.addSpacing(10)
        controls.addWidget(QtWidgets.QLabel("Ms:"))
        controls.addWidget(self.ms_value_label)
        clear_ms = QtWidgets.QPushButton("Clear Ms")
        clear_ms.clicked.connect(lambda: self._clear_point("Ms"))
        controls.addWidget(clear_ms)
        controls.addStretch(1)
        layout.addLayout(controls)

        button_box = QtWidgets.QDialogButtonBox(
            QtWidgets.QDialogButtonBox.StandardButton.Ok | QtWidgets.QDialogButtonBox.StandardButton.Cancel,
            parent=self,
        )
        button_box.accepted.connect(self.accept)
        button_box.rejected.connect(self.reject)
        layout.addWidget(button_box)

        self._refresh_lines()

    @staticmethod
    def _format_value(value: Optional[float]) -> str:
        if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
            return "unset"
        return f"{float(value):.3f}".rstrip("0").rstrip(".")

    def _clear_point(self, label: str) -> None:
        self._points[label] = None
        self._refresh_lines()

    def _handle_click(self, label: str, event: Any) -> None:
        if event is None or event.inaxes is None or event.xdata is None:
            return
        if event.button != 1:
            return
        target = "As" if self.as_radio.isChecked() else "Ms"
        self._points[target] = float(event.xdata)
        self._refresh_lines()

    def _handle_motion(self, label: str, event: Any) -> None:
        if event is None or event.inaxes is None or event.xdata is None:
            self.cursor_value_label.setText("—")
            return
        self.cursor_value_label.setText(f"{float(event.xdata):.3f} mA")

    def _refresh_lines(self) -> None:
        for label, plot in self._plots.items():
            axes = plot["axes"]
            canvas = plot["canvas"]
            for point_name, color in (("As", "tab:green"), ("Ms", "tab:purple")):
                value = self._points.get(point_name)
                line = self._lines[label].get(point_name)
                if value is None:
                    if line is not None:
                        line.remove()
                        self._lines[label][point_name] = None
                    continue
                if line is None:
                    line = axes.axvline(float(value), color=color, linestyle="--", linewidth=1.2)
                    self._lines[label][point_name] = line
                else:
                    line.set_xdata([float(value), float(value)])
            canvas.draw_idle()
        self.as_value_label.setText(self._format_value(self._points.get("As")))
        self.ms_value_label.setText(self._format_value(self._points.get("Ms")))

    def result_points(self) -> Dict[str, Optional[float]]:
        return dict(self._points)

class _SectionWorker(QtCore.QObject):
    progress = QtCore.pyqtSignal(int, int, object)
    finished = QtCore.pyqtSignal(object)
    failed = QtCore.pyqtSignal(object)
    cancelled = QtCore.pyqtSignal()

    def __init__(self, section: "MiniDatabaseSection", paths: Iterable[Path]) -> None:
        super().__init__()
        self._section = section
        self._paths = [Path(p) for p in paths]

    def _emit_progress(self, current: int, total: int, message: Optional[str]) -> None:
        try:
            payload = str(message) if message is not None else None
        except Exception:
            payload = None
        try:
            self.progress.emit(int(current), int(total), payload)
        except Exception:
            pass

    @QtCore.pyqtSlot()
    def run(self) -> None:  # pragma: no cover - runs in worker thread
        try:
            result = self._section.process(self._paths, progress=self._emit_progress)
        except BuildCancelledError:
            try:
                self.cancelled.emit()
            except Exception:
                pass
        except Exception as exc:  # pragma: no cover - defensive
            try:
                self.failed.emit(exc)
            except Exception:
                pass
        else:
            try:
                self.finished.emit(result)
            except Exception:
                pass


class _CandidateCollectWorker(QtCore.QObject):
    finished = QtCore.pyqtSignal(object)
    failed = QtCore.pyqtSignal(object)

    def __init__(self, section: "MiniDatabaseSection") -> None:
        super().__init__()
        self._section = section

    @QtCore.pyqtSlot()
    def run(self) -> None:  # pragma: no cover - runs in worker thread
        try:
            candidates = self._section._collect_candidates()
        except Exception as exc:
            try:
                self.failed.emit(exc)
            except Exception:
                pass
        else:
            try:
                self.finished.emit(candidates)
            except Exception:
                pass


class _PendingScanWorker(QtCore.QObject):
    """Background worker that counts pending files for a section."""

    finished = QtCore.pyqtSignal(int)
    failed = QtCore.pyqtSignal(object)

    def __init__(
        self,
        sources: list[str],
        processed: dict[str, float],
        supported_suffixes: tuple[str, ...],
        recursive_search: bool,
    ) -> None:
        super().__init__()
        self._sources = [str(source) for source in sources]
        self._processed = dict(processed)
        self._supported_suffixes = tuple(supported_suffixes)
        self._recursive_search = bool(recursive_search)

    @QtCore.pyqtSlot()
    def run(self) -> None:  # pragma: no cover - runs in worker thread
        try:
            count = self._compute_pending_count()
        except Exception as exc:
            try:
                self.failed.emit(exc)
            except Exception:
                pass
        else:
            try:
                self.finished.emit(int(count))
            except Exception:
                pass

    def _compute_pending_count(self) -> int:
        candidates: Dict[str, Path] = {}
        suffixes = {s.lower() for s in self._supported_suffixes}
        thread = QtCore.QThread.currentThread()
        for source in self._sources:
            if thread is not None and thread.isInterruptionRequested():
                return 0
            root = Path(source).expanduser()
            if not root.exists():
                continue
            try:
                iterator: Iterable[Path] = (
                    root.rglob("*") if self._recursive_search else root.glob("*")
                )
            except Exception:
                continue
            for path in iterator:
                if thread is not None and thread.isInterruptionRequested():
                    return 0
                if not path.is_file():
                    continue
                if suffixes and path.suffix.lower() not in suffixes:
                    continue
                try:
                    resolved = str(path.resolve())
                except Exception:
                    resolved = str(path)
                candidates.setdefault(resolved, path)
        pending_count = 0
        processed = self._processed
        for path in candidates.values():
            if thread is not None and thread.isInterruptionRequested():
                return pending_count
            key = str(path)
            try:
                mtime = path.stat().st_mtime
            except OSError:
                continue
            if float(processed.get(key, -1.0)) != float(mtime):
                pending_count += 1
        return pending_count


def _microscope_index_to_frame(
    index: Dict[MicrowireKey, MicroscopeMeasurements],
    overrides: Dict[str, Dict[str, float]],
) -> pd.DataFrame:
    columns = MICROSCOPE_TABLE_COLUMNS.copy()

    def _category_value(
        detection: Optional[MicroscopeDetection],
        expected_category: str,
    ) -> Optional[float]:
        if not isinstance(detection, MicroscopeDetection):
            return None
        if getattr(detection, "category", None) != expected_category:
            return None
        try:
            numeric = float(detection.value)
        except (TypeError, ValueError):
            return None
        if not math.isfinite(numeric) or numeric <= 0:
            return None
        return numeric

    def _image_path(entries: Sequence[MicroscopeDetection]) -> Optional[str]:
        for detection in entries:
            crop = getattr(detection, "crop_path", None)
            if crop:
                return str(crop)
            source = getattr(detection, "image_path", None)
            if source:
                return str(source)
        return None

    rows: List[Dict[str, Any]] = []
    for (composition, draw, piece, suffix), measurements in sorted(
        index.items(),
        key=lambda item: (
            str(item[0][0]).lower(),
            int(item[0][1]),
            int(item[0][2]),
            (str(item[0][3]).lower() if item[0][3] is not None else ""),
        ),
    ):
        key = _microwire_key_to_str((composition, draw, piece, suffix))
        override = overrides.get(key, {})
        d_value = override.get("d")
        if d_value is None:
            d_value = _category_value(measurements.best_core_detection(), "core")
        D_value = override.get("D")
        if D_value is None:
            D_value = _category_value(measurements.best_glass_detection(), "glass")
        ratio = None
        if isinstance(d_value, (int, float)) and isinstance(D_value, (int, float)) and D_value:
            try:
                ratio = float(d_value) / float(D_value)
            except ZeroDivisionError:
                ratio = None
        if isinstance(ratio, (int, float)):
            ratio = round(float(ratio), 3)

        core_image = _image_path(measurements.core)
        glass_image = _image_path(measurements.glass)
        image_paths: List[str] = []
        for bucket in (measurements.core, measurements.glass, measurements.other):
            for detection in bucket:
                path = getattr(detection, "image_path", None)
                if path:
                    image_paths.append(str(path))
        if image_paths:
            image_paths = list(dict.fromkeys(image_paths))

        rows.append(
            {
                "Composition": composition,
                "Microwire": _microwire_label(draw, piece, suffix),
                MICROSCOPE_D_COLUMN: d_value,
                MICROSCOPE_CAP_D_COLUMN: D_value,
                "d/D": ratio,
                BRITTLE_COLUMN: "brittle" if getattr(measurements, "brittle", False) else None,
                MICROSCOPE_IMAGE_COLUMNS[0]: None,
                MICROSCOPE_IMAGE_COLUMNS[1]: None,
                "_key": key,
                "_core_image": core_image,
                "_glass_image": glass_image,
                "_images": image_paths,
            }
        )
    if not rows:
        return pd.DataFrame(columns=columns)
    return pd.DataFrame(rows, columns=columns)


def _video_index_to_frame(
    index: Dict[Tuple[str, int, Optional[int]], VideoMetricsSummary],
    fabrication_frame: Optional[pd.DataFrame] = None,
) -> pd.DataFrame:
    def _is_missing(value: object) -> bool:
        if value is None:
            return True
        if isinstance(value, str) and not value.strip():
            return True
        try:
            return bool(pd.isna(value))
        except Exception:
            return False

    base_columns: List[str] = []
    if isinstance(fabrication_frame, pd.DataFrame) and not fabrication_frame.empty:
        for column in fabrication_frame.columns:
            text = str(column)
            if text.startswith("_"):
                continue
            if text not in base_columns:
                base_columns.append(text)
    if not base_columns:
        base_columns = [
            "Composition",
            "Data source",
            "e/a",
            ESTIMATED_TRANSITION_COLUMN,
            "Draw",
            "Piece",
            "Length (m)",
            "Piece date",
            MICROSCOPE_D_COLUMN,
            MICROSCOPE_CAP_D_COLUMN,
            "d/D",
            "Resistance (Ω)",
            CORE_TEMPERATURE_COLUMN,
            GLASS_TEMPERATURE_COLUMN,
            "Mass (g)",
            "Winding speed (m/min)",
            "Glass feeding (mm/min)",
            "Underpressure",
            GLASS_PULL_COLUMN,
            "Notes",
            "Production datetime",
        ]
    for column in _fabrication_frame_columns():
        if str(column).startswith("_"):
            continue
        if column not in base_columns:
            base_columns.append(column)
    if "Microwire" not in base_columns:
        base_columns.insert(1, "Microwire")
    if "Draw" not in base_columns:
        base_columns.append("Draw")
    if "Piece" not in base_columns:
        base_columns.append("Piece")
    if VIDEO_END_LENGTH_COLUMN not in base_columns:
        base_columns.append(VIDEO_END_LENGTH_COLUMN)
    if VIDEO_MW_LENGTH_COLUMN not in base_columns:
        base_columns.append(VIDEO_MW_LENGTH_COLUMN)
    columns = list(base_columns) + ["_sources", "_group_key"]
    fabrication_lookup: Dict[Tuple[str, int, int], pd.Series] = {}
    if isinstance(fabrication_frame, pd.DataFrame) and not fabrication_frame.empty:
        for _, row in fabrication_frame.iterrows():
            composition = str(row.get("Composition") or "").strip()
            if not composition or composition == "Imported data:":
                continue
            try:
                draw = int(row.get("Draw"))
                piece = int(row.get("Piece"))
            except (TypeError, ValueError):
                continue
            fabrication_lookup[(composition, draw, piece)] = row
    piece_summaries: Dict[Tuple[str, int, int], VideoMetricsSummary] = {}
    draw_summaries: Dict[Tuple[str, int], VideoMetricsSummary] = {}
    for (composition, draw, piece), summary in sorted(index.items()):
        if piece is None:
            draw_summaries[(composition, draw)] = summary
        else:
            piece_summaries[(composition, draw, piece)] = summary
    rows: List[Dict[str, Any]] = []
    seen_keys: Set[Tuple[str, int, int]] = set()
    for (composition, draw, piece), summary in sorted(index.items()):
        if piece is None:
            continue
        row: Dict[str, Any] = {column: None for column in columns}
        row["Composition"] = composition
        row["Draw"] = draw
        row["Piece"] = piece
        row["Microwire"] = _microwire_label(draw, piece, None)
        ea_value = _compute_ea_from_composition(composition)
        row["e/a"] = ea_value
        row[ESTIMATED_TRANSITION_COLUMN] = _estimate_transition_temp_c(ea_value)
        fabrication_row = None
        if piece is not None:
            fabrication_row = fabrication_lookup.get((composition, draw, piece))
        if fabrication_row is not None:
            for column in base_columns:
                if column in {"Composition", "Draw", "Piece", "Microwire"}:
                    continue
                candidate = fabrication_row.get(column)
                if not _is_missing(candidate) and _is_missing(row.get(column)):
                    row[column] = candidate
        if piece is not None:
            seen_keys.add((composition, draw, piece))
        if row.get(ESTIMATED_TRANSITION_COLUMN) in (None, ""):
            row[ESTIMATED_TRANSITION_COLUMN] = _estimate_transition_temp_c(row.get("e/a"))
        temperature = summary.temperature()
        if not _is_missing(temperature):
            row[CORE_TEMPERATURE_COLUMN] = temperature
        underpressure = summary.underpressure()
        if not _is_missing(underpressure):
            row["Underpressure"] = underpressure
        winding_speed = summary.winding_speed()
        if not _is_missing(winding_speed):
            row["Winding speed (m/min)"] = winding_speed
        glass_feed = summary.glass_feed()
        if not _is_missing(glass_feed):
            row["Glass feeding (mm/min)"] = glass_feed
        row["_sources"] = sorted(str(path) for path in getattr(summary, "sources", set()))
        row["_group_key"] = _microwire_key_to_str((composition, draw, piece, None))
        rows.append(row)
    for (composition, draw, piece), fabrication_row in sorted(fabrication_lookup.items()):
        if (composition, draw, piece) in seen_keys:
            continue
        summary = piece_summaries.get((composition, draw, piece))
        if summary is None:
            summary = draw_summaries.get((composition, draw))
        row: Dict[str, Any] = {column: None for column in columns}
        row["Composition"] = composition
        row["Draw"] = draw
        row["Piece"] = piece
        row["Microwire"] = _microwire_label(draw, piece, None)
        ea_value = fabrication_row.get("e/a")
        if _is_missing(ea_value):
            ea_value = _compute_ea_from_composition(composition)
        row["e/a"] = ea_value
        row[ESTIMATED_TRANSITION_COLUMN] = _estimate_transition_temp_c(ea_value)
        for column in base_columns:
            if column in {"Composition", "Draw", "Piece", "Microwire"}:
                continue
            candidate = fabrication_row.get(column)
            if not _is_missing(candidate):
                row[column] = candidate
        if row.get(ESTIMATED_TRANSITION_COLUMN) in (None, ""):
            row[ESTIMATED_TRANSITION_COLUMN] = _estimate_transition_temp_c(row.get("e/a"))
        if summary is not None:
            temperature = summary.temperature()
            if not _is_missing(temperature):
                row[CORE_TEMPERATURE_COLUMN] = temperature
            underpressure = summary.underpressure()
            if not _is_missing(underpressure):
                row["Underpressure"] = underpressure
            winding_speed = summary.winding_speed()
            if not _is_missing(winding_speed):
                row["Winding speed (m/min)"] = winding_speed
            glass_feed = summary.glass_feed()
            if not _is_missing(glass_feed):
                row["Glass feeding (mm/min)"] = glass_feed
            row["_sources"] = sorted(str(path) for path in getattr(summary, "sources", set()))
        else:
            row["_sources"] = []
        row["_group_key"] = _microwire_key_to_str((composition, draw, piece, None))
        rows.append(row)
    if not rows:
        return pd.DataFrame(columns=columns)
    return pd.DataFrame(rows, columns=columns)


def _strain_records_to_frame(records: Dict[MicrowireKey, StrainRecord]) -> pd.DataFrame:
    columns = [
        "Composition",
        "Draw",
        "Piece",
        "Microwire",
        "Strain (%)",
        "Broke",
    ]
    rows: List[Dict[str, Any]] = []
    for (composition, draw, piece, suffix), record in sorted(records.items()):
        rows.append(
            {
                "Composition": composition,
                "Draw": draw,
                "Piece": piece,
                "Microwire": record.microwire_label or _microwire_label(draw, piece, suffix),
                "Strain (%)": record.percent,
                "Broke": bool(record.broke),
            }
        )
    if not rows:
        return pd.DataFrame(columns=columns)
    return pd.DataFrame(rows, columns=columns)


def _apply_microscope_overrides(
    index: Dict[MicrowireKey, MicroscopeMeasurements],
    overrides: Dict[str, Dict[str, float]],
) -> Dict[MicrowireKey, MicroscopeMeasurements]:
    result: Dict[MicrowireKey, MicroscopeMeasurements] = {}
    for key, measurements in index.items():
        clone = MicroscopeMeasurements(
            core=list(measurements.core),
            glass=list(measurements.glass),
            other=list(measurements.other),
            brittle=bool(getattr(measurements, "brittle", False)),
        )
        token = _microwire_key_to_text(key) or ""
        override = overrides.get(token, {})
        if not override:
            parts = _split_microwire_key(key)
            if parts is not None:
                composition, draw, piece, _suffix = parts
                base_token = _microwire_key_to_str((composition, draw, piece, None))
                override = overrides.get(base_token, {})
        d_value = override.get("d")
        if isinstance(d_value, (int, float)) and d_value > 0:
            detection = MicroscopeDetection(
                value=float(d_value),
                image_path=None,
                source="manual",
            )
            detection.category = "core"
            clone.core.insert(0, detection)
        D_value = override.get("D")
        if isinstance(D_value, (int, float)) and D_value > 0:
            detection = MicroscopeDetection(
                value=float(D_value),
                image_path=None,
                source="manual",
            )
            detection.category = "glass"
            clone.glass.insert(0, detection)
        result[key] = clone
    return result


def _filter_other_end_microscope_index(
    index: Dict[MicrowireKey, MicroscopeMeasurements],
    *,
    show_other_ends: bool,
) -> Dict[MicrowireKey, MicroscopeMeasurements]:
    if show_other_ends:
        return dict(index)
    filtered: Dict[MicrowireKey, MicroscopeMeasurements] = {}
    for key, measurements in index.items():
        suffix = None
        if isinstance(key, tuple) and len(key) >= 4:
            suffix = key[3]
        if str(suffix or "").strip().lower() == "oe":
            continue
        filtered[key] = measurements
    return filtered


def _sample_from_path(path: Path, sources: Sequence[str]) -> str:
    for source in sources:
        root = Path(source).expanduser()
        try:
            if root.is_file() and path.resolve() == root.resolve():
                return path.stem
        except Exception:
            pass
        try:
            rel = path.resolve().relative_to(root.resolve())
        except Exception:
            continue
        parts = rel.parts
        if len(parts) >= 2:
            if parts[0].lower() in {"sweep", "sweeps"}:
                return parts[1]
            return parts[0]
        if len(parts) == 1:
            return path.stem
    parent = path.parent.name
    return parent if parent else path.stem


_SAMPLE_VARIANT_RE = re.compile(
    r"^\s*(?P<comp>[A-Za-z][A-Za-z0-9]*)\s+(?P<draw>\d{1,3})\s*[-_/]\s*(?P<piece>\d{1,3})(?P<suffix>[A-Za-z][A-Za-z0-9]*)?(?P<rest_sep>[\s\-_/.]+(?P<rest>.+))?$"
)


MicrowireKey = Tuple[str, int, int, Optional[str]]


def _microwire_key_to_text(value: object) -> Optional[str]:
    parts = _split_microwire_key(value)
    if parts is None:
        return None
    return _microwire_key_to_str(parts)


def _microwire_parts_from_label_safe(
    label: str,
) -> Optional[Tuple[int, int, Optional[str]]]:
    parts = _microwire_parts_from_label(label)
    if parts is not None:
        return parts
    fallback = _microwire_tuple_from_label(label)
    if fallback is not None:
        return fallback[0], fallback[1], None
    return None


def _split_sample_variant(sample: str) -> Tuple[str, Optional[str]]:
    text = str(sample or "").strip()
    if not text:
        return "", None
    match = _SAMPLE_VARIANT_RE.match(text)
    if not match:
        return text, None
    comp = match.group("comp").strip()
    draw = match.group("draw").strip()
    piece = match.group("piece").strip()
    suffix = match.group("suffix") or ""
    suffix = suffix.strip()
    base = f"{comp} {draw}-{piece}{suffix}"
    rest = (match.group("rest") or "").strip()
    if rest:
        rest = rest.strip(" -_/")
    return base, rest or None


def _microwire_key_from_path(path: Path, sample: str) -> Optional[MicrowireKey]:
    key = _microscope_key(path)
    if key is None and sample:
        try:
            key = _microscope_key(Path(sample))
        except Exception:
            key = None
    return key


def _microwire_info_from_key(
    key: Optional[MicrowireKey],
) -> Tuple[Optional[str], Optional[str]]:
    parts = _split_microwire_key(key) if key is not None else None
    if parts is None:
        return None, None
    composition, draw, piece, suffix = parts
    if not composition:
        return None, None
    try:
        microwire = _microwire_label(int(draw), int(piece), suffix)
    except Exception:
        microwire = f"{draw}/{piece}"
    return str(composition), microwire


def _record_label_for_display(record: object) -> str:
    label = getattr(record, "label", None)
    if isinstance(label, str) and label.strip():
        return label.strip()
    path = getattr(record, "path", None)
    if isinstance(path, Path):
        return path.stem
    if isinstance(path, str):
        return Path(path).stem
    sample = getattr(record, "sample", None)
    return str(sample).strip() if sample else ""


def _record_path_key(record: object) -> Optional[str]:
    path = getattr(record, "path", None)
    if isinstance(path, Path):
        return str(path)
    if isinstance(path, str) and path:
        return path
    return None


def _shape_memory_current_mA_from_record(record: ShapeMemoryStressStrainRecord) -> Optional[float]:
    text = ""
    path = getattr(record, "path", None)
    if isinstance(path, Path):
        text = path.stem
    elif isinstance(path, str):
        text = Path(path).stem
    match = re.search(r"(\d+(?:[.,]\d+)?)\s*mA", text, re.IGNORECASE)
    if not match:
        return None
    try:
        return float(match.group(1).replace(",", "."))
    except Exception:
        return None


def _shape_memory_current_mA_from_text(value: object) -> Optional[float]:
    text = str(value or "").strip()
    if not text:
        return None
    match = re.search(r"(\d+(?:[.,]\d+)?)\s*mA", text, re.IGNORECASE)
    if not match:
        return None
    try:
        return float(match.group(1).replace(",", "."))
    except Exception:
        return None


def _shape_memory_is_fracture_record(record: ShapeMemoryStressStrainRecord) -> bool:
    path = getattr(record, "path", None)
    text = ""
    if isinstance(path, Path):
        text = path.stem
    elif isinstance(path, str):
        text = Path(path).stem
    label = getattr(record, "label", None)
    return "fracture" in text.casefold() or (
        isinstance(label, str) and "fracture" in label.casefold()
    )


def _shape_memory_row_has_record_metadata(row: Mapping[str, Any]) -> bool:
    raw_sources = row.get("_sources")
    if isinstance(raw_sources, str) and raw_sources.strip():
        return True
    if isinstance(raw_sources, (list, tuple, set)):
        for value in raw_sources:
            if str(value or "").strip():
                return True
    for column in (
        SHAPE_MEMORY_STRESS_STRAIN_COLUMN,
        _SHAPE_MEMORY_STANDARD_SOURCE_COLUMN,
        _SHAPE_MEMORY_FRACTURE_SOURCE_COLUMN,
    ):
        value = row.get(column)
        if isinstance(value, str) and value.strip():
            return True
        if isinstance(value, (list, tuple, set)):
            for item in value:
                if str(item or "").strip():
                    return True
    return False


def _shape_memory_row_has_saved_payload(row: Mapping[str, Any]) -> bool:
    return _shape_memory_payload_has_values(row, _SHAPE_MEMORY_STANDARD_VALUE_COLUMNS) or _shape_memory_payload_has_values(
        row, _SHAPE_MEMORY_FRACTURE_VALUE_COLUMNS
    )


def _microscope_diameter_lookup(frame: pd.DataFrame | None) -> Dict[str, Optional[float]]:
    lookup: Dict[str, Optional[float]] = {}
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        return lookup
    for _, microscope_row in frame.iterrows():
        lookup_key = _row_to_microwire_key(microscope_row)
        if not lookup_key:
            raw_key = str(microscope_row.get("_key") or "").strip()
            if raw_key:
                parsed_key = _microwire_key_from_string(raw_key)
                split_key = _split_microwire_key(parsed_key)
                if split_key is not None:
                    lookup_key = _microwire_key_to_str(split_key)
        if not lookup_key:
            continue
        try:
            d_value = float(microscope_row.get(MICROSCOPE_D_COLUMN))
        except Exception:
            d_value = math.nan
        lookup[lookup_key] = d_value if math.isfinite(d_value) and d_value > 0 else None
    return lookup


def _current_density_from_diameter_um(
    current_mA: Optional[float], diameter_um: Optional[float]
) -> Optional[float]:
    if current_mA is None or diameter_um is None:
        return None
    try:
        current_a = float(current_mA) / 1000.0
        diameter_mm = float(diameter_um) / 1000.0
    except Exception:
        return None
    if not math.isfinite(current_a) or not math.isfinite(diameter_mm) or diameter_mm <= 0:
        return None
    area_mm2 = math.pi * (diameter_mm / 2.0) ** 2
    if area_mm2 <= 0:
        return None
    return current_a / area_mm2


def _visibility_items_from_records(records: Sequence[object]) -> List[Tuple[str, str]]:
    items: List[Tuple[str, str]] = []
    seen: Set[str] = set()
    for record in records:
        path = _record_path_key(record)
        if not path or path in seen:
            continue
        seen.add(path)
        label = _record_label_for_display(record)
        sample = getattr(record, "sample", None)
        if isinstance(sample, str) and sample.strip():
            if label and label != sample:
                label = f"{sample} — {label}"
            else:
                label = sample
        if not label:
            label = Path(path).name
        items.append((label, path))
    return items


def _visibility_groups_from_records(
    records: Sequence[object],
) -> Dict[str, List[Tuple[str, str]]]:
    groups: Dict[str, List[Tuple[str, str]]] = {}
    seen: Set[str] = set()
    for record in records:
        path = _record_path_key(record)
        if not path or path in seen:
            continue
        seen.add(path)
        label = _record_label_for_display(record)
        sample = getattr(record, "sample", None)
        group_label = label
        if isinstance(sample, str) and sample.strip():
            if group_label:
                if sample not in group_label:
                    group_label = f"{sample} — {group_label}"
            else:
                group_label = sample
        if not group_label:
            group_label = Path(path).name
        item_label = Path(path).name
        groups.setdefault(group_label, []).append((item_label, path))
    return groups


def _hidden_paths_from_section(section: object) -> Set[str]:
    extra = getattr(getattr(section, "data", None), "extra", None)
    if isinstance(extra, Mapping):
        hidden = extra.get("hidden_paths")
        if isinstance(hidden, (list, tuple, set)):
            return {str(path) for path in hidden if path}
    return set()


def _section_payload_enabled(section: object, name: str) -> bool:
    extra = getattr(getattr(section, "data", None), "extra", None)
    if not isinstance(extra, Mapping):
        return False
    payloads = extra.get("payloads")
    if not isinstance(payloads, Mapping):
        return False
    stored_name = payloads.get(name)
    return isinstance(stored_name, str) and stored_name == name


def _record_key_for_group(record: object) -> Optional[MicrowireKey]:
    key = getattr(record, "key", None)
    key_parts = _split_microwire_key(key)
    if key_parts is not None:
        return key_parts
    return None


def _row_to_microwire_key(row: pd.Series) -> Optional[str]:
    composition = str(row.get("Composition") or "").strip()
    microwire = str(row.get("Microwire") or "").strip()
    if not composition or not microwire:
        return None
    parsed = _microwire_parts_from_label_safe(microwire)
    if parsed is None:
        return None
    draw, piece, suffix = parsed
    try:
        return _microwire_key_to_str((composition, int(draw), int(piece), suffix))
    except (TypeError, ValueError):
        return None


def _row_sample_value(row: pd.Series) -> Optional[str]:
    for key in ("Sample", "_sample", "sample"):
        value = row.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return _row_to_microwire_key(row)


def _group_graph_records_by_key(records: Sequence[object]) -> Dict[str, List[object]]:
    grouped: Dict[str, List[object]] = {}
    for record in records:
        key = _record_key_for_group(record)
        if key is None:
            sample = getattr(record, "sample", None)
            if isinstance(sample, str) and sample.strip():
                try:
                    key = _microscope_key(Path(sample))
                except Exception:
                    key = None
        if key is None:
            continue
        group_key = _microwire_key_to_text(key)
        if not group_key:
            continue
        grouped.setdefault(group_key, []).append(record)
    return grouped


def _graph_records_to_frame(
    records: Sequence[object],
    graph_column: str,
    *,
    sample_column: str = "Sample",
) -> pd.DataFrame:
    columns = []
    if sample_column:
        columns.append(sample_column)
    columns.extend(
        [
            "Composition",
            "Microwire",
            graph_column,
            "_group_key",
            "_sources",
        ]
    )
    if not records:
        return pd.DataFrame(columns=columns)
    grouped: Dict[str, List[object]] = {}
    for record in records:
        sample = getattr(record, "sample", None)
        if not isinstance(sample, str) or not sample.strip():
            path = getattr(record, "path", None)
            if isinstance(path, Path):
                sample = path.stem
            elif isinstance(path, str):
                sample = Path(path).stem
            else:
                sample = "sample"
        grouped.setdefault(sample, []).append(record)
    rows: List[Dict[str, Any]] = []
    for sample, group in sorted(grouped.items()):
        key: Optional[MicrowireKey] = None
        for record in group:
            key = _record_key_for_group(record)
            if key is not None:
                break
        composition, microwire = _microwire_info_from_key(key)
        labels: List[str] = []
        sources: List[str] = []
        for record in group:
            label = _record_label_for_display(record)
            if label and label not in labels:
                labels.append(label)
            path = getattr(record, "path", None)
            if isinstance(path, Path):
                sources.append(str(path))
            elif isinstance(path, str):
                sources.append(path)
        group_key = _microwire_key_to_text(key) if key is not None else ""
        rows.append(
            {
                sample_column: sample if sample_column else None,
                "Composition": composition,
                "Microwire": microwire,
                graph_column: labels,
                "_group_key": group_key,
                "_sources": list(dict.fromkeys(sources)),
            }
        )
    return pd.DataFrame(rows, columns=columns)


def _mini_dma_records_to_frame(records: Sequence[MiniDmaRecord]) -> pd.DataFrame:
    frame = _graph_records_to_frame(
        records,
        MINI_DMA_COLUMN,
        sample_column="_sample",
    )
    if MINI_DMA_STRAIN_COLUMN not in frame.columns:
        frame[MINI_DMA_STRAIN_COLUMN] = [[] for _ in range(len(frame.index))]
    frame[MINI_DMA_STRAIN_COLUMN] = frame[MINI_DMA_STRAIN_COLUMN].astype(object)
    if MINI_DMA_TRANSITION_COLUMN not in frame.columns:
        frame[MINI_DMA_TRANSITION_COLUMN] = [[] for _ in range(len(frame.index))]
    frame[MINI_DMA_TRANSITION_COLUMN] = frame[MINI_DMA_TRANSITION_COLUMN].astype(object)
    if MINI_DMA_BREAK_COLUMN not in frame.columns:
        frame[MINI_DMA_BREAK_COLUMN] = pd.Series([""] * len(frame.index), dtype=object)
    else:
        frame[MINI_DMA_BREAK_COLUMN] = frame[MINI_DMA_BREAK_COLUMN].astype(object)
    if not records or frame.empty:
        return frame

    grouped: Dict[str, List[MiniDmaRecord]] = {}
    for record in records:
        sample = getattr(record, "sample", None)
        if isinstance(sample, str) and sample.strip():
            grouped.setdefault(sample, []).append(record)
    for index, row in frame.iterrows():
        sample = row.get("_sample", "")
        group = grouped.get(sample, []) if isinstance(sample, str) else []
        strain_lines: List[str] = []
        transition_lines: List[str] = []
        break_lines: List[str] = []
        for record in group:
            for line in getattr(record, "strain_summary", ()) or ():
                if line and line not in strain_lines:
                    strain_lines.append(str(line))
            for line in getattr(record, "transition_summary", ()) or ():
                if line and line not in transition_lines:
                    transition_lines.append(str(line))
            break_summary = getattr(record, "break_summary", "") or ""
            if break_summary and break_summary not in break_lines:
                break_lines.append(str(break_summary))
        frame.at[index, MINI_DMA_STRAIN_COLUMN] = strain_lines
        frame.at[index, MINI_DMA_TRANSITION_COLUMN] = transition_lines
        frame.at[index, MINI_DMA_BREAK_COLUMN] = (
            list(dict.fromkeys(break_lines)) if break_lines else ""
        )
    return frame


def _mini_dma_resolve_measurement_path(path: Path) -> Path | None:
    try:
        if mini_dma_core is not None:
            return mini_dma_core.resolve_measurement_path(path)
    except Exception:
        return None
    candidate = Path(path)
    if candidate.is_dir():
        candidate = candidate / "measurement.csv"
    if candidate.name.casefold() != "measurement.csv":
        return None
    try:
        if candidate.exists() and candidate.is_file():
            return candidate
    except OSError:
        return None
    return None


def _read_mini_dma_metadata(measurement_path: Path) -> Dict[str, Any]:
    metadata_path = measurement_path.with_name("metadata.json")
    try:
        payload = json.loads(metadata_path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return payload if isinstance(payload, dict) else {}


def _mini_dma_timestamp(value: object) -> Optional[float]:
    if value in (None, ""):
        return None
    if isinstance(value, (int, float)):
        numeric = float(value)
        return numeric if math.isfinite(numeric) else None
    text = str(value).strip()
    if not text:
        return None
    normalized = text.replace("Z", "+00:00")
    try:
        parsed = datetime.fromisoformat(normalized)
    except ValueError:
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y%m%d_%H%M%S"):
            try:
                parsed = datetime.strptime(text, fmt)
                break
            except ValueError:
                parsed = None  # type: ignore[assignment]
        if parsed is None:
            return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=UTC)
    return parsed.timestamp()


def _mini_dma_metadata_sort_timestamp(
    metadata: Mapping[str, Any],
    measurement_path: Path,
) -> float:
    for key in ("created_utc", "timestamp_utc", "started_utc", "finished_utc"):
        parsed = _mini_dma_timestamp(metadata.get(key))
        if parsed is not None:
            return parsed
    for candidate in (measurement_path.with_name("metadata.json"), measurement_path):
        try:
            return float(candidate.stat().st_mtime)
        except OSError:
            continue
    return 0.0


def _mini_dma_clear_completion_status(metadata: Mapping[str, Any]) -> Tuple[bool, str]:
    state = str(metadata.get("session_state") or "").strip().casefold()
    finished_utc = metadata.get("finished_utc")
    has_finished_utc = _mini_dma_timestamp(finished_utc) is not None or bool(str(finished_utc or "").strip())
    if state == "finished":
        if has_finished_utc:
            return True, "metadata session_state=finished with finished_utc"
        return False, "metadata session_state=finished but missing finished_utc"
    if state:
        return False, f"metadata session_state={state}"
    if has_finished_utc:
        return True, "metadata finished_utc present"
    try:
        point_count = int(float(metadata.get("point_count")))
        estimated = int(float(metadata.get("recipe_estimated_points")))
    except (TypeError, ValueError):
        point_count = 0
        estimated = 0
    if point_count > 0 and estimated > 0 and point_count >= estimated:
        return True, "fallback point_count reached recipe_estimated_points"
    if metadata:
        return False, "metadata lacks session_state and finished_utc"
    return True, "legacy fallback: metadata.json missing"


def _mini_dma_reportability_sample_key(
    measurement_path: Path,
    metadata: Mapping[str, Any],
    sources: Sequence[str],
) -> str:
    metadata_sample = str(metadata.get("sample_name") or "").strip()
    if metadata_sample:
        return metadata_sample.replace("/", "_")
    run_path = measurement_path.parent
    sample = _sample_from_path(run_path, sources)
    return sample or run_path.name


def _reportable_mini_dma_measurements(
    paths: Sequence[Path],
    *,
    sources: Sequence[str] = (),
    excluded_dirs: Collection[str] | None = None,
) -> Tuple[List[Path], List[Dict[str, Any]]]:
    ignored = {str(name).casefold() for name in (excluded_dirs or MiniDmaSection.excluded_refresh_dirs)}
    source_roots: List[Path] = []
    for source in sources:
        try:
            candidate = Path(source).expanduser()
            root = candidate.resolve() if candidate.is_dir() else candidate.parent.resolve()
        except Exception:
            root = Path(source).expanduser()
        source_roots.append(root)

    def _ignored_part_for(measurement_path: Path) -> Optional[str]:
        try:
            resolved_path = measurement_path.resolve()
        except OSError:
            resolved_path = measurement_path
        for root in source_roots:
            try:
                relative_parts = resolved_path.relative_to(root).parts[:-1]
            except ValueError:
                continue
            return next((part for part in relative_parts if part.casefold() in ignored), None)
        return next((part for part in measurement_path.parts[:-1] if part.casefold() in ignored), None)

    candidates: Dict[str, Dict[str, Any]] = {}
    for raw_path in paths:
        measurement_path = _mini_dma_resolve_measurement_path(Path(raw_path))
        if measurement_path is None:
            continue
        try:
            resolved = str(measurement_path.resolve())
        except OSError:
            resolved = str(measurement_path)
        if resolved in candidates:
            continue
        ignored_part = _ignored_part_for(measurement_path)
        metadata = _read_mini_dma_metadata(measurement_path)
        sample_key = _mini_dma_reportability_sample_key(measurement_path, metadata, sources)
        timestamp = _mini_dma_metadata_sort_timestamp(metadata, measurement_path)
        finished, status_reason = _mini_dma_clear_completion_status(metadata)
        candidates[resolved] = {
            "sample": sample_key,
            "run_folder": str(measurement_path.parent),
            "measurement": str(measurement_path),
            "timestamp": timestamp,
            "metadata_session_state": metadata.get("session_state"),
            "metadata_finished_utc": metadata.get("finished_utc"),
            "metadata_created_utc": metadata.get("created_utc"),
            "reportable": False,
            "skip_reason": f"ignored folder: {ignored_part}" if ignored_part else "",
            "status_reason": status_reason,
            "_path": measurement_path,
            "_finished": finished,
            "_ignored": ignored_part is not None,
        }

    grouped: Dict[str, List[Dict[str, Any]]] = {}
    for entry in candidates.values():
        if entry["_ignored"]:
            continue
        grouped.setdefault(str(entry["sample"]), []).append(entry)

    for sample, group in grouped.items():
        newest = max(
            group,
            key=lambda item: (
                float(item.get("timestamp") or 0.0),
                str(item.get("run_folder") or ""),
            ),
        )
        if not newest["_finished"]:
            reason = f"newest active run is unfinished: {newest['status_reason']}"
            for entry in group:
                entry["skip_reason"] = reason
            continue
        for entry in group:
            if entry["_finished"]:
                entry["reportable"] = True
                entry["skip_reason"] = ""
            else:
                entry["skip_reason"] = f"run is unfinished: {entry['status_reason']}"

    reportable = [
        cast(Path, entry["_path"])
        for entry in sorted(
            candidates.values(),
            key=lambda item: (str(item.get("sample") or ""), float(item.get("timestamp") or 0.0), str(item.get("run_folder") or "")),
        )
        if bool(entry.get("reportable"))
    ]
    audit: List[Dict[str, Any]] = []
    for entry in sorted(
        candidates.values(),
        key=lambda item: (str(item.get("sample") or ""), float(item.get("timestamp") or 0.0), str(item.get("run_folder") or "")),
    ):
        clean = {
            key: value
            for key, value in entry.items()
            if not key.startswith("_") and key != "timestamp"
        }
        clean["timestamp"] = float(entry.get("timestamp") or 0.0)
        audit.append(clean)
    return reportable, audit


def _drop_visible_sample_column(section: "MiniDatabaseSection") -> None:
    frame = section.model.frame() if hasattr(section, "model") else None
    if not isinstance(frame, pd.DataFrame):
        return
    sample_columns: List[str] = []
    for column in frame.columns:
        normalized = str(column).strip().lower()
        if normalized in {"sample", "_sample"}:
            sample_columns.append(str(column))
    if not sample_columns:
        return
    cleaned = frame.copy()
    if "_sample" not in cleaned.columns and sample_columns:
        cleaned["_sample"] = cleaned[sample_columns[0]]
    cleaned = cleaned.drop(columns=sample_columns)
    try:
        section.data.table = cleaned
    except Exception:
        pass
    try:
        section.model.set_frame(cleaned)
    except Exception:
        pass
    try:
        section.store.save(section.data)
    except Exception:
        pass



class MiniDatabaseSection(QtWidgets.QWidget):
    """Base widget for mini-database sections that process a subset of data."""

    section_key = "base"
    section_title = "Base"
    supported_suffixes: tuple[str, ...] = ()
    recursive_search = True

    status_changed = QtCore.pyqtSignal(str)
    sources_changed = QtCore.pyqtSignal(list)
    data_updated = QtCore.pyqtSignal()
    log_emitted = QtCore.pyqtSignal(int, str)
    _processing_owner: ClassVar[Optional["MiniDatabaseSection"]] = None
    _refresh_queue: ClassVar[List["MiniDatabaseSection"]] = []
    _project_load_batch_mode: ClassVar[bool] = False
    _skip_initial_store_load: ClassVar[bool] = False
    _SCROLL_SINGLE_STEP = 12

    def __init__(
        self,
        logger: logging.Logger,
        log_callback: Callable[[int, str], None],
        parent: QtWidgets.QWidget | None = None,
    ) -> None:
        super().__init__(parent)
        init_started_s = time.perf_counter()
        self.logger = logger
        self._log_callback = log_callback
        self.store = MiniDatabaseStore(self.section_key)
        if self._skip_initial_store_load:
            self.data = MiniDatabaseData()
            _log_builder_timing(
                self.logger,
                "section_init_store_load_skipped",
                init_started_s,
                section=self.section_key,
            )
        else:
            load_started_s = time.perf_counter()
            self.data = self.store.load()
            _log_builder_timing(
                self.logger,
                "section_init_store_load",
                load_started_s,
                section=self.section_key,
                rows=len(self.data.table.index)
                if isinstance(self.data.table, pd.DataFrame)
                else 0,
            )
        self.model = DataFrameModel(self.data.table)
        self._search_proxy = _TableSearchProxyModel(self)
        self.table_view: QtWidgets.QTableView | None = None
        self._table_splitter: QtWidgets.QSplitter | None = None
        self.search_edit: QtWidgets.QLineEdit | None = None
        self.search_clear_button: QtWidgets.QPushButton | None = None
        self._cancel_requested = False
        self.log_emitted.connect(
            self._dispatch_log,
            QtCore.Qt.ConnectionType.QueuedConnection,
        )
        self._worker_thread: QtCore.QThread | None = None
        self._worker: Optional["_SectionWorker"] = None
        self._candidate_thread: QtCore.QThread | None = None
        self._candidate_worker: Optional[_CandidateCollectWorker] = None
        self._active_candidates: List[Path] = []
        self._pending_count_cache: int | None = None
        self._pending_scan_in_progress = False
        self._pending_scan_generation = 0
        self._suppress_pending_scan_once = True
        self._pending_scan_thread: QtCore.QThread | None = None
        self._pending_scan_worker: Optional[_PendingScanWorker] = None
        self._progress_dialog: QtWidgets.QProgressDialog | None = None

        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(8)
        self.main_layout = layout

        controls = QtWidgets.QHBoxLayout()
        self.source_button = QtWidgets.QPushButton()
        self.source_button.setText("Connect folder…")
        self.source_button.clicked.connect(self._toggle_source)
        controls.addWidget(self.source_button)

        self.open_sources_button = QtWidgets.QPushButton("Open source file(s)")
        self.open_sources_button.setEnabled(False)
        self.open_sources_button.clicked.connect(self._open_selected_sources)
        controls.addWidget(self.open_sources_button)

        controls.addStretch(1)

        self.refresh_button = QtWidgets.QPushButton("Refresh")
        self.refresh_button.clicked.connect(self.refresh)
        controls.addWidget(self.refresh_button)

        self.stop_button = QtWidgets.QPushButton("Stop")
        self.stop_button.setEnabled(False)
        self.stop_button.clicked.connect(self._request_cancel)
        controls.addWidget(self.stop_button)

        layout.addLayout(controls)
        self.controls_layout = controls

        search_row = QtWidgets.QHBoxLayout()
        search_row.setContentsMargins(0, 0, 0, 0)
        search_row.setSpacing(6)
        search_row.addWidget(QtWidgets.QLabel("Search:"))
        self.search_edit = QtWidgets.QLineEdit(self)
        self.search_edit.setClearButtonEnabled(True)
        self.search_edit.setPlaceholderText("Filter rows across visible columns")
        self.search_edit.textChanged.connect(self._handle_search_changed)
        search_row.addWidget(self.search_edit, 1)
        self.search_clear_button = QtWidgets.QPushButton("Clear")
        self.search_clear_button.setEnabled(False)
        self.search_clear_button.clicked.connect(self._clear_search)
        search_row.addWidget(self.search_clear_button)
        search_row.addWidget(QtWidgets.QLabel("Source:"))
        self.source_filter_combo = QtWidgets.QComboBox(self)
        self.source_filter_combo.addItem(SOURCE_LABEL_ALL)
        self.source_filter_combo.setEnabled(False)
        self.source_filter_combo.currentTextChanged.connect(
            self._handle_source_filter_changed
        )
        search_row.addWidget(self.source_filter_combo)
        layout.addLayout(search_row)

        self.status_label = QtWidgets.QLabel()
        layout.addWidget(self.status_label)

        progress_row = QtWidgets.QHBoxLayout()
        self.progress_bar = QtWidgets.QProgressBar()
        self.progress_bar.setRange(0, 100)
        self.progress_bar.setValue(0)
        progress_row.addWidget(self.progress_bar, 1)
        self.progress_label = QtWidgets.QLabel("Idle")
        progress_row.addWidget(self.progress_label)
        self.progress_eta_label = QtWidgets.QLabel("")
        self.progress_eta_label.setAlignment(QtCore.Qt.AlignmentFlag.AlignRight | QtCore.Qt.AlignmentFlag.AlignVCenter)
        progress_row.addWidget(self.progress_eta_label)
        layout.addLayout(progress_row)
        self.progress_bar.hide()
        self.progress_label.hide()
        self.progress_eta_label.hide()
        self._progress_total: int = 0
        self._progress_current: int = 0
        self._progress_start: float | None = None

        self.sources_list = QtWidgets.QListWidget(self)
        self.sources_list.hide()

        right_panel = self.create_right_panel(self)
        layout.addWidget(right_panel, 1)
        if isinstance(self.table_view, QtWidgets.QTableView):
            self._search_proxy.setSourceModel(self.model)
            self._search_proxy.set_row_predicate(self._row_filter_accepts)
            self.table_view.setModel(self._search_proxy)
        self._configure_table_view()

        self._populate_sources_list()
        self.data.table = _with_source_label_column(self.data.table)
        self.model.set_frame(self.data.table)
        self._refresh_source_filter_options()
        self._auto_fit_columns()
        self._update_status()
        self._reset_progress_ui()
        self._hook_table_selection()
        self._update_open_sources_enabled()
        try:
            if hasattr(self, "_sanitize_graph_columns"):
                self._sanitize_graph_columns()
        except Exception:
            pass
        _log_builder_timing(
            self.logger,
            "section_init_total",
            init_started_s,
            section=self.section_key,
        )

    # ------------------------------------------------------------------ UI helpers
    def create_right_panel(self, parent: QtWidgets.QWidget) -> QtWidgets.QWidget:
        table = QtWidgets.QTableView(parent)
        table.setModel(self.model)
        header = table.horizontalHeader()
        if header is not None:
            header.setStretchLastSection(False)
            header.setSectionResizeMode(QtWidgets.QHeaderView.ResizeMode.Interactive)
        table.setAlternatingRowColors(True)
        table.setSelectionBehavior(
            QtWidgets.QAbstractItemView.SelectionBehavior.SelectRows
        )
        table.setSelectionMode(
            QtWidgets.QAbstractItemView.SelectionMode.ExtendedSelection
        )
        table.setSortingEnabled(True)
        self.table_view = table
        container = QtWidgets.QWidget(parent)
        layout = QtWidgets.QVBoxLayout(container)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.addWidget(table, 1)
        return container

    def _configure_table_view(self) -> None:
        table = self.table_view
        if not isinstance(table, QtWidgets.QTableView):
            return
        table.setSizePolicy(
            QtWidgets.QSizePolicy.Policy.Expanding,
            QtWidgets.QSizePolicy.Policy.Expanding,
        )
        try:
            table.setIconSize(
                QtCore.QSize(ANNEALING_GRAPH_WIDTH, ANNEALING_GRAPH_HEIGHT)
            )
        except Exception:
            pass
        header = table.horizontalHeader()
        if header is not None:
            header.setStretchLastSection(True)
        table.setVerticalScrollMode(
            QtWidgets.QAbstractItemView.ScrollMode.ScrollPerPixel
        )
        table.setHorizontalScrollMode(
            QtWidgets.QAbstractItemView.ScrollMode.ScrollPerPixel
        )
        vertical_bar = table.verticalScrollBar()
        if vertical_bar is not None:
            vertical_bar.setSingleStep(self._SCROLL_SINGLE_STEP)

    def _close_active_editor(self) -> None:
        table = self.table_view
        if not isinstance(table, QtWidgets.QTableView):
            return
        editor = table.focusWidget()
        if editor is None or editor is table:
            return
        try:
            table.closeEditor(
                editor,
                QtWidgets.QAbstractItemDelegate.EndEditHint.NoHint,
            )
        except Exception:
            pass

    def _auto_fit_columns(self) -> None:
        if self._project_load_batch_mode:
            return
        table = self.table_view
        if not isinstance(table, QtWidgets.QTableView):
            return
        model = getattr(table, "model", lambda: None)()
        source_model = None
        if hasattr(model, "sourceModel"):
            try:
                source_model = model.sourceModel()
            except Exception:
                source_model = None
        decoration_model = source_model if isinstance(source_model, DataFrameModel) else model
        if isinstance(decoration_model, DataFrameModel):
            decoration_model.suppress_decorations(True)
        try:
            table.resizeColumnsToContents()
        except Exception:
            return
        finally:
            if isinstance(decoration_model, DataFrameModel):
                decoration_model.suppress_decorations(False)
        frame: Optional[pd.DataFrame] = None
        if hasattr(model, "frame"):
            try:
                frame = model.frame()
            except Exception:
                frame = None
        if frame is None and source_model is not None and hasattr(source_model, "frame"):
            try:
                frame = source_model.frame()
            except Exception:
                frame = None
        if frame is None or getattr(frame, "empty", False):
            return
        try:
            icon_width = table.iconSize().width()
        except Exception:
            icon_width = 0
        if icon_width <= 0:
            icon_width = ANNEALING_GRAPH_WIDTH
        graph_width = max(int(icon_width), ANNEALING_GRAPH_WIDTH) + 80
        for idx, column_name in enumerate(frame.columns):
            label = str(column_name)
            label_lower = label.lower()
            if (
                "graph" not in label_lower
                and "figure" not in label_lower
                and label not in MICROSCOPE_IMAGE_COLUMNS
            ):
                continue
            current = table.columnWidth(idx)
            target = graph_width if graph_width > current else current
            if target > 0:
                table.setColumnWidth(idx, target)

        numeric_width_hints = {
            VIDEO_END_LENGTH_COLUMN,
            VIDEO_MW_LENGTH_COLUMN,
            "Length (m)",
            "Piece date",
            "Resistance (Ω)",
            CORE_TEMPERATURE_COLUMN,
            GLASS_TEMPERATURE_COLUMN,
            "Mass (g)",
            "Winding speed (m/min)",
            "Glass feeding (mm/min)",
            "Underpressure",
            "Production datetime",
        }
        try:
            metrics = table.fontMetrics()
        except Exception:
            metrics = None
        for idx, column_name in enumerate(frame.columns):
            label = str(column_name)
            if label not in numeric_width_hints:
                continue
            if metrics is None:
                continue
            header_target = max(90, metrics.horizontalAdvance(label) + 28)
            current = table.columnWidth(idx)
            desired = max(header_target, min(current, 200))
            table.setColumnWidth(idx, desired)

        header = table.horizontalHeader()
        v_header = table.verticalHeader()
        total_width = 0
        try:
            total_width = header.length()
        except Exception:
            total_width = 0
        if v_header is not None:
            total_width += v_header.width()
        total_width += table.frameWidth() * 2
        screen_rect = None
        try:
            window = self.window()
            if isinstance(window, QtWidgets.QWidget):
                screen = QtGui.QGuiApplication.screenAt(
                    window.mapToGlobal(window.rect().center())
                )
                if screen is None:
                    screen = QtGui.QGuiApplication.primaryScreen()
                if screen is not None:
                    screen_rect = screen.availableGeometry()
        except Exception:
            screen_rect = None
        try:
            table.setSizePolicy(
                QtWidgets.QSizePolicy.Policy.Expanding,
                QtWidgets.QSizePolicy.Policy.Expanding,
            )
        except Exception:
            pass
        if screen_rect is not None:
            max_width = max(640, screen_rect.width() - 200)
        else:
            max_width = 1600
        desired = total_width if total_width > 0 else table.sizeHint().width()
        constrained = max(240, min(desired, max_width))
        table.setMinimumWidth(0)
        table.setMaximumWidth(16777215)
        splitter = self._table_splitter
        if isinstance(splitter, QtWidgets.QSplitter):
            available = screen_rect.width() if screen_rect is not None else constrained * 2
            left = max(320, int(available * 0.7))
            right = max(240, available - left)
            splitter.setSizes([left, right])

    def _update_source_button(self) -> None:
        has_sources = self.sources_list.count() > 0
        text = "Remove folder…" if has_sources else "Connect folder…"
        self.source_button.setText(text)
        if has_sources:
            self.source_button.setToolTip("Disconnect the currently linked folder.")
        else:
            self.source_button.setToolTip("Select a folder to analyse.")

    def has_project_data(self) -> bool:
        frame = self.data.table if isinstance(self.data.table, pd.DataFrame) else pd.DataFrame()
        return bool(self.data.sources) or bool(self.data.processed) or bool(self.data.extra) or not frame.empty

    def apply_data(self, data: MiniDatabaseData) -> None:
        self.data = data
        self.data.table = _with_source_label_column(self.data.table)
        try:
            self.store.save(self.data)
        except Exception:
            pass
        self._invalidate_pending_cache()
        self._close_active_editor()
        self.model.set_frame(self.data.table)
        self._populate_sources_list()
        self._refresh_source_filter_options()
        self._auto_fit_columns()
        self._update_status()
        self._reset_progress_ui()
        self._update_open_sources_enabled()
        try:
            self.sources_changed.emit(list(self.data.sources))
        except Exception:
            pass
        try:
            self.status_changed.emit(self.status_label.text())
        except Exception:
            pass

    def _populate_sources_list(self) -> None:
        self.sources_list.clear()
        for source in self.data.sources:
            self.sources_list.addItem(source)
        self._update_source_button()

    def _reset_progress_ui(self) -> None:
        self.progress_bar.setRange(0, 100)
        self.progress_bar.setValue(0)
        self.progress_label.setText("Idle")
        self.progress_eta_label.clear()
        self._progress_total = 0
        self._progress_current = 0
        self._progress_start = None
        self._cancel_requested = False
        self.stop_button.setEnabled(False)

    def _hide_columns(self, names: Sequence[str]) -> None:
        if not isinstance(self.table_view, QtWidgets.QTableView):
            return
        model = self.model
        frame: Optional[pd.DataFrame] = None
        if hasattr(model, "frame"):
            try:
                frame = model.frame()
            except Exception:
                frame = None
        if frame is None:
            return
        columns = list(frame.columns)
        normalized_targets = {str(name).strip().lower() for name in names}
        for index, column in enumerate(columns):
            normalized = str(column).strip().lower()
            try:
                self.table_view.setColumnHidden(index, normalized in normalized_targets)
            except Exception:
                continue

    def _hook_table_selection(self) -> None:
        if not isinstance(self.table_view, QtWidgets.QTableView):
            return
        selection_model = self.table_view.selectionModel()
        if selection_model is not None:
            selection_model.selectionChanged.connect(
                lambda *_: self._update_open_sources_enabled()
            )
        model = self.table_view.model()
        if isinstance(model, QtCore.QAbstractItemModel):
            model.modelReset.connect(self._update_open_sources_enabled)
            model.dataChanged.connect(lambda *_: self._update_open_sources_enabled())

    def _selected_rows(self) -> List[int]:
        if not isinstance(self.table_view, QtWidgets.QTableView):
            return []
        selection = self.table_view.selectionModel()
        if selection is None:
            return []
        rows: Set[int] = set()
        for index in selection.selectedRows():
            if not index.isValid():
                continue
            source_row = self._search_proxy.map_row_to_source(index.row())
            if source_row is not None:
                rows.add(source_row)
        return sorted(rows)

    def _row_series(self, row: int) -> Optional[pd.Series]:
        frame = self.model.frame()
        if row < 0 or row >= len(frame.index):
            return None
        try:
            return frame.iloc[row]
        except Exception:
            return None

    @staticmethod
    def _path_key(path: Path) -> str:
        try:
            return str(path.resolve())
        except Exception:
            return str(path)

    def _row_sources(self, row: pd.Series) -> List[Path]:
        _ = row
        return []

    def _row_visible(self, row: pd.Series) -> bool:
        _ = row
        return True

    def _row_source_filter_accepts(self, row: pd.Series) -> bool:
        combo = getattr(self, "source_filter_combo", None)
        if not isinstance(combo, QtWidgets.QComboBox):
            return True
        selected = str(combo.currentText() or "").strip()
        if not selected or selected == SOURCE_LABEL_ALL:
            return True
        return selected in _source_labels_from_row(row)

    def _row_filter_accepts(self, row: pd.Series) -> bool:
        return self._row_visible(row) and self._row_source_filter_accepts(row)

    def _refresh_source_filter_options(self) -> None:
        combo = getattr(self, "source_filter_combo", None)
        if not isinstance(combo, QtWidgets.QComboBox):
            return
        current = str(combo.currentText() or SOURCE_LABEL_ALL)
        frame = self.model.frame()
        labels: List[str] = []
        if isinstance(frame, pd.DataFrame) and not frame.empty:
            for _, row in frame.iterrows():
                for label in _source_labels_from_row(row):
                    if label and label not in labels:
                        labels.append(label)
        labels = sorted(labels, key=str.casefold)
        combo.blockSignals(True)
        try:
            combo.clear()
            combo.addItem(SOURCE_LABEL_ALL)
            for label in labels:
                combo.addItem(label)
            target = current if current in labels else SOURCE_LABEL_ALL
            combo.setCurrentText(target)
            combo.setEnabled(bool(labels))
        finally:
            combo.blockSignals(False)
        try:
            self._search_proxy.invalidateFilter()
        except Exception:
            pass

    def _handle_source_filter_changed(self, _text: str) -> None:
        try:
            self._search_proxy.invalidateFilter()
        except Exception:
            pass
        self._update_open_sources_enabled()

    def _handle_search_changed(self, text: str) -> None:
        self._search_proxy.set_search_text(text)
        if isinstance(self.search_clear_button, QtWidgets.QPushButton):
            self.search_clear_button.setEnabled(bool(str(text).strip()))
        self._update_open_sources_enabled()

    def _clear_search(self) -> None:
        if isinstance(self.search_edit, QtWidgets.QLineEdit):
            self.search_edit.clear()

    def _update_open_sources_enabled(self) -> None:
        if not hasattr(self, "open_sources_button"):
            return
        rows = self._selected_rows()
        enabled = False
        if rows:
            for row_index in rows:
                series = self._row_series(row_index)
                if series is None:
                    continue
                if self._row_sources(series):
                    enabled = True
                    break
        self.open_sources_button.setEnabled(enabled)

    def _open_file(self, path: Path) -> bool:
        resolved = path.expanduser()
        if not resolved.exists():
            self.log(
                f"{self.section_title}: source file missing — {resolved}",
                level=logging.WARNING,
            )
            return False
        url = QtCore.QUrl.fromLocalFile(str(resolved))
        opened = QtGui.QDesktopServices.openUrl(url)
        if not opened:
            opened = self._fallback_open_file(resolved)
        if not opened:
            self.log(
                f"{self.section_title}: could not open {resolved}",
                level=logging.WARNING,
            )
        return opened

    def _fallback_open_file(self, path: Path) -> bool:
        try:
            if sys.platform == "darwin":
                completed = subprocess.run(
                    ["open", str(path)],
                    check=False,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                )
                return completed.returncode == 0
            if sys.platform.startswith("win"):
                os.startfile(str(path))  # type: ignore[attr-defined]
                return True
            completed = subprocess.run(
                ["xdg-open", str(path)],
                check=False,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            return completed.returncode == 0
        except (FileNotFoundError, OSError):
            return False

    def _open_selected_sources(self) -> None:
        rows = self._selected_rows()
        if not rows:
            QtWidgets.QMessageBox.information(
                self,
                self.section_title,
                "Select one or more rows to open their source files.",
            )
            return
        opened_any = False
        missing: List[Path] = []
        seen: set[Path] = set()
        for row_index in rows:
            series = self._row_series(row_index)
            if series is None:
                continue
            for path in self._row_sources(series):
                if path in seen:
                    continue
                seen.add(path)
                if self._open_file(path):
                    opened_any = True
                else:
                    missing.append(path)
        if not opened_any and missing:
            details = "\n".join(str(p) for p in missing[:5])
            if len(missing) > 5:
                details += "\n…"
            QtWidgets.QMessageBox.warning(
                self,
                self.section_title,
                f"None of the selected rows have available source files.\n\n{details}",
            )
    def _start_progress(self, total: int) -> None:
        self._progress_total = max(int(total), 0)
        self._progress_current = 0
        self._progress_start = time.monotonic()
        if self._progress_dialog is not None:
            try:
                self._progress_dialog.close()
            except Exception:
                pass
        if self._progress_total <= 0:
            dialog = QtWidgets.QProgressDialog("Scanning files...", None, 0, 0, self)
            dialog.setWindowTitle(self.section_title)
            dialog.setWindowModality(QtCore.Qt.WindowModality.NonModal)
            dialog.setCancelButton(None)
            dialog.setMinimumDuration(0)
            dialog.setAutoClose(False)
            dialog.setAutoReset(False)
            dialog.setMinimumWidth(320)
            dialog.setLabelText("Scanning files...")
            dialog.show()
            self._progress_dialog = dialog
            return
        dialog = QtWidgets.QProgressDialog(
            f"Processing 0/{self._progress_total}",
            None,
            0,
            100,
            self,
        )
        dialog.setWindowTitle(self.section_title)
        dialog.setWindowModality(QtCore.Qt.WindowModality.NonModal)
        dialog.setCancelButton(None)
        dialog.setMinimumDuration(0)
        dialog.setAutoClose(False)
        dialog.setAutoReset(False)
        dialog.setMinimumWidth(320)
        dialog.setLabelText(f"Processing 0/{self._progress_total}")
        dialog.setValue(0)
        dialog.show()
        self._progress_dialog = dialog

    def _update_progress(self, current: int, total: Optional[int], message: Optional[str]) -> None:
        if total is not None:
            self._progress_total = max(int(total), 0)
        self._progress_current = max(int(current), 0)
        total_units = self._progress_total
        dialog = self._progress_dialog
        if total_units <= 0:
            if dialog is not None:
                dialog.setRange(0, 0)
        else:
            percent = int(round(min(self._progress_current / total_units, 1.0) * 100)) if total_units else 0
            if dialog is not None:
                dialog.setRange(0, 100)
                dialog.setValue(max(0, min(100, percent)))
        parts: list[str] = []
        if message:
            parts.append(message)
        if total_units > 0:
            parts.append(f"{self._progress_current}/{total_units}")
        else:
            parts.append(f"{self._progress_current} processed")
        label_text = " - ".join(parts)
        start = self._progress_start
        eta_text = ""
        if (
            start is not None
            and self._progress_current > 0
            and total_units > 0
            and self._progress_current < total_units
        ):
            elapsed = time.monotonic() - start
            rate = elapsed / self._progress_current if self._progress_current else None
            if rate and math.isfinite(rate):
                eta = rate * (total_units - self._progress_current)
                eta_text = f"ETA {_format_duration(eta)}"
        elif start is not None and self._progress_current and (
            total_units == 0 or self._progress_current >= total_units
        ):
            elapsed = time.monotonic() - start
            eta_text = f"Elapsed {_format_duration(elapsed)}"
        if dialog is not None:
            dialog.setLabelText("\n".join(part for part in (label_text, eta_text) if part))
        QtWidgets.QApplication.processEvents(
            QtCore.QEventLoop.ProcessEventsFlag.AllEvents
        )

    def _request_cancel(self) -> None:
        if self._cancel_requested:
            return
        self._cancel_requested = True
        self.stop_button.setEnabled(False)
        candidate_thread = self._candidate_thread
        if candidate_thread is not None:
            try:
                candidate_thread.requestInterruption()
            except Exception:
                pass
            try:
                candidate_thread.quit()
            except Exception:
                pass
        if self._progress_dialog is not None:
            self._progress_dialog.setRange(0, 0)
            self._progress_dialog.setLabelText("Cancelling...")
        QtWidgets.QApplication.processEvents(
            QtCore.QEventLoop.ProcessEventsFlag.AllEvents
        )

    def is_cancelled(self) -> bool:
        return self._cancel_requested

    def _check_cancelled(self) -> None:
        if self._cancel_requested:
            raise BuildCancelledError()

    def _finish_progress(self) -> None:
        if self._progress_dialog is not None:
            try:
                self._progress_dialog.setRange(0, 100)
                self._progress_dialog.setValue(100)
                text = (
                    f"Complete - {self._progress_total} file(s)"
                    if self._progress_total > 0
                    else "Complete"
                )
                start = self._progress_start
                if start is not None:
                    elapsed = time.monotonic() - start
                    text = f"{text}\nElapsed {_format_duration(elapsed)}"
                self._progress_dialog.setLabelText(text)
                self._progress_dialog.close()
            except Exception:
                pass
        self._progress_dialog = None
        self._progress_start = None
        self._cancel_requested = False
        self.stop_button.setEnabled(False)
        self._release_processing()

    def _fail_progress(self) -> None:
        if self._progress_dialog is not None:
            try:
                self._progress_dialog.setRange(0, 100)
                self._progress_dialog.setValue(0)
                self._progress_dialog.setLabelText("Failed")
                self._progress_dialog.close()
            except Exception:
                pass
        self._progress_dialog = None
        self._progress_start = None
        self._cancel_requested = False
        self.stop_button.setEnabled(False)
        self._release_processing()

    def _cancel_progress(self) -> None:
        if self._progress_dialog is not None:
            try:
                self._progress_dialog.setRange(0, 100)
                self._progress_dialog.setValue(0)
                self._progress_dialog.setLabelText("Cancelled")
                self._progress_dialog.close()
            except Exception:
                pass
        self._progress_dialog = None
        self._progress_start = None
        self._cancel_requested = False
        self.stop_button.setEnabled(False)
        self._release_processing()

    def _release_processing(self) -> None:
        if MiniDatabaseSection._processing_owner is self:
            MiniDatabaseSection._processing_owner = None
            if MiniDatabaseSection._refresh_queue:
                next_section = MiniDatabaseSection._refresh_queue.pop(0)
                if isinstance(next_section, MiniDatabaseSection):
                    QtCore.QTimer.singleShot(0, next_section.refresh)

    def _progress_callback(
        self, current: int, total: int, message: Optional[str] = None
    ) -> None:
        if self._progress_start is None:
            self._start_progress(total)
        self._update_progress(current, total, message)

    def _sync_sources(self) -> None:
        sources: list[str] = []
        for index in range(self.sources_list.count()):
            item = self.sources_list.item(index)
            if item is not None:
                sources.append(item.text())
        self.data.sources = sources
        self.store.save(self.data)
        self._invalidate_pending_cache()
        try:
            self.sources_changed.emit(list(sources))
        except Exception:
            pass
        self._update_status()
        self._update_source_button()

    def set_sources(self, sources: Iterable[str]) -> None:
        unique = []
        seen: Set[str] = set()
        for source in sources:
            normalised = str(Path(source).expanduser())
            if normalised not in seen:
                seen.add(normalised)
                unique.append(normalised)
        self.sources_list.clear()
        for path in unique:
            self.sources_list.addItem(path)
        self._sync_sources()

    def _toggle_source(self) -> None:
        if self.sources_list.count() == 0:
            self._add_source()
        else:
            self._prompt_remove_source()

    def _add_source(self) -> None:
        start_dir = _dialog_start_directory()
        directory = QtWidgets.QFileDialog.getExistingDirectory(
            self,
            self.section_title,
            str(start_dir),
        )
        if not directory:
            return
        normalised = str(Path(directory).expanduser())
        existing = {self.sources_list.item(idx).text() for idx in range(self.sources_list.count())}
        if normalised not in existing:
            self.sources_list.addItem(normalised)
            self._sync_sources()

    def _prompt_remove_source(self) -> None:
        sources = [self.sources_list.item(idx).text() for idx in range(self.sources_list.count())]
        if not sources:
            return
        target = sources[0]
        if len(sources) > 1:
            selection, ok = QtWidgets.QInputDialog.getItem(
                self,
                self.section_title,
                "Select a folder to disconnect:",
                sources,
                0,
                False,
            )
            if not ok or not selection:
                return
            target = selection
        message = QtWidgets.QMessageBox(self)
        message.setWindowTitle(self.section_title)
        message.setIcon(QtWidgets.QMessageBox.Icon.Warning)
        message.setText("Remove the connected folder?")
        message.setInformativeText(target)
        remove_btn = message.addButton("Remove folder", QtWidgets.QMessageBox.ButtonRole.AcceptRole)
        message.addButton(QtWidgets.QMessageBox.StandardButton.Cancel)
        message.exec()
        if message.clickedButton() is not remove_btn:
            return
        for idx in range(self.sources_list.count() - 1, -1, -1):
            item = self.sources_list.item(idx)
            if item is not None and item.text() == target:
                self.sources_list.takeItem(idx)
        self._sync_sources()

    # ------------------------------------------------------------------ data handling
    def _collect_candidates(self) -> List[Path]:
        candidates: Dict[str, Path] = {}
        for source in self.data.sources:
            root = Path(source).expanduser()
            if not root.exists():
                continue
            iterator: Iterable[Path]
            try:
                iterator = root.rglob("*") if self.recursive_search else root.glob("*")
            except Exception:
                continue
            for path in iterator:
                if not path.is_file():
                    continue
                if self.supported_suffixes and path.suffix.lower() not in self.supported_suffixes:
                    continue
                try:
                    resolved = str(path.resolve())
                except Exception:
                    resolved = str(path)
                candidates.setdefault(resolved, path)
        return sorted(candidates.values())

    def _pending_paths(self) -> List[Path]:
        pending: List[Path] = []
        processed = self.data.processed
        for path in self._collect_candidates():
            key = str(path)
            try:
                mtime = path.stat().st_mtime
            except OSError:
                continue
            if float(processed.get(key, -1.0)) != float(mtime):
                pending.append(path)
        return pending

    def _invalidate_pending_cache(self) -> None:
        self._stop_pending_scan(wait_ms=200)
        self._pending_count_cache = None
        self._pending_scan_in_progress = False
        self._pending_scan_generation += 1

    def _stop_pending_scan(self, *, wait_ms: int = 500) -> None:
        thread = self._pending_scan_thread
        self._pending_scan_thread = None
        self._pending_scan_worker = None
        self._pending_scan_in_progress = False
        if thread is None:
            return
        try:
            thread.requestInterruption()
        except Exception:
            pass
        try:
            thread.quit()
        except Exception:
            pass
        try:
            if thread.isRunning():
                thread.wait(max(0, int(wait_ms)))
        except Exception:
            pass
        try:
            if thread.isRunning():
                thread.terminate()
                thread.wait(200)
        except Exception:
            pass

    def _request_pending_scan(self) -> None:
        if self._pending_scan_in_progress:
            return
        if not self.data.sources:
            self._pending_count_cache = 0
            return
        self._stop_pending_scan(wait_ms=100)
        self._pending_scan_generation += 1
        generation = self._pending_scan_generation
        worker = _PendingScanWorker(
            list(self.data.sources),
            dict(self.data.processed),
            tuple(self.supported_suffixes),
            bool(self.recursive_search),
        )
        thread = QtCore.QThread(self)
        worker.moveToThread(thread)
        thread.started.connect(worker.run)
        worker.finished.connect(partial(self._handle_pending_scan_finished, generation, thread, worker))
        worker.failed.connect(partial(self._handle_pending_scan_failed, generation, thread, worker))
        worker.finished.connect(thread.quit)
        worker.failed.connect(thread.quit)
        thread.finished.connect(worker.deleteLater)
        thread.finished.connect(thread.deleteLater)
        self._pending_scan_thread = thread
        self._pending_scan_worker = worker
        self._pending_scan_in_progress = True
        thread.start()

    def _handle_pending_scan_finished(
        self,
        generation: int,
        thread: QtCore.QThread,
        worker: _PendingScanWorker,
        count: int,
    ) -> None:
        if generation != self._pending_scan_generation:
            return
        self._pending_scan_in_progress = False
        self._pending_count_cache = int(count)
        self._pending_scan_thread = None
        self._pending_scan_worker = None
        self._update_status()

    def _handle_pending_scan_failed(
        self,
        generation: int,
        thread: QtCore.QThread,
        worker: _PendingScanWorker,
        exc: object,
    ) -> None:
        if generation != self._pending_scan_generation:
            return
        self._pending_scan_in_progress = False
        self._pending_scan_thread = None
        self._pending_scan_worker = None
        self.logger.debug("%s pending scan failed", self.section_key, exc_info=exc)
        self._update_status()

    def _update_status(self) -> None:
        sources_count = len(self.data.sources)
        pending_count = self._pending_count_cache
        if sources_count == 0:
            message = "Connect one or more folders to begin."
            self.refresh_button.setEnabled(False)
            self._pending_count_cache = 0
        elif self._project_load_batch_mode:
            self.refresh_button.setEnabled(True)
            if not self.data.table.empty:
                message = f"Up to date ({len(self.data.table)} record(s))."
            else:
                message = "No processed data available yet."
        else:
            self.refresh_button.setEnabled(True)
            if pending_count is None:
                if getattr(self, "_suppress_pending_scan_once", False):
                    self._suppress_pending_scan_once = False
                    message = "Connected folder(s); press Refresh to scan for new files."
                else:
                    message = "Scanning for new or updated files..."
                if not self._pending_scan_in_progress and message.startswith("Scanning"):
                    self._request_pending_scan()
            elif pending_count:
                message = f"⚠️ {pending_count} new or updated file(s) pending processing."
            elif not self.data.table.empty:
                message = f"Up to date ({len(self.data.table)} record(s))."
            else:
                message = "No processed data available yet."
        self.status_label.setText(message)
        try:
            self.status_changed.emit(message)
        except Exception:
            pass

    def _dispatch_log(self, level: int, message: str) -> None:
        try:
            self._log_callback(level, message)
        except Exception:
            self.logger.log(level, message)

    def log(self, message: str, level: int = logging.INFO) -> None:
        text = str(message)
        try:
            self.log_emitted.emit(int(level), text)
        except Exception:
            self._dispatch_log(level, text)

    def reset_to_blank(self) -> None:
        """Clear all processed data and disconnect sources for a fresh start."""

        payload_names: Set[str] = set()
        extra = getattr(self.data, "extra", None)
        if isinstance(extra, Mapping):
            payloads = extra.get("payloads")
            if isinstance(payloads, Mapping):
                for value in payloads.values():
                    if isinstance(value, str) and value.strip():
                        payload_names.add(value.strip())
        for payload_name in payload_names:
            try:
                self.store.clear_payload(payload_name)
            except Exception:
                continue
        self.data = MiniDatabaseData()
        self.model.set_frame(pd.DataFrame())
        self.sources_list.clear()
        self._refresh_source_filter_options()
        self._sync_sources()
        self.store.clear_table()
        self.store.save(self.data)
        self._auto_fit_columns()
        self._update_status()
        self._reset_progress_ui()
        self._update_open_sources_enabled()
        try:
            self.data_updated.emit()
        except Exception:
            pass
        try:
            if hasattr(self, "_sanitize_graph_columns"):
                self._sanitize_graph_columns()
        except Exception:
            pass

    def export_project_payload(self) -> Dict[str, Any]:
        frame = self.data.table if isinstance(self.data.table, pd.DataFrame) else pd.DataFrame()
        frame = _with_source_label_column(frame)
        columns = [str(col) for col in getattr(frame, "columns", [])]
        rows: List[Dict[str, Any]] = []
        if isinstance(frame, pd.DataFrame) and not frame.empty:
            for record in frame.to_dict(orient="records"):
                payload: Dict[str, Any] = {}
                for column in columns:
                    payload[column] = _json_safe(record.get(column))
                rows.append(payload)
        index_payload: List[Any] = []
        if isinstance(frame, pd.DataFrame) and not frame.empty:
            for entry in frame.index.tolist():
                index_payload.append(_json_safe(entry))
        extra_payload = _json_safe(self.data.extra)
        if not isinstance(extra_payload, (dict, list, tuple, str, int, float, bool)) and extra_payload is not None:
            extra_payload = str(extra_payload)
        project_payloads: Dict[str, Dict[str, str]] = {}
        payload_refs = {}
        if isinstance(self.data.extra, Mapping):
            payloads_extra = self.data.extra.get("payloads")
            if isinstance(payloads_extra, Mapping):
                payload_refs = {
                    str(key): str(value)
                    for key, value in payloads_extra.items()
                    if isinstance(key, str) and isinstance(value, str) and value.strip()
                }
        for name in sorted(set(payload_refs.values())):
            try:
                stored_payload = self.store.load_payload(name)
            except Exception:
                stored_payload = None
            if stored_payload is None:
                continue
            encoded_payload = _encode_project_payload(stored_payload)
            if encoded_payload is not None:
                project_payloads[name] = encoded_payload
        return {
            "section": self.section_key,
            "title": self.section_title,
            "columns": columns,
            "rows": rows,
            "index": index_payload,
            "extra": extra_payload,
            "sources": list(self.data.sources),
            "processed": dict(self.data.processed),
            "payloads": project_payloads,
        }

    def import_project_payload(self, payload: Mapping[str, Any]) -> None:
        """Restore section state from a project payload."""

        started_s = time.perf_counter()
        if not isinstance(payload, Mapping):
            self.reset_to_blank()
            _log_builder_timing(
                self.logger,
                "section_import",
                started_s,
                section=self.section_key,
                rows=0,
                payloads=0,
                reset=True,
            )
            return

        decoded_payload_count = 0
        columns_payload = payload.get("columns")
        if isinstance(columns_payload, (list, tuple)):
            column_names = [str(column) for column in columns_payload]
        else:
            column_names = []
        rows_payload = payload.get("rows")
        if isinstance(rows_payload, (list, tuple)):
            frame = pd.DataFrame(list(rows_payload), columns=column_names or None)
        else:
            frame = pd.DataFrame(columns=column_names)

        index_payload = payload.get("index")
        if isinstance(index_payload, list) and len(index_payload) == len(frame.index):
            try:
                frame.index = pd.Index(index_payload)
            except Exception:
                pass

        extra_payload = payload.get("extra")
        extra: Dict[str, Any]
        if isinstance(extra_payload, Mapping):
            extra = dict(extra_payload)
        else:
            extra = {}

        sources_payload = payload.get("sources")
        sources = (
            [str(source) for source in sources_payload]
            if isinstance(sources_payload, (list, tuple))
            else []
        )

        processed_payload = payload.get("processed")
        processed: Dict[str, float] = {}
        if isinstance(processed_payload, Mapping):
            for key, value in processed_payload.items():
                try:
                    processed[str(key)] = float(value)
                except (TypeError, ValueError):
                    continue

        frame = _with_source_label_column(frame)
        self.data = MiniDatabaseData(sources=sources, processed=processed, table=frame, extra=extra)
        self.model.set_frame(frame)
        self._refresh_source_filter_options()
        self._pending_count_cache = 0
        save_started_s = time.perf_counter()
        self.store.save(self.data)
        _log_builder_timing(
            self.logger,
            "section_import_store_save",
            save_started_s,
            section=self.section_key,
            rows=len(frame.index) if isinstance(frame, pd.DataFrame) else 0,
        )
        project_payloads = payload.get("payloads")
        if isinstance(project_payloads, Mapping):
            for name, encoded in project_payloads.items():
                if not isinstance(name, str) or not name.strip():
                    continue
                payload_started_s = time.perf_counter()
                decoded = _decode_project_payload(encoded)
                if decoded is None:
                    continue
                try:
                    self.store.save_payload(name.strip(), decoded)
                    decoded_payload_count += 1
                    _log_builder_timing(
                        self.logger,
                        "section_import_payload",
                        payload_started_s,
                        section=self.section_key,
                        payload=name.strip(),
                    )
                except Exception:
                    self.logger.exception(
                        "Failed to restore project payload %s for section %s",
                        name,
                        self.section_key,
                    )
        self._populate_sources_list()
        if self._project_load_batch_mode:
            self._reset_progress_ui()
            _log_builder_timing(
                self.logger,
                "section_import",
                started_s,
                section=self.section_key,
                rows=len(frame.index) if isinstance(frame, pd.DataFrame) else 0,
                payloads=decoded_payload_count,
                batch=True,
            )
            return
        self._auto_fit_columns()
        self._update_status()
        self._update_open_sources_enabled()
        self._reset_progress_ui()
        try:
            self.sources_changed.emit(list(sources))
        except Exception:
            pass
        try:
            self.data_updated.emit()
        except Exception:
            pass
        _log_builder_timing(
            self.logger,
            "section_import",
            started_s,
            section=self.section_key,
            rows=len(frame.index) if isinstance(frame, pd.DataFrame) else 0,
            payloads=decoded_payload_count,
        )

    def _new_project(self) -> None:
        if self._dirty:
            box = QtWidgets.QMessageBox(self)
            box.setWindowTitle("Unsaved project")
            box.setText("Save changes to this Microwire Data Builder project before starting a new one?")
            save_btn = box.addButton(QtWidgets.QMessageBox.StandardButton.Save)
            discard_btn = box.addButton("Discard", QtWidgets.QMessageBox.ButtonRole.DestructiveRole)
            cancel_btn = box.addButton(QtWidgets.QMessageBox.StandardButton.Cancel)
            box.setDefaultButton(save_btn)
            box.exec()
            clicked = box.clickedButton()
            if clicked is cancel_btn:
                return
            if clicked is save_btn:
                self._save_project()
                if self._dirty:
                    return
        self._suppress_dirty = True
        for section in self.sections.values():
            if isinstance(section, MiniDatabaseSection):
                section.reset_to_blank()
        self._project_path = None
        self._dirty = False
        self._suppress_dirty = False
        self._update_project_title()
        self._update_project_actions()
        self._refresh_sections_after_project_load()

    # Compatibility alias used by menu wiring in some launch contexts
    def new_project(self) -> None:
        self._new_project()

    def has_project_data(self) -> bool:
        frame = self.data.table if isinstance(self.data.table, pd.DataFrame) else pd.DataFrame()
        if isinstance(frame, pd.DataFrame) and not frame.empty:
            return True
        return bool(self.data.extra)

    def refresh(self) -> None:
        self._cancel_requested = False
        self.stop_button.setEnabled(True)
        owner = MiniDatabaseSection._processing_owner
        if owner is not None and owner is not self:
            other_title = getattr(owner, "section_title", "Another section")
            if self not in MiniDatabaseSection._refresh_queue:
                MiniDatabaseSection._refresh_queue.append(self)
            status_message = f"Queued - waiting for {other_title}"
            self.status_label.setText(status_message)
            try:
                self.status_changed.emit(status_message)
            except Exception:
                pass
            self.log(
                f"{self.section_title}: queued refresh while {other_title} completes."
            )
            self._reset_progress_ui()
            self.stop_button.setEnabled(False)
            return
        self._start_progress(0)
        try:
            QtWidgets.QApplication.processEvents(
                QtCore.QEventLoop.ProcessEventsFlag.AllEvents
            )
        except Exception:
            pass
        MiniDatabaseSection._processing_owner = self
        status_message = "Scanning files..."
        self.status_label.setText(status_message)
        try:
            self.status_changed.emit(status_message)
        except Exception:
            pass
        self._start_candidate_worker()

    def _start_candidate_worker(self) -> None:
        if self._candidate_thread is not None and self._candidate_thread.isRunning():
            try:
                self._candidate_thread.quit()
                self._candidate_thread.wait(100)
            except Exception:
                pass
        self._cleanup_candidate_thread()
        thread = QtCore.QThread(self)
        worker = _CandidateCollectWorker(self)
        worker.moveToThread(thread)
        thread.started.connect(worker.run)
        worker.finished.connect(self._handle_candidate_scan_finished)
        worker.failed.connect(self._handle_candidate_scan_failed)
        worker.finished.connect(thread.quit)
        worker.failed.connect(thread.quit)
        thread.finished.connect(worker.deleteLater)
        thread.finished.connect(thread.deleteLater)
        self._candidate_thread = thread
        self._candidate_worker = worker
        thread.start()

    def _cleanup_candidate_thread(self) -> None:
        thread = self._candidate_thread
        self._candidate_thread = None
        self._candidate_worker = None
        if thread is None:
            return
        try:
            if thread.isRunning():
                thread.quit()
                thread.wait(100)
        except Exception:
            pass

    def _handle_candidate_scan_finished(self, payload: object) -> None:
        self._cleanup_candidate_thread()
        candidates = [Path(path) for path in payload] if isinstance(payload, list) else []
        if not candidates:
            self.log(f"{self.section_title}: no files found in connected folders.")
            self.data.processed = {}
            self.data.table = pd.DataFrame()
            self.store.save(self.data)
            self.model.set_frame(self.data.table)
            self._auto_fit_columns()
            self._update_status()
            self._reset_progress_ui()
            self._release_processing()
            try:
                self.data_updated.emit()
            except Exception:
                pass
            return
        status_message = f"Processing {len(candidates)} file(s)."
        self.status_label.setText(status_message)
        try:
            self.status_changed.emit(status_message)
        except Exception:
            pass
        self._start_progress(len(candidates))
        self._start_section_worker(candidates)

    def _handle_candidate_scan_failed(self, exc: object) -> None:
        self._cleanup_candidate_thread()
        self._active_candidates = []
        self._fail_progress()
        if isinstance(exc, Exception):
            self.logger.exception("%s candidate scan failed", self.section_title, exc_info=exc)
            detail = str(exc) if str(exc) else exc.__class__.__name__
        else:
            self.logger.error("%s candidate scan failed: %s", self.section_title, exc)
            detail = str(exc)
        QtWidgets.QMessageBox.critical(
            self,
            self.section_title,
            f"Failed to scan connected files:\\n{detail}",
        )

    def _start_section_worker(self, candidates: List[Path]) -> None:
        self._active_candidates = list(candidates)
        if self._worker_thread is not None and self._worker_thread.isRunning():
            try:
                self._worker_thread.quit()
                self._worker_thread.wait(100)
            except Exception:
                pass
        self._cleanup_worker_thread()
        thread = QtCore.QThread(self)
        worker = _SectionWorker(self, candidates)
        worker.moveToThread(thread)
        thread.started.connect(worker.run)
        worker.progress.connect(self._handle_worker_progress)
        worker.finished.connect(self._handle_worker_finished)
        worker.failed.connect(self._handle_worker_failed)
        worker.cancelled.connect(self._handle_worker_cancelled)
        worker.finished.connect(thread.quit)
        worker.failed.connect(thread.quit)
        worker.cancelled.connect(thread.quit)
        thread.finished.connect(self._cleanup_worker_thread)
        self._worker_thread = thread
        self._worker = worker
        thread.start()

    def _cleanup_worker_thread(self) -> None:
        if self._worker is not None:
            try:
                self._worker.deleteLater()
            except Exception:
                pass
            self._worker = None
        if self._worker_thread is not None:
            try:
                self._worker_thread.deleteLater()
            except Exception:
                pass
            self._worker_thread = None

    def _shutdown_background_threads(self) -> None:
        self._cancel_requested = True
        self._stop_pending_scan(wait_ms=800)
        thread = self._worker_thread
        if thread is not None:
            try:
                thread.quit()
            except Exception:
                pass
            try:
                if thread.isRunning():
                    thread.wait(800)
            except Exception:
                pass
            try:
                if thread.isRunning():
                    thread.terminate()
                    thread.wait(200)
            except Exception:
                pass
        self._cleanup_worker_thread()

    def closeEvent(self, event: QtGui.QCloseEvent) -> None:  # type: ignore[override]
        self._shutdown_background_threads()
        super().closeEvent(event)

    def _handle_worker_progress(self, current: int, total: int, message: object) -> None:
        text: Optional[str] = None
        if isinstance(message, str) and message:
            text = message
        self._progress_callback(int(current), int(total), text)

    def _handle_worker_finished(self, result: SectionProcessResult) -> None:
        self._finish_progress()
        existing_payloads = set(self.data.extra.get("payloads", {}).keys())
        new_payloads = set(result.payloads.keys())
        for name in existing_payloads - new_payloads:
            self.store.clear_payload(name)

        payload_map: Dict[str, str] = {}
        for name, payload in result.payloads.items():
            self.store.save_payload(name, payload)
            payload_map[name] = name
        if payload_map:
            self.data.extra["payloads"] = payload_map
        if result.extra:
            self.data.extra.update(result.extra)
        self.data.processed = result.processed
        self.data.table = _with_source_label_column(result.table)
        self.store.save(self.data)
        self._close_active_editor()
        self.model.set_frame(self.data.table)
        self._refresh_source_filter_options()
        self._auto_fit_columns()
        self._update_status()
        processed_count = len(self._active_candidates)
        self.log(
            f"{self.section_title}: processed {processed_count} file(s)."
        )
        self._active_candidates = []
        self._update_open_sources_enabled()
        try:
            self.sources_changed.emit(list(self.data.sources))
        except Exception:
            pass
        try:
            self.data_updated.emit()
        except Exception:
            pass

    def _handle_worker_failed(self, exc: object) -> None:
        self._active_candidates = []
        self._fail_progress()
        if isinstance(exc, Exception):
            self.logger.exception("%s processing failed", self.section_title, exc_info=exc)
            detail = str(exc) if str(exc) else exc.__class__.__name__
        else:
            self.logger.error("%s processing failed: %s", self.section_title, exc)
            detail = str(exc)
        QtWidgets.QMessageBox.critical(
            self,
            self.section_title,
            f"Failed to process data:\\n{detail}",
        )

    def _handle_worker_cancelled(self) -> None:
        self._active_candidates = []
        self.log(f"{self.section_title}: processing cancelled by user.")
        self._cancel_progress()

    # ------------------------------------------------------------------ hooks for subclasses
    def process(
        self,
        paths: List[Path],
        progress: Optional[Callable[[int, int, Optional[str]], None]] = None,
    ) -> SectionProcessResult:
        raise NotImplementedError

class FabricationSection(MiniDatabaseSection):
    section_key = "fabrication"
    section_title = "Fabrication data"
    supported_suffixes = (".xlsx", ".xls", ".xlsm")
    raw_index_payload_name = "fabrication_index_raw"

    def __init__(
        self,
        logger: logging.Logger,
        log_callback: Callable[[int, str], None],
        parent: QtWidgets.QWidget | None = None,
    ) -> None:
        self._table_splitter: QtWidgets.QSplitter | None = None
        self._separate_imported = False
        self._microscope_snapshot: pd.DataFrame | None = None
        self._source_status_cache: Dict[Tuple[str, ...], bool] = {}
        super().__init__(logger, log_callback, parent)
        self._normalize_temperature_columns()
        self._hide_columns(["_source_paths", "_source_path"])
        self.model.set_editable_columns(self._editable_columns())
        self.model.set_text_columns({GLASS_PULL_COLUMN, "Notes"})
        self.model.set_background_provider(self._background_brush_for_cell)
        self.model.set_foreground_provider(self._foreground_brush_for_cell)
        try:
            self.model.dataChanged.connect(self._handle_cell_edited)
        except Exception:
            pass
        self.missing_data_button = QtWidgets.QPushButton("Missing data…", self)
        self.missing_data_button.clicked.connect(self._show_missing_data_dialog)
        try:
            self.controls_layout.insertWidget(2, self.missing_data_button)
        except Exception:
            pass

    def _load_raw_index(self) -> Optional[FabricationIndex]:
        try:
            raw_index = self.store.load_payload(self.raw_index_payload_name)
        except Exception:
            raw_index = None
        if isinstance(raw_index, FabricationIndex):
            return raw_index
        try:
            visible_index = self.store.load_payload("fabrication_index")
        except Exception:
            visible_index = None
        if isinstance(visible_index, FabricationIndex):
            return visible_index
        return None

    def _store_indexes(
        self,
        visible_index: FabricationIndex,
        *,
        raw_index: Optional[FabricationIndex] = None,
    ) -> None:
        raw_payload = raw_index if isinstance(raw_index, FabricationIndex) else visible_index
        self.store.save_payload("fabrication_index", visible_index)
        self.store.save_payload(self.raw_index_payload_name, raw_payload)
        payload_map = dict(self.data.extra.get("payloads", {}))
        payload_map["fabrication_index"] = "fabrication_index"
        payload_map[self.raw_index_payload_name] = self.raw_index_payload_name
        self.data.extra["payloads"] = payload_map

    def _build_visible_table_from_index(
        self,
        raw_index: FabricationIndex,
        *,
        relevant_map: Optional[Dict[str, Dict[Optional[int], Set[Optional[int]]]]] = None,
        relevant_compositions: Optional[Set[str]] = None,
    ) -> Tuple[pd.DataFrame, FabricationIndex, int, int]:
        if relevant_map is None or relevant_compositions is None:
            relevant_map, relevant_compositions = self._load_relevant_map()
        filtered_index = raw_index
        removed_draws = 0
        removed_pieces = 0
        if relevant_compositions:
            original_draws = len(raw_index.draw_level)
            original_pieces = len(raw_index.piece_level)
            filtered_index = self._filter_index(raw_index, relevant_map, relevant_compositions)
            removed_draws = original_draws - len(filtered_index.draw_level)
            removed_pieces = original_pieces - len(filtered_index.piece_level)
        table = _fabrication_index_to_frame(filtered_index)
        table = self._augment_table_with_relevant_microscope_rows(
            table,
            relevant_map,
            source_index=raw_index,
        )
        table = self._apply_fabrication_source_labels(table)
        table = self._apply_imported_separation(table)
        return table, filtered_index, removed_draws, removed_pieces

    def _rebuild_table_from_raw_index(self) -> bool:
        raw_index = self._load_raw_index()
        if not isinstance(raw_index, FabricationIndex):
            return False
        table, filtered_index, _removed_draws, _removed_pieces = self._build_visible_table_from_index(
            raw_index
        )
        self.data.table = table
        self._store_indexes(filtered_index, raw_index=raw_index)
        self.store.save(self.data)
        self.model.set_frame(table)
        self._normalize_temperature_columns()
        self._hide_columns(["_source_paths", "_source_path"])
        self._auto_fit_columns()
        self._update_status()
        return True

    def _normalize_temperature_columns(self) -> None:
        frame = self.data.table if isinstance(self.data.table, pd.DataFrame) else None
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return
        updated = frame.copy()
        if "Temperature (°C)" in updated.columns:
            if CORE_TEMPERATURE_COLUMN not in updated.columns:
                updated = updated.rename(columns={"Temperature (°C)": CORE_TEMPERATURE_COLUMN})
            else:
                legacy = updated["Temperature (°C)"]
                target = updated[CORE_TEMPERATURE_COLUMN]
                updated[CORE_TEMPERATURE_COLUMN] = target.where(
                    ~(target.isna() | (target == "")),
                    legacy,
                )
                updated = updated.drop(columns=["Temperature (°C)"])
        if GLASS_TEMPERATURE_COLUMN not in updated.columns:
            updated[GLASS_TEMPERATURE_COLUMN] = None
        if ESTIMATED_TRANSITION_COLUMN not in updated.columns:
            if "e/a" in updated.columns:
                updated[ESTIMATED_TRANSITION_COLUMN] = updated["e/a"].map(
                    _estimate_transition_temp_c
                )
            else:
                updated[ESTIMATED_TRANSITION_COLUMN] = None
        elif "e/a" in updated.columns:
            series = updated[ESTIMATED_TRANSITION_COLUMN]
            computed = updated["e/a"].map(_estimate_transition_temp_c)
            mask = series.isna() | (series == "")
            updated[ESTIMATED_TRANSITION_COLUMN] = series.where(~mask, computed)
        if GLASS_PULL_COLUMN not in updated.columns:
            updated[GLASS_PULL_COLUMN] = None
        if updated is not frame:
            self.data.table = updated
            self.model.set_frame(updated)
            try:
                self.store.save(self.data)
            except Exception:
                pass

    def _collect_candidates(self) -> List[Path]:
        _, relevant_compositions = self._load_relevant_map()
        tokens = {
            self._normalise_token(comp)
            for comp in relevant_compositions
            if self._normalise_token(comp)
        }
        if not tokens:
            return super()._collect_candidates()

        candidates: Dict[str, Path] = {}

        def _should_consider(path: Path, root: Path) -> bool:
            try:
                relative = path.relative_to(root)
                text = self._normalise_token(str(relative))
            except Exception:
                text = self._normalise_token(path.name)
            if not text:
                return False
            return any(token in text for token in tokens)

        for source in self.data.sources:
            root = Path(source).expanduser()
            if not root.exists():
                continue
            try:
                resolved_root = root.resolve()
            except Exception:
                resolved_root = root
            if self.recursive_search:
                stack: List[Tuple[Path, bool]] = [(resolved_root, False)]
                while stack:
                    current, matched = stack.pop()
                    try:
                        entries = list(current.iterdir())
                    except Exception:
                        continue
                    for entry in entries:
                        if entry.is_dir():
                            next_matched = matched or _should_consider(entry, resolved_root)
                            if current is resolved_root or next_matched:
                                stack.append((entry, next_matched))
                            continue
                        if not entry.is_file():
                            continue
                        if self.supported_suffixes and entry.suffix.lower() not in self.supported_suffixes:
                            continue
                        if not (matched or _should_consider(entry, resolved_root)):
                            continue
                        try:
                            resolved = str(entry.resolve())
                        except Exception:
                            resolved = str(entry)
                        candidates.setdefault(resolved, entry)
            else:
                try:
                    entries = list(resolved_root.iterdir())
                except Exception:
                    entries = []
                for entry in entries:
                    if not entry.is_file():
                        continue
                    if self.supported_suffixes and entry.suffix.lower() not in self.supported_suffixes:
                        continue
                    if not _should_consider(entry, resolved_root):
                        continue
                    try:
                        resolved = str(entry.resolve())
                    except Exception:
                        resolved = str(entry)
                    candidates.setdefault(resolved, entry)
        if not candidates:
            return super()._collect_candidates()
        return sorted(candidates.values())

    def _update_status(self) -> None:  # type: ignore[override]
        super()._update_status()
        missing_entries = self._missing_data_entries()
        if not missing_entries:
            return
        base_message = self.status_label.text()
        preview = ", ".join(
            f"{entry['Composition']} {entry['Microwire']}"
            for entry in missing_entries[:3]
        )
        if len(missing_entries) > 3:
            preview += ", …"
        message = (
            f"{base_message} — Missing fabrication data for {len(missing_entries)} visible wire(s): {preview}"
        )
        self.status_label.setText(message)
        try:
            self.status_changed.emit(message)
        except Exception:
            pass

    @staticmethod
    def _normalise_int(value: object) -> Optional[int]:
        if value is None:
            return None
        if isinstance(value, (int,)):
            return int(value)
        try:
            numeric = float(value)
        except (TypeError, ValueError):
            return None
        if math.isnan(numeric):
            return None
        return int(numeric)

    def _measured_keys_by_source(
        self,
    ) -> Tuple[Set[Tuple[str, int, int]], Set[Tuple[str, int, int]]]:
        annealing_keys: Set[Tuple[str, int, int]] = set()
        microscope_keys: Set[Tuple[str, int, int]] = set()
        try:
            store = MiniDatabaseStore("annealing")
            records = store.load_payload("annealing_records")
        except Exception:
            records = None
        if isinstance(records, list):
            for record in records:
                metadata = getattr(record, "metadata", None)
                if metadata is None:
                    continue
                composition = getattr(metadata, "composition_token", None)
                draw_value = self._normalise_int(getattr(metadata, "draw_x", None))
                piece_value = self._normalise_int(getattr(metadata, "piece_y", None))
                composition_key = str(composition or "").strip()
                if not composition_key or draw_value is None or piece_value is None:
                    continue
                annealing_keys.add((composition_key, int(draw_value), int(piece_value)))
        microscope_table = (
            self._microscope_snapshot.copy()
            if isinstance(self._microscope_snapshot, pd.DataFrame)
            else pd.DataFrame()
        )
        if microscope_table.empty:
            microscope_data = None
            if not MiniDatabaseSection._skip_initial_store_load:
                try:
                    microscope_data = MiniDatabaseStore("microscope").load()
                except Exception:
                    microscope_data = None
            microscope_table = (
                microscope_data.table
                if microscope_data is not None and isinstance(microscope_data.table, pd.DataFrame)
                else pd.DataFrame()
            )
        if isinstance(microscope_table, pd.DataFrame) and not microscope_table.empty:
            for _, row in microscope_table.iterrows():
                composition_key = str(row.get("Composition") or "").strip()
                microwire_label = str(row.get("Microwire") or "").strip()
                if not composition_key or not microwire_label:
                    continue
                parsed = _microwire_parts_from_label_safe(microwire_label)
                if parsed is None:
                    continue
                draw_value, piece_value, suffix = parsed
                if str(suffix or "").strip().lower() == "oe":
                    continue
                microscope_keys.add((composition_key, int(draw_value), int(piece_value)))
        return annealing_keys, microscope_keys

    def _source_label_for_key(
        self,
        key: Tuple[str, int, int],
        annealing_keys: Set[Tuple[str, int, int]],
        microscope_keys: Set[Tuple[str, int, int]],
    ) -> str:
        in_annealing = key in annealing_keys
        in_microscope = key in microscope_keys
        if in_annealing and in_microscope:
            return "Measured"
        if in_microscope:
            return "Microscope only"
        if in_annealing:
            return "Measured"
        return "Fabrication only"

    @staticmethod
    def _row_source_paths(row: pd.Series) -> List[str]:
        raw_sources = row.get("_source_paths")
        if not isinstance(raw_sources, (list, tuple, set)):
            return []
        sources: List[str] = []
        for candidate in raw_sources:
            if not candidate:
                continue
            try:
                resolved = str(Path(candidate))
            except Exception:
                resolved = str(candidate)
            if resolved and resolved not in sources:
                sources.append(resolved)
        return sources

    def _resolve_fabrication_data_source(
        self,
        row: pd.Series,
        annealing_keys: Set[Tuple[str, int, int]],
        microscope_keys: Set[Tuple[str, int, int]],
    ) -> Optional[str]:
        composition = str(row.get("Composition") or "").strip()
        if not composition or composition == "Imported data:":
            return str(row.get("Data source") or "").strip() or None

        current_source = str(row.get("Data source") or "").strip()
        source_paths = self._row_source_paths(row)
        has_imported = "Imported" in current_source or any(
            "Imported" in source for source in source_paths
        )

        try:
            key = (
                composition,
                int(row.get("Draw")),
                int(row.get("Piece")),
            )
        except Exception:
            key = None

        label: Optional[str] = None
        if key is not None:
            label = self._source_label_for_key(key, annealing_keys, microscope_keys)
            if label == "Fabrication only" and not source_paths:
                label = None
        if label is None and current_source and "Imported" not in current_source:
            label = current_source
        if has_imported:
            return _data_source_with_import(label)
        return label

    def _apply_fabrication_source_labels(self, frame: pd.DataFrame) -> pd.DataFrame:
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return frame
        annealing_keys, microscope_keys = self._measured_keys_by_source()
        updated = frame.copy()
        if "Data source" not in updated.columns:
            updated["Data source"] = None
        data_source_idx = updated.columns.get_loc("Data source")
        for row_idx in range(len(updated.index)):
            row = updated.iloc[row_idx]
            label = self._resolve_fabrication_data_source(
                row,
                annealing_keys,
                microscope_keys,
            )
            updated.iat[row_idx, data_source_idx] = label
        return updated

    def _load_relevant_map(
        self,
    ) -> Tuple[Dict[str, Dict[Optional[int], Set[Optional[int]]]], Set[str]]:
        relevant: Dict[str, Dict[Optional[int], Set[Optional[int]]]] = {}
        annealing_keys, microscope_keys = self._measured_keys_by_source()
        for composition_key, draw_value, piece_value in sorted(annealing_keys | microscope_keys):
            bucket = relevant.setdefault(composition_key, {})
            piece_bucket = bucket.setdefault(int(draw_value), set())
            piece_bucket.add(int(piece_value))
        return relevant, set(relevant.keys())

    def _missing_data_entries(self, *, include_possible_mismatch: bool = False) -> List[Dict[str, str]]:
        frame = self.data.table if isinstance(self.data.table, pd.DataFrame) else pd.DataFrame()
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return []
        watched_columns = [
            "Length (m)",
            "Piece date",
            "Resistance (Ω)",
            CORE_TEMPERATURE_COLUMN,
            "Mass (g)",
            "Winding speed (m/min)",
            "Glass feeding (mm/min)",
            "Underpressure",
        ]
        entries: List[Dict[str, str]] = []
        for _, row in frame.iterrows():
            composition = str(row.get("Composition") or "").strip()
            if not composition or composition == "Imported data:":
                continue
            microwire = str(row.get("Microwire") or "").strip()
            if not microwire:
                try:
                    microwire = f"{int(row.get('Draw'))}/{int(row.get('Piece'))}"
                except Exception:
                    microwire = ""
            missing_fields = [
                column for column in watched_columns if column in frame.columns and _is_blank(row.get(column))
            ]
            if not missing_fields:
                continue
            source_missing = self._row_missing_source_files(row)
            possible_mismatch = ""
            if include_possible_mismatch and source_missing:
                possible_mismatch = ", ".join(_possible_source_mismatches(composition, self.data.sources))
            entries.append(
                {
                    "Composition": composition,
                    "Microwire": microwire,
                    "Data source": str(row.get("Data source") or "").strip(),
                    "Source files": "Missing" if source_missing else "Present",
                    "Possible mismatch": possible_mismatch,
                    "Missing fields": ", ".join(missing_fields),
                }
            )
        return entries

    def _show_missing_data_dialog(self) -> None:
        entries = self._missing_data_entries(include_possible_mismatch=True)
        dialog = QtWidgets.QDialog(self)
        dialog.setWindowTitle("Fabrication Missing Data")
        dialog.resize(980, 640)
        layout = QtWidgets.QVBoxLayout(dialog)
        summary = QtWidgets.QLabel(
            f"{len(entries)} visible wire(s) still have missing fabrication fields."
            if entries
            else "No visible wires are currently missing fabrication fields."
        )
        summary.setWordWrap(True)
        layout.addWidget(summary)
        table = QtWidgets.QTableWidget(dialog)
        table.setColumnCount(6)
        table.setHorizontalHeaderLabels(
            ["Composition", "Microwire", "Data source", "Source files", "Possible mismatch", "Missing fields"]
        )
        table.setRowCount(len(entries))
        table.setEditTriggers(QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        table.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectionBehavior.SelectRows)
        table.setSelectionMode(QtWidgets.QAbstractItemView.SelectionMode.SingleSelection)
        table.setSortingEnabled(False)
        for row_index, entry in enumerate(entries):
            for column_index, key in enumerate(
                ("Composition", "Microwire", "Data source", "Source files", "Possible mismatch", "Missing fields")
            ):
                item = QtWidgets.QTableWidgetItem(entry.get(key, ""))
                table.setItem(row_index, column_index, item)
        header = table.horizontalHeader()
        if header is not None:
            header.setStretchLastSection(True)
        table.resizeColumnsToContents()
        layout.addWidget(table, 1)
        button_box = QtWidgets.QDialogButtonBox(QtWidgets.QDialogButtonBox.StandardButton.Close, dialog)
        button_box.rejected.connect(dialog.reject)
        button_box.accepted.connect(dialog.accept)
        layout.addWidget(button_box)
        dialog.exec()

    def set_microscope_snapshot(self, frame: pd.DataFrame | None) -> None:
        self._microscope_snapshot = frame.copy() if isinstance(frame, pd.DataFrame) else None
        if self._rebuild_table_from_raw_index():
            return
        table = self.data.table if isinstance(self.data.table, pd.DataFrame) else pd.DataFrame()
        relevant_map, _ = self._load_relevant_map()
        if isinstance(table, pd.DataFrame):
            updated = self._augment_table_with_relevant_microscope_rows(table, relevant_map)
            updated = self._apply_fabrication_source_labels(updated)
            if not updated.equals(table):
                self.data.table = updated
                self.model.set_frame(updated)
                self._hide_columns(["_source_paths", "_source_path"])

    @staticmethod
    def _allow_draw(
        relevant_map: Dict[str, Dict[Optional[int], Set[Optional[int]]]],
        composition: str,
        draw: int,
    ) -> bool:
        draw_map = relevant_map.get(composition)
        if not draw_map:
            return True
        if draw in draw_map:
            return True
        if None in draw_map:
            return True
        return False

    @staticmethod
    def _allow_piece(
        relevant_map: Dict[str, Dict[Optional[int], Set[Optional[int]]]],
        composition: str,
        draw: int,
        piece: int,
    ) -> bool:
        if int(piece) <= 0:
            return False
        draw_map = relevant_map.get(composition)
        if not draw_map:
            return True
        direct = draw_map.get(draw)
        if direct is not None:
            return int(piece) in _relevant_sibling_piece_candidates([int(piece)], direct)
        allowed: Set[Optional[int]] = set()
        fallback = draw_map.get(None)
        if fallback:
            allowed.update(fallback)
        if not allowed:
            return False
        if None in allowed:
            return True
        return int(piece) in _relevant_sibling_piece_candidates([int(piece)], allowed)

    def _filter_index(
        self,
        index: FabricationIndex,
        relevant_map: Dict[str, Dict[Optional[int], Set[Optional[int]]]],
        relevant_compositions: Set[str],
    ) -> FabricationIndex:
        filtered = FabricationIndex()
        available_by_draw: Dict[Tuple[str, int], Dict[int, Mapping[str, object]]] = {}
        for (composition, draw, piece), piece_data in index.piece_level.items():
            comp_key = str(composition).strip()
            available_by_draw.setdefault((comp_key, int(draw)), {})[int(piece)] = dict(piece_data)
        for (composition, draw), draw_data in index.draw_level.items():
            comp_key = str(composition).strip()
            if comp_key not in relevant_compositions:
                continue
            if self._allow_draw(relevant_map, comp_key, int(draw)):
                filtered.set_draw(comp_key, int(draw), dict(draw_data))
        for (composition, draw, piece), piece_data in index.piece_level.items():
            comp_key = str(composition).strip()
            if comp_key not in relevant_compositions:
                continue
            draw_int = int(draw)
            piece_int = int(piece)
            if not self._allow_draw(relevant_map, comp_key, draw_int):
                continue
            draw_map = relevant_map.get(comp_key)
            if not draw_map:
                allowed_pieces = {
                    candidate
                    for candidate in available_by_draw.get((comp_key, draw_int), {})
                    if candidate > 0
                }
            else:
                relevant_pieces = draw_map.get(draw_int)
                if relevant_pieces is None:
                    relevant_pieces = draw_map.get(None)
                if relevant_pieces and None in relevant_pieces:
                    allowed_pieces = {
                        candidate
                        for candidate in available_by_draw.get((comp_key, draw_int), {})
                        if candidate > 0
                    }
                else:
                    piece_records = available_by_draw.get((comp_key, draw_int), {})
                    allowed_pieces = set(
                        _relevant_sibling_piece_candidates(
                            piece_records.keys(),
                            relevant_pieces,
                            piece_records,
                        )
                    )
            if piece_int not in allowed_pieces:
                continue
            filtered.set_piece(comp_key, draw_int, piece_int, dict(piece_data))
        return filtered

    def _augment_table_with_relevant_microscope_rows(
        self,
        frame: pd.DataFrame,
        relevant_map: Dict[str, Dict[Optional[int], Set[Optional[int]]]],
        *,
        source_index: Optional[FabricationIndex] = None,
    ) -> pd.DataFrame:
        if not isinstance(frame, pd.DataFrame):
            frame = pd.DataFrame()
        columns = list(frame.columns) if not frame.empty else list(_fabrication_frame_columns())
        updated = frame.copy() if not frame.empty else pd.DataFrame(columns=columns)
        annealing_keys, microscope_keys = self._measured_keys_by_source()
        existing: Set[Tuple[str, int, int]] = set()
        if not updated.empty:
            for _, row in updated.iterrows():
                comp = str(row.get("Composition") or "").strip()
                try:
                    draw = int(row.get("Draw"))
                    piece = int(row.get("Piece"))
                except Exception:
                    continue
                if comp:
                    existing.add((comp, draw, piece))

        new_rows: List[Dict[str, Any]] = []
        for composition, draws in relevant_map.items():
            comp_key = str(composition).strip()
            if not comp_key:
                continue
            for draw, pieces in draws.items():
                if draw is None:
                    continue
                candidate_pieces: List[int] = []
                if isinstance(source_index, FabricationIndex):
                    piece_records = {
                        int(piece_value): dict(piece_data)
                        for (piece_comp, piece_draw, piece_value), piece_data in source_index.piece_level.items()
                        if str(piece_comp).strip() == comp_key and int(piece_draw) == int(draw)
                    }
                    available_pieces = {
                        int(piece_value) for piece_value in piece_records.keys()
                    }
                    candidate_pieces = _relevant_sibling_piece_candidates(
                        available_pieces,
                        pieces,
                        piece_records,
                    )
                if not candidate_pieces:
                    candidate_pieces = _relevant_sibling_piece_candidates(
                        [],
                        pieces,
                    )
                for piece in candidate_pieces:
                    key = (comp_key, int(draw), int(piece))
                    if key in existing:
                        continue
                    piece_record = (
                        source_index.get_piece(comp_key, int(draw), piece)
                        if isinstance(source_index, FabricationIndex)
                        else None
                    )
                    draw_record = (
                        source_index.get_draw(comp_key, int(draw))
                        if isinstance(source_index, FabricationIndex)
                        else None
                    )
                    row = _fabrication_row_from_records(
                        comp_key,
                        int(draw),
                        piece,
                        piece_record,
                        draw_record,
                        columns=columns,
                    )
                    row["Data source"] = self._resolve_fabrication_data_source(
                        pd.Series(row),
                        annealing_keys,
                        microscope_keys,
                    )
                    new_rows.append(row)
        if not new_rows:
            return self._apply_fabrication_source_labels(updated)
        appended = pd.DataFrame(new_rows)
        for column in columns:
            if column not in appended.columns:
                appended[column] = None
        existing_rows: List[Dict[str, Any]] = []
        if not updated.empty:
            try:
                cleaned_updated = updated.dropna(how="all")
            except Exception:
                cleaned_updated = updated
            if not cleaned_updated.empty:
                existing_rows = [
                    dict(existing_row)
                    for existing_row in cleaned_updated.to_dict(orient="records")
                ]
        new_rows = [
            dict(row)
            for row in appended.loc[:, columns].to_dict(orient="records")
        ]
        combined = pd.DataFrame(existing_rows + new_rows, columns=columns)
        return self._apply_fabrication_source_labels(combined)

    @staticmethod
    def _normalise_token(text: str) -> str:
        return re.sub(r"[^a-z0-9]", "", str(text).lower())

    def _filter_candidates_for_relevance(
        self,
        candidates: List[Path],
        relevant_map: Dict[str, Dict[Optional[int], Set[Optional[int]]]],
        relevant_compositions: Set[str],
    ) -> Tuple[List[Path], int, bool]:
        if not relevant_compositions:
            return candidates, 0, False
        composition_tokens = {
            comp: self._normalise_token(comp)
            for comp in relevant_compositions
            if self._normalise_token(comp)
        }
        if not composition_tokens:
            return candidates, 0, False
        draw_tokens: Dict[str, Set[str]] = {}
        for comp, draw_map in relevant_map.items():
            comp_key = self._normalise_token(comp)
            if not comp_key:
                continue
            bucket = draw_tokens.setdefault(comp_key, set())
            for draw, pieces in draw_map.items():
                if draw is not None:
                    bucket.add(self._normalise_token(draw))
                for piece in pieces:
                    if piece is not None:
                        bucket.add(self._normalise_token(f"{draw}{piece}"))
        filtered: List[Path] = []
        skipped = 0
        for path in candidates:
            text = self._normalise_token(path)
            if not text:
                filtered.append(path)
                continue
            matched = False
            for _, token in composition_tokens.items():
                if token and token in text:
                    matched = True
                    break
                draw_set = draw_tokens.get(token)
                if draw_set and any(draw_token in text for draw_token in draw_set if draw_token):
                    matched = True
                    break
            if matched:
                filtered.append(path)
            else:
                skipped += 1
        if not filtered:
            return candidates, 0, True
        return filtered, skipped, False

    def process(
        self,
        paths: List[Path],
        progress: Optional[Callable[[int, int, Optional[str]], None]] = None,
    ) -> SectionProcessResult:
        unique_paths = list(dict.fromkeys(Path(p) for p in paths))

        relevant_map, relevant_compositions = self._load_relevant_map()
        filtered_paths, skipped, reverted = self._filter_candidates_for_relevance(
            unique_paths, relevant_map, relevant_compositions
        )
        if reverted:
            self.log(
                "Fabrication data: relevance filter could not match any files; falling back to full file list."
            )
        elif skipped:
            self.log(
                f"Fabrication data: skipped {skipped} file(s) without matching current annealing composition."
            )

        def _progress(idx: int, total: int) -> None:
            self._check_cancelled()
            if progress is None:
                return
            message: Optional[str] = None
            if 0 < idx <= len(filtered_paths):
                message = f"Parsing {filtered_paths[idx - 1].name}"
            try:
                progress(idx, total, message)
            except Exception:
                pass

        raw_index = build_fabrication_index(
            filtered_paths,
            self.logger,
            progress_callback=_progress,
            cancel_callback=self.is_cancelled,
        )
        self._check_cancelled()
        table, index, removed_draws, removed_pieces = self._build_visible_table_from_index(
            raw_index,
            relevant_map=relevant_map,
            relevant_compositions=relevant_compositions,
        )
        if removed_draws > 0 or removed_pieces > 0:
            self.log(
                "Fabrication data: skipped %d draw(s) and %d piece(s) without matching current annealing records."
                % (removed_draws, removed_pieces)
            )
        processed: Dict[str, float] = {}
        for path in filtered_paths:
            try:
                processed[str(path)] = float(path.stat().st_mtime)
            except OSError:
                continue
        return SectionProcessResult(
            table=table,
            processed=processed,
            payloads={
                "fabrication_index": index,
                self.raw_index_payload_name: raw_index,
            },
        )

    def refresh(self) -> None:
        super().refresh()
        self._source_status_cache.clear()
        if self._rebuild_table_from_raw_index():
            return
        table = self.data.table
        if isinstance(table, pd.DataFrame):
            relevant_map, _ = self._load_relevant_map()
            table = self._augment_table_with_relevant_microscope_rows(table, relevant_map)
            if "Temperature (°C)" in table.columns and CORE_TEMPERATURE_COLUMN not in table.columns:
                table = table.rename(columns={"Temperature (°C)": CORE_TEMPERATURE_COLUMN})
                table[GLASS_TEMPERATURE_COLUMN] = None
            if ESTIMATED_TRANSITION_COLUMN not in table.columns:
                if "e/a" in table.columns:
                    table[ESTIMATED_TRANSITION_COLUMN] = table["e/a"].map(
                        _estimate_transition_temp_c
                    )
                else:
                    table[ESTIMATED_TRANSITION_COLUMN] = None
            elif "e/a" in table.columns:
                series = table[ESTIMATED_TRANSITION_COLUMN]
                computed = table["e/a"].map(_estimate_transition_temp_c)
                mask = series.isna() | (series == "")
                table[ESTIMATED_TRANSITION_COLUMN] = series.where(~mask, computed)
            if GLASS_PULL_COLUMN not in table.columns:
                table[GLASS_PULL_COLUMN] = None
            self.data.table = self._apply_imported_separation(table)
            self.model.set_frame(self.data.table)
        self._hide_columns(["_source_paths", "_source_path"])

    def import_project_payload(self, payload: Mapping[str, Any]) -> None:  # type: ignore[override]
        super().import_project_payload(payload)
        self._source_status_cache.clear()
        self._normalize_temperature_columns()
        saved_rows = payload.get("rows") if isinstance(payload, Mapping) else None
        if (
            not isinstance(saved_rows, (list, tuple))
            or len(saved_rows) == 0
        ) and self._rebuild_table_from_raw_index():
            return
        table = self.data.table
        if isinstance(table, pd.DataFrame):
            relevant_map, _ = self._load_relevant_map()
            table = self._augment_table_with_relevant_microscope_rows(table, relevant_map)
            self.data.table = self._apply_imported_separation(table)
            self.model.set_frame(self.data.table)
        self._hide_columns(["_source_paths", "_source_path"])

    def _row_sources(self, row: pd.Series) -> List[Path]:
        sources: List[Path] = []
        raw_paths: List[str] = []
        path_values = row.get("_source_paths")
        if isinstance(path_values, (list, tuple, set)):
            raw_paths.extend(str(value) for value in path_values if value)
        fallback = row.get("_source_path")
        if fallback:
            raw_paths.append(str(fallback))
        for entry in dict.fromkeys(raw_paths):
            try:
                sources.append(Path(entry))
            except Exception:
                continue
        return sources

    def _source_paths_exist(self, sources: Sequence[Path]) -> bool:
        key = tuple(str(path) for path in sources)
        if key in self._source_status_cache:
            return self._source_status_cache[key]
        exists = False
        for path in sources:
            try:
                if path.exists():
                    exists = True
                    break
            except OSError:
                continue
        self._source_status_cache[key] = exists
        return exists

    def _row_missing_source_files(self, row: pd.Series) -> bool:
        data_source = str(row.get("Data source") or "").strip()
        if "Imported" in data_source:
            return False
        sources = self._row_sources(row)
        if not sources:
            return True
        return not self._source_paths_exist(sources)

    def _background_brush_for_cell(self, row: pd.Series, column: str) -> Optional[QtGui.QBrush]:
        if self._row_missing_source_files(row):
            return QtGui.QBrush(QtGui.QColor("#3a0a0a"))
        return None

    def _foreground_brush_for_cell(self, row: pd.Series, column: str) -> Optional[QtGui.QBrush]:
        if self._row_missing_source_files(row):
            return QtGui.QBrush(QtGui.QColor("#ffd6d6"))
        return None

    def set_import_separation(self, enabled: bool) -> None:
        self._separate_imported = bool(enabled)
        table = self.data.table if isinstance(self.data.table, pd.DataFrame) else pd.DataFrame()
        if not isinstance(table, pd.DataFrame) or table.empty:
            if self._rebuild_table_from_raw_index():
                return
            try:
                index = self.store.load_payload("fabrication_index")
            except Exception:
                index = None
            if not isinstance(index, FabricationIndex):
                return
            table = _fabrication_index_to_frame(index)
        table = self._apply_imported_separation(table)
        self.data.table = table
        try:
            self.store.save(self.data)
        except Exception:
            pass
        self.model.set_frame(table)
        self._hide_columns(["_source_paths", "_source_path"])
        self._auto_fit_columns()
        self._update_status()

    def _apply_imported_separation(self, table: pd.DataFrame) -> pd.DataFrame:
        if not isinstance(table, pd.DataFrame) or table.empty:
            return table
        if "Data source" not in table.columns or "Composition" not in table.columns:
            return table
        table = table.loc[
            table["Composition"].astype(str).str.strip() != "Imported data:"
        ].copy()
        if not self._separate_imported:
            return table
        imported_mask = table["Data source"].astype(str).str.contains("Imported", na=False)
        if not imported_mask.any():
            return table
        normal = table.loc[~imported_mask]
        imported = table.loc[imported_mask]
        separator = {column: None for column in table.columns}
        separator["Composition"] = "Imported data:"
        combined = pd.concat([normal, pd.DataFrame([separator]), imported], ignore_index=True)
        return combined

    @staticmethod
    def _coerce_text(value: Any) -> Optional[str]:
        if value is None:
            return None
        try:
            if pd.isna(value):
                return None
        except Exception:
            if isinstance(value, float) and math.isnan(value):
                return None
        text = str(value).strip()
        return text if text else None

    def _editable_columns(self) -> Set[str]:
        return {GLASS_PULL_COLUMN, "Notes"}

    def _handle_cell_edited(
        self,
        top_left: QtCore.QModelIndex,
        bottom_right: QtCore.QModelIndex,
        roles: Tuple[QtCore.Qt.ItemDataRole, ...] = (),
    ) -> None:
        if roles and QtCore.Qt.ItemDataRole.EditRole not in roles:
            return
        base_frame = self.data.table if isinstance(self.data.table, pd.DataFrame) else None
        if isinstance(base_frame, pd.DataFrame) and not base_frame.empty:
            frame = self.model._coerce_frame(base_frame)
        else:
            frame = self.model.frame()
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return
        columns = [
            frame.columns[col_idx]
            for col_idx in range(top_left.column(), bottom_right.column() + 1)
            if 0 <= col_idx < len(frame.columns)
        ]
        relevant = self._editable_columns()
        if not any(column in relevant for column in columns):
            return
        try:
            index = self.store.load_payload("fabrication_index")
        except Exception:
            index = None
        if not isinstance(index, FabricationIndex):
            index = FabricationIndex()
        raw_index = self._load_raw_index()
        if not isinstance(raw_index, FabricationIndex):
            raw_index = index
        updated_any = False
        for row_idx in range(top_left.row(), bottom_right.row() + 1):
            if row_idx < 0 or row_idx >= len(frame.index):
                continue
            series = frame.iloc[row_idx]
            composition = str(series.get("Composition") or "").strip()
            if not composition:
                continue
            try:
                draw = int(series.get("Draw"))
                piece = int(series.get("Piece"))
            except (TypeError, ValueError):
                continue
            key = (composition, draw, piece)
            existing_piece_data = raw_index.piece_level.get(key, index.piece_level.get(key, {}))
            piece_data = dict(existing_piece_data)
            row_updated = False
            for column in columns:
                if column not in relevant:
                    continue
                field = "notes" if column == "Notes" else "glass_pull_off"
                value = self._coerce_text(series.get(column))
                if value is None:
                    piece_data.pop(field, None)
                else:
                    piece_data[field] = value
                row_updated = True
                updated_any = True
            if row_updated:
                if piece_data:
                    piece_data.setdefault("_source_path", piece_data.get("_source_path") or "Manual")
                    index.piece_level[key] = dict(piece_data)
                    raw_index.piece_level[key] = dict(piece_data)
                else:
                    index.piece_level.pop(key, None)
                    raw_index.piece_level.pop(key, None)
        if updated_any:
            self.data.table = frame
            self._store_indexes(index, raw_index=raw_index)
            self.store.save(self.data)

    def apply_imported_samples(self, records: Iterable[Dict[str, Any]]) -> int:
        index = self.store.load_payload("fabrication_index")
        if not isinstance(index, FabricationIndex):
            index = FabricationIndex()
        raw_index = self._load_raw_index()
        if not isinstance(raw_index, FabricationIndex):
            raw_index = index
        added = 0
        for record in records:
            composition = str(record.get("Composition") or "").strip()
            microwire = str(record.get("Microwire") or "").strip()
            if not composition or not microwire:
                continue
            parts = _microwire_parts_from_label_safe(microwire)
            if parts is None:
                continue
            draw_x, piece_y, _suffix = parts
            piece_data: Dict[str, object] = {
                "length_m": record.get("Length (m)"),
                "piece_date": record.get("Piece date"),
                "fabrication_resistance_ohm": record.get("Resistance (Ω)"),
                "glass_pull_off": record.get(GLASS_PULL_COLUMN),
                "notes": record.get("Notes"),
                "_source_path": _primary_saved_source_path(record) or "Imported",
            }
            temperature_value = record.get(CORE_TEMPERATURE_COLUMN)
            if temperature_value in (None, ""):
                temperature_value = record.get("Temperature (°C)")
            glass_temperature_value = record.get(GLASS_TEMPERATURE_COLUMN)
            draw_data: Dict[str, object] = {
                "fabrication_temperature_c": temperature_value,
                "fabrication_glass_temperature_c": glass_temperature_value,
                "mass_g": record.get("Mass (g)"),
                "winding_speed_m_per_min": record.get("Winding speed (m/min)"),
                "glass_feed_mm_per_min": record.get("Glass feeding (mm/min)"),
                "underpressure": record.get("Underpressure"),
                "production_datetime": record.get("Production datetime"),
                "fabrication_resistance_ohm": record.get("Resistance (Ω)"),
                "notes": record.get("Notes"),
                "_source_path": _primary_saved_source_path(record) or "Imported",
            }
            before = bool(index.get_piece(composition, draw_x, piece_y))
            index.set_piece(composition, int(draw_x), int(piece_y), piece_data)
            index.set_draw(composition, int(draw_x), draw_data)
            raw_index.set_piece(composition, int(draw_x), int(piece_y), dict(piece_data))
            raw_index.set_draw(composition, int(draw_x), dict(draw_data))
            if not before:
                added += 1
        table, index, _removed_draws, _removed_pieces = self._build_visible_table_from_index(
            raw_index
        )
        self.data.table = table
        self._store_indexes(index, raw_index=raw_index)
        self.store.save(self.data)
        self.model.set_frame(table)
        self._auto_fit_columns()
        self._update_status()
        try:
            self.data_updated.emit()
        except Exception:
            pass
        return added


class AnnealingSection(MiniDatabaseSection):
    section_key = "annealing"
    section_title = "Current annealing"
    supported_suffixes = (".txt", ".dat", ".csv", ".tsv")

    def __init__(
        self,
        logger: logging.Logger,
        log_callback: Callable[[int, str], None],
        parent: QtWidgets.QWidget | None = None,
    ) -> None:
        self._table_splitter: QtWidgets.QSplitter | None = None
        self._preview_other_count = 1
        self._preview_spacing = 6
        super().__init__(logger, log_callback, parent)
        self._hidden_paths: Set[str] = set()
        self._all_records: List[MeasurementRecord] = []
        self._pixmap_cache: Dict[Tuple[object, ...], Optional[QtGui.QPixmap]] = {}
        self._phase_points: Dict[str, Dict[str, float]] = {}
        self._transition_reviews: Dict[str, Dict[str, Any]] = {}
        stored_phase_points = self.data.extra.get("phase_points")
        if isinstance(stored_phase_points, dict):
            cleaned: Dict[str, Dict[str, float]] = {}
            for key, payload in stored_phase_points.items():
                if not isinstance(key, str) or not isinstance(payload, dict):
                    continue
                entry = self._clean_phase_points_payload(payload)
                if entry:
                    cleaned[key] = entry
            self._phase_points = cleaned
        self._load_transition_reviews()
        self._load_hidden_paths()
        if isinstance(self.model, DataFrameModel):
            self.model.set_decoration_provider(self._preview_decoration)
            self.model.set_tooltip_provider(self._tooltip_for_cell)
        self._sanitize_graph_columns()
        self._record_groups: Dict[str, List[MeasurementRecord]] = {}
        self.export_button = QtWidgets.QPushButton("Export worksheet…")
        self.export_button.clicked.connect(self._export_worksheet)
        self.controls_layout.addWidget(self.export_button)
        self.open_pyplot_button = QtWidgets.QPushButton("Open in PyPlot")
        self.open_pyplot_button.setToolTip("Open the selected annealing files in PyPlot.")
        self.open_pyplot_button.clicked.connect(self._open_selected_in_pyplot)
        self.controls_layout.addWidget(self.open_pyplot_button)
        self.open_origin_button = QtWidgets.QPushButton("Open in Origin")
        self.open_origin_button.setToolTip("Send the selected annealing files to Origin via PyPlot.")
        self.open_origin_button.clicked.connect(self._open_selected_in_origin)
        self.controls_layout.addWidget(self.open_origin_button)
        self.visibility_button = QtWidgets.QPushButton("Visibility...")
        self.visibility_button.setToolTip("Show or hide specific annealing graphs.")
        self.visibility_button.clicked.connect(self._open_visibility_dialog)
        self.controls_layout.addWidget(self.visibility_button)
        self.review_transitions_button = QtWidgets.QPushButton("Review transitions")
        self.review_transitions_button.setToolTip("Review automatic As/Af/Ms/Mf candidates on annealing graphs.")
        self.review_transitions_button.clicked.connect(self._open_transition_review)
        self.controls_layout.addWidget(self.review_transitions_button)
        self._update_export_enabled()
        self._refresh_record_groups()
        self._hide_columns(["_group_key", "_sources"])

    def create_right_panel(self, parent: QtWidgets.QWidget) -> QtWidgets.QWidget:
        table = QtWidgets.QTableView(parent)
        table.setModel(self.model)
        header = table.horizontalHeader()
        if header is not None:
            header.setStretchLastSection(False)
            header.setSectionResizeMode(QtWidgets.QHeaderView.ResizeMode.Interactive)
        table.setAlternatingRowColors(True)
        table.setSelectionBehavior(
            QtWidgets.QAbstractItemView.SelectionBehavior.SelectRows
        )
        table.setSelectionMode(
            QtWidgets.QAbstractItemView.SelectionMode.ExtendedSelection
        )
        table.setEditTriggers(
            QtWidgets.QAbstractItemView.EditTrigger.DoubleClicked
            | QtWidgets.QAbstractItemView.EditTrigger.SelectedClicked
            | QtWidgets.QAbstractItemView.EditTrigger.EditKeyPressed
        )
        table.setSortingEnabled(True)
        table.setVerticalScrollMode(QtWidgets.QAbstractItemView.ScrollMode.ScrollPerPixel)
        table.setHorizontalScrollMode(QtWidgets.QAbstractItemView.ScrollMode.ScrollPerPixel)
        table.setIconSize(
            QtCore.QSize(self._preview_icon_width(), ANNEALING_GRAPH_HEIGHT)
        )
        vertical_header = table.verticalHeader()
        if vertical_header is not None:
            default_height = ANNEALING_GRAPH_HEIGHT + 24
            vertical_header.setDefaultSectionSize(default_height)
            vertical_header.setMinimumSectionSize(default_height)
        self.table_view = table
        return table

    def _configure_table_view(self) -> None:  # type: ignore[override]
        super()._configure_table_view()
        table = self.table_view
        if not isinstance(table, QtWidgets.QTableView):
            return
        header = table.horizontalHeader()
        if header is not None:
            header.setStretchLastSection(False)
            header.setSectionResizeMode(QtWidgets.QHeaderView.ResizeMode.Interactive)

    def _auto_fit_columns(self) -> None:  # type: ignore[override]
        super()._auto_fit_columns()
        QtCore.QTimer.singleShot(0, self._ensure_preview_columns_wide)

    def _ensure_preview_columns_wide(self) -> None:
        table = self.table_view
        if not isinstance(table, QtWidgets.QTableView):
            return
        frame = self.model.frame()
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return
        required_widths = {
            ANNEALING_HIGH_GRAPH_COLUMN: ANNEALING_GRAPH_WIDTH + 80,
            ANNEALING_OTHER_GRAPH_COLUMN: self._preview_icon_width() + 80,
        }
        for column_name, minimum in required_widths.items():
            if column_name not in frame.columns:
                continue
            idx = frame.columns.get_loc(column_name)
            if table.columnWidth(idx) < minimum:
                table.setColumnWidth(idx, minimum)

    def apply_data(self, data: MiniDatabaseData) -> None:  # type: ignore[override]
        super().apply_data(data)
        self._load_transition_reviews()
        self._sanitize_graph_columns()
        self._hide_columns(["_group_key", "_sources"])
        self._refresh_record_groups()
        self._prune_transition_reviews()
        self._prune_phase_points()
        self._update_export_enabled()

    def process(
        self,
        paths: List[Path],
        progress: Optional[Callable[[int, int, Optional[str]], None]] = None,
    ) -> SectionProcessResult:
        records: List[MeasurementRecord] = []
        processed: Dict[str, float] = {}
        total = len(paths)
        sanity_failures: List[Tuple[Path, Optional[float]]] = []
        for idx, path in enumerate(paths, start=1):
            self._check_cancelled()
            metadata = _metadata_from_path(path)
            if (
                not getattr(metadata, "composition_token", None)
                or getattr(metadata, "draw_x", None) is None
                or getattr(metadata, "piece_y", None) is None
            ):
                self.logger.warning(
                    "Skipping %s because the microwire draw/piece identifiers could not be parsed",
                    path,
                )
                if progress is not None:
                    try:
                        progress(idx, total, f"Skipped: {path.name}")
                    except Exception:
                        pass
                continue
            try:
                df = _load_annealing(path, expected_setpoint_mA=metadata.setpoint_mA)
            except Exception:
                self.logger.exception("Failed to parse %s", path)
                if progress is not None:
                    try:
                        progress(idx, total, f"Failed: {path.name}")
                    except Exception:
                        pass
                continue
            ok, mean_error = _resistance_sanity_check(df)
            if not ok:
                sanity_failures.append((path, mean_error))
            record = MeasurementRecord(
                path=path,
                metadata=metadata,
                dataframe=df,
                sanity_ok=ok,
                sanity_error=mean_error,
                transition_summary=_annealing_transition_summary(df, label=path.name),
            )
            records.append(record)
            try:
                processed[str(path)] = float(path.stat().st_mtime)
            except OSError:
                processed[str(path)] = 0.0
            if progress is not None:
                try:
                    progress(idx, total, f"Parsed {path.name}")
                except Exception:
                    pass
        table = _annealing_records_to_frame(records, self.logger)
        column_keys = table.get("_group_key") if isinstance(table, pd.DataFrame) else None
        valid_keys = {
            str(value)
            for value in (column_keys.tolist() if column_keys is not None else [])
            if value not in (None, "", "None") and not (isinstance(value, float) and math.isnan(value))
        }
        self._prune_phase_points(valid_keys, store=False)
        if sanity_failures:
            preview = ", ".join(p.name for p, _ in sanity_failures[:5])
            if len(sanity_failures) > 5:
                preview += ", …"
            errors = [err for _, err in sanity_failures if isinstance(err, (int, float))]
            worst = f" (worst error {max(errors) * 100:.1f}%)" if errors else ""
            summary = (
                f"{self.section_title}: R≈V/I sanity check failed for {len(sanity_failures)} file(s){worst}"
            )
            if preview:
                summary += f": {preview}"
            self.log(summary, level=logging.WARNING)
            self.logger.warning(summary)
        return SectionProcessResult(
            table=table,
            processed=processed,
            payloads={"annealing_records": records},
            extra={
                "phase_points": dict(self._phase_points),
                TRANSITION_REVIEW_EXTRA_KEY: self._transition_reviews_payload(),
            },
        )

    def refresh(self) -> None:
        super().refresh()
        self._sanitize_graph_columns()
        self._hide_columns(["_group_key", "_sources"])
        self._refresh_record_groups()
        self._prune_transition_reviews()
        self._prune_phase_points()
        self._update_export_enabled()

    def import_project_payload(self, payload: Mapping[str, Any]) -> None:  # type: ignore[override]
        super().import_project_payload(payload)
        self._load_transition_reviews()
        self._sanitize_graph_columns()
        self._hide_columns(["_group_key", "_sources"])
        self._refresh_record_groups()
        self._prune_transition_reviews()
        self._prune_phase_points()
        self._update_export_enabled()

    def _update_export_enabled(self) -> None:
        has_rows = isinstance(self.data.table, pd.DataFrame) and not self.data.table.empty
        if hasattr(self, "export_button"):
            self.export_button.setEnabled(has_rows)

    def _load_hidden_paths(self) -> None:
        hidden = self.data.extra.get("hidden_paths")
        if isinstance(hidden, (list, tuple, set)):
            self._hidden_paths = {str(path) for path in hidden if path}
        else:
            self._hidden_paths = set()

    def _store_hidden_paths(self) -> None:
        self.data.extra["hidden_paths"] = sorted(self._hidden_paths)
        try:
            self.store.save(self.data)
        except Exception:
            self.logger.exception("Failed to persist annealing visibility settings")

    def _visible_records(
        self, records: Sequence[MeasurementRecord]
    ) -> List[MeasurementRecord]:
        if not self._hidden_paths:
            return list(records)
        return [
            record
            for record in records
            if _record_path_key(record) not in self._hidden_paths
        ]

    def _open_visibility_dialog(self) -> None:
        items = _visibility_items_from_records(self._all_records)
        if not items:
            QtWidgets.QMessageBox.information(
                self,
                self.section_title,
                "No annealing graphs are available yet.",
            )
            return
        groups = _visibility_groups_from_records(self._all_records)
        dialog = _GraphVisibilityDialog(
            "Annealing graph visibility",
            items,
            self._hidden_paths,
            groups=groups,
            parent=self,
        )
        if dialog.exec() == QtWidgets.QDialog.DialogCode.Accepted:
            self._hidden_paths = dialog.hidden_paths()
            self._store_hidden_paths()
            self._refresh_record_groups()

    def _transition_review_records(self) -> List[MeasurementRecord]:
        selected = self._selected_records()

        def _dedupe(records: Sequence[MeasurementRecord]) -> List[MeasurementRecord]:
            result: List[MeasurementRecord] = []
            seen: Set[int] = set()
            for record in records:
                marker = id(record)
                if marker in seen:
                    continue
                seen.add(marker)
                result.append(record)
            return result

        if selected:
            return _dedupe(selected)
        if self._all_records:
            return self._visible_records(self._all_records)
        records: List[MeasurementRecord] = []
        for group in self._record_groups.values():
            records.extend(group)
        return _dedupe(records)

    def _open_transition_review(self) -> None:
        records = self._transition_review_records()
        if not records:
            QtWidgets.QMessageBox.information(
                self,
                self.section_title,
                "No current annealing graphs are available yet.",
            )
            return
        dialog = _AnnealingTransitionReviewDialog(
            records,
            self.logger,
            self,
            transition_reviews_provider=self.transition_reviews_snapshot,
            transition_reviews_setter=self.set_transition_review_for_record,
        )
        dialog.exec()

    def _load_transition_reviews(self) -> None:
        raw = self.data.extra.get(TRANSITION_REVIEW_EXTRA_KEY)
        if isinstance(raw, dict) and isinstance(raw.get("records"), dict):
            raw_records = raw.get("records")
        elif isinstance(raw, dict):
            raw_records = raw
        else:
            raw_records = {}
        cleaned: Dict[str, Dict[str, Any]] = {}
        if isinstance(raw_records, dict):
            for record_id, payload in raw_records.items():
                if not isinstance(record_id, str) or not isinstance(payload, dict):
                    continue
                entry = self._clean_transition_review_payload(record_id, payload)
                if entry:
                    cleaned[record_id] = entry
        self._transition_reviews = cleaned

    def _transition_reviews_payload(self) -> Dict[str, Any]:
        return {
            "schema_version": TRANSITION_REVIEW_SCHEMA_VERSION,
            "records": self.transition_reviews_snapshot(),
        }

    def _clean_transition_review_payload(
        self,
        record_id: str,
        payload: Mapping[str, Any],
    ) -> Dict[str, Any]:
        record_id = str(record_id).strip()
        if not record_id:
            return {}
        status = str(payload.get("status") or TRANSITION_REVIEW_STATUS_UNREVIEWED).strip()
        if status not in {
            TRANSITION_REVIEW_STATUS_UNREVIEWED,
            TRANSITION_REVIEW_STATUS_ACCEPTED_AUTO,
            TRANSITION_REVIEW_STATUS_MANUAL_ADJUSTED,
            TRANSITION_REVIEW_STATUS_NO_TRANSITION,
            TRANSITION_REVIEW_STATUS_EXCLUDED,
            TRANSITION_REVIEW_STATUS_NEEDS_ATTENTION,
        }:
            status = TRANSITION_REVIEW_STATUS_NEEDS_ATTENTION
        included = bool(payload.get("included", status in TRANSITION_REVIEW_INCLUDED_STATUSES))
        if status in {TRANSITION_REVIEW_STATUS_NO_TRANSITION, TRANSITION_REVIEW_STATUS_EXCLUDED}:
            included = False
        entry: Dict[str, Any] = {
            "transition_record_id": record_id,
            "source_kind": str(payload.get("source_kind") or "current_annealing"),
            "status": status,
            "included": included,
            "auto_values_mA": _clean_transition_values(payload.get("auto_values_mA")),
            "manual_values_mA": _clean_transition_values(payload.get("manual_values_mA")),
            "final_values_mA": _clean_transition_values(payload.get("final_values_mA")),
        }
        for key in (
            "sample_key",
            "composition",
            "microwire",
            "source_path",
            "graph_label",
            "setpoint_mA",
            "notes",
            "updated_at",
        ):
            value = payload.get(key)
            if value not in (None, ""):
                entry[key] = value
        return entry

    def _store_transition_reviews(self) -> None:
        self.data.extra[TRANSITION_REVIEW_EXTRA_KEY] = self._transition_reviews_payload()
        try:
            self.store.save(self.data)
        except Exception:
            self.logger.exception("Failed to persist transition review records")

    def transition_reviews_snapshot(self) -> Dict[str, Dict[str, Any]]:
        snapshot: Dict[str, Dict[str, Any]] = {}
        for record_id, payload in self._transition_reviews.items():
            cleaned = self._clean_transition_review_payload(record_id, payload)
            if cleaned:
                snapshot[record_id] = cleaned
        return snapshot

    def set_transition_review_for_record(
        self,
        record_id: str,
        payload: Mapping[str, Any],
    ) -> None:
        record_id = str(record_id).strip()
        if not record_id:
            return
        entry = self._clean_transition_review_payload(record_id, payload)
        if not entry:
            self._transition_reviews.pop(record_id, None)
        else:
            record = self._record_by_transition_id(record_id)
            if record is not None:
                entry.update(self._transition_review_metadata(record_id, record))
            entry["updated_at"] = datetime.now(UTC).isoformat()
            self._transition_reviews[record_id] = entry
        self._store_transition_reviews()
        try:
            self.data_updated.emit()
        except Exception:
            pass

    def _record_by_transition_id(self, record_id: str) -> Optional[MeasurementRecord]:
        for record in self._all_records:
            if _transition_record_id_for_annealing_record(record) == record_id:
                return record
        for records in self._record_groups.values():
            for record in records:
                if _transition_record_id_for_annealing_record(record) == record_id:
                    return record
        return None

    def _prune_transition_reviews(self, *, store: bool = True) -> None:
        records = list(self._all_records)
        if not records:
            for group in self._record_groups.values():
                records.extend(group)
        valid_ids = {
            _transition_record_id_for_annealing_record(record)
            for record in records
        }
        if not valid_ids:
            if self._transition_reviews:
                self._transition_reviews.clear()
                if store:
                    self._store_transition_reviews()
            return
        removed = False
        for record_id in list(self._transition_reviews.keys()):
            if record_id not in valid_ids:
                self._transition_reviews.pop(record_id, None)
                removed = True
        if removed and store:
            self._store_transition_reviews()

    def _transition_review_metadata(
        self,
        record_id: str,
        record: MeasurementRecord,
    ) -> Dict[str, Any]:
        metadata = getattr(record, "metadata", None)
        sample_key = _phase_point_key_for_annealing_record(record)
        path = getattr(record, "path", None)
        setpoint = _extract_setpoint(record)
        composition = getattr(metadata, "composition_token", None)
        draw = getattr(metadata, "draw_x", None)
        piece = getattr(metadata, "piece_y", None)
        suffix = None
        if sample_key:
            parsed = _microwire_key_from_string(sample_key)
            if parsed is not None:
                _composition, _draw, _piece, suffix = parsed
        microwire = ""
        if draw is not None and piece is not None:
            try:
                microwire = _microwire_label(int(draw), int(piece), suffix)
            except Exception:
                microwire = f"{draw}/{piece}"
        graph_label = str(getattr(metadata, "file_name", "") or "")
        if not graph_label and path:
            try:
                graph_label = Path(path).name
            except Exception:
                graph_label = str(path)
        return {
            "transition_record_id": record_id,
            "source_kind": "current_annealing",
            "sample_key": sample_key or "",
            "composition": str(composition or ""),
            "microwire": microwire,
            "source_path": str(path or ""),
            "graph_label": graph_label,
            "setpoint_mA": setpoint,
        }

    def _clean_phase_points_payload(self, payload: Dict[str, Any]) -> Dict[str, float]:
        entry: Dict[str, float] = {}
        for label in PHASE_POINT_LABELS + ("As", "Ms"):
            value = payload.get(label)
            if isinstance(value, (int, float)) and math.isfinite(float(value)):
                entry[label] = float(value)
        if "As1" not in entry and "As" in entry:
            entry["As1"] = entry["As"]
        if "Ms1" not in entry and "Ms" in entry:
            entry["Ms1"] = entry["Ms"]
        if "As1" in entry:
            entry["As"] = entry["As1"]
        if "Ms1" in entry:
            entry["Ms"] = entry["Ms1"]
        return entry

    def _store_phase_points(self) -> None:
        snapshot: Dict[str, Dict[str, float]] = {}
        for key, payload in self._phase_points.items():
            if not isinstance(key, str) or not isinstance(payload, dict):
                continue
            cleaned = self._clean_phase_points_payload(payload)
            if cleaned:
                snapshot[key] = cleaned
        self.data.extra["phase_points"] = snapshot
        try:
            self.store.save(self.data)
        except Exception:
            self.logger.exception("Failed to persist phase transition points")

    def phase_points_snapshot(self) -> Dict[str, Dict[str, float]]:
        snapshot: Dict[str, Dict[str, float]] = {}
        for key, payload in self._phase_points.items():
            if not isinstance(key, str) or not isinstance(payload, dict):
                continue
            cleaned = self._clean_phase_points_payload(payload)
            if cleaned:
                snapshot[key] = cleaned
        return snapshot

    def set_phase_points_for_key(
        self,
        key: str,
        *,
        as_value: Optional[float] = None,
        ms_value: Optional[float] = None,
        phase_values: Optional[Dict[str, Optional[float]]] = None,
    ) -> None:
        key_text = str(key).strip()
        if not key_text:
            return
        entry: Dict[str, float] = {}

        def _clean(value: Optional[float]) -> Optional[float]:
            if value is None:
                return None
            try:
                numeric = float(value)
            except (TypeError, ValueError):
                return None
            return numeric if math.isfinite(numeric) else None

        phase_values = phase_values or {}
        for label in PHASE_POINT_LABELS:
            cleaned = _clean(phase_values.get(label))
            if cleaned is not None:
                entry[label] = cleaned
        if "As1" not in entry:
            as_clean = _clean(as_value)
            if as_clean is not None:
                entry["As1"] = as_clean
        if "Ms1" not in entry:
            ms_clean = _clean(ms_value)
            if ms_clean is not None:
                entry["Ms1"] = ms_clean
        if "As1" in entry:
            entry["As"] = entry["As1"]
        if "Ms1" in entry:
            entry["Ms"] = entry["Ms1"]
        if entry:
            self._phase_points[key_text] = entry
        elif key_text in self._phase_points:
            self._phase_points.pop(key_text, None)
        self._store_phase_points()
        try:
            self.data_updated.emit()
        except Exception:
            pass

    def _prune_phase_points(self, valid_keys: Optional[Iterable[str]] = None, *, store: bool = True) -> None:
        if valid_keys is None:
            frame = self.data.table if isinstance(self.data.table, pd.DataFrame) else pd.DataFrame()
            if frame.empty or "_group_key" not in frame.columns:
                valid_set: Set[str] = set()
            else:
                valid_set = {str(value) for value in frame["_group_key"].dropna().astype(str)}
        else:
            valid_set = {str(value) for value in valid_keys if value}
        removed = False
        for key in list(self._phase_points.keys()):
            if key not in valid_set:
                self._phase_points.pop(key, None)
                removed = True
        if removed and store:
            self._store_phase_points()

    def _selected_group_key(self) -> Optional[str]:
        rows = self._selected_rows()
        if not rows:
            return None
        series = self._row_series(rows[0])
        if series is None:
            return None
        key = series.get("_group_key")
        if key in (None, "", float("nan")):
            return None
        return str(key)

    def _selected_records(self) -> List[MeasurementRecord]:
        rows = self._selected_rows()
        records: List[MeasurementRecord] = []
        if not rows:
            return records
        for row_index in rows:
            series = self._row_series(row_index)
            if series is None:
                continue
            key = series.get("_group_key")
            if key in (None, "", float("nan")):
                continue
            records.extend(self._record_groups.get(str(key), []))
        return records

    def _open_selected_in_pyplot(self) -> None:
        records = self._selected_records()
        if not records:
            QtWidgets.QMessageBox.information(
                self,
                self.section_title,
                "Select one or more rows to open their graphs.",
            )
            return
        paths = [
            record.path for record in records if isinstance(record.path, Path)
        ]
        paths = list(dict.fromkeys(paths))
        if not paths:
            QtWidgets.QMessageBox.information(
                self,
                self.section_title,
                "No files are available for the selected rows.",
            )
            return
        _open_pyplot_for_paths(
            paths,
            "Current Annealing",
            self.logger,
            auto_plot=True,
            open_origin=False,
        )

    def _open_selected_in_origin(self) -> None:
        records = self._selected_records()
        if not records:
            QtWidgets.QMessageBox.information(
                self,
                self.section_title,
                "Select one or more rows to open their graphs.",
            )
            return
        paths = [
            record.path for record in records if isinstance(record.path, Path)
        ]
        paths = list(dict.fromkeys(paths))
        if not paths:
            QtWidgets.QMessageBox.information(
                self,
                self.section_title,
                "No files are available for the selected rows.",
            )
            return
        _open_pyplot_for_paths(
            paths,
            "Current Annealing",
            self.logger,
            auto_plot=True,
            open_origin=True,
        )


    def _update_open_sources_enabled(self) -> None:
        super()._update_open_sources_enabled()

    def _handle_worker_finished(self, result: SectionProcessResult) -> None:
        super()._handle_worker_finished(result)
        self._sanitize_graph_columns()
        self._hide_columns(["_group_key", "_sources"])
        self._refresh_record_groups()
        self._update_export_enabled()

    def _refresh_record_groups(self) -> None:
        grouped: Dict[str, List[MeasurementRecord]] = {}
        try:
            payload = self.store.load_payload("annealing_records")
        except Exception:
            payload = None
        all_records = list(payload) if isinstance(payload, list) else []
        self._all_records = list(all_records)
        visible_records = self._visible_records(all_records)
        if visible_records:
            for record in visible_records:
                metadata = getattr(record, "metadata", None)
                if metadata is None:
                    continue
                composition = getattr(metadata, "composition_token", None)
                draw = getattr(metadata, "draw_x", None)
                piece = getattr(metadata, "piece_y", None)
                if composition is None or draw is None or piece is None:
                    continue
                suffix = None
                path_value = getattr(record, "path", None)
                if isinstance(path_value, Path):
                    parsed_key = _microscope_key(path_value)
                    if parsed_key is not None:
                        _, _, _, suffix = parsed_key
                try:
                    key = _microwire_key_to_str((composition, int(draw), int(piece), suffix))
                except (TypeError, ValueError):
                    continue
                grouped.setdefault(key, []).append(record)
        self._record_groups = grouped
        max_other = 1
        for records in grouped.values():
            _high_record, other_records = _select_anchor_and_other_records(records)
            if other_records:
                max_other = max(max_other, len(other_records))
        frame = self.data.table if isinstance(self.data.table, pd.DataFrame) else pd.DataFrame()
        if isinstance(frame, pd.DataFrame) and not frame.empty:
            other_file_column = "Other annealing files"
            for _, row in frame.iterrows():
                max_other = max(
                    max_other,
                    _shape_memory_graph_item_count(row.get(ANNEALING_OTHER_GRAPH_COLUMN)),
                    _shape_memory_graph_item_count(row.get(other_file_column)),
                )
        self._preview_other_count = max_other
        self._invalidate_previews()
        self._update_preview_icon_size()

    def _sanitize_graph_columns(self) -> None:
        frame = self.data.table if isinstance(self.data.table, pd.DataFrame) else pd.DataFrame()
        if frame.empty:
            return

        def _graph_cell_items(value: Any) -> List[Any]:
            if value is None:
                return []
            if isinstance(value, str):
                stripped = value.strip()
                return [stripped] if stripped else []
            if isinstance(value, (list, tuple, set)):
                items: List[Any] = []
                for item in value:
                    items.extend(_graph_cell_items(item))
                return items
            return [value]

        def _merge_graph_cells(left: Any, right: Any) -> Any:
            merged: List[Any] = []
            for item in _graph_cell_items(left) + _graph_cell_items(right):
                duplicate = False
                for existing in merged:
                    if existing == item:
                        duplicate = True
                        break
                if not duplicate:
                    merged.append(item)
            if not merged:
                return None
            if len(merged) == 1:
                return merged[0]
            return merged

        changed = False
        if ANNEALING_OTHER_GRAPH_COLUMN not in frame.columns:
            frame[ANNEALING_OTHER_GRAPH_COLUMN] = None
        for legacy_column in (
            ANNEALING_LEGACY_OTHER_GRAPH_COLUMN,
            ANNEALING_LEGACY_LOW_GRAPH_COLUMN,
        ):
            if legacy_column not in frame.columns:
                continue
            frame[ANNEALING_OTHER_GRAPH_COLUMN] = [
                _merge_graph_cells(target, legacy)
                for target, legacy in zip(
                    frame[ANNEALING_OTHER_GRAPH_COLUMN].tolist(),
                    frame[legacy_column].tolist(),
                )
            ]
            frame = frame.drop(columns=[legacy_column])
            changed = True
        for column in (ANNEALING_HIGH_GRAPH_COLUMN, ANNEALING_OTHER_GRAPH_COLUMN):
            if column not in frame.columns:
                continue
            series = frame[column]
            if not hasattr(series, "apply"):
                continue
            cleaned = series.apply(
                lambda value: None
                if isinstance(value, (QtGui.QPixmap, QtGui.QImage))
                else value
            )
            if not cleaned.equals(series):
                frame[column] = cleaned
                changed = True
        drop_columns = {
            ANNEALING_AS_COLUMN,
            ANNEALING_MS_COLUMN,
            "Low current setpoint",
            "Updated",
        }
        if any(column in frame.columns for column in drop_columns):
            frame = frame.drop(columns=[column for column in drop_columns if column in frame.columns])
            changed = True

        desired_order = [
            "Composition",
            "Microwire",
            ANNEALING_HIGH_GRAPH_COLUMN,
            ANNEALING_OTHER_GRAPH_COLUMN,
            "_group_key",
            "_sources",
        ]
        current_columns = list(frame.columns)
        preferred = [col for col in desired_order if col in frame.columns]
        remainder = [col for col in current_columns if col not in desired_order]
        new_order = preferred + remainder
        if new_order != current_columns and new_order:
            frame = frame.loc[:, new_order]
            changed = True
        if changed:
            self.data.table = frame
            if isinstance(self.model, DataFrameModel):
                self.model.set_frame(frame)
                self._auto_fit_columns()
            try:
                self.store.save(self.data)
            except Exception:
                pass
            try:
                self.data_updated.emit()
            except Exception:
                pass
        self._invalidate_previews()

    def _invalidate_previews(self) -> None:
        self._pixmap_cache.clear()
        if isinstance(self.model, DataFrameModel):
            try:
                self.model.layoutChanged.emit()
            except Exception:
                pass

    def _preview_icon_width(self) -> int:
        count = max(int(getattr(self, "_preview_other_count", 1)), 1)
        return ANNEALING_GRAPH_WIDTH * count + self._preview_spacing * (count - 1)

    def _update_preview_icon_size(self) -> None:
        table = self.table_view
        if not isinstance(table, QtWidgets.QTableView):
            return
        width = self._preview_icon_width()
        try:
            table.setIconSize(
                QtCore.QSize(max(width, ANNEALING_GRAPH_WIDTH), ANNEALING_GRAPH_HEIGHT)
            )
        except Exception:
            pass
        header = table.verticalHeader()
        if header is not None:
            try:
                header.setDefaultSectionSize(ANNEALING_GRAPH_HEIGHT + 24)
            except Exception:
                pass
        self._auto_fit_columns()

    def _preview_decoration(
        self,
        row: pd.Series,
        column: str,
    ) -> Optional[QtGui.QPixmap]:
        if column not in {ANNEALING_HIGH_GRAPH_COLUMN, ANNEALING_OTHER_GRAPH_COLUMN}:
            return None
        key = row.get("_group_key")
        if not isinstance(key, str) or not key:
            return None
        cache_key: Tuple[object, ...] = (key, column)
        if cache_key in self._pixmap_cache:
            return self._pixmap_cache[cache_key]
        records = self._record_groups.get(key)
        if not records:
            loaded_records: List[MeasurementRecord] = []
            for source in self._row_sources(row):
                try:
                    metadata = _metadata_from_path(source)
                    frame = _load_annealing(source, expected_setpoint_mA=metadata.setpoint_mA)
                except Exception:
                    continue
                loaded_records.append(
                    MeasurementRecord(
                        path=source,
                        metadata=metadata,
                        dataframe=frame,
                        sanity_ok=True,
                        sanity_error=None,
                    )
                )
            records = loaded_records
        pixmap: Optional[QtGui.QPixmap] = None
        if records:
            diameter_um = _diameter_um_from_mapping(row.to_dict())
            high_record, other_records = _select_anchor_and_other_records(records)
            if column == ANNEALING_HIGH_GRAPH_COLUMN:
                target = high_record
                if target is None and other_records:
                    pixmap = _render_missing_high_measurement_pixmap(other_records)
                else:
                    pixmap = _render_measurement_pixmap(
                        target,
                        self.logger,
                        wire_diameter_um=diameter_um,
                    )
            else:
                if other_records:
                    preview_count = max(
                        len(other_records),
                        _shape_memory_graph_item_count(row.get(ANNEALING_OTHER_GRAPH_COLUMN)),
                        _shape_memory_graph_item_count(row.get("Other annealing files")),
                        1,
                    )
                    signature = tuple(
                        str(getattr(record, "path", "")) for record in other_records
                    )
                    cache_key = (key, column, signature, preview_count)
                    cached = self._pixmap_cache.get(cache_key)
                    if cached is not None:
                        return cached
                    pixmaps: List[QtGui.QPixmap] = []
                    for record in other_records:
                        preview = _render_measurement_pixmap(
                            record,
                            self.logger,
                            wire_diameter_um=diameter_um,
                        )
                        if preview is not None:
                            pixmaps.append(preview)
                    pixmap = _combine_pixmaps_side_by_side(
                        pixmaps,
                        width_px=ANNEALING_GRAPH_WIDTH * preview_count
                        + self._preview_spacing * (preview_count - 1),
                        height_px=ANNEALING_GRAPH_HEIGHT,
                        spacing=self._preview_spacing,
                        scale_to_fit=False,
                    )
                    self._pixmap_cache[cache_key] = pixmap
                    return pixmap
        if pixmap is None:
            path_value = row.get(column)
            if isinstance(path_value, str) and path_value:
                candidate = Path(path_value)
                if candidate.exists():
                    loaded = QtGui.QPixmap(str(candidate))
                    if not loaded.isNull():
                        pixmap = loaded
        self._pixmap_cache[cache_key] = pixmap
        return pixmap

    def _tooltip_for_cell(self, row: pd.Series, column: str) -> Optional[str]:
        if column != ANNEALING_HIGH_GRAPH_COLUMN:
            return None
        key = row.get("_group_key")
        if not isinstance(key, str) or not key:
            return None
        records = self._record_groups.get(key, [])
        if not records:
            return None
        high_record, _other_records = _select_anchor_and_other_records(records)
        if high_record is not None:
            return None
        return _missing_high_measurement_message(records)

    def _preview_background(
        self,
        row: pd.Series,
        column: str,
    ) -> Optional[QtGui.QBrush]:
        _ = column
        frame = self.preview_model.frame()
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return None
        try:
            row_idx = int(row.name)
        except Exception:
            return None
        if row_idx < 0 or row_idx >= len(frame.index):
            return None
        group_index = 0
        previous_group: Optional[str] = None
        for idx in range(row_idx + 1):
            current_row = frame.iloc[idx]
            current_group = "|".join(
                [
                    str(current_row.get("Composition") or "").strip(),
                    str(current_row.get("Microwire") or "").strip(),
                ]
            )
            if previous_group is None:
                previous_group = current_group
            elif current_group != previous_group:
                group_index += 1
                previous_group = current_group
        color = QtGui.QColor("#1a1a1a" if group_index % 2 == 0 else "#202733")
        return QtGui.QBrush(color)

    def _row_sources(self, row: pd.Series) -> List[Path]:
        sources: List[Path] = []
        raw_sources = row.get("_sources")
        if isinstance(raw_sources, (list, tuple)):
            for entry in raw_sources:
                if not entry:
                    continue
                try:
                    sources.append(Path(entry))
                except Exception:
                    continue
        key = row.get("_group_key")
        if isinstance(key, str):
            for record in self._record_groups.get(key, []):
                path = getattr(record, "path", None)
                if path:
                    try:
                        candidate = Path(path)
                    except Exception:
                        continue
                    if candidate not in sources:
                        sources.append(candidate)
        return sources

    def _export_worksheet(self) -> None:
        records = self.store.load_payload("annealing_records")
        if not isinstance(records, list) or not records:
            QtWidgets.QMessageBox.information(
                self,
                self.section_title,
                "Process current annealing files before exporting.",
            )
            return

        path_str, _ = QtWidgets.QFileDialog.getSaveFileName(
            self,
            "Save annealing worksheet",
            str(Path.cwd() / "annealing_summary.xlsx"),
            "Excel files (*.xlsx)",
        )
        if not path_str:
            return
        output_path = Path(path_str)
        if output_path.suffix.lower() != ".xlsx":
            output_path = output_path.with_suffix(".xlsx")

        try:
            import xlsxwriter  # type: ignore[import-not-found]
        except ImportError:
            QtWidgets.QMessageBox.warning(
                self,
                self.section_title,
                "xlsxwriter is required to export worksheets.",
            )
            return

        grouped: Dict[MicrowireKey, List[MeasurementRecord]] = {}
        for record in records:
            metadata = getattr(record, "metadata", None)
            if metadata is None:
                continue
            draw_x = getattr(metadata, "draw_x", None)
            piece_y = getattr(metadata, "piece_y", None)
            composition = getattr(metadata, "composition_token", None)
            if composition is None or draw_x is None or piece_y is None:
                continue
            suffix = None
            path = getattr(record, "path", None)
            if isinstance(path, Path):
                parsed_key = _microscope_key(path)
                if parsed_key is not None:
                    _, _, _, suffix = parsed_key
            grouped.setdefault((str(composition), int(draw_x), int(piece_y), suffix), []).append(record)

        if not grouped:
            QtWidgets.QMessageBox.warning(
                self,
                self.section_title,
                "No complete microwire records available for export.",
            )
            return

        try:
            with TemporaryDirectory() as tmpdir:
                workbook = xlsxwriter.Workbook(str(output_path))
                try:
                    worksheet = workbook.add_worksheet("Summary")
                    header_format = workbook.add_format({"bold": True})
                    headers = [
                        "Composition",
                        "Microwire",
                        "1000 mA file",
                        "Other annealing files",
                        "Graph — 1000 mA",
                        "Graph — other annealing",
                    ]
                    worksheet.write_row(0, 0, headers, header_format)
                    worksheet.set_column(0, 1, 18)
                    worksheet.set_column(2, 2, 22)
                    worksheet.set_column(3, 3, 40)
                    worksheet.set_column(4, 5, 42)

                    plot_dir = Path(tmpdir)
                    row_idx = 1
                    for (composition, draw_x, piece_y, suffix), recs in sorted(
                        grouped.items(),
                        key=lambda item: (
                            str(item[0][0]).lower(),
                            int(item[0][1]),
                            int(item[0][2]),
                            (str(item[0][3]).lower() if item[0][3] is not None else ""),
                        ),
                    ):
                        high_record, other_records = _select_anchor_and_other_records(recs)

                        microwire_label = _microwire_label(draw_x, piece_y, suffix)
                        high_file = (
                            high_record.metadata.file_name if high_record else ""
                        )
                        other_files = ", ".join(
                            record.metadata.file_name
                            for record in other_records
                            if getattr(record.metadata, "file_name", None)
                        )

                        worksheet.write_row(
                            row_idx,
                            0,
                            [
                                composition,
                                microwire_label,
                                high_file,
                                other_files,
                                "",
                                "",
                            ],
                        )

                        worksheet.set_row(row_idx, 160)

                        def _plot(record: MeasurementRecord) -> Optional[Path]:
                            if record is None:
                                return None
                            try:
                                plot_path = _plot_measurement_matplotlib(
                                    record.dataframe,
                                    Path(record.path),
                                    plot_dir,
                                    DEFAULT_FIGSIZE,
                                )
                            except Exception:
                                self.logger.exception(
                                    "Failed to render plot for %s", record.path
                                )
                                return None
                            return plot_path

                        high_plot = _plot(high_record) if high_record else None
                        other_pixmaps = [
                            _render_measurement_pixmap(record, self.logger)
                            for record in other_records
                        ]
                        other_pixmaps = [
                            pixmap for pixmap in other_pixmaps if isinstance(pixmap, QtGui.QPixmap)
                        ]
                        other_plot = _combine_pixmaps_side_by_side(
                            other_pixmaps,
                            width_px=max(
                                ANNEALING_GRAPH_WIDTH,
                                ANNEALING_GRAPH_WIDTH * max(len(other_pixmaps), 1),
                            ),
                            height_px=ANNEALING_GRAPH_HEIGHT,
                            spacing=self._preview_spacing,
                            scale_to_fit=False,
                        ) if other_pixmaps else None
                        other_plot_path: Optional[Path] = None
                        if other_plot is not None and not other_plot.isNull():
                            other_plot_path = (
                                plot_dir
                                / f"{composition}_{draw_x}_{piece_y}_{suffix or 'base'}_other.png"
                            )
                            other_plot.save(str(other_plot_path), "PNG")
                        image_options = {"x_scale": 0.6, "y_scale": 0.6}
                        if high_plot is not None:
                            worksheet.insert_image(
                                row_idx,
                                4,
                                str(high_plot),
                                image_options,
                            )
                        if other_plot_path is not None:
                            worksheet.insert_image(
                                row_idx,
                                5,
                                str(other_plot_path),
                                image_options,
                            )
                        row_idx += 1
                finally:
                    workbook.close()
        except Exception as exc:
            try:
                if output_path.exists():
                    output_path.unlink()
            except OSError:
                pass
            QtWidgets.QMessageBox.critical(
                self,
                self.section_title,
                f"Failed to export worksheet:\n{exc}",
            )
            return

        self.log(f"Current annealing worksheet saved to {output_path}")
        QtWidgets.QMessageBox.information(
            self,
            self.section_title,
            f"Worksheet saved to {output_path}",
        )


class _MicroscopePreviewLabel(QtWidgets.QLabel):
    def __init__(self, placeholder: str, parent: Optional[QtWidgets.QWidget] = None) -> None:
        super().__init__(placeholder, parent)
        self._placeholder = placeholder
        self._pixmap: Optional[QtGui.QPixmap] = None
        self._scale_timer = QtCore.QTimer(self)
        self._scale_timer.setSingleShot(True)
        self._scale_timer.timeout.connect(self._update_scaled_pixmap)
        self.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self.setFrameShape(QtWidgets.QFrame.Shape.StyledPanel)
        self.setWordWrap(True)

    def set_placeholder(self) -> None:
        try:
            self._scale_timer.stop()
        except Exception:
            pass
        self._pixmap = None
        super().setPixmap(QtGui.QPixmap())
        super().setText(self._placeholder)

    def set_preview(self, pixmap: Optional[QtGui.QPixmap]) -> None:
        if pixmap is None or pixmap.isNull():
            self.set_placeholder()
            return
        self._pixmap = QtGui.QPixmap(pixmap)
        self._schedule_scaled_pixmap()

    def resizeEvent(self, event: QtGui.QResizeEvent) -> None:  # pragma: no cover - Qt callback
        super().resizeEvent(event)
        self._schedule_scaled_pixmap()

    def _schedule_scaled_pixmap(self) -> None:
        if self._pixmap is None:
            return
        try:
            self._scale_timer.start(0)
        except Exception:
            self._update_scaled_pixmap()

    def _update_scaled_pixmap(self) -> None:
        if self._pixmap is None:
            return
        target_size = self.size()
        if target_size.width() <= 0 or target_size.height() <= 0:
            return
        scaled = self._pixmap.scaled(
            target_size,
            QtCore.Qt.AspectRatioMode.KeepAspectRatio,
            QtCore.Qt.TransformationMode.SmoothTransformation,
        )
        super().setPixmap(scaled)
        super().setText("")


class MicroscopeSection(MiniDatabaseSection):
    section_key = "microscope"
    section_title = "Microscope"
    supported_suffixes = MICROSCOPE_EXTENSIONS
    partial_row_ready = QtCore.pyqtSignal(dict)

    def __init__(
        self,
        logger: logging.Logger,
        log_callback: Callable[[int, str], None],
        parent: QtWidgets.QWidget | None = None,
    ) -> None:
        self._overrides: Dict[str, Dict[str, float]] = {}
        self._validated: Dict[str, Dict[str, Any]] = {}
        self._selected_key: str | None = None
        self._pixmap_cache: Dict[Tuple[str, str], Optional[QtGui.QPixmap]] = {}
        self._expected_keys_current: Set[MicrowireKey] = set()
        self._prepopulated_keys: Set[str] = set()
        self._table_splitter: QtWidgets.QSplitter | None = None
        self._active_column: str = ""
        self._pending_advance_key: str | None = None
        self._pending_advance_column: str | None = None
        self._pending_advance_review: bool = False
        self._pending_partial_rows: List[dict] = []
        self._pending_partial_flush = False
        super().__init__(logger, log_callback, parent)
        self._show_other_ends = bool(self.data.extra.get("show_other_ends", True))

        # Removed the missing-items list UI; missing values are visible in the table.
        self._missing_summary_label = None  # type: ignore[assignment]
        self._missing_list = None  # type: ignore[assignment]
        if hasattr(self, "controls_layout"):
            try:
                self.other_end_checkbox = QtWidgets.QCheckBox("Show other ends")
                self.other_end_checkbox.setChecked(self._show_other_ends)
                self.other_end_checkbox.toggled.connect(self._toggle_other_ends)
                self.controls_layout.addWidget(self.other_end_checkbox)
            except Exception:
                pass

        self._load_extra_state()

        # Always normalise the table after load so legacy "Reviewed" columns
        # are removed even when there are no overrides/validations stored.
        self._apply_overrides_to_table(clear_preview_cache=True)
        self._normalise_brittle_column()
        self._refresh_status_column()
        self._update_hidden_columns()
        self._update_missing_summary()
        self.partial_row_ready.connect(
            self._apply_partial_row,
            QtCore.Qt.ConnectionType.QueuedConnection,
        )
        self._update_review_buttons()
        QtCore.QTimer.singleShot(0, self._ensure_table_autosized)
        self._install_diameter_handlers()
        self.model.set_editable_columns({MICROSCOPE_D_COLUMN, MICROSCOPE_CAP_D_COLUMN})
        self.model.set_background_provider(self._background_brush_for_cell)
        self.model.set_foreground_provider(self._foreground_brush_for_cell)
        try:
            self.model.dataChanged.connect(self._handle_cell_edited)
        except Exception:
            pass

    def import_project_payload(self, payload: Mapping[str, Any]) -> None:  # type: ignore[override]
        super().import_project_payload(payload)
        self._load_extra_state()
        self._apply_overrides_to_table(clear_preview_cache=True)
        self._normalise_brittle_column()
        self._refresh_status_column()
        self._show_other_ends = bool(self.data.extra.get("show_other_ends", True))
        if hasattr(self, "other_end_checkbox"):
            self.other_end_checkbox.setChecked(self._show_other_ends)
        self._search_proxy.set_row_predicate(self._row_visible)
        self._update_hidden_columns()
        self._update_missing_summary()
        self._update_review_buttons()
        self._connect_selection_model()
        self._ensure_valid_selection()
        QtCore.QTimer.singleShot(0, self._ensure_table_autosized)

    def apply_data(self, data: MiniDatabaseData) -> None:  # type: ignore[override]
        super().apply_data(data)
        self._load_extra_state()
        self._apply_overrides_to_table(restore_selection=False, clear_preview_cache=True)
        self._normalise_brittle_column()
        self._refresh_status_column()
        self._show_other_ends = bool(self.data.extra.get("show_other_ends", True))
        if hasattr(self, "other_end_checkbox"):
            self.other_end_checkbox.setChecked(self._show_other_ends)
        self._search_proxy.set_row_predicate(self._row_visible)
        self._connect_selection_model()
        self._ensure_valid_selection()

    def _connect_selection_model(self) -> None:
        selection_model = self.table_view.selectionModel() if isinstance(self.table_view, QtWidgets.QTableView) else None
        if selection_model is None:
            return
        try:
            selection_model.selectionChanged.connect(self._handle_selection_changed)
        except Exception:
            pass
        try:
            selection_model.currentChanged.connect(self._handle_current_changed)
        except Exception:
            pass

    def _load_extra_state(self) -> None:
        stored_overrides = self.data.extra.get("overrides")
        if isinstance(stored_overrides, dict):
            self._overrides = {
                str(key): {k: float(v) for k, v in value.items() if isinstance(v, (int, float))}
                for key, value in stored_overrides.items()
                if isinstance(value, dict)
            }
        else:
            self._overrides = {}

        stored_validated = self.data.extra.get("validated")
        if isinstance(stored_validated, dict):
            cleaned: Dict[str, Dict[str, Any]] = {}
            for key, payload in stored_validated.items():
                if not isinstance(payload, dict):
                    continue
                cleaned[str(key)] = dict(payload)
            self._validated = cleaned
        else:
            self._validated = {}

    def _normalise_brittle_column(self) -> None:
        frame = self.data.table if isinstance(self.data.table, pd.DataFrame) else pd.DataFrame()
        if frame.empty:
            return
        updated = frame.copy()
        if BRITTLE_COLUMN not in updated.columns:
            updated[BRITTLE_COLUMN] = None
        changed = False
        for idx, row in updated.iterrows():
            current = row.get(BRITTLE_COLUMN)
            if str(current).strip().lower() == "brittle":
                continue
            sources: List[Path] = []
            image_values = row.get("_images")
            if not isinstance(image_values, (list, tuple, set)):
                image_values = []
            for path_value in image_values:
                try:
                    sources.append(Path(path_value))
                except Exception:
                    continue
            for path_value in (row.get("_core_image"), row.get("_glass_image")):
                if not path_value:
                    continue
                try:
                    candidate = Path(path_value)
                except Exception:
                    continue
                if candidate not in sources:
                    sources.append(candidate)
            core_present = bool(row.get("_core_image"))
            glass_present = bool(row.get("_glass_image"))
            brittle = any(_microscope_is_brittle(path) for path in sources) or (
                glass_present and not core_present
            )
            if (str(current).strip().lower() == "brittle") != brittle:
                updated.at[idx, BRITTLE_COLUMN] = "brittle" if brittle else None
                changed = True
        if not changed and list(updated.columns) == list(frame.columns):
            return
        updated = updated.loc[:, [column for column in MICROSCOPE_TABLE_COLUMNS if column in updated.columns]]
        self.data.table = updated
        self.model.set_frame(updated)
        try:
            self.store.save(self.data)
        except Exception:
            pass

    def create_right_panel(self, parent: QtWidgets.QWidget) -> QtWidgets.QWidget:
        splitter = QtWidgets.QSplitter(QtCore.Qt.Orientation.Horizontal, parent)
        splitter.setChildrenCollapsible(False)
        splitter.setOpaqueResize(False)
        splitter.setStretchFactor(0, 3)
        splitter.setStretchFactor(1, 2)
        self._table_splitter = splitter

        table = QtWidgets.QTableView(splitter)
        table.setModel(self.model)
        header = table.horizontalHeader()
        if header is not None:
            header.setStretchLastSection(True)
            header.setSectionResizeMode(QtWidgets.QHeaderView.ResizeMode.ResizeToContents)
            header.setMinimumSectionSize(60)
        table.setSizePolicy(
            QtWidgets.QSizePolicy.Policy.Expanding,
            QtWidgets.QSizePolicy.Policy.Expanding,
        )
        table.setAlternatingRowColors(True)
        table.setSelectionBehavior(
            QtWidgets.QAbstractItemView.SelectionBehavior.SelectItems
        )
        table.setSelectionMode(
            QtWidgets.QAbstractItemView.SelectionMode.ExtendedSelection
        )
        table.setEditTriggers(
            QtWidgets.QAbstractItemView.EditTrigger.DoubleClicked
            | QtWidgets.QAbstractItemView.EditTrigger.EditKeyPressed
            | QtWidgets.QAbstractItemView.EditTrigger.AnyKeyPressed
        )
        table.setSortingEnabled(True)
        v_header = table.verticalHeader()
        if v_header is not None:
            default_height = 40
            v_header.setDefaultSectionSize(default_height)
            v_header.setMinimumSectionSize(default_height)
        self.table_view = table
        selection_model = table.selectionModel()
        if selection_model is not None:
            selection_model.selectionChanged.connect(self._handle_selection_changed)
            selection_model.currentChanged.connect(self._handle_current_changed)
        table.installEventFilter(self)
        table.clicked.connect(lambda *_args: self._handle_selection_changed())
        table.pressed.connect(lambda *_args: self._handle_selection_changed())
        table.setTabKeyNavigation(False)
        self._tab_forward_shortcut = QtGui.QShortcut(
            QtGui.QKeySequence(QtCore.Qt.Key.Key_Tab),
            table,
        )
        self._tab_forward_shortcut.setContext(
            QtCore.Qt.ShortcutContext.WidgetWithChildrenShortcut
        )
        self._tab_forward_shortcut.activated.connect(
            lambda: self._advance_d_column(True)
        )
        self._tab_backward_shortcut = QtGui.QShortcut(
            QtGui.QKeySequence(QtCore.Qt.Key.Key_Backtab),
            table,
        )
        self._tab_backward_shortcut.setContext(
            QtCore.Qt.ShortcutContext.WidgetWithChildrenShortcut
        )
        self._tab_backward_shortcut.activated.connect(
            lambda: self._advance_d_column(False)
        )

        preview_container = QtWidgets.QWidget(splitter)
        preview_container.setMinimumWidth(360)
        preview_layout = QtWidgets.QVBoxLayout(preview_container)
        preview_layout.setContentsMargins(0, 0, 0, 0)
        preview_layout.setSpacing(6)

        scroll = QtWidgets.QScrollArea(preview_container)
        scroll.setWidgetResizable(True)
        scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        scroll.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        scroll.setSizePolicy(
            QtWidgets.QSizePolicy.Policy.Expanding,
            QtWidgets.QSizePolicy.Policy.Ignored,
        )
        scroll.setMinimumHeight(0)
        preview_layout.addWidget(scroll, 1)

        stack_widget = QtWidgets.QWidget()
        stack_layout = QtWidgets.QVBoxLayout(stack_widget)
        stack_layout.setContentsMargins(0, 0, 0, 0)
        stack_layout.setSpacing(8)

        def _make_preview_panel(title: str) -> tuple[QtWidgets.QWidget, _MicroscopePreviewLabel]:
            panel = QtWidgets.QWidget(stack_widget)
            panel.setSizePolicy(
                QtWidgets.QSizePolicy.Policy.Expanding,
                QtWidgets.QSizePolicy.Policy.Expanding,
            )
            column_layout = QtWidgets.QVBoxLayout(panel)
            column_layout.setContentsMargins(0, 0, 0, 0)
            column_layout.setSpacing(4)
            caption = QtWidgets.QLabel(title, panel)
            caption.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
            caption.setStyleSheet("font-weight: 600;")
            column_layout.addWidget(caption)
            label = _MicroscopePreviewLabel("Select a row to preview.", panel)
            label.setMinimumSize(320, 240)
            label.setSizePolicy(
                QtWidgets.QSizePolicy.Policy.Expanding,
                QtWidgets.QSizePolicy.Policy.Expanding,
            )
            label.setScaledContents(False)
            column_layout.addWidget(label, 1)
            stack_layout.addWidget(panel, 1)
            return panel, label

        self.core_preview_panel, self.core_preview_label = _make_preview_panel("Core image")
        self.glass_preview_panel, self.glass_preview_label = _make_preview_panel("Glass image")
        scroll.setWidget(stack_widget)

        form = QtWidgets.QFormLayout()
        form.setContentsMargins(0, 0, 0, 0)
        form.setSpacing(4)

        self.d_edit = QtWidgets.QLineEdit()
        self.d_edit.setPlaceholderText("auto")
        self.D_edit = QtWidgets.QLineEdit()
        self.D_edit.setPlaceholderText("auto")
        self.d_edit.returnPressed.connect(partial(self._apply_override, MICROSCOPE_D_COLUMN))
        self.D_edit.returnPressed.connect(partial(self._apply_override, MICROSCOPE_CAP_D_COLUMN))
        form.addRow(MICROSCOPE_D_COLUMN, self.d_edit)
        form.addRow(MICROSCOPE_CAP_D_COLUMN, self.D_edit)
        preview_layout.addLayout(form)

        button_row = QtWidgets.QHBoxLayout()
        self.apply_override_button = QtWidgets.QPushButton("Apply override")
        self.apply_override_button.clicked.connect(self._apply_override)
        button_row.addWidget(self.apply_override_button)
        self.clear_override_button = QtWidgets.QPushButton("Clear override")
        self.clear_override_button.clicked.connect(self._clear_override)
        button_row.addWidget(self.clear_override_button)
        self.mark_reviewed_button = QtWidgets.QPushButton("Mark reviewed")
        self.mark_reviewed_button.clicked.connect(self._mark_reviewed)
        button_row.addWidget(self.mark_reviewed_button)
        self.clear_review_button = QtWidgets.QPushButton("Clear review")
        self.clear_review_button.clicked.connect(self._clear_review)
        button_row.addWidget(self.clear_review_button)
        preview_layout.addLayout(button_row)

        return splitter

    def reset_to_blank(self) -> None:  # type: ignore[override]
        super().reset_to_blank()
        self._overrides.clear()
        self._validated.clear()
        self._prepopulated_keys.clear()
        self._expected_keys_current = set()
        self._pixmap_cache.clear()
        self._show_other_ends = True
        if hasattr(self, "other_end_checkbox"):
            self.other_end_checkbox.setChecked(True)
        self._refresh_status_column()
        self._search_proxy.set_row_predicate(self._row_visible)
        self._update_missing_summary()
        self._update_review_buttons()

    def _toggle_other_ends(self, checked: bool) -> None:
        self._show_other_ends = bool(checked)
        self.data.extra["show_other_ends"] = self._show_other_ends
        try:
            self.store.save(self.data)
        except Exception:
            pass
        self._search_proxy.set_row_predicate(self._row_visible)
        self._refresh_status_column()
        self._ensure_valid_selection()

    def _row_visible(self, row: pd.Series) -> bool:  # type: ignore[override]
        if self._show_other_ends:
            return True
        microwire = str(row.get("Microwire") or "").strip()
        parsed = _microwire_parts_from_label_safe(microwire)
        if parsed is None:
            return True
        suffix = str(parsed[2] or "").strip().lower()
        return suffix != "oe"

    def _collect_candidates(self) -> List[Path]:  # type: ignore[override]
        return MiniDatabaseSection._collect_candidates(self)

    def _auto_fit_columns(self) -> None:  # type: ignore[override]
        super()._auto_fit_columns()
        QtCore.QTimer.singleShot(0, self._ensure_table_autosized)

    def _ensure_table_autosized(self) -> None:
        if self._project_load_batch_mode:
            return
        table = self.table_view
        if not isinstance(table, QtWidgets.QTableView):
            return
        try:
            table.resizeColumnsToContents()
        except Exception:
            return
        header = table.horizontalHeader()
        column_count = header.count() if header is not None else 0
        total_width = table.frameWidth() * 2
        v_header = table.verticalHeader()
        if v_header is not None:
            try:
                total_width += v_header.sizeHint().width()
            except Exception:
                total_width += v_header.width()
        for index in range(column_count):
            total_width += table.columnWidth(index)
        max_width = None
        try:
            window = self.window()
            if isinstance(window, QtWidgets.QWidget):
                screen = QtGui.QGuiApplication.screenAt(
                    window.mapToGlobal(window.rect().center())
                )
                if screen is None:
                    screen = QtGui.QGuiApplication.primaryScreen()
                if screen is not None:
                    max_width = max(640, screen.availableGeometry().width() - 200)
        except Exception:
            max_width = None
        if total_width > 0:
            preview_min = 360
            table_min = 480
            available_width = (
                max_width
                if max_width is not None
                else total_width + preview_min + 200
            )
            available_width = max(available_width, table_min + preview_min + 80)
            table_target = min(max(total_width, table_min), available_width - preview_min)
            preview_target = max(preview_min, available_width - table_target)
            if preview_target < preview_min and available_width > preview_min:
                preview_target = preview_min
                table_target = max(table_min, available_width - preview_target)
            table.setMinimumWidth(table_min)
            table.setMaximumWidth(max(table_min, available_width - preview_min))
        splitter = self._table_splitter
        if isinstance(splitter, QtWidgets.QSplitter) and column_count:
            sizes = splitter.sizes()
            total = sum(sizes) if sizes and any(sizes) else (total_width + 360)
            if max_width is not None:
                total = max(total, max_width)
            table_target = min(max(total_width, 480), total - 360)
            preview_target = total - table_target
            preview_target = max(preview_target, 360)
            splitter.setSizes([table_target, preview_target])

    def _expected_microwire_keys(self) -> Set[MicrowireKey]:
        keys: Set[MicrowireKey] = set()
        try:
            annealing_records = MiniDatabaseStore("annealing").load_payload(
                "annealing_records"
            )
        except Exception:
            annealing_records = None
        if not isinstance(annealing_records, list):
            return keys
        for record in annealing_records:
            metadata = getattr(record, "metadata", None)
            if metadata is None:
                continue
            composition = getattr(metadata, "composition_token", None)
            draw = getattr(metadata, "draw_x", None)
            piece = getattr(metadata, "piece_y", None)
            if not composition or draw is None or piece is None:
                continue
            suffix = None
            path = getattr(record, "path", None)
            if isinstance(path, Path):
                suffix = _microscope_expected_suffix_from_path(path)
            try:
                keys.add((str(composition), int(draw), int(piece), suffix))
            except (TypeError, ValueError):
                continue
        keys.update(self._extra_expected_keys())
        return keys

    def _extra_expected_keys(self) -> Set[MicrowireKey]:
        extra: Set[MicrowireKey] = set()
        tokens = set(self._overrides.keys()) | set(self._validated.keys())
        for token in tokens:
            if not token:
                continue
            parts = _microwire_key_from_string(str(token))
            if parts is not None:
                extra.add(parts)
        return extra

    def _protected_key_tokens(self) -> Set[str]:
        return {str(key) for key in self._overrides.keys()} | {str(key) for key in self._validated.keys()}

    def _build_initial_table_frame(self, expected_keys: Set[MicrowireKey]) -> pd.DataFrame:
        frame = self.data.table if isinstance(self.data.table, pd.DataFrame) else pd.DataFrame()
        if frame.empty:
            frame = pd.DataFrame(columns=MICROSCOPE_TABLE_COLUMNS)
        else:
            frame = frame.copy()
        if expected_keys:
            allowed = {
                _microwire_key_to_str((composition, draw, piece, suffix))
                for composition, draw, piece, suffix in expected_keys
            }
            allowed.update(self._protected_key_tokens())
            if "_key" in frame.columns:
                try:
                    mask = frame["_key"].astype(str).isin(allowed)
                    frame = frame.loc[mask].reset_index(drop=True)
                except Exception:
                    pass
            else:
                filtered_rows: List[int] = []
                for idx, row in frame.iterrows():
                    composition = str(row.get("Composition", "")).strip()
                    microwire_label = str(row.get("Microwire", "")).strip()
                    wire_tuple = _microwire_parts_from_label_safe(microwire_label)
                    if wire_tuple is None:
                        continue
                    draw, piece, suffix = wire_tuple
                    key_str = _microwire_key_to_str(
                        (composition, int(draw), int(piece), suffix)
                    )
                    if key_str in allowed:
                        filtered_rows.append(idx)
                if filtered_rows:
                    frame = frame.loc[filtered_rows].reset_index(drop=True)
        for column in MICROSCOPE_TABLE_COLUMNS:
            if column not in frame.columns:
                frame[column] = pd.Series([None] * len(frame))
        existing_keys = set(str(key) for key in frame.get("_key", []))
        new_rows: List[Dict[str, object]] = []
        for composition, draw, piece, suffix in sorted(
            expected_keys,
            key=lambda key: (
                str(key[0]).lower(),
                int(key[1]),
                int(key[2]),
                (str(key[3]).lower() if key[3] is not None else ""),
            ),
        ):
            key_str = _microwire_key_to_str((composition, draw, piece, suffix))
            if key_str in existing_keys:
                continue
            new_rows.append(
                {
                    "Composition": composition,
                    "Microwire": _microwire_label(draw, piece, suffix),
                    MICROSCOPE_D_COLUMN: None,
                    MICROSCOPE_CAP_D_COLUMN: None,
                    "d/D": None,
                    MICROSCOPE_STATUS_COLUMN: None,
                    BRITTLE_COLUMN: None,
                    MICROSCOPE_IMAGE_COLUMNS[0]: None,
                    MICROSCOPE_IMAGE_COLUMNS[1]: None,
                    "_key": key_str,
                    "_core_image": None,
                    "_glass_image": None,
                    "_images": [],
                }
            )
        if new_rows:
            if frame.empty:
                frame = pd.DataFrame(new_rows)
            else:
                try:
                    base_frame = frame.dropna(how="all")
                except Exception:
                    base_frame = frame
                existing_rows = (
                    base_frame.to_dict(orient="records")
                    if not base_frame.empty
                    else []
                )
                frame = pd.DataFrame(existing_rows + new_rows)
        frame = frame.loc[:, MICROSCOPE_TABLE_COLUMNS]
        frame = self._with_status_column(frame)
        frame = frame.sort_values(["Composition", "Microwire"]).reset_index(drop=True)
        return frame

    def _prepare_initial_table(self, expected_keys: Set[MicrowireKey]) -> None:
        frame = self._build_initial_table_frame(expected_keys)
        self.data.table = frame
        self.model.set_frame(frame)
        self._auto_fit_columns()
        self._update_missing_summary()

    def _merge_rows_into_frame(
        self,
        frame: pd.DataFrame,
        rows: Sequence[Mapping[str, Any]],
    ) -> pd.DataFrame:
        if not rows:
            if isinstance(frame, pd.DataFrame):
                return frame.copy()
            return pd.DataFrame(columns=MICROSCOPE_TABLE_COLUMNS)
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            columns: List[object] = []
            for row in rows:
                for column in row.keys():
                    if column not in columns:
                        columns.append(column)
            merged = pd.DataFrame(columns=columns)
        else:
            merged = frame.copy()
        if "_key" not in merged.columns:
            merged["_key"] = pd.Series([None] * len(merged))
        existing_rows: List[Dict[str, Any]] = []
        if not merged.empty:
            try:
                cleaned_frame = merged.dropna(how="all")
            except Exception:
                cleaned_frame = merged
            if not cleaned_frame.empty:
                existing_rows = [
                    dict(existing_row)
                    for existing_row in cleaned_frame.to_dict(orient="records")
                ]
        row_map: Dict[str, Dict[str, Any]] = {}
        ordered_keys: List[str] = []
        for existing_row in existing_rows:
            key = str(existing_row.get("_key", ""))
            row_map[key] = existing_row
            ordered_keys.append(key)
        for row in rows:
            key = str(row.get("_key", ""))
            target = row_map.get(key)
            if target is None:
                target = {}
                row_map[key] = target
                ordered_keys.append(key)
            for column, value in row.items():
                target[column] = value
        merged = pd.DataFrame([row_map[key] for key in ordered_keys if key in row_map])
        for column in MICROSCOPE_TABLE_COLUMNS:
            if column not in merged.columns:
                merged[column] = pd.Series([None] * len(merged))
        merged = merged.loc[:, MICROSCOPE_TABLE_COLUMNS]
        merged = self._with_status_column(merged)
        return merged

    def _build_image_ref_rows(
        self,
        candidates: Iterable[Path],
        expected_keys: Set[MicrowireKey],
        frame: pd.DataFrame,
    ) -> List[Dict[str, Any]]:
        candidate_list = [Path(path) for path in candidates]
        expected = set(expected_keys)
        for path in candidate_list:
            key_tuple = _microscope_key(path)
            if key_tuple is not None:
                expected.add(key_tuple)
        allowed: Set[str] | None = None
        if expected:
            allowed = set()
            for item in expected:
                composition: object
                draw: object
                piece: object
                suffix: object | None
                try:
                    composition, draw, piece, suffix = item  # type: ignore[misc]
                except Exception:
                    try:
                        composition, draw, piece = item  # type: ignore[misc]
                    except Exception:
                        continue
                    suffix = None
                try:
                    key_token = _microwire_key_to_str(
                        (str(composition), int(draw), int(piece), suffix)
                    )
                except Exception:
                    continue
                allowed.add(key_token)
        grouped: Dict[str, Dict[str, Any]] = {}
        for path in candidate_list:
            key_tuple = _microscope_key(path)
            if key_tuple is None:
                continue
            composition, draw, piece, suffix = key_tuple
            key = _microwire_key_to_str((composition, draw, piece, suffix))
            if allowed is not None and key not in allowed:
                continue
            entry = grouped.setdefault(
                key,
                {
                    "_key": key,
                    "Composition": composition,
                    "Microwire": _microwire_label(draw, piece, suffix),
                    "_images": [],
                },
            )
            images: List[str] = entry.setdefault("_images", [])  # type: ignore[assignment]
            image_path = str(path)
            if image_path not in images:
                images.append(image_path)
            category = _microscope_category(path)
            if category == "core" and not entry.get("_core_image"):
                entry["_core_image"] = image_path
            elif category == "glass" and not entry.get("_glass_image"):
                entry["_glass_image"] = image_path

        existing_row_map: Dict[str, Dict[str, Any]] = {}
        if isinstance(frame, pd.DataFrame) and not frame.empty:
            try:
                for row in frame.to_dict(orient="records"):
                    existing_row_map[str(row.get("_key", ""))] = dict(row)
            except Exception:
                existing_row_map = {}

        rows_to_apply: List[Dict[str, Any]] = []
        for key, payload in grouped.items():
            images_list = payload.get("_images", [])
            if isinstance(images_list, list):
                payload["_images"] = list(dict.fromkeys(images_list))
            existing_row = existing_row_map.get(key, {})
            existing_d = existing_row.get(MICROSCOPE_D_COLUMN)
            existing_D = existing_row.get(MICROSCOPE_CAP_D_COLUMN)
            existing_ratio = existing_row.get("d/D")
            existing_brittle = existing_row.get(BRITTLE_COLUMN)
            existing_core_image = existing_row.get("_core_image")
            existing_glass_image = existing_row.get("_glass_image")
            existing_images = existing_row.get("_images")
            merged_images: List[str] = []
            if isinstance(existing_images, (list, tuple)):
                merged_images.extend(str(item) for item in existing_images if item)
            merged_images.extend(str(item) for item in payload.get("_images", []) if item)
            merged_images = list(dict.fromkeys(merged_images))
            rows_to_apply.append(
                {
                    "Composition": payload.get("Composition", ""),
                    "Microwire": payload.get("Microwire", ""),
                    MICROSCOPE_D_COLUMN: existing_d,
                    MICROSCOPE_CAP_D_COLUMN: existing_D,
                    "d/D": existing_ratio,
                    MICROSCOPE_STATUS_COLUMN: None,
                    BRITTLE_COLUMN: (
                        existing_brittle
                        if existing_brittle
                        else (
                            "brittle"
                            if (
                                any("brittle" in str(item).lower() for item in merged_images)
                                or (
                                    (payload.get("_glass_image") or existing_glass_image)
                                    and not (payload.get("_core_image") or existing_core_image)
                                )
                            )
                            else None
                        )
                    ),
                    MICROSCOPE_IMAGE_COLUMNS[0]: None,
                    MICROSCOPE_IMAGE_COLUMNS[1]: None,
                    "_key": key,
                    "_core_image": payload.get("_core_image") or existing_core_image,
                    "_glass_image": payload.get("_glass_image") or existing_glass_image,
                    "_images": merged_images,
                }
            )
        return rows_to_apply

    @staticmethod
    def _is_valid_diameter(value: object) -> bool:
        try:
            numeric = float(value)
        except (TypeError, ValueError):
            return False
        return math.isfinite(numeric) and numeric > 0

    def _validated_value(self, key: str, column: str) -> Optional[float]:
        entry = self._validated.get(key)
        if not isinstance(entry, dict):
            return None
        has_flags = "d_reviewed" in entry or "D_reviewed" in entry
        if column == MICROSCOPE_D_COLUMN:
            if has_flags and not entry.get("d_reviewed"):
                return None
            value = entry.get("d")
        elif column == MICROSCOPE_CAP_D_COLUMN:
            if has_flags and not entry.get("D_reviewed"):
                return None
            value = entry.get("D")
        else:
            return None
        if not self._is_valid_diameter(value):
            return None
        return float(value)

    def _record_to_row(
        self,
        key: MicrowireKey,
        measurement: MicroscopeMeasurements,
    ) -> Dict[str, object]:
        composition, draw, piece, suffix = key
        key_str = _microwire_key_to_str((composition, draw, piece, suffix))
        override = self._overrides.get(key_str, {})

        d_value = override.get("d")
        if d_value is None:
            core_detection = measurement.best_core_detection()
            if (
                isinstance(core_detection, MicroscopeDetection)
                and getattr(core_detection, "category", None) == "core"
                and self._is_valid_diameter(getattr(core_detection, "value", None))
            ):
                try:
                    d_value = float(core_detection.value)
                except (TypeError, ValueError):
                    d_value = None
        if d_value is None:
            validated = self._validated_value(key_str, MICROSCOPE_D_COLUMN)
            if validated is not None:
                d_value = validated

        D_value = override.get("D")
        if D_value is None:
            glass_detection = measurement.best_glass_detection()
            if (
                isinstance(glass_detection, MicroscopeDetection)
                and getattr(glass_detection, "category", None) == "glass"
                and self._is_valid_diameter(getattr(glass_detection, "value", None))
            ):
                try:
                    D_value = float(glass_detection.value)
                except (TypeError, ValueError):
                    D_value = None
        if D_value is None:
            validated = self._validated_value(key_str, MICROSCOPE_CAP_D_COLUMN)
            if validated is not None:
                D_value = validated

        ratio = None
        if isinstance(d_value, (int, float)) and isinstance(D_value, (int, float)) and D_value:
            try:
                ratio = round(float(d_value) / float(D_value), 3)
            except ZeroDivisionError:
                ratio = None

        def _first_image(entries: Sequence[MicroscopeDetection]) -> Optional[str]:
            for detection in entries:
                crop = getattr(detection, "crop_path", None)
                if crop:
                    return str(crop)
                source = getattr(detection, "image_path", None)
                if source:
                    return str(source)
            return None

        core_image = _first_image(measurement.core)
        glass_image = _first_image(measurement.glass)
        image_paths: List[str] = []
        for bucket in (measurement.core, measurement.glass, measurement.other):
            for detection in bucket:
                path = getattr(detection, "image_path", None)
                if path:
                    image_paths.append(str(path))
        if image_paths:
            image_paths = list(dict.fromkeys(image_paths))

        return {
            "Composition": composition,
            "Microwire": _microwire_label(draw, piece, suffix),
            MICROSCOPE_D_COLUMN: d_value,
            MICROSCOPE_CAP_D_COLUMN: D_value,
            "d/D": ratio,
            MICROSCOPE_STATUS_COLUMN: None,
            MICROSCOPE_IMAGE_COLUMNS[0]: None,
            MICROSCOPE_IMAGE_COLUMNS[1]: None,
            "_key": key_str,
            "_core_image": core_image,
            "_glass_image": glass_image,
            "_images": image_paths,
        }

    def _apply_partial_row(self, row: dict) -> None:
        table = self.table_view
        if (
            isinstance(table, QtWidgets.QTableView)
            and table.state() == QtWidgets.QAbstractItemView.State.EditingState
        ):
            self._pending_partial_rows.append(row)
            if not self._pending_partial_flush:
                self._pending_partial_flush = True
                QtCore.QTimer.singleShot(0, self._flush_pending_partial_rows)
            return
        self._apply_partial_row_now(row)

    def _flush_pending_partial_rows(self) -> None:
        self._pending_partial_flush = False
        table = self.table_view
        if (
            isinstance(table, QtWidgets.QTableView)
            and table.state() == QtWidgets.QAbstractItemView.State.EditingState
        ):
            self._pending_partial_flush = True
            QtCore.QTimer.singleShot(50, self._flush_pending_partial_rows)
            return
        if not self._pending_partial_rows:
            return
        pending = list(self._pending_partial_rows)
        self._pending_partial_rows.clear()
        self._apply_partial_rows_now(pending)

    def _apply_partial_row_now(self, row: dict) -> None:
        self._apply_partial_rows_now([row])

    def _apply_partial_rows_now(self, rows: Sequence[dict]) -> None:
        if not rows:
            return
        frame = self.data.table if isinstance(self.data.table, pd.DataFrame) else pd.DataFrame()
        frame = self._merge_rows_into_frame(frame, rows)
        frame = self._with_status_column(frame)
        self.data.table = frame
        self.model.set_frame(frame)
        self._auto_fit_columns()
        self._update_missing_summary()

    def _update_missing_summary(self) -> None:
        if getattr(self, "_missing_list", None) is None:
            return
        frame = self.data.table if isinstance(self.data.table, pd.DataFrame) else pd.DataFrame()
        missing_entries: List[Tuple[str, str]] = []
        missing_d = 0
        missing_D = 0
        missing_core_images = 0
        missing_glass_images = 0
        if not frame.empty and "_key" in frame.columns:
            for _, row in frame.iterrows():
                key = str(row.get("_key", ""))
                composition = str(row.get("Composition", "") or "")
                microwire = str(row.get("Microwire", "") or "")
                needs: List[str] = []
                d_value = row.get(MICROSCOPE_D_COLUMN)
                D_value = row.get(MICROSCOPE_CAP_D_COLUMN)
                if not self._is_valid_diameter(d_value):
                    missing_d += 1
                    needs.append("d")
                if not self._is_valid_diameter(D_value):
                    missing_D += 1
                    needs.append("D")
                if not row.get("_core_image"):
                    missing_core_images += 1
                if not row.get("_glass_image"):
                    missing_glass_images += 1
                if needs:
                    label = f"{composition} {microwire} (missing {', '.join(needs)})".strip()
                    missing_entries.append((key, label))
        summary_parts = []
        summary_parts.append(f"Missing d: {missing_d}")
        summary_parts.append(f"Missing D: {missing_D}")
        summary_parts.append(f"Missing core images: {missing_core_images}")
        summary_parts.append(f"Missing glass images: {missing_glass_images}")
        summary_text = " | ".join(summary_parts)
        self._missing_summary_label.setText(summary_text)
        self._missing_summary_label.setVisible(True)

        self._missing_list.clear()
        if missing_entries:
            for key, label in missing_entries:
                item = QtWidgets.QListWidgetItem(label)
                item.setData(QtCore.Qt.ItemDataRole.UserRole, key)
                self._missing_list.addItem(item)
            self._missing_list.setVisible(True)
        else:
            self._missing_list.setVisible(False)

    def _install_diameter_handlers(self) -> None:
        for edit in (self.d_edit, self.D_edit):
            try:
                edit.textEdited.connect(partial(self._normalize_decimal_input, edit))
            except Exception:
                pass
            for key, handler in (
                (QtCore.Qt.Key.Key_Up, self._select_previous_row),
                (QtCore.Qt.Key.Key_Down, self._select_next_row),
            ):
                shortcut = QtGui.QShortcut(QtGui.QKeySequence(key), edit)
                shortcut.setContext(QtCore.Qt.ShortcutContext.WidgetShortcut)
                shortcut.activated.connect(handler)

    def _normalize_decimal_input(self, edit: QtWidgets.QLineEdit, text: str) -> None:
        normalized = text.replace(",", ".")
        if normalized == text:
            return
        cursor = edit.cursorPosition()
        delta = len(normalized) - len(text)
        blocker = QtCore.QSignalBlocker(edit)
        try:
            edit.setText(normalized)
        finally:
            del blocker
        try:
            edit.setCursorPosition(max(0, cursor + delta))
        except Exception:
            pass

    def _normalized_decimal_text(self, edit: QtWidgets.QLineEdit) -> str:
        return edit.text().replace(",", ".").strip()

    def _select_previous_row(self) -> None:
        self._move_selection(-1)

    def _select_next_row(self) -> None:
        self._move_selection(1)

    def _move_selection(self, offset: int) -> None:
        if not isinstance(self.table_view, QtWidgets.QTableView):
            return
        model = self.table_view.model()
        selection = self.table_view.selectionModel()
        if model is None or selection is None:
            return
        row_count = model.rowCount()
        if row_count <= 0:
            return
        current_index = selection.currentIndex()
        current_row = current_index.row() if current_index.isValid() else 0
        current_col = current_index.column() if current_index.isValid() else 0
        new_row = max(0, min(row_count - 1, current_row + offset))
        target_index = model.index(new_row, max(0, current_col))
        if target_index.isValid():
            selection.setCurrentIndex(
                target_index,
                QtCore.QItemSelectionModel.SelectionFlag.ClearAndSelect,
            )
        try:
            self.table_view.scrollTo(
                model.index(new_row, max(0, current_col)),
            QtWidgets.QAbstractItemView.ScrollHint.PositionAtCenter,
        )
        except Exception:
            pass
        self._focus_d_input(select_all=True)

    def eventFilter(self, obj: QtCore.QObject, event: QtCore.QEvent) -> bool:
        if obj is self.table_view and event.type() == QtCore.QEvent.Type.KeyPress:
            key_event = cast(QtGui.QKeyEvent, event)
            key = key_event.key()
            if key in (QtCore.Qt.Key.Key_Return, QtCore.Qt.Key.Key_Enter):
                index = self._current_index()
                if index.isValid():
                    try:
                        column_label = str(self.model.frame().columns[index.column()])
                    except Exception:
                        column_label = ""
                    if column_label in {MICROSCOPE_D_COLUMN, MICROSCOPE_CAP_D_COLUMN}:
                        if (
                            isinstance(self.table_view, QtWidgets.QTableView)
                            and self.table_view.state()
                            == QtWidgets.QAbstractItemView.State.EditingState
                        ):
                            key_value = self._selected_key
                            if not key_value:
                                row = self._selected_row()
                                raw_key = row.get("_key") if row is not None else None
                                if raw_key is not None:
                                    key_value = str(raw_key)
                            self._queue_editor_commit_advance(key_value, column_label)
                            return False
                        self._mark_reviewed_and_advance(column_label)
                        return True
        return super().eventFilter(obj, event)

    def _mark_reviewed_and_advance_for_key(self, key: str, column_label: str) -> None:
        self._select_row_for_key(key, column_label=column_label)
        self._mark_reviewed_and_advance(column_label)

    def _queue_editor_commit_advance(self, key: Optional[str], column_label: str) -> None:
        key_text = str(key).strip() if key else ""
        if not key_text or not column_label:
            return

        def _advance() -> None:
            row = self._row_for_key(key_text)
            if row is None:
                return
            self._select_row_for_key(key_text, column_label=column_label)
            self._selected_key = key_text
            if self._is_valid_diameter(row.get(column_label)):
                self._mark_reviewed(auto=True, columns={column_label})
            self._advance_to_next_pending(column_label)

        QtCore.QTimer.singleShot(75, _advance)

    def _mark_reviewed_and_advance(self, column_label: str) -> None:
        index = self._current_index()
        if not index.isValid():
            return
        self._mark_reviewed(auto=True, columns={column_label})
        self._advance_to_next_pending(column_label)

    def _advance_after_review(self, index: QtCore.QModelIndex, column_label: str) -> None:
        if not isinstance(self.table_view, QtWidgets.QTableView):
            return
        model = self.table_view.model()
        selection = self.table_view.selectionModel()
        if model is None or selection is None:
            return
        columns = list(self.model.frame().columns)
        try:
            d_col = columns.index(MICROSCOPE_D_COLUMN)
            D_col = columns.index(MICROSCOPE_CAP_D_COLUMN)
        except ValueError:
            return
        row_count = model.rowCount()
        if row_count <= 0:
            return
        target_row = index.row()
        target_col = index.column()
        if column_label == MICROSCOPE_D_COLUMN:
            target_col = D_col
        elif column_label == MICROSCOPE_CAP_D_COLUMN and target_row + 1 < row_count:
            target_row += 1
            target_col = d_col
        target = model.index(target_row, target_col)
        if not target.isValid():
            return
        selection.setCurrentIndex(
            target,
            QtCore.QItemSelectionModel.SelectionFlag.ClearAndSelect,
        )
        try:
            self.table_view.scrollTo(
                target,
                QtWidgets.QAbstractItemView.ScrollHint.PositionAtCenter,
            )
        except Exception:
            pass
        try:
            self.table_view.setFocus(QtCore.Qt.FocusReason.OtherFocusReason)
        except Exception:
            pass

    def _advance_to_next_pending(self, column_label: str) -> None:
        frame = self.model.frame()
        if frame.empty:
            return
        index = self._current_index()
        if not index.isValid():
            return
        row = self._source_row(index.row())
        if row is None:
            return
        order = [MICROSCOPE_D_COLUMN, MICROSCOPE_CAP_D_COLUMN]
        try:
            current_idx = order.index(column_label)
        except ValueError:
            current_idx = 0
        candidates: List[Tuple[int, str]] = []
        for row_idx in range(row, len(frame.index)):
            start = current_idx + 1 if row_idx == row else 0
            for label in order[start:]:
                candidates.append((row_idx, label))
        for row_idx in range(0, row + 1):
            limit = current_idx if row_idx == row else len(order)
            for label in order[:limit]:
                candidates.append((row_idx, label))

        for row_idx, label in candidates:
            row_series = frame.iloc[row_idx]
            key = str(row_series.get("_key") or "").strip()
            if not key:
                continue
            value = row_series.get(label)
            if (not self._is_valid_diameter(value)) or (not self._is_cell_reviewed(key, label)):
                self._select_row_for_key(key, label)
                try:
                    self.table_view.setFocus(QtCore.Qt.FocusReason.OtherFocusReason)
                except Exception:
                    pass
                return

    def _close_table_editor(self) -> None:
        table = self.table_view
        if not isinstance(table, QtWidgets.QTableView):
            return
        editor = table.focusWidget()
        if editor is None or editor is table:
            return
        try:
            table.closeEditor(
                editor,
                QtWidgets.QAbstractItemDelegate.EndEditHint.NoHint,
            )
        except Exception:
            pass

    def _advance_d_column(self, forward: bool) -> None:
        if not isinstance(self.table_view, QtWidgets.QTableView):
            return
        model = self.table_view.model()
        selection = self.table_view.selectionModel()
        if model is None or selection is None:
            return
        frame = self.model.frame()
        columns = list(frame.columns) if hasattr(frame, "columns") else []
        try:
            d_col = columns.index(MICROSCOPE_D_COLUMN)
            D_col = columns.index(MICROSCOPE_CAP_D_COLUMN)
        except ValueError:
            return
        row_count = model.rowCount()
        if row_count <= 0:
            return
        current = selection.currentIndex()
        row = current.row() if current.isValid() else 0
        col = current.column() if current.isValid() else d_col
        if forward:
            if col == d_col:
                target_row, target_col = row, D_col
            elif col == D_col:
                target_row = min(row + 1, row_count - 1)
                target_col = d_col
            else:
                target_row, target_col = row, d_col
        else:
            if col == D_col:
                target_row, target_col = row, d_col
            elif col == d_col:
                target_row = max(row - 1, 0)
                target_col = D_col if row > 0 else d_col
            else:
                target_row, target_col = row, d_col
        target = model.index(target_row, target_col)
        if not target.isValid():
            return
        self._close_table_editor()
        selection.setCurrentIndex(
            target,
            QtCore.QItemSelectionModel.SelectionFlag.ClearAndSelect,
        )
        try:
            self.table_view.scrollTo(
                target,
                QtWidgets.QAbstractItemView.ScrollHint.PositionAtCenter,
            )
        except Exception:
            pass
        try:
            self.table_view.edit(target)
        except Exception:
            pass

    def _background_brush_for_cell(self, row: pd.Series, column: str) -> Optional[QtGui.QBrush]:
        missing_images = self._row_missing_images(row)
        if missing_images:
            return QtGui.QBrush(QtGui.QColor("#3a0a0a"))
        key = str(row.get("_key", ""))
        if column in {MICROSCOPE_D_COLUMN, MICROSCOPE_CAP_D_COLUMN}:
            value = row.get(column)
            if not self._is_valid_diameter(value):
                return QtGui.QBrush(QtGui.QColor("#3a0a0a"))
            reviewed = self._is_cell_reviewed(key, column)
            return QtGui.QBrush(QtGui.QColor("#0f3b26" if reviewed else "#3a0a0a"))
        return None

    def _foreground_brush_for_cell(self, row: pd.Series, column: str) -> Optional[QtGui.QBrush]:
        missing_images = self._row_missing_images(row)
        if missing_images:
            return QtGui.QBrush(QtGui.QColor("#ffd6d6"))
        key = str(row.get("_key", ""))
        if column in {MICROSCOPE_D_COLUMN, MICROSCOPE_CAP_D_COLUMN}:
            value = row.get(column)
            if not self._is_valid_diameter(value):
                return QtGui.QBrush(QtGui.QColor("#ef4444"))
            reviewed = self._is_cell_reviewed(key, column)
            return QtGui.QBrush(QtGui.QColor("#22c55e" if reviewed else "#ef4444"))
        return None

    def _reviewed_for_row(self, key: str, column: str, row: pd.Series) -> bool:
        entry = self._validated.get(key)
        if not isinstance(entry, dict):
            return False
        has_flags = "d_reviewed" in entry or "D_reviewed" in entry
        if column == MICROSCOPE_D_COLUMN:
            reviewed = bool(entry.get("d_reviewed")) if has_flags else True
        elif column == MICROSCOPE_CAP_D_COLUMN:
            reviewed = bool(entry.get("D_reviewed")) if has_flags else True
        else:
            return False
        return bool(reviewed and self._is_valid_diameter(row.get(column)))

    def _status_for_row(self, row: pd.Series) -> str:
        key = str(row.get("_key") or "").strip()
        suffix = ""
        parsed = _microwire_key_from_string(key) if key else None
        if parsed is not None:
            suffix = str(parsed[3] or "").strip().lower()
        prefix = "Other end - " if suffix == "oe" else ""

        brittle = str(row.get(BRITTLE_COLUMN) or "").strip().lower() == "brittle"
        core_present = self._has_image_value(row.get("_core_image"))
        glass_present = self._has_image_value(row.get("_glass_image"))
        images = row.get("_images")
        has_any_image = bool(images) if isinstance(images, (list, tuple, set)) else False
        if not core_present and not glass_present and not has_any_image:
            return f"{prefix}Missing image"
        missing_labeled: List[str] = []
        if not brittle and not core_present:
            missing_labeled.append("core")
        if not glass_present:
            missing_labeled.append("glass")
        if missing_labeled:
            return f"{prefix}Image found; missing {'/'.join(missing_labeled)} label"

        d_valid = self._is_valid_diameter(row.get(MICROSCOPE_D_COLUMN))
        D_valid = self._is_valid_diameter(row.get(MICROSCOPE_CAP_D_COLUMN))
        if not d_valid or not D_valid:
            missing_values = []
            if not d_valid:
                missing_values.append("d")
            if not D_valid:
                missing_values.append("D")
            return f"{prefix}Image found; enter/review {' and '.join(missing_values)}"

        d_reviewed = self._reviewed_for_row(key, MICROSCOPE_D_COLUMN, row)
        D_reviewed = self._reviewed_for_row(key, MICROSCOPE_CAP_D_COLUMN, row)
        if not d_reviewed or not D_reviewed:
            return f"{prefix}Values need review"
        return f"{prefix}Reviewed"

    @staticmethod
    def _has_image_value(value: object) -> bool:
        if value is None:
            return False
        try:
            if pd.isna(value):
                return False
        except (TypeError, ValueError):
            pass
        if isinstance(value, str):
            text = value.strip()
            return bool(text and text.lower() not in {"nan", "none"})
        return bool(value)

    def _with_status_column(self, frame: pd.DataFrame) -> pd.DataFrame:
        if not isinstance(frame, pd.DataFrame):
            return pd.DataFrame(columns=MICROSCOPE_TABLE_COLUMNS)
        updated = frame.copy()
        for column in MICROSCOPE_TABLE_COLUMNS:
            if column not in updated.columns:
                updated[column] = pd.Series([None] * len(updated))
        if updated.empty:
            return updated.loc[:, MICROSCOPE_TABLE_COLUMNS]
        for index, row in updated.iterrows():
            updated.at[index, MICROSCOPE_STATUS_COLUMN] = self._status_for_row(row)
        return updated.loc[:, MICROSCOPE_TABLE_COLUMNS]

    def _refresh_status_column(self) -> None:
        selected_key = self._selected_key
        active_column = self._active_column
        if not selected_key:
            row = self._selected_row()
            if row is not None:
                raw_key = row.get("_key")
                selected_key = str(raw_key) if raw_key is not None else None
        frame = self.data.table if isinstance(self.data.table, pd.DataFrame) else pd.DataFrame()
        updated = self._with_status_column(frame)
        self.data.table = updated
        self.model.set_frame(updated)
        if selected_key:
            self._select_row_for_key(selected_key, active_column or None)

    def _is_cell_reviewed(self, key: str, column: str) -> bool:
        row = self._row_for_key(key)
        if row is None:
            return False
        return self._reviewed_for_row(key, column, row)

    def _row_missing_images(self, row: pd.Series) -> bool:
        brittle = bool(row.get(BRITTLE_COLUMN))
        core_present = self._has_image_value(row.get("_core_image"))
        glass_present = self._has_image_value(row.get("_glass_image"))
        extras = row.get("_images")
        if not core_present and isinstance(extras, (list, tuple)) and extras:
            core_present = True
        if not glass_present and isinstance(extras, (list, tuple)) and extras:
            glass_present = True
        if brittle:
            return not glass_present
        return not (core_present and glass_present)

    def _row_for_key(self, key: str) -> Optional[pd.Series]:
        frame = self.model.frame()
        if frame.empty or "_key" not in frame.columns:
            return None
        try:
            matches = frame.index[frame["_key"] == key].tolist()
        except Exception:
            return None
        if not matches:
            return None
        try:
            return frame.iloc[matches[0]]
        except Exception:
            return None

    def _sync_review_flags_for_row(self, key: str, row: pd.Series) -> bool:
        entry = self._validated.get(key)
        if not isinstance(entry, dict):
            return False
        changed = False
        if not self._is_valid_diameter(row.get(MICROSCOPE_D_COLUMN)):
            if "d_reviewed" in entry:
                entry.pop("d_reviewed", None)
                changed = True
            if "d" in entry:
                entry.pop("d", None)
                changed = True
        if not self._is_valid_diameter(row.get(MICROSCOPE_CAP_D_COLUMN)):
            if "D_reviewed" in entry:
                entry.pop("D_reviewed", None)
                changed = True
            if "D" in entry:
                entry.pop("D", None)
                changed = True
        if not changed:
            return False
        if not entry.get("d_reviewed") and not entry.get("D_reviewed"):
            self._validated.pop(key, None)
        else:
            self._validated[key] = entry
        return True

    def _handle_cell_edited(
        self,
        top_left: QtCore.QModelIndex,
        bottom_right: QtCore.QModelIndex,
        roles: list[int] | None = None,
    ) -> None:
        if roles and QtCore.Qt.ItemDataRole.EditRole not in roles and QtCore.Qt.ItemDataRole.DisplayRole not in roles:
            return
        frame = self.model.frame()
        self.data.table = frame.copy()
        validation_changed = False
        advance_request: Tuple[str, str] | None = None
        edited_rows = range(top_left.row(), bottom_right.row() + 1)
        for row_idx in edited_rows:
            try:
                row = frame.iloc[row_idx]
            except Exception:
                continue
            key = str(row.get("_key", ""))
            if (
                advance_request is None
                and self._pending_advance_column is None
                and top_left.row() == bottom_right.row()
                and top_left.column() == bottom_right.column()
                and row_idx == top_left.row()
            ):
                try:
                    column_label = str(frame.columns[top_left.column()])
                except Exception:
                    column_label = ""
                if (
                    key
                    and column_label in {MICROSCOPE_D_COLUMN, MICROSCOPE_CAP_D_COLUMN}
                    and self._is_valid_diameter(row.get(column_label))
                ):
                    advance_request = (key, column_label)
            override: Dict[str, float] = {}
            d_val = row.get(MICROSCOPE_D_COLUMN)
            D_val = row.get(MICROSCOPE_CAP_D_COLUMN)
            if isinstance(d_val, (int, float)) and math.isfinite(float(d_val)):
                override["d"] = float(d_val)
            if isinstance(D_val, (int, float)) and math.isfinite(float(D_val)):
                override["D"] = float(D_val)
            if override:
                self._overrides[key] = override
            elif key in self._overrides:
                self._overrides.pop(key, None)
            if self._sync_review_flags_for_row(key, row):
                validation_changed = True
        self._store_overrides(
            restore_selection=(
                advance_request is None and self._pending_advance_column is None
            ),
            autosize=False,
        )
        if validation_changed:
            self._store_validation()
        if advance_request is not None:
            key, column_label = advance_request
            self._select_row_for_key(key, column_label)
            self._selected_key = key
            self._mark_reviewed(auto=True, columns={column_label})
            self._advance_to_next_pending(column_label)

    def _queue_advance_after_restore(
        self,
        key: Optional[str],
        column_label: str,
        *,
        mark_review: bool,
    ) -> None:
        if not column_label:
            return
        self._pending_advance_key = str(key) if key else None
        self._pending_advance_column = column_label
        self._pending_advance_review = bool(mark_review)

    def _restore_selection(self) -> None:
        key = self._pending_advance_key or self._selected_key
        if not key:
            self._pending_advance_key = None
            self._pending_advance_column = None
            self._pending_advance_review = False
            return
        active_column = self._pending_advance_column or self._active_column

        def _restore() -> None:
            self._select_row_for_key(key, active_column)
            self._selected_key = key
            if self._pending_advance_column:
                column_label = self._pending_advance_column
                if self._pending_advance_review:
                    self._mark_reviewed(auto=True, columns={column_label})
                self._advance_to_next_pending(column_label)
                self._pending_advance_key = None
                self._pending_advance_column = None
                self._pending_advance_review = False

        QtCore.QTimer.singleShot(50, _restore)

    def _handle_missing_item_activated(self, item: QtWidgets.QListWidgetItem) -> None:
        key = item.data(QtCore.Qt.ItemDataRole.UserRole)
        if isinstance(key, str):
            self._select_row_for_key(key)

    def _select_row_for_key(self, key: str, column_label: str | None = None) -> None:
        frame = self.model.frame()
        if frame.empty or "_key" not in frame.columns:
            return
        row_idx = None
        try:
            mask = frame["_key"] == key
            row_idx = next(
                idx for idx, matched in enumerate(mask.tolist()) if bool(matched)
            )
        except Exception:
            row_idx = None
        if row_idx is None:
            return
        if isinstance(self.table_view, QtWidgets.QTableView):
            col_idx = 0
            if column_label and hasattr(frame, "columns") and column_label in frame.columns:
                col_idx = list(frame.columns).index(column_label)
            source_index = self.model.index(row_idx, col_idx)
            target = self._search_proxy.mapFromSource(source_index)
            if target is not None and target.isValid():
                selection = self.table_view.selectionModel()
                if selection is not None:
                    selection.setCurrentIndex(
                        target,
                        QtCore.QItemSelectionModel.SelectionFlag.ClearAndSelect,
                    )
                try:
                    self.table_view.scrollTo(
                        target,
                        QtWidgets.QAbstractItemView.ScrollHint.PositionAtCenter,
                    )
                except Exception:
                    pass
                self._handle_selection_changed()

    def _update_hidden_columns(self) -> None:
        if not isinstance(self.table_view, QtWidgets.QTableView):
            return
        frame = self.model.frame()
        if not isinstance(frame, pd.DataFrame):
            return
        hidden_columns = ["_key", "_images", "_core_image", "_glass_image", "Reviewed"]
        hidden_columns.extend(MICROSCOPE_IMAGE_COLUMNS)
        for column_name in hidden_columns:
            try:
                column_index = list(frame.columns).index(column_name)
            except Exception:
                continue
            self.table_view.setColumnHidden(column_index, True)

    def _row_sources(self, row: pd.Series) -> List[Path]:
        sources: List[Path] = []
        images = row.get("_images")
        if isinstance(images, (list, tuple, set)):
            for entry in images:
                if not entry:
                    continue
                try:
                    sources.append(Path(entry))
                except Exception:
                    continue
        for column_name in ("_core_image", "_glass_image"):
            path_value = row.get(column_name)
            if not path_value:
                continue
            try:
                candidate = Path(path_value)
            except Exception:
                continue
            if candidate not in sources:
                sources.append(candidate)
        key = str(row.get("_key") or "").strip()
        entry = self._validated.get(key, {}) if key else {}
        extra_sources = entry.get("sources") if isinstance(entry, dict) else None
        if isinstance(extra_sources, list):
            for item in extra_sources:
                if not isinstance(item, dict):
                    continue
                path_text = item.get("path")
                if not path_text:
                    continue
                try:
                    candidate = Path(str(path_text))
                except Exception:
                    continue
                if candidate not in sources:
                    sources.append(candidate)
        return sources

    def _image_decoration(
        self,
        row: pd.Series,
        column: str,
    ) -> Optional[QtGui.QPixmap]:
        if column not in MICROSCOPE_IMAGE_COLUMNS:
            return None
        key = row.get("_key")
        if not isinstance(key, str) or not key:
            return None
        cache_key = (key, column)
        cached = self._pixmap_cache.get(cache_key)
        if cached is not None or cache_key in self._pixmap_cache:
            return cached
        hidden = "_core_image" if column == MICROSCOPE_IMAGE_COLUMNS[0] else "_glass_image"
        path_value = row.get(hidden)
        pixmap: Optional[QtGui.QPixmap] = None
        candidates: List[Path] = []
        if path_value:
            try:
                candidates.append(Path(path_value))
            except Exception:
                pass
        extras = row.get("_images")
        if isinstance(extras, (list, tuple)):
            for entry in extras:
                try:
                    candidates.append(Path(entry))
                except Exception:
                    continue
        if not candidates:
            candidates = self._row_sources(row)
        for candidate in candidates:
            if candidate and candidate.exists():
                reader = QtGui.QImageReader(str(candidate))
                reader.setAutoTransform(True)
                reader.setQuality(100)
                image = reader.read()
                if not image.isNull():
                    pixmap = QtGui.QPixmap.fromImage(image)
                    break
        self._pixmap_cache[cache_key] = pixmap
        return pixmap

    def _current_index(self) -> QtCore.QModelIndex:
        if not isinstance(self.table_view, QtWidgets.QTableView):
            return QtCore.QModelIndex()
        selection = self.table_view.selectionModel()
        if selection is None:
            return QtCore.QModelIndex()
        index = selection.currentIndex()
        return index if index.isValid() else QtCore.QModelIndex()

    def _source_row(self, proxy_row: int) -> Optional[int]:
        return self._search_proxy.map_row_to_source(proxy_row)

    def _selected_rows(self) -> List[int]:  # type: ignore[override]
        if not isinstance(self.table_view, QtWidgets.QTableView):
            return []
        selection = self.table_view.selectionModel()
        if selection is None:
            return []
        rows: Set[int] = set()
        for index in selection.selectedRows():
            if not index.isValid():
                continue
            source_row = self._source_row(index.row())
            if source_row is not None:
                rows.add(source_row)
        if not rows:
            indexes = selection.selectedIndexes()
            if not indexes:
                current = selection.currentIndex()
                indexes = [current] if current.isValid() else []
            for index in indexes:
                if not index.isValid():
                    continue
                source_row = self._source_row(index.row())
                if source_row is not None:
                    rows.add(source_row)
        return sorted(rows)

    def _preview_pixmap_for_row(
        self,
        row: pd.Series,
        column_name: str,
    ) -> Optional[QtGui.QPixmap]:
        key = str(row.get("_key") or "").strip()
        if not key:
            return None
        if column_name == "_core_image":
            cache_column = MICROSCOPE_IMAGE_COLUMNS[0]
        elif column_name == "_glass_image":
            cache_column = MICROSCOPE_IMAGE_COLUMNS[1]
        else:
            return None
        cache_key = (key, cache_column)
        cached = self._pixmap_cache.get(cache_key)
        if cached is not None or cache_key in self._pixmap_cache:
            return cached

        path_value = row.get(column_name)
        candidate = None
        if path_value:
            try:
                candidate = Path(path_value)
            except Exception:
                candidate = None
        if candidate is None or not candidate.exists():
            for source in self._row_sources(row):
                lower_name = source.name.lower()
                if column_name == "_core_image" and "core" in lower_name and source.exists():
                    candidate = source
                    break
                if column_name == "_glass_image" and "glass" in lower_name and source.exists():
                    candidate = source
                    break
        if (candidate is None or not candidate.exists()) and row.get("_images"):
            try:
                fallback = Path(row["_images"][0])
                if fallback.exists():
                    candidate = fallback
            except Exception:
                candidate = None

        pixmap: Optional[QtGui.QPixmap] = None
        if candidate and candidate.exists():
            reader = QtGui.QImageReader(str(candidate))
            reader.setAutoTransform(True)
            reader.setQuality(100)
            image = reader.read()
            if not image.isNull():
                loaded = QtGui.QPixmap.fromImage(image)
                if not loaded.isNull():
                    pixmap = loaded
        self._pixmap_cache[cache_key] = pixmap
        return pixmap

    def _ensure_valid_selection(self, column_label: str | None = None) -> None:
        if not isinstance(self.table_view, QtWidgets.QTableView):
            return
        model = self.table_view.model()
        selection = self.table_view.selectionModel()
        if model is None or selection is None:
            return
        row_count = model.rowCount()
        if row_count <= 0:
            self._handle_selection_changed()
            return
        current = selection.currentIndex()
        if current.isValid() and self._selected_row() is not None:
            self._handle_selection_changed()
            return
        col_idx = 0
        frame = self.model.frame()
        if (
            column_label
            and hasattr(frame, "columns")
            and column_label in frame.columns
        ):
            try:
                col_idx = list(frame.columns).index(column_label)
            except Exception:
                col_idx = 0
        target = model.index(0, max(0, col_idx))
        if not target.isValid():
            self._handle_selection_changed()
            return
        try:
            selection.setCurrentIndex(
                target,
                QtCore.QItemSelectionModel.SelectionFlag.ClearAndSelect,
            )
        except Exception:
            pass
        try:
            self.table_view.scrollTo(
                target,
                QtWidgets.QAbstractItemView.ScrollHint.PositionAtCenter,
            )
        except Exception:
            pass
        self._handle_selection_changed()

    def _selected_row(self) -> Optional[pd.Series]:
        index = self._current_index()
        if not index.isValid():
            return None
        row = self._source_row(index.row())
        if row is None:
            return None
        try:
            return self.model.frame().iloc[row]
        except Exception:
            return None

    def _focus_d_input(self, select_all: bool = False) -> None:
        table = self.table_view
        if not isinstance(table, QtWidgets.QTableView):
            return
        try:
            table.setFocus(QtCore.Qt.FocusReason.OtherFocusReason)
            if select_all:
                index = self._current_index()
                if index.isValid():
                    table.setCurrentIndex(index)
        except Exception:
            pass

    def _handle_current_changed(self, current: QtCore.QModelIndex, _: QtCore.QModelIndex) -> None:
        self._handle_selection_changed()

    def _handle_selection_changed(self, *_: Any) -> None:
        index = self._current_index()
        row = self._selected_row()
        if row is None:
            self._selected_key = None
            self._active_column = ""
            for label in (self.core_preview_label, self.glass_preview_label):
                label.set_placeholder()
                label.show()
            if hasattr(self, "core_preview_panel") and hasattr(self, "glass_preview_panel"):
                self.core_preview_panel.show()
                self.glass_preview_panel.show()
            self.d_edit.clear()
            self.D_edit.clear()
            self._update_review_buttons()
            return
        key = row.get("_key")
        self._selected_key = str(key) if key is not None else None
        d_value = row.get(MICROSCOPE_D_COLUMN)
        D_value = row.get(MICROSCOPE_CAP_D_COLUMN)
        self.d_edit.setText("" if d_value is None or (isinstance(d_value, float) and math.isnan(d_value)) else f"{float(d_value):.3f}")
        self.D_edit.setText("" if D_value is None or (isinstance(D_value, float) and math.isnan(D_value)) else f"{float(D_value):.3f}")

        active_column = ""
        if index.isValid():
            try:
                active_column = str(self.model.frame().columns[index.column()])
            except Exception:
                active_column = ""
        self._active_column = active_column

        if active_column == MICROSCOPE_D_COLUMN:
            show_core, show_glass = True, False
        elif active_column == MICROSCOPE_CAP_D_COLUMN:
            show_core, show_glass = False, True
        else:
            show_core = show_glass = True

        for column_name, label, should_show in (
            ("_core_image", self.core_preview_label, show_core),
            ("_glass_image", self.glass_preview_label, show_glass),
        ):
            if not should_show:
                label.set_placeholder()
                continue
            pixmap = self._preview_pixmap_for_row(row, column_name)
            if pixmap is not None and not pixmap.isNull():
                label.set_preview(pixmap)
                continue
            label.set_placeholder()
        if hasattr(self, "core_preview_panel") and hasattr(self, "glass_preview_panel"):
            self.core_preview_panel.setVisible(show_core)
            self.glass_preview_panel.setVisible(show_glass)
        else:
            self.core_preview_label.setVisible(show_core)
            self.glass_preview_label.setVisible(show_glass)

        self._update_open_sources_enabled()
        self._update_review_buttons()

    def _apply_override(self, advance_column: str | None = None) -> None:
        if not self._selected_key:
            return
        selected_key = str(self._selected_key)
        d_text = self._normalized_decimal_text(self.d_edit)
        D_text = self._normalized_decimal_text(self.D_edit)
        override: Dict[str, float] = {}
        if d_text:
            try:
                override["d"] = float(d_text)
            except ValueError:
                QtWidgets.QMessageBox.warning(self, self.section_title, "Invalid d value.")
                return
        if D_text:
            try:
                override["D"] = float(D_text)
            except ValueError:
                QtWidgets.QMessageBox.warning(self, self.section_title, "Invalid D value.")
                return
        if override:
            self._overrides[selected_key] = override
        else:
            self._overrides.pop(selected_key, None)
        self._store_overrides(restore_selection=False, autosize=False)
        self._select_row_for_key(selected_key, advance_column or MICROSCOPE_D_COLUMN)
        self._selected_key = selected_key
        columns: set[str] = set()
        if "d" in override:
            columns.add(MICROSCOPE_D_COLUMN)
        if "D" in override:
            columns.add(MICROSCOPE_CAP_D_COLUMN)
        if columns:
            self._mark_reviewed(auto=True, columns=columns)
        if advance_column:
            self._advance_to_next_pending(advance_column)

    def _clear_override(self) -> None:
        if not self._selected_key:
            return
        if self._selected_key in self._overrides:
            self._overrides.pop(self._selected_key, None)
            self._store_overrides()
        row = self._row_for_key(self._selected_key)
        if row is not None and self._sync_review_flags_for_row(self._selected_key, row):
            self._store_validation()
        self.d_edit.clear()
        self.D_edit.clear()

    def _mark_reviewed(
        self,
        *,
        auto: bool = False,
        columns: set[str] | None = None,
        allow_without_sources: bool = True,
    ) -> None:
        if not self._selected_key:
            return
        row = self._selected_row()
        if row is None:
            return
        key = self._selected_key
        sources = self._row_sources(row)
        if not sources and not allow_without_sources:
            if auto:
                self.logger.warning("Auto-review skipped for %s due to missing sources", key)
            else:
                QtWidgets.QMessageBox.warning(
                    self,
                    self.section_title,
                    "No source images are associated with the selected row; cannot mark as reviewed.",
                )
            return

        metadata: List[Dict[str, Any]] = []
        for source in sources:
            try:
                stat = source.stat()
            except OSError:
                continue
            metadata.append(
                {
                    "path": str(source),
                    "key": self._path_key(source),
                    "mtime": float(stat.st_mtime),
                    "size": int(stat.st_size),
                }
            )
        if not metadata and not allow_without_sources:
            QtWidgets.QMessageBox.warning(
                self,
                self.section_title,
                "The source files for this row are not accessible; review status was not updated.",
            )
            return

        existing = self._validated.get(key, {})
        entry: Dict[str, Any] = dict(existing) if isinstance(existing, dict) else {}
        if metadata:
            entry["sources"] = metadata
        else:
            entry.setdefault("sources", [])
        if allow_without_sources and not sources:
            entry["allow_without_sources"] = True

        d_value = row.get(MICROSCOPE_D_COLUMN)
        if isinstance(d_value, (int, float)) and math.isfinite(float(d_value)):
            entry["d"] = float(d_value)
        D_value = row.get(MICROSCOPE_CAP_D_COLUMN)
        if isinstance(D_value, (int, float)) and math.isfinite(float(D_value)):
            entry["D"] = float(D_value)

        columns_to_mark = columns or {MICROSCOPE_D_COLUMN, MICROSCOPE_CAP_D_COLUMN}
        if MICROSCOPE_D_COLUMN in columns_to_mark:
            entry["d_reviewed"] = True
        if MICROSCOPE_CAP_D_COLUMN in columns_to_mark:
            entry["D_reviewed"] = True

        entry["timestamp"] = datetime.now(UTC).isoformat().replace("+00:00", "Z")
        self._validated[key] = entry
        self._store_validation()
        override_changed = False
        override_entry = dict(self._overrides.get(key, {}))
        if MICROSCOPE_D_COLUMN in columns_to_mark and self._is_valid_diameter(d_value):
            if override_entry.get("d") != float(d_value):
                override_entry["d"] = float(d_value)
                override_changed = True
        if MICROSCOPE_CAP_D_COLUMN in columns_to_mark and self._is_valid_diameter(D_value):
            if override_entry.get("D") != float(D_value):
                override_entry["D"] = float(D_value)
                override_changed = True
        if override_changed:
            self._overrides[key] = override_entry
            self._store_overrides()

    def _clear_review(self) -> None:
        if not self._selected_key:
            return
        if self._selected_key in self._validated:
            self._validated.pop(self._selected_key, None)
            self._store_validation()
        self._update_review_buttons()

    def _store_validation(self, persist: bool = True) -> None:
        self.data.extra["validated"] = self._validated
        if persist:
            self.store.save(self.data)
        self._refresh_status_column()
        self._refresh_review_display()
        self._update_review_buttons()
        try:
            self.data_updated.emit()
        except Exception:
            pass

    def _refresh_review_display(self) -> None:
        try:
            rows = self.model.rowCount()
            cols = self.model.columnCount()
        except Exception:
            rows = cols = 0
        if rows <= 0 or cols <= 0:
            return
        try:
            self.model.dataChanged.emit(
                self.model.index(0, 0),
                self.model.index(rows - 1, cols - 1),
                [
                    QtCore.Qt.ItemDataRole.BackgroundRole,
                    QtCore.Qt.ItemDataRole.ForegroundRole,
                ],
            )
        except Exception:
            try:
                self.model.layoutChanged.emit()
            except Exception:
                pass
        if isinstance(self.table_view, QtWidgets.QTableView):
            try:
                self.table_view.viewport().update()
            except Exception:
                pass

    def _refresh_validations(self) -> None:
        changed = False
        for key, payload in list(self._validated.items()):
            entry_changed = False
            sources = payload.get("sources")
            allow_without_sources = bool(payload.get("allow_without_sources"))
            if not isinstance(sources, list) or (not sources and not allow_without_sources):
                continue
            else:
                for source in sources:
                    path_text = source.get("path")
                    if not path_text:
                        continue
                    path_obj = Path(path_text)
                    try:
                        stat = path_obj.stat()
                    except OSError:
                        continue
                    if float(source.get("mtime", -1.0)) != float(stat.st_mtime):
                        source["mtime"] = float(stat.st_mtime)
                        entry_changed = True
                    if int(source.get("size", -1)) != int(stat.st_size):
                        source["size"] = int(stat.st_size)
                        entry_changed = True
                    source.setdefault("key", self._path_key(path_obj))
            if entry_changed:
                self._validated[key] = payload
                changed = True
        if changed:
            self._store_validation()

    def _update_review_buttons(self) -> None:
        if not hasattr(self, "mark_reviewed_button"):
            return
        has_selection = bool(self._selected_key)
        key = self._selected_key or ""
        has_any_review = bool(has_selection and self._validated.get(key))
        if has_selection:
            d_reviewed = self._is_cell_reviewed(key, MICROSCOPE_D_COLUMN)
            D_reviewed = self._is_cell_reviewed(key, MICROSCOPE_CAP_D_COLUMN)
            is_reviewed = d_reviewed and D_reviewed
        else:
            is_reviewed = False
        self.mark_reviewed_button.setEnabled(has_selection)
        self.mark_reviewed_button.setText("Update review" if is_reviewed else "Mark reviewed")
        self.clear_review_button.setEnabled(has_any_review)

    def _store_overrides(
        self,
        *,
        restore_selection: bool = True,
        autosize: bool = True,
    ) -> None:
        self.data.extra["overrides"] = self._overrides
        self.store.save(self.data)
        self._apply_overrides_to_table(
            restore_selection=restore_selection,
            autosize=autosize,
        )
        self._update_hidden_columns()
        self._update_missing_summary()
        try:
            self.data_updated.emit()
        except Exception:
            pass
        if restore_selection:
            self._restore_selection()
        if autosize:
            self._ensure_table_autosized()

    def _apply_overrides_to_table(
        self,
        *,
        restore_selection: bool = True,
        autosize: bool = True,
        clear_preview_cache: bool = False,
    ) -> None:
        frame = self.data.table.copy()
        frame = frame.drop(columns=["Reviewed"], errors="ignore")
        if frame.empty:
            self.model.set_frame(frame)
            return
        if clear_preview_cache:
            self._pixmap_cache.clear()
        for index, row in frame.iterrows():
            key = str(row.get("_key"))
            override = self._overrides.get(key)
            d_value = row.get(MICROSCOPE_D_COLUMN)
            D_value = row.get(MICROSCOPE_CAP_D_COLUMN)
            if override:
                if "d" in override:
                    d_value = override.get("d")
                if "D" in override:
                    D_value = override.get("D")
            if not self._is_valid_diameter(d_value):
                validated = self._validated_value(key, MICROSCOPE_D_COLUMN)
                if validated is not None:
                    d_value = validated
            if not self._is_valid_diameter(D_value):
                validated = self._validated_value(key, MICROSCOPE_CAP_D_COLUMN)
                if validated is not None:
                    D_value = validated
            ratio = None
            if isinstance(d_value, (int, float)) and isinstance(D_value, (int, float)) and D_value:
                try:
                    ratio = float(d_value) / float(D_value)
                except ZeroDivisionError:
                    ratio = None
            frame.at[index, MICROSCOPE_D_COLUMN] = d_value
            frame.at[index, MICROSCOPE_CAP_D_COLUMN] = D_value
            frame.at[index, "d/D"] = round(ratio, 3) if ratio is not None else None
        frame = self._with_status_column(frame)
        self.data.table = frame
        self.model.set_frame(frame)
        if autosize:
            self._auto_fit_columns()
        self._update_missing_summary()
        self._update_review_buttons()
        if restore_selection:
            self._restore_selection()

    @staticmethod
    def _build_microscope_index_from_table(
        table: pd.DataFrame,
    ) -> Dict[MicrowireKey, MicroscopeMeasurements]:
        index: Dict[MicrowireKey, MicroscopeMeasurements] = {}
        if not isinstance(table, pd.DataFrame) or table.empty:
            return index
        for _, row in table.iterrows():
            key = _microwire_key_from_string(str(row.get("_key") or "").strip())
            if key is None:
                continue
            measurements = index.setdefault(key, MicroscopeMeasurements())
            core_path = row.get("_core_image")
            glass_path = row.get("_glass_image")
            try:
                core_image = Path(core_path) if core_path else None
            except Exception:
                core_image = None
            try:
                glass_image = Path(glass_path) if glass_path else None
            except Exception:
                glass_image = None

            d_value = row.get(MICROSCOPE_D_COLUMN)
            if isinstance(d_value, (int, float)) and math.isfinite(float(d_value)) and float(d_value) > 0:
                detection = MicroscopeDetection(
                    value=float(d_value),
                    image_path=core_image,
                    source="manual",
                )
                detection.category = "core"
                measurements.core.append(detection)
            elif core_image is not None:
                measurements.add_placeholder("core", core_image)

            D_value = row.get(MICROSCOPE_CAP_D_COLUMN)
            if isinstance(D_value, (int, float)) and math.isfinite(float(D_value)) and float(D_value) > 0:
                detection = MicroscopeDetection(
                    value=float(D_value),
                    image_path=glass_image,
                    source="manual",
                )
                detection.category = "glass"
                measurements.glass.append(detection)
            elif glass_image is not None:
                measurements.add_placeholder("glass", glass_image)

            if str(row.get(BRITTLE_COLUMN) or "").strip().lower() == "brittle":
                measurements.brittle = True
        return index

    def refresh(self) -> None:
        self._refresh_validations()
        self._expected_keys_current = self._expected_microwire_keys()
        super().refresh()

    def _prepopulate_image_refs(self, candidates: Iterable[Path]) -> None:
        frame = self.data.table if isinstance(self.data.table, pd.DataFrame) else pd.DataFrame()
        rows_to_apply = self._build_image_ref_rows(
            candidates,
            set(self._expected_keys_current or self._expected_microwire_keys()),
            frame,
        )
        for row in rows_to_apply:
            key = str(row.get("_key", ""))
            self._pixmap_cache.pop((key, MICROSCOPE_IMAGE_COLUMNS[0]), None)
            self._pixmap_cache.pop((key, MICROSCOPE_IMAGE_COLUMNS[1]), None)
            self._prepopulated_keys.add(key)
        if rows_to_apply:
            self._apply_partial_rows_now(rows_to_apply)
        if rows_to_apply:
            self._update_missing_summary()

    def _start_section_worker(self, candidates: List[Path]) -> None:  # type: ignore[override]
        super()._start_section_worker(candidates)

    def process(
        self,
        paths: List[Path],
        progress: Optional[Callable[[int, int, Optional[str]], None]] = None,
    ) -> SectionProcessResult:
        self._refresh_validations()
        existing_processed = (
            dict(self.data.processed)
            if isinstance(getattr(self.data, "processed", None), dict)
            else {}
        )
        unique_paths = list(dict.fromkeys(Path(p) for p in paths))

        def _progress(idx: int, total: int) -> None:
            self._check_cancelled()
            if progress is None:
                return
            message = None
            if 0 < idx <= len(unique_paths):
                try:
                    message = f"Grouping {unique_paths[idx - 1].name}"
                except Exception:
                    message = None
            try:
                progress(idx, total, message)
            except Exception:
                pass

        expected_keys = self._expected_keys_current or self._expected_microwire_keys()
        discovered_keys: Set[MicrowireKey] = set()
        for candidate in unique_paths:
            try:
                parsed_key = _microscope_key(Path(candidate))
            except Exception:
                parsed_key = None
            if parsed_key is not None:
                discovered_keys.add(parsed_key)
        if discovered_keys:
            expected_keys = set(expected_keys) | discovered_keys
        table = self._build_initial_table_frame(expected_keys)
        self._check_cancelled()
        rows_to_apply = self._build_image_ref_rows(unique_paths, expected_keys, table)
        if rows_to_apply:
            table = self._merge_rows_into_frame(table, rows_to_apply)
        table = self._with_status_column(table)
        merged_index = self._build_microscope_index_from_table(table)
        filtered_overrides = {
            key: value
            for key, value in self._overrides.items()
            if any(
                key == _microwire_key_to_str((comp, draw, piece, suffix))
                for comp, draw, piece, suffix in merged_index.keys()
            )
        }

        processed: Dict[str, float] = dict(existing_processed)
        for path in unique_paths:
            try:
                processed[str(path)] = float(path.stat().st_mtime)
            except OSError:
                continue

        extra_payload = {
            "overrides": filtered_overrides,
            "validated": self._validated,
        }
        return SectionProcessResult(
            table=table,
            processed=processed,
            payloads={"microscope_index": merged_index},
            extra=extra_payload,
        )

    def _handle_worker_finished(self, result: SectionProcessResult) -> None:
        super()._handle_worker_finished(result)
        self._load_extra_state()
        self._apply_overrides_to_table(restore_selection=False)
        try:
            self.store.save(self.data)
        except Exception:
            pass
        self._update_missing_summary()
        self._update_review_buttons()
        self._ensure_valid_selection()

    @property
    def overrides(self) -> Dict[str, Dict[str, float]]:
        return dict(self._overrides)


class _CurrentDensityPreviewPanel(QtWidgets.QWidget):
    phaseValuesEdited = QtCore.pyqtSignal(dict)
    def __init__(self, logger: logging.Logger, parent: QtWidgets.QWidget | None = None) -> None:
        super().__init__(parent)
        self._logger = logger
        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(8)

        self.header_label = QtWidgets.QLabel("Select a row to preview annealing plots.", self)
        self.header_label.setAlignment(
            QtCore.Qt.AlignmentFlag.AlignLeft | QtCore.Qt.AlignmentFlag.AlignVCenter
        )
        layout.addWidget(self.header_label)

        self._phase_controls = _PhasePointEditorControls(
            self,
            title="Manual transition currents (mA)",
        )
        self._phase_controls.valuesEdited.connect(self.phaseValuesEdited.emit)
        layout.addWidget(self._phase_controls)

        self._high_display = _AnnealingPlotDisplay(ANNEALING_HIGH_GRAPH_DISPLAY_TITLE, logger, self)
        self._other_display = _AnnealingPlotGallery(ANNEALING_OTHER_GRAPH_COLUMN, logger, self)
        layout.addWidget(self._high_display, 1)
        layout.addWidget(self._other_display, 1)
        layout.setStretch(2, 1)
        layout.setStretch(3, 1)
        self._high_display.valuePicked.connect(self._phase_controls.apply_picked_value)
        self._other_display.valuePicked.connect(self._phase_controls.apply_picked_value)

    def update_selection(
        self,
        key: Optional[MicrowireKey],
        high: Optional[MeasurementRecord],
        other_records: Sequence[MeasurementRecord],
        phase_values: Mapping[str, Any],
    ) -> None:
        if key is None:
            self.header_label.setText("Select a row to preview annealing plots.")
            self._high_display.clear("Select a row to view the exact 1000 mA measurement.")
            self._other_display.clear("Select a row to view the other annealing measurements.")
            self._phase_controls.setEnabled(False)
            self._phase_controls.set_values({})
            return
        composition, draw, piece, suffix = key
        try:
            microwire = _microwire_label(draw, piece, suffix)
        except Exception:
            microwire = f"{draw}/{piece}"
        self.header_label.setText(f"{composition} — {microwire}")
        self._phase_controls.setEnabled(True)
        self._phase_controls.set_values(phase_values)

        self._high_display.set_record(
            high,
            setpoint=_extract_setpoint(high),
            description=_missing_high_measurement_message(other_records),
        )
        self._other_display.set_records(
            other_records,
            description="No other annealing measurements available for this microwire.",
        )


class CurrentDensitySection(QtWidgets.QWidget):
    section_key = "current_density"
    section_title = "Annealing transitions"

    status_changed = QtCore.pyqtSignal(str)
    sources_changed = QtCore.pyqtSignal(list)
    data_updated = QtCore.pyqtSignal()

    def __init__(
        self,
        annealing_section: AnnealingSection,
        microscope_section: MicroscopeSection,
        logger: logging.Logger,
        log_callback: Callable[[int, str], None],
        parent: QtWidgets.QWidget | None = None,
    ) -> None:
        super().__init__(parent)
        self.logger = logger
        self._log_callback = log_callback
        self._annealing_section = annealing_section
        self._microscope_section = microscope_section
        self._current_frame = pd.DataFrame(columns=CURRENT_DENSITY_COLUMNS)
        self._last_sources: List[str] = []
        self._table_splitter: QtWidgets.QSplitter | None = None
        self._preview_panel: _CurrentDensityPreviewPanel | None = None
        self._search_proxy = _TableSearchProxyModel(self)
        self.search_edit: QtWidgets.QLineEdit | None = None
        self.search_clear_button: QtWidgets.QPushButton | None = None

        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(8)

        controls = QtWidgets.QHBoxLayout()
        self.refresh_button = QtWidgets.QPushButton("Refresh")
        self.refresh_button.clicked.connect(self.refresh_data)
        controls.addWidget(self.refresh_button)
        self.export_button = QtWidgets.QPushButton("Export worksheet...")
        self.export_button.clicked.connect(self._export_worksheet)
        self.export_button.setEnabled(False)
        controls.addWidget(self.export_button)
        controls.addStretch(1)
        layout.addLayout(controls)

        search_row = QtWidgets.QHBoxLayout()
        search_row.addWidget(QtWidgets.QLabel("Search:"))
        self.search_edit = QtWidgets.QLineEdit(self)
        self.search_edit.setClearButtonEnabled(True)
        self.search_edit.setPlaceholderText("Filter rows across visible columns")
        self.search_edit.textChanged.connect(self._handle_search_changed)
        search_row.addWidget(self.search_edit, 1)
        self.search_clear_button = QtWidgets.QPushButton("Clear")
        self.search_clear_button.setEnabled(False)
        self.search_clear_button.clicked.connect(lambda: self.search_edit.clear())
        search_row.addWidget(self.search_clear_button)
        layout.addLayout(search_row)

        self.status_label = QtWidgets.QLabel("Waiting for data.", self)
        layout.addWidget(self.status_label)

        self.model = DataFrameModel(self._current_frame)
        self.model.set_editable_columns(set(PHASE_POINT_COLUMN_MAP.values()))
        self.model.dataChanged.connect(self._handle_model_data_changed)
        self._search_proxy.setSourceModel(self.model)

        splitter = QtWidgets.QSplitter(QtCore.Qt.Orientation.Horizontal, self)
        splitter.setChildrenCollapsible(False)
        splitter.setOpaqueResize(False)
        splitter.setStretchFactor(0, 2)
        splitter.setStretchFactor(1, 3)
        layout.addWidget(splitter, 1)
        self._table_splitter = splitter

        table = QtWidgets.QTableView(splitter)
        table.setModel(self.model)
        table.setAlternatingRowColors(True)
        table.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectionBehavior.SelectItems)
        table.setSelectionMode(QtWidgets.QAbstractItemView.SelectionMode.ExtendedSelection)
        table.setSortingEnabled(True)
        table.setVerticalScrollMode(QtWidgets.QAbstractItemView.ScrollMode.ScrollPerPixel)
        table.setHorizontalScrollMode(QtWidgets.QAbstractItemView.ScrollMode.ScrollPerPixel)
        table.setEditTriggers(
            QtWidgets.QAbstractItemView.EditTrigger.DoubleClicked
            | QtWidgets.QAbstractItemView.EditTrigger.SelectedClicked
            | QtWidgets.QAbstractItemView.EditTrigger.EditKeyPressed
        )
        header = table.horizontalHeader()
        if header is not None:
            header.setStretchLastSection(False)
            header.setSectionsMovable(True)
            header.setSectionsClickable(True)
            header.setSectionResizeMode(QtWidgets.QHeaderView.ResizeMode.ResizeToContents)
        vertical_bar = table.verticalScrollBar()
        if vertical_bar is not None:
            vertical_bar.setSingleStep(MiniDatabaseSection._SCROLL_SINGLE_STEP)
        table.setModel(self._search_proxy)
        splitter.addWidget(table)
        self.table_view = table

        selection_model = table.selectionModel()
        if selection_model is not None:
            selection_model.selectionChanged.connect(self._handle_selection_changed)

        preview_panel = _CurrentDensityPreviewPanel(logger, splitter)
        splitter.addWidget(preview_panel)
        self._preview_panel = preview_panel
        preview_panel.phaseValuesEdited.connect(self._apply_phase_values)

        if hasattr(self._annealing_section, "data_updated"):
            try:
                self._annealing_section.data_updated.connect(self.refresh_data)
            except Exception:
                pass
        if hasattr(self._microscope_section, "data_updated"):
            try:
                self._microscope_section.data_updated.connect(self.refresh_data)
            except Exception:
                pass
        QtCore.QTimer.singleShot(0, self.refresh_data)

    def log(self, message: str, level: int = logging.INFO) -> None:
        try:
            self._log_callback(level, message)
        except Exception:
            self.logger.log(level, message)

    def refresh_data(self) -> None:
        previous_order = self._current_column_order()
        selected_key = self._current_selection_key()
        try:
            frame = self._calculate_frame()
        except Exception:
            self.logger.exception("Failed to calculate annealing transition summary")
            self.status_label.setText("Failed to calculate annealing transition summary.")
            self.export_button.setEnabled(False)
            return
        self._current_frame = frame
        self.model.set_frame(frame)
        if previous_order:
            QtCore.QTimer.singleShot(
                0,
                lambda: (
                    self._apply_column_order(previous_order),
                    self._hide_internal_columns(),
                ),
            )
        else:
            self._hide_internal_columns()
        if not MiniDatabaseSection._project_load_batch_mode:
            try:
                self.table_view.resizeColumnsToContents()
            except Exception:
                pass
        self._restore_selection(selected_key)
        self._update_preview()
        total = len(frame.index) if isinstance(frame, pd.DataFrame) else 0
        annotated = 0
        if (
            total
            and isinstance(frame, pd.DataFrame)
            and ANNEALING_AS_COLUMN in frame.columns
            and ANNEALING_MS_COLUMN in frame.columns
        ):
            as_series = pd.to_numeric(frame[ANNEALING_AS_COLUMN], errors="coerce")
            ms_series = pd.to_numeric(frame[ANNEALING_MS_COLUMN], errors="coerce")
            annotated = int((as_series.notna() & ms_series.notna()).sum())
        status_text = (
            f"{annotated} of {total} graph row(s) have As1/Ms1 annotated."
            if total
            else "No overlapping microscope and annealing data yet."
        )
        self.status_label.setText(status_text)
        self.export_button.setEnabled(total > 0)
        try:
            self.status_changed.emit(status_text)
        except Exception:
            pass
        try:
            self.sources_changed.emit(list(self._last_sources))
        except Exception:
            pass
        try:
            self.data_updated.emit()
        except Exception:
            pass

    def current_density_snapshot(self) -> Dict[str, Dict[str, Any]]:
        frame = self.model.frame()
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return {}
        snapshot: Dict[str, Dict[str, Any]] = {}
        for _, row in frame.iterrows():
            key_text = str(row.get("_group_key") or "").strip()
            if not key_text:
                key_tuple = self._extract_key(
                    row.get("Composition"),
                    row.get("Microwire"),
                    None,
                )
                if key_tuple:
                    key_text = _microwire_key_to_str(key_tuple)
            if not key_text:
                continue
            if key_text in snapshot:
                continue
            entry: Dict[str, Any] = {}
            for column in frame.columns:
                if str(column).startswith("_") or column == "Graph":
                    continue
                entry[column] = row.get(column)
            if entry:
                snapshot[key_text] = entry
        return snapshot

    def _hide_internal_columns(self) -> None:
        table = self.table_view
        frame = self.model.frame()
        if not isinstance(table, QtWidgets.QTableView):
            return
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return
        try:
            columns = list(frame.columns)
        except Exception:
            return
        for idx, column in enumerate(columns):
            try:
                table.setColumnHidden(idx, str(column).startswith("_"))
            except Exception:
                continue

    def _current_selection_key(self) -> Optional[MicrowireKey]:
        table = self.table_view
        if not isinstance(table, QtWidgets.QTableView):
            return None
        selection_model = table.selectionModel()
        if selection_model is None:
            return None
        current_index = selection_model.currentIndex()
        if current_index.isValid():
            row_index = self._source_row(current_index.row())
        else:
            rows = selection_model.selectedRows()
            if not rows:
                return None
            row_index = self._source_row(rows[0].row())
        frame = self.model.frame()
        if not isinstance(frame, pd.DataFrame) or row_index < 0 or row_index >= len(frame.index):
            return None
        key_value = frame.iloc[row_index].get("_group_key")
        return self._parse_group_key(key_value)

    def _restore_selection(self, key: Optional[MicrowireKey]) -> None:
        if key is None:
            return
        table = self.table_view
        frame = self.model.frame()
        if not isinstance(table, QtWidgets.QTableView):
            return
        if not isinstance(frame, pd.DataFrame) or "_group_key" not in frame.columns:
            return
        target = _microwire_key_to_str(key)
        try:
            matches = frame.index[frame["_group_key"] == target].tolist()
        except Exception:
            matches = []
        if not matches:
            return
        row = matches[0]
        try:
            source_index = self.model.index(int(row), 0)
            index = self._search_proxy.mapFromSource(source_index)
            if index.isValid():
                table.selectRow(index.row())
                table.scrollTo(index, QtWidgets.QAbstractItemView.ScrollHint.PositionAtCenter)
        except Exception:
            pass

    def _update_preview(self) -> None:
        panel = self._preview_panel
        if panel is None:
            return
        key = self._current_selection_key()
        if key is None:
            panel.update_selection(None, None, [], {})
            return
        row = self._selected_row_series()
        record = self._record_for_row(row)
        if record is not None:
            high, other_records = record, []
        else:
            high, other_records = self._fetch_records_for_key(key)
        panel.update_selection(key, high, other_records, self._selected_phase_values())

    def _handle_selection_changed(self, *_args: Any) -> None:
        self._update_preview()

    def _handle_model_data_changed(
        self,
        top_left: QtCore.QModelIndex,
        bottom_right: QtCore.QModelIndex,
        roles: Tuple[QtCore.Qt.ItemDataRole, ...] = (),
    ) -> None:
        if roles and QtCore.Qt.ItemDataRole.EditRole not in roles:
            return
        frame = self.model.frame()
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return
        try:
            columns_slice = frame.columns[top_left.column() : bottom_right.column() + 1]
        except Exception:
            columns_slice = []
        relevant = set(PHASE_POINT_COLUMN_MAP.values())
        if not any(column in relevant for column in columns_slice):
            return
        updated = False
        for row in range(top_left.row(), bottom_right.row() + 1):
            if row < 0 or row >= len(frame.index):
                continue
            series = frame.iloc[row]
            key_raw = series.get("_group_key")
            key = str(key_raw).strip() if key_raw not in (None, "", float("nan")) else ""
            if not key:
                continue
            phase_values = {
                label: self._coerce_phase_value(series.get(column))
                for label, column in PHASE_POINT_COLUMN_MAP.items()
            }
            try:
                parsed_key = self._parse_group_key(key)
                if parsed_key is None:
                    continue
                record = self._record_for_row(series)
                if record is not None:
                    self._store_transition_review_for_record(record, phase_values)
                else:
                    self._store_transition_review_for_key(parsed_key, phase_values)
                updated = True
            except Exception:
                self.logger.exception("Failed to persist phase transition points for %s", key)
        if updated:
            QtCore.QTimer.singleShot(0, self.refresh_data)

    def _column_index_for_label(self, label: str) -> Optional[int]:
        target_column = PHASE_POINT_COLUMN_MAP.get(label)
        if not target_column:
            return None
        frame = self.model.frame()
        if not isinstance(frame, pd.DataFrame):
            return None
        try:
            return int(frame.columns.get_loc(target_column))
        except Exception:
            return None

    def _selected_source_row(self) -> Optional[int]:
        table = self.table_view
        if not isinstance(table, QtWidgets.QTableView):
            return None
        selection_model = table.selectionModel()
        if selection_model is None:
            return None
        current_index = selection_model.currentIndex()
        if current_index.isValid():
            row = self._source_row(current_index.row())
            if row is not None:
                return row
        rows = selection_model.selectedRows()
        if rows:
            return self._source_row(rows[0].row())
        return None

    def _selected_phase_values(self) -> Dict[str, Optional[float]]:
        frame = self.model.frame()
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return {}
        row = self._selected_source_row()
        if row is None or row < 0 or row >= len(frame.index):
            return {}
        series = frame.iloc[row]
        return {
            label: self._coerce_phase_value(series.get(column))
            for label, column in PHASE_POINT_COLUMN_MAP.items()
        }

    def _apply_phase_values(self, values: Dict[str, Optional[float]]) -> None:
        row = self._selected_row_series()
        key = self._current_selection_key()
        if key is None:
            return
        cleaned = {
            label: self._coerce_phase_value(values.get(label))
            for label in PHASE_POINT_LABELS
        }
        try:
            record = self._record_for_row(row) if row is not None else None
            if record is not None:
                self._store_transition_review_for_record(record, cleaned)
            else:
                self._store_transition_review_for_key(key, cleaned)
        except Exception:
            self.logger.exception("Failed to persist phase transition points for %s", _microwire_key_to_str(key))
            return
        self.refresh_data()

    def _selected_row_series(self) -> Optional[pd.Series]:
        frame = self.model.frame()
        row = self._selected_source_row()
        if not isinstance(frame, pd.DataFrame) or row is None or row < 0 or row >= len(frame.index):
            return None
        return frame.iloc[row]

    def _store_transition_review_for_key(
        self,
        key: MicrowireKey,
        phase_values: Mapping[str, Any],
    ) -> None:
        high, other_records = self._fetch_records_for_key(key)
        record = high or (other_records[0] if other_records else None)
        if record is None:
            return
        self._store_transition_review_for_record(record, phase_values)

    def _store_transition_review_for_record(
        self,
        record: MeasurementRecord,
        phase_values: Mapping[str, Any],
    ) -> None:
        record_id = _transition_record_id_for_annealing_record(record)
        setter = getattr(self._annealing_section, "set_transition_review_for_record", None)
        if not callable(setter):
            return
        cleaned = _clean_transition_values(phase_values)
        payload = {
            "status": TRANSITION_REVIEW_STATUS_MANUAL_ADJUSTED if cleaned else TRANSITION_REVIEW_STATUS_UNREVIEWED,
            "included": bool(cleaned),
            "manual_values_mA": cleaned,
            "final_values_mA": cleaned,
            "auto_values_mA": _auto_transition_values_for_annealing_record(record),
        }
        setter(record_id, payload)

    def _record_for_row(self, row: Optional[pd.Series]) -> Optional[MeasurementRecord]:
        if row is None:
            return None
        record_id = str(row.get("_record_id") or "").strip()
        if not record_id:
            return None
        lookup = getattr(self._annealing_section, "_record_by_transition_id", None)
        if callable(lookup):
            try:
                record = lookup(record_id)
            except Exception:
                record = None
            if isinstance(record, MeasurementRecord):
                return record
        key = self._parse_group_key(row.get("_group_key"))
        if key is None:
            return None
        high, other_records = self._fetch_records_for_key(key)
        for record in (high, *other_records):
            if record is not None and _transition_record_id_for_annealing_record(record) == record_id:
                return record
        return None

    def _source_row(self, proxy_row: int) -> Optional[int]:
        return self._search_proxy.map_row_to_source(proxy_row)

    def _handle_search_changed(self, text: str) -> None:
        self._search_proxy.set_search_text(text)
        if isinstance(self.search_clear_button, QtWidgets.QPushButton):
            self.search_clear_button.setEnabled(bool(str(text).strip()))

    @staticmethod
    def _coerce_phase_value(value: Any) -> Optional[float]:
        if value is None:
            return None
        if hasattr(pd, "isna"):
            try:
                if pd.isna(value):
                    return None
            except Exception:
                pass
        if isinstance(value, (int, float)):
            numeric = float(value)
            return numeric if math.isfinite(numeric) else None
        if isinstance(value, str):
            text = value.strip()
            if not text:
                return None
            try:
                numeric = float(text)
            except ValueError:
                return None
            return numeric if math.isfinite(numeric) else None
        return None

    def _fetch_records_for_key(
        self,
        key: MicrowireKey,
    ) -> Tuple[Optional[MeasurementRecord], List[MeasurementRecord]]:
        key_str = _microwire_key_to_str(key)
        groups = getattr(self._annealing_section, "_record_groups", {})
        if not isinstance(groups, dict):
            return None, []
        records = groups.get(key_str, [])
        if not records:
            parts = _split_microwire_key(key)
            if parts is not None:
                composition, draw, piece, _suffix = parts
                base_key = _microwire_key_to_str((composition, draw, piece, None))
                records = groups.get(base_key, [])
        if not records:
            return None, []
        return _select_anchor_and_other_records(records)

    @staticmethod
    def _parse_group_key(value: object) -> Optional[MicrowireKey]:
        if value is None:
            return None
        text = str(value).strip()
        if not text:
            return None
        return _microwire_key_from_string(text)

    @staticmethod
    def _empty_review_counts() -> Dict[str, int]:
        return {
            "total": 0,
            "accepted": 0,
            "manual": 0,
            "no_transition": 0,
            "excluded": 0,
            "needs_attention": 0,
            "unreviewed": 0,
            "auto_candidates": 0,
        }

    @staticmethod
    def _format_review_counts(counts: Mapping[str, int]) -> str:
        if int(counts.get("total", 0) or 0) <= 0:
            return ""
        keys = (
            "total",
            "accepted",
            "manual",
            "no_transition",
            "excluded",
            "needs_attention",
            "unreviewed",
            "auto_candidates",
        )
        return "; ".join(f"{key}={int(counts.get(key, 0) or 0)}" for key in keys)

    @staticmethod
    def _status_from_review_counts(counts: Mapping[str, int]) -> str:
        total = int(counts.get("total", 0) or 0)
        if total <= 0:
            return "Not measured"
        manual = int(counts.get("manual", 0) or 0)
        accepted = int(counts.get("accepted", 0) or 0)
        no_transition = int(counts.get("no_transition", 0) or 0)
        excluded = int(counts.get("excluded", 0) or 0)
        needs_attention = int(counts.get("needs_attention", 0) or 0)
        unreviewed = int(counts.get("unreviewed", 0) or 0)
        negative = no_transition + excluded
        reviewed = manual + accepted + negative
        if needs_attention and needs_attention == total:
            return "Needs attention"
        if manual == total:
            return "Manual adjusted"
        if accepted == total:
            return "Accepted auto"
        if negative == total:
            return "No transition" if no_transition else "Excluded"
        if reviewed or needs_attention:
            return "Partly reviewed"
        if int(counts.get("auto_candidates", 0) or 0):
            return "Auto candidate"
        if unreviewed or total:
            return "Unreviewed"
        return "Not measured"

    def _review_counts_for_annealing_records(
        self,
        records: Sequence[MeasurementRecord],
    ) -> Dict[str, int]:
        counts = self._empty_review_counts()
        annealing = self._annealing_section
        snapshot_provider = getattr(annealing, "transition_reviews_snapshot", None)
        if callable(snapshot_provider):
            raw_reviews = snapshot_provider()
        else:
            raw_reviews = getattr(annealing, "_transition_reviews", {})
        if not isinstance(raw_reviews, dict):
            raw_reviews = {}
        for record in records:
            counts["total"] += 1
            record_id = _transition_record_id_for_annealing_record(record)
            payload = raw_reviews.get(record_id, {}) if isinstance(raw_reviews, dict) else {}
            status = str(payload.get("status") if isinstance(payload, dict) else "").strip()
            if status == TRANSITION_REVIEW_STATUS_MANUAL_ADJUSTED:
                counts["manual"] += 1
            elif status == TRANSITION_REVIEW_STATUS_ACCEPTED_AUTO:
                counts["accepted"] += 1
            elif status == TRANSITION_REVIEW_STATUS_NO_TRANSITION:
                counts["no_transition"] += 1
            elif status == TRANSITION_REVIEW_STATUS_EXCLUDED:
                counts["excluded"] += 1
            elif status == TRANSITION_REVIEW_STATUS_NEEDS_ATTENTION:
                counts["needs_attention"] += 1
            else:
                counts["unreviewed"] += 1
                if _auto_transition_values_for_annealing_record(record):
                    counts["auto_candidates"] += 1
        return counts

    def _calculate_frame(self) -> pd.DataFrame:
        diameter_map = self._collect_microscope_data()
        setpoint_map = self._collect_setpoint_data()
        phase_map = self._collect_phase_points()
        groups = getattr(self._annealing_section, "_record_groups", {})
        keys = sorted(
            set(setpoint_map.keys()) | set(phase_map.keys()),
            key=lambda item: (
                str(item[0]).lower(),
                int(item[1]),
                int(item[2]),
                (str(item[3]).lower() if item[3] is not None else ""),
            ),
        )
        rows: List[Dict[str, Any]] = []
        all_sources: Set[str] = set()
        if not keys:
            columns = CURRENT_DENSITY_COLUMNS + ["_group_key", "_record_id"]
            return pd.DataFrame(columns=columns)
        for composition, draw, piece, suffix in keys:
            key = (composition, draw, piece, suffix)
            base_key = (composition, draw, piece, None)
            micro_info = diameter_map.get(key) or diameter_map.get(base_key, {})
            setpoint_info = setpoint_map.get(key) or setpoint_map.get(base_key, {})
            diameter_um = micro_info.get("diameter")
            area_mm2 = self._diameter_to_area(diameter_um)
            setpoints = setpoint_info.get("setpoints", [])
            sources = setpoint_info.get("sources", [])
            all_sources.update(str(source) for source in sources)
            composition_label = micro_info.get("composition") or setpoint_info.get("composition") or composition
            try:
                microwire_label = micro_info.get("label") or _microwire_label(draw, piece, suffix)
            except Exception:
                microwire_label = micro_info.get("label") or f"{draw}/{piece}"
            key_text = _microwire_key_to_str(key)
            records = []
            if isinstance(groups, dict):
                raw_records = groups.get(key_text, [])
                if not raw_records and suffix is not None:
                    raw_records = groups.get(_microwire_key_to_str(base_key), [])
                if isinstance(raw_records, list):
                    high_record, other_records = _select_anchor_and_other_records(raw_records)
                    records = [record for record in (high_record, *other_records) if record is not None]
            if not records:
                rows.append(
                    self._current_density_row(
                        composition_label,
                        microwire_label,
                        diameter_um,
                        area_mm2,
                        phase_map.get(key) or phase_map.get(base_key, {}),
                        setpoints,
                        sources,
                        key_text,
                        graph_label="",
                        record=None,
                    )
                )
                continue
            for record in records:
                row_sources = list(sources)
                path = getattr(record, "path", None)
                if path:
                    try:
                        row_sources.append(str(Path(path)))
                    except Exception:
                        row_sources.append(str(path))
                all_sources.update(str(source) for source in row_sources)
                rows.append(
                    self._current_density_row(
                        composition_label,
                        microwire_label,
                        diameter_um,
                        area_mm2,
                        self._phase_values_for_annealing_record(record),
                        setpoints,
                        row_sources,
                        key_text,
                        graph_label=_record_label_for_display(record),
                        record=record,
                    )
                )
        self._last_sources = sorted(all_sources)
        if not rows:
            columns = CURRENT_DENSITY_COLUMNS + ["_group_key", "_record_id"]
            return pd.DataFrame(columns=columns)
        frame = pd.DataFrame(rows)
        desired_order = [column for column in CURRENT_DENSITY_COLUMNS + ["_group_key", "_record_id"] if column in frame.columns]
        return frame.loc[:, desired_order]

    def _phase_values_for_annealing_record(self, record: MeasurementRecord) -> Dict[str, float]:
        values = _auto_transition_values_for_annealing_record(record)
        record_id = _transition_record_id_for_annealing_record(record)
        snapshot_provider = getattr(self._annealing_section, "transition_reviews_snapshot", None)
        raw_reviews = snapshot_provider() if callable(snapshot_provider) else getattr(self._annealing_section, "_transition_reviews", {})
        payload = raw_reviews.get(record_id, {}) if isinstance(raw_reviews, dict) else {}
        if isinstance(payload, dict):
            status = str(payload.get("status") or "").strip()
            if status in {
                TRANSITION_REVIEW_STATUS_NO_TRANSITION,
                TRANSITION_REVIEW_STATUS_EXCLUDED,
            }:
                return {}
            final_values = _clean_transition_values(payload.get("final_values_mA"))
            manual_values = _clean_transition_values(payload.get("manual_values_mA"))
            if final_values:
                values.update(final_values)
            if manual_values:
                values.update(manual_values)
        return values

    def _current_density_row(
        self,
        composition_label: str,
        microwire_label: str,
        diameter_um: Any,
        area_mm2: Optional[float],
        phase_info: Mapping[str, Any],
        setpoints: Sequence[Any],
        sources: Sequence[Any],
        key_text: str,
        *,
        graph_label: str,
        record: Optional[MeasurementRecord],
    ) -> Dict[str, Any]:
        phase_values = dict(phase_info)
        if phase_values.get("As1") is None and phase_values.get("As") is not None:
            phase_values["As1"] = phase_values.get("As")
        if phase_values.get("Ms1") is None and phase_values.get("Ms") is not None:
            phase_values["Ms1"] = phase_values.get("Ms")
        notes: List[str] = []
        if diameter_um is None or area_mm2 is None:
            notes.append("Missing diameter")
        as1_value = phase_values.get("As1")
        af1_value = phase_values.get("Af1")
        ms1_value = phase_values.get("Ms1")
        mf1_value = phase_values.get("Mf1")
        as2_value = phase_values.get("As2")
        af2_value = phase_values.get("Af2")
        ms2_value = phase_values.get("Ms2")
        mf2_value = phase_values.get("Mf2")
        if as1_value is None:
            notes.append("As1 missing")
        if ms1_value is None:
            notes.append("Ms1 missing")
        if not setpoints:
            notes.append("No setpoint data")
        review_records = [record] if record is not None else []
        review_counts = self._review_counts_for_annealing_records(review_records)
        return {
            "Composition": composition_label,
            "Microwire": microwire_label,
            "Graph": graph_label,
            MICROSCOPE_D_COLUMN: diameter_um,
            ANNEALING_AS_COLUMN: as1_value,
            ANNEALING_AF1_COLUMN: af1_value,
            ANNEALING_MS_COLUMN: ms1_value,
            ANNEALING_MF1_COLUMN: mf1_value,
            ANNEALING_AS2_COLUMN: as2_value,
            ANNEALING_AF2_COLUMN: af2_value,
            ANNEALING_MS2_COLUMN: ms2_value,
            ANNEALING_MF2_COLUMN: mf2_value,
            CURRENT_DENSITY_AS_DENSITY_COLUMN: self._compute_density(as1_value, area_mm2),
            CURRENT_DENSITY_MS_DENSITY_COLUMN: self._compute_density(ms1_value, area_mm2),
            **{
                column: self._compute_density(phase_values.get(label), area_mm2)
                for label, column in CURRENT_DENSITY_PER_LABEL_COLUMNS.items()
            },
            CURRENT_DENSITY_AS_DELTA_COLUMN: self._compute_delta(as2_value, as1_value),
            CURRENT_DENSITY_AF_DELTA_COLUMN: self._compute_delta(af2_value, af1_value),
            CURRENT_DENSITY_MS_DELTA_COLUMN: self._compute_delta(ms2_value, ms1_value),
            CURRENT_DENSITY_MF_DELTA_COLUMN: self._compute_delta(mf2_value, mf1_value),
            CURRENT_DENSITY_MF_AF1_DELTA_COLUMN: self._compute_delta(mf1_value, af1_value),
            CURRENT_DENSITY_MF_AF2_DELTA_COLUMN: self._compute_delta(mf2_value, af2_value),
            "Setpoints (mA)": self._format_setpoints(setpoints),
            "Sources": self._summarise_sources(sources),
            CURRENT_ANNEALING_TRANSITION_STATUS_COLUMN: self._status_from_review_counts(review_counts),
            CURRENT_ANNEALING_TRANSITION_COUNTS_COLUMN: self._format_review_counts(review_counts),
            "Notes": "; ".join(notes) if notes else "",
            "_group_key": key_text,
            "_record_id": _transition_record_id_for_annealing_record(record) if record is not None else "",
        }

    def _collect_microscope_data(self) -> Dict[MicrowireKey, Dict[str, Any]]:
        result: Dict[MicrowireKey, Dict[str, Any]] = {}
        table = getattr(getattr(self._microscope_section, "data", None), "table", None)
        if not isinstance(table, pd.DataFrame) or table.empty:
            return result
        for _, row in table.iterrows():
            key = self._extract_key(row.get("Composition"), row.get("Microwire"), row.get("_key"))
            if key is None:
                continue
            composition, draw, piece, suffix = key
            diameter = _diameter_um_from_mapping(row.to_dict())
            composition_label = self._normalise_text(row.get("Composition")) or composition
            label = self._normalise_text(row.get("Microwire"))
            if not label:
                try:
                    label = _microwire_label(draw, piece, suffix)
                except Exception:
                    label = f"{draw}/{piece}"
            result[key] = {
                "composition": composition_label,
                "label": label,
                "diameter": diameter,
            }
        return result

    def _collect_setpoint_data(self) -> Dict[MicrowireKey, Dict[str, Any]]:
        result: Dict[MicrowireKey, Dict[str, Any]] = {}
        groups = getattr(self._annealing_section, "_record_groups", {})
        if not isinstance(groups, dict) or not groups:
            return result
        for records in groups.values():
            for record in records:
                metadata = getattr(record, "metadata", None)
                if metadata is None:
                    continue
                composition = getattr(metadata, "composition_token", None)
                draw = getattr(metadata, "draw_x", None)
                piece = getattr(metadata, "piece_y", None)
                setpoint = getattr(metadata, "setpoint_mA", None)
                if (
                    composition is None
                    or draw is None
                    or piece is None
                    or setpoint is None
                ):
                    continue
                suffix = None
                path = getattr(record, "path", None)
                if isinstance(path, Path):
                    parsed_key = _microscope_key(path)
                    if parsed_key is not None:
                        _, _, _, suffix = parsed_key
                try:
                    key = (
                        str(composition),
                        int(draw),
                        int(piece),
                        str(suffix).strip() if suffix is not None and str(suffix).strip() else None,
                    )
                    setpoint_value = float(setpoint)
                except (TypeError, ValueError):
                    continue
                if not math.isfinite(setpoint_value):
                    continue
                entry = result.setdefault(
                    key,
                    {
                        "setpoints": [],
                        "sources": set(),
                        "composition": str(composition),
                    },
                )
                entry["setpoints"].append(setpoint_value)
                path = getattr(record, "path", None)
                if path:
                    try:
                        entry["sources"].add(str(Path(path)))
                    except Exception:
                        pass
        for entry in result.values():
            entry["setpoints"] = sorted(dict.fromkeys(entry["setpoints"]))
            entry["sources"] = sorted(entry["sources"])
        return result

    def _collect_phase_points(self) -> Dict[MicrowireKey, Dict[str, float]]:
        result = self._collect_auto_annealing_phase_points()
        for key_tuple, values in self._collect_reviewed_transition_phase_points().items():
            combined = dict(result.get(key_tuple, {}))
            combined.update(values)
            result[key_tuple] = combined
        return result

    def _collect_reviewed_transition_phase_points(self) -> Dict[MicrowireKey, Dict[str, float]]:
        annealing = self._annealing_section
        snapshot_provider = getattr(annealing, "transition_reviews_snapshot", None)
        if callable(snapshot_provider):
            raw_reviews = snapshot_provider()
        else:
            raw_reviews = getattr(annealing, "_transition_reviews", {})
        if not isinstance(raw_reviews, dict):
            return {}
        candidates: Dict[MicrowireKey, List[Tuple[Tuple[int, float, str], Dict[str, float]]]] = {}
        for record_id, payload in raw_reviews.items():
            if not isinstance(payload, dict):
                continue
            if payload.get("included") is False:
                continue
            status = str(payload.get("status") or "").strip()
            if status and status not in TRANSITION_REVIEW_INCLUDED_STATUSES:
                continue
            key_text = str(payload.get("sample_key") or "").strip()
            if not key_text:
                record = None
                lookup = getattr(annealing, "_record_by_transition_id", None)
                if callable(lookup):
                    record = lookup(str(record_id))
                if record is not None:
                    key_text = _phase_point_key_for_annealing_record(record) or ""
            key_tuple = _microwire_key_from_string(key_text)
            if key_tuple is None:
                continue
            values = _clean_transition_values(payload.get("auto_values_mA"))
            final_values = _clean_transition_values(payload.get("final_values_mA"))
            manual_values = _clean_transition_values(payload.get("manual_values_mA"))
            if final_values:
                values.update(final_values)
            if manual_values:
                values.update(manual_values)
            if not values:
                continue
            setpoint = _coerce_finite_float(payload.get("setpoint_mA"))
            setpoint_sort = -setpoint if setpoint is not None else float("inf")
            status_rank = 0 if status == TRANSITION_REVIEW_STATUS_MANUAL_ADJUSTED else 1
            graph_label = str(payload.get("graph_label") or record_id)
            candidates.setdefault(key_tuple, []).append(((status_rank, setpoint_sort, graph_label), values))
        result: Dict[MicrowireKey, Dict[str, float]] = {}
        for key_tuple, entries in candidates.items():
            if not entries:
                continue
            _sort_key, selected = min(entries, key=lambda item: item[0])
            result[key_tuple] = dict(selected)
        return result

    def _collect_auto_annealing_phase_points(self) -> Dict[MicrowireKey, Dict[str, float]]:
        result: Dict[MicrowireKey, Dict[str, float]] = {}
        groups = getattr(self._annealing_section, "_record_groups", {})
        if not isinstance(groups, dict):
            return result
        for key_text, records in groups.items():
            if not isinstance(records, list):
                continue
            key = _microwire_key_from_string(str(key_text))
            if key is None:
                continue
            candidates: List[Tuple[Tuple[int, float, str], Dict[str, float]]] = []
            for record in records:
                dataframe = getattr(record, "dataframe", None)
                if not isinstance(dataframe, pd.DataFrame) or dataframe.empty:
                    continue
                try:
                    summary = summarize_annealing_transition_currents(dataframe)
                except Exception:
                    continue
                values = {
                    "As1": summary.as_current_mA,
                    "Af1": summary.af_current_mA,
                    "Ms1": summary.ms_current_mA,
                    "Mf1": summary.mf_current_mA,
                }
                cleaned: Dict[str, float] = {}
                for label, value in values.items():
                    if isinstance(value, (int, float)) and math.isfinite(float(value)):
                        cleaned[label] = float(value)
                if set(cleaned) != {"As1", "Af1", "Ms1", "Mf1"}:
                    continue
                metadata = getattr(record, "metadata", None)
                setpoint = getattr(metadata, "setpoint_mA", None)
                try:
                    setpoint_value = float(setpoint)
                except (TypeError, ValueError):
                    setpoint_value = float("inf")
                high_anchor = 1 if math.isfinite(setpoint_value) and setpoint_value >= 900.0 else 0
                filename = str(getattr(metadata, "file_name", "") or getattr(record, "path", ""))
                candidates.append(((high_anchor, setpoint_value, filename), cleaned))
            if not candidates:
                continue
            _sort_key, selected = min(candidates, key=lambda item: item[0])
            selected = dict(selected)
            selected["As"] = selected["As1"]
            selected["Ms"] = selected["Ms1"]
            result[key] = selected
        return result

    @staticmethod
    def _normalise_text(value: object) -> str:
        if value is None:
            return ""
        if isinstance(value, (float, int)):
            try:
                if math.isnan(float(value)):
                    return ""
            except Exception:
                pass
        text = str(value).strip()
        if not text or text.lower() in {"nan", "none"}:
            return ""
        return text

    def _extract_key(
        self,
        composition: object,
        microwire: object,
        stored_key: object,
    ) -> Optional[MicrowireKey]:
        comp_text = self._normalise_text(composition)
        if isinstance(stored_key, str):
            parts = _microwire_key_from_string(stored_key)
            if parts is not None:
                base_comp, draw, piece, suffix = parts
                comp_value = comp_text or base_comp
                if comp_value:
                    return (comp_value, draw, piece, suffix)
        label_text = self._normalise_text(microwire)
        if label_text and comp_text:
            draw_piece = _microwire_parts_from_label_safe(label_text)
            if draw_piece is not None:
                draw, piece, suffix = draw_piece
                return (comp_text, int(draw), int(piece), suffix)
        return None

    @staticmethod
    def _to_positive_float(value: object) -> Optional[float]:
        if value is None:
            return None
        if isinstance(value, (int, float)):
            numeric = float(value)
        else:
            text = str(value).strip().replace(",", ".")
            if not text:
                return None
            try:
                numeric = float(text)
            except ValueError:
                return None
        if not math.isfinite(numeric) or numeric <= 0:
            return None
        return numeric

    @staticmethod
    def _diameter_to_area(diameter_um: Optional[float]) -> Optional[float]:
        if diameter_um is None or not math.isfinite(diameter_um) or diameter_um <= 0:
            return None
        radius_mm = (diameter_um * 1e-3) / 2.0
        if radius_mm <= 0:
            return None
        return math.pi * radius_mm * radius_mm

    @staticmethod
    def _compute_density(setpoint_mA: Optional[float], area_mm2: Optional[float]) -> Optional[float]:
        if setpoint_mA is None or area_mm2 is None or area_mm2 <= 0:
            return None
        current_A = setpoint_mA / 1000.0
        return current_A / area_mm2

    @staticmethod
    def _compute_delta(value_2: Optional[float], value_1: Optional[float]) -> Optional[float]:
        if value_2 is None or value_1 is None:
            return None
        if not (math.isfinite(value_2) and math.isfinite(value_1)):
            return None
        return value_2 - value_1

    @staticmethod
    def _format_setpoints(values: Sequence[float]) -> str:
        if not values:
            return ""
        formatted = [f"{value:.3f}".rstrip("0").rstrip(".") if isinstance(value, float) else str(value) for value in values]
        return ", ".join(formatted)

    @staticmethod
    def _summarise_sources(sources: Iterable[str]) -> str:
        unique = []
        for entry in sources:
            text = str(entry)
            if text and text not in unique:
                unique.append(text)
        names = [Path(text).name for text in unique]
        return ", ".join(names)

    def _current_column_order(self) -> List[str]:
        header = self.table_view.horizontalHeader()
        frame = self.model.frame()
        if header is None or not isinstance(frame, pd.DataFrame):
            return []
        order: List[str] = []
        for visual_index in range(header.count()):
            logical = header.logicalIndex(visual_index)
            try:
                column = str(frame.columns[logical])
            except Exception:
                continue
            order.append(column)
        return order

    def _apply_column_order(self, order: Sequence[str]) -> None:
        if not order:
            return
        header = self.table_view.horizontalHeader()
        frame = self.model.frame()
        if header is None or not isinstance(frame, pd.DataFrame):
            return
        mapping = {str(column): idx for idx, column in enumerate(frame.columns)}
        for target_visual, column_name in enumerate(order):
            logical = mapping.get(column_name)
            if logical is None:
                continue
            current_visual = header.visualIndex(logical)
            if current_visual == target_visual:
                continue
            header.moveSection(current_visual, target_visual)

    def _ordered_export_frame(self) -> pd.DataFrame:
        frame = self.model.frame()
        if not isinstance(frame, pd.DataFrame):
            return pd.DataFrame(columns=CURRENT_DENSITY_COLUMNS)
        order = self._current_column_order()
        if order:
            missing = [column for column in frame.columns if column not in order]
            order = list(order) + missing
            export_frame = frame.loc[:, order].copy()
        else:
            export_frame = frame.copy()
        export_frame = export_frame.loc[
            :,
            [column for column in export_frame.columns if not str(column).startswith("_")],
        ]
        return export_frame

    def _export_worksheet(self) -> None:
        frame = self._ordered_export_frame()
        if frame.empty:
            QtWidgets.QMessageBox.information(
                self,
                "Export worksheet",
                "There is no current density data to export yet.",
            )
            return
        start_dir = _dialog_start_directory()
        suggested = start_dir / "current_density.xlsx"
        path_str, selected_filter = QtWidgets.QFileDialog.getSaveFileName(
            self,
            "Export worksheet",
            str(suggested),
            "Excel files (*.xlsx);;CSV files (*.csv)",
        )
        if not path_str:
            return
        path = Path(path_str)
        suffix = path.suffix.lower()
        if suffix not in {".xlsx", ".csv"}:
            if "Excel" in selected_filter:
                path = path.with_suffix(".xlsx")
                suffix = ".xlsx"
            else:
                path = path.with_suffix(".csv")
                suffix = ".csv"
        export_frame = frame.copy()
        for column in export_frame.columns:
            series = export_frame[column]
            if getattr(series, "dtype", None) == object:
                export_frame[column] = series.map(
                    lambda value: "" if isinstance(value, (QtGui.QPixmap, QtGui.QImage)) else value
                )
        try:
            if suffix == ".xlsx":
                export_frame.to_excel(path, index=False)
            else:
                export_frame.to_csv(path, index=False)
        except Exception as exc:
            self.logger.exception("Failed to export current density worksheet")
            QtWidgets.QMessageBox.critical(
                self,
                "Export worksheet",
                f"Failed to export worksheet:\n{exc}",
            )
            return
        self.log(f"Annealing transitions worksheet exported to {path}")
        QtWidgets.QMessageBox.information(
            self,
            "Export worksheet",
            f"Worksheet exported to:\n{path}",
        )


def _vsm_transition_review_record_id(record: VsmTemperatureScanRecord) -> str:
    path = getattr(record, "path", None)
    if isinstance(path, Path):
        try:
            path_text = str(path.resolve())
        except Exception:
            path_text = str(path)
    else:
        path_text = ""
    parts = [
        "vsm_temperature_scan",
        path_text,
        str(getattr(record, "sample", "") or ""),
        str(getattr(record, "label", "") or ""),
        repr(getattr(record, "key", None)),
    ]
    digest = hashlib.sha1("\n".join(parts).encode("utf-8", errors="replace")).hexdigest()[:16]
    return f"vsm-ts:{digest}"


def _vsm_transition_review_is_final(status: str | None) -> bool:
    return str(status or "").strip() in {
        TRANSITION_REVIEW_STATUS_ACCEPTED_AUTO,
        TRANSITION_REVIEW_STATUS_MANUAL_ADJUSTED,
        TRANSITION_REVIEW_STATUS_NO_TRANSITION,
        TRANSITION_REVIEW_STATUS_EXCLUDED,
    }


def _vsm_transition_review_blocks_values(payload: Mapping[str, Any] | None) -> bool:
    if not isinstance(payload, Mapping):
        return False
    status = str(payload.get("status") or "").strip()
    return status in {
        TRANSITION_REVIEW_STATUS_NO_TRANSITION,
        TRANSITION_REVIEW_STATUS_EXCLUDED,
    }


class _TransitionTempPreviewPanel(QtWidgets.QWidget):
    valuePicked = QtCore.pyqtSignal(str, float)
    valueCleared = QtCore.pyqtSignal(str)
    acceptNextRequested = QtCore.pyqtSignal()
    noTransitionRequested = QtCore.pyqtSignal()
    excludeRequested = QtCore.pyqtSignal()
    previousRequested = QtCore.pyqtSignal()
    nextUnreviewedRequested = QtCore.pyqtSignal()
    scanChanged = QtCore.pyqtSignal()

