        self.excel_checkbox.setChecked(export_excel)
        formats_layout.addWidget(self.excel_checkbox)
        self.html_checkbox = QtWidgets.QCheckBox("HTML (self-contained)")
        self.html_checkbox.setChecked(export_html)
