    def log(self, message: str, level: int = logging.INFO) -> None:
        try:
            self._log_callback(level, message)
        except Exception:
            self.logger.log(level, message)

    def attach_compare_section(self, compare_section: "CompareSection") -> None:
        self._compare_section = compare_section
        self._update_preview_graph_buttons()

    def attach_project_context(self, path_getter: Callable[[], Optional[Path]]) -> None:
        self._project_path_getter = path_getter

    def invalidate_source_caches(self) -> None:
        _clear_source_record_caches(self)
        self._graph_pixmap_cache.clear()
        model = getattr(self, "preview_model", None)
        if isinstance(model, DataFrameModel):
            try:
                model.layoutChanged.emit()
            except Exception:
                pass

    def _analysis_filtered_rows(self) -> tuple[int, ...]:
        raw_frame = self._raw_preview_frame
        if not isinstance(raw_frame, pd.DataFrame) or raw_frame.empty:
            return ()
        if self._preview_row_index_map:
            return tuple(
                idx for idx in self._preview_row_index_map if 0 <= int(idx) < len(raw_frame.index)
            )
        return tuple(range(len(raw_frame.index)))

    def _analysis_selected_rows(self) -> tuple[int, ...]:
        raw_frame = self._raw_preview_frame
        if not isinstance(raw_frame, pd.DataFrame) or raw_frame.empty:
            return ()
        mapped_rows: list[int] = []
        for row in self._selected_preview_rows():
            if row < 0:
                continue
            if self._preview_row_index_map and row < len(self._preview_row_index_map):
                mapped_rows.append(int(self._preview_row_index_map[row]))
            else:
                mapped_rows.append(int(row))
        return tuple(sorted({idx for idx in mapped_rows if 0 <= idx < len(raw_frame.index)}))

    def _open_eda_window(self) -> None:
        from microwire_eda.core import MicrowireEdaConfig, ROW_SCOPE_ALL, ROW_SCOPE_FILTERED

        raw_frame = self._raw_preview_frame if isinstance(self._raw_preview_frame, pd.DataFrame) else None
        project_path = self._project_path_getter() if callable(self._project_path_getter) else None
        if raw_frame is None or raw_frame.empty:
            if project_path is None:
                QtWidgets.QMessageBox.information(
                    self,
                    "Microwire EDA",
                    "Preview the database or save/open a project before launching analysis.",
                )
                return
            config = MicrowireEdaConfig(
                input_path=project_path,
                row_scope=ROW_SCOPE_ALL,
                output_dir=Path(self._output_dir or Path.cwd()) / "eda_report",
                report_title="Microwire EDA Report",
            )
            _open_microwire_eda_window(config, self.logger)
            return

        filtered_rows = self._analysis_filtered_rows()
        selected_rows = self._analysis_selected_rows()
        default_scope = ROW_SCOPE_FILTERED if filtered_rows else ROW_SCOPE_ALL
        source_frame = raw_frame.copy()
        filtered_scope_rows: tuple[int, ...] = ()
        selected_scope_rows: tuple[int, ...] = ()
        if filtered_rows:
            source_frame = raw_frame.iloc[list(filtered_rows)].reset_index(drop=True)
            filtered_scope_rows = tuple(range(len(source_frame.index)))
            filtered_index_map = {int(original): idx for idx, original in enumerate(filtered_rows)}
            selected_scope_rows = tuple(
                filtered_index_map[idx]
                for idx in selected_rows
                if int(idx) in filtered_index_map
            )
        config = MicrowireEdaConfig(
            input_path=project_path,
            row_scope=default_scope,
            output_dir=Path(self._output_dir or Path.cwd()) / "eda_report",
            report_title="Microwire EDA Report",
            source_dataframe=source_frame,
            filtered_row_indices=filtered_scope_rows,
            selected_row_indices=selected_scope_rows,
            metadata={"source": "builder_assemble"},
        )
        _open_microwire_eda_window(config, self.logger)

    def has_project_data(self) -> bool:
        frame = self._raw_preview_frame
        return isinstance(frame, pd.DataFrame) and not frame.empty

    @staticmethod
    def _dedupe_frame_columns(frame: pd.DataFrame) -> pd.DataFrame:
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return frame
        columns = [str(column) for column in frame.columns]
        seen: Set[str] = set()
        duplicates = [column for column in columns if column in seen or seen.add(column)]
        if not duplicates:
            return frame
        deduped = pd.DataFrame(index=frame.index)
        for column in columns:
            if column in deduped.columns:
                existing = deduped[column]
                incoming = frame[column]
                if isinstance(incoming, pd.DataFrame):
                    for _, series in incoming.items():
                        existing = existing.where(~(existing.isna() | (existing == "")), series)
                    deduped[column] = existing
                else:
                    deduped[column] = existing.where(
                        ~(existing.isna() | (existing == "")),
                        incoming,
                    )
                continue
            incoming = frame[column]
            if isinstance(incoming, pd.DataFrame):
                first = incoming.iloc[:, 0].copy()
                for idx in range(1, incoming.shape[1]):
                    series = incoming.iloc[:, idx]
                    first = first.where(~(first.isna() | (first == "")), series)
                deduped[column] = first
            else:
                deduped[column] = incoming.copy()
        return deduped

    def export_project_payload(self) -> Dict[str, Any]:
        frame = self._raw_preview_frame if isinstance(self._raw_preview_frame, pd.DataFrame) else pd.DataFrame()
        frame = _with_source_label_column(frame)
        frame = self._dedupe_frame_columns(frame)
        columns = [str(col) for col in getattr(frame, "columns", [])]
        rows: List[Dict[str, Any]] = []
        if not frame.empty:
            for record in frame.to_dict(orient="records"):
                payload: Dict[str, Any] = {}
                for column in columns:
                    payload[column] = _json_safe(record.get(column))
                rows.append(payload)
        index_payload: List[Any] = []
        if not frame.empty:
            for entry in frame.index.tolist():
                index_payload.append(_json_safe(entry))
        return {
            "section": "assemble",
            "title": "Assemble",
            "columns": columns,
            "rows": rows,
            "index": index_payload,
            "selected_columns": list(self._selected_columns or []),
            "column_order": list(self._column_order),
            "sort_spec": list(self._sort_spec),
            "search_query": self._preview_search_text,
            "source_filter": self._preview_source_filter_text,
            "export_settings": self._export_settings_payload(),
            "graph_preview": bool(self.graph_panel_checkbox.isChecked()),
            "imported_rows": [
                {str(key): _json_safe(val) for key, val in row.items()}
                for row in self._imported_rows.values()
            ],
            "imported_sources": list(self._imported_sources),
            "show_imported": bool(self._show_imported),
            "show_oe_samples": bool(self._show_oe_samples),
        }

    def import_project_payload(self, payload: Mapping[str, Any]) -> None:
        if not isinstance(payload, Mapping):
            return
        self._apply_export_settings(payload.get("export_settings", {}))
        graph_preview = payload.get("graph_preview")
        if isinstance(graph_preview, bool):
            try:
                if _builder_project_load_active():
                    blocker = QtCore.QSignalBlocker(self.graph_panel_checkbox)
                    try:
                        self.graph_panel_checkbox.setChecked(False)
                    finally:
                        del blocker
                    if hasattr(self, "graph_preview_panel"):
                        self.graph_preview_panel.setVisible(False)
                else:
                    self.graph_panel_checkbox.setChecked(graph_preview)
            except Exception:
                pass
        selected_columns = payload.get("selected_columns")
        if isinstance(selected_columns, (list, tuple)):
            mapped = []
            for col in selected_columns:
                if not col:
                    continue
                mapped.append(self._normalise_saved_column_name(col))
            self._selected_columns = set(mapped)
        else:
            self._selected_columns = None
        column_order = payload.get("column_order")
        if isinstance(column_order, (list, tuple)):
            mapped = []
            for col in column_order:
                if not col:
                    continue
                mapped.append(self._normalise_saved_column_name(col))
            self._column_order = mapped
        else:
            self._column_order = []
        sort_spec = payload.get("sort_spec")
        restored_sort: List[Tuple[str, bool]] = []
        if isinstance(sort_spec, (list, tuple)):
            for entry in sort_spec:
                if not entry:
                    continue
                if isinstance(entry, (list, tuple)) and entry:
                    column = entry[0]
                    ascending = entry[1] if len(entry) > 1 else True
                elif isinstance(entry, dict):
                    column = entry.get("column")
                    ascending = entry.get("ascending", True)
                else:
                    continue
                if isinstance(column, str):
                    column = self._normalise_saved_column_name(column)
                    restored_sort.append((column, bool(ascending)))
        self._sort_spec = restored_sort
        search_query = payload.get("search_query")
        if isinstance(search_query, str):
            self._preview_search_text = self._normalise_search_text(search_query)
        else:
            self._preview_search_text = ""
        if hasattr(self, "search_edit"):
            self.search_edit.blockSignals(True)
            self.search_edit.setText(self._preview_search_text)
            self.search_edit.blockSignals(False)
        if hasattr(self, "search_clear_button"):
            self.search_clear_button.setEnabled(bool(self._preview_search_text))
        source_filter = payload.get("source_filter")
        self._preview_source_filter_text = (
            str(source_filter).strip()
            if isinstance(source_filter, str) and source_filter.strip()
            else SOURCE_LABEL_ALL
        )

        columns_payload = payload.get("columns")
        if isinstance(columns_payload, (list, tuple)):
            column_names = []
            for column in columns_payload:
                column_names.append(self._normalise_saved_column_name(column))
        else:
            column_names = []
        rows_payload = payload.get("rows")
        if isinstance(rows_payload, (list, tuple)):
            frame = pd.DataFrame(list(rows_payload), columns=column_names or None)
        else:
            frame = pd.DataFrame(columns=column_names)
        if isinstance(frame, pd.DataFrame):
            frame = self._dedupe_frame_columns(frame)
            self._known_columns = {str(column) for column in frame.columns}
        index_payload = payload.get("index")
        if isinstance(index_payload, list) and len(index_payload) == len(frame.index):
            try:
                frame.index = pd.Index(index_payload)
            except Exception:
                pass
        if isinstance(frame, pd.DataFrame):
            frame = self._apply_column_universe(frame)
            frame = _with_source_label_column(frame)
        if self._selected_columns is not None:
            self._sync_section_states_from_columns(self._selected_columns, frame.columns)
        imported_rows = payload.get("imported_rows")
        if isinstance(imported_rows, list):
            cleaned_rows: Dict[str, Dict[str, Any]] = {}
            for row in imported_rows:
                if isinstance(row, Mapping):
                    record = {str(k): v for k, v in row.items()}
                    key = _row_to_microwire_key(pd.Series(record))
                    if key:
                        cleaned_rows[key] = record
            self._imported_rows = cleaned_rows
        imported_sources = payload.get("imported_sources")
        if isinstance(imported_sources, list):
            self._imported_sources = [str(entry) for entry in imported_sources if entry]
        show_imported = payload.get("show_imported")
        if isinstance(show_imported, bool):
            self._show_imported = show_imported
        show_oe_samples = payload.get("show_oe_samples")
        if isinstance(show_oe_samples, bool):
            self._show_oe_samples = show_oe_samples
        if hasattr(self, "oe_samples_checkbox"):
            try:
                self.oe_samples_checkbox.blockSignals(True)
                self.oe_samples_checkbox.setChecked(bool(self._show_oe_samples))
            finally:
                self.oe_samples_checkbox.blockSignals(False)
        self._measured_preview_frame = None
        self._raw_preview_frame = frame
        self._refresh_preview_source_filter_options()
        self._refresh_preview_frame()

    def _open_export_dialog(self) -> None:
        dialog = _AssemblyExportDialog(
            output_dir=self._output_dir,
            output_name=self._output_name,
            export_csv=self._export_csv,
            export_excel=self._export_excel,
            export_html=self._export_html,
            export_word=self._export_word,
            export_matplotlib=self._export_matplotlib,
            export_origin=self._export_origin,
            parent=self,
        )
        if dialog.exec() == QtWidgets.QDialog.DialogCode.Accepted:
            self._apply_export_settings(dialog.export_settings())
            self._combine()

    def _export_settings_payload(self) -> Dict[str, Any]:
        return {
            "output_dir": self._output_dir,
            "output_name": self._output_name,
            "export_csv": self._export_csv,
            "export_excel": self._export_excel,
            "export_html": self._export_html,
            "export_word": self._export_word,
            "export_matplotlib": self._export_matplotlib,
            "export_origin": self._export_origin,
            "sections": dict(self._section_states),
        }

    def _apply_export_settings(self, settings: Mapping[str, Any]) -> None:
        if not isinstance(settings, Mapping):
            return
        output_dir = settings.get("output_dir")
        if isinstance(output_dir, str) and output_dir.strip():
            self._output_dir = output_dir.strip()
        output_name = settings.get("output_name")
        if isinstance(output_name, str) and output_name.strip():
            self._output_name = output_name.strip()
        self._export_csv = bool(settings.get("export_csv", self._export_csv))
        self._export_excel = bool(settings.get("export_excel", self._export_excel))
        self._export_html = bool(settings.get("export_html", self._export_html))
        self._export_word = bool(settings.get("export_word", self._export_word))
        self._export_matplotlib = bool(settings.get("export_matplotlib", self._export_matplotlib))
        self._export_origin = bool(settings.get("export_origin", self._export_origin))
        if self._export_word:
            self._export_origin = True
        sections = settings.get("sections")
        if isinstance(sections, Mapping):
            for key, _label in self._section_choices:
                if key in sections:
                    self._section_states[key] = bool(sections.get(key))
        self._update_export_summary()

    def _open_import_dialog(self) -> None:
        if openpyxl is None:
            QtWidgets.QMessageBox.warning(
                self,
                "Microwire Data Builder",
                "Importing workbooks requires openpyxl.",
            )
            return
        start_dir = _dialog_start_directory("sample_data")
        path_text, _ = QtWidgets.QFileDialog.getOpenFileName(
            self,
            "Import workbook as source",
            str(start_dir),
            "Excel files (*.xlsx *.xlsm *.xltx *.xltm);;All files (*.*)",
        )
        if not path_text:
            return
        path = Path(path_text)
        fabrication_index = self._load_payload("fabrication", "fabrication_index")
        if not isinstance(fabrication_index, FabricationIndex):
            fabrication_index = FabricationIndex()
        new_rows = self._load_import_rows(path, fabrication_index)
        if not new_rows:
            QtWidgets.QMessageBox.information(
                self,
                "Microwire Data Builder",
                "No usable rows were found in that workbook.",
            )
            return
        stats = self._merge_imported_payload(new_rows)
        if not stats["new_samples"] and not stats["updated_samples"] and not self._imported_rows:
            QtWidgets.QMessageBox.information(
                self,
                "Microwire Data Builder",
                "No new rows were added from that workbook.",
            )
        if str(path) not in self._imported_sources:
            self._imported_sources.append(str(path))
        base_frame = self._measured_preview_frame or self._raw_preview_frame
        if isinstance(base_frame, pd.DataFrame) and not base_frame.empty:
            merged = self._merge_imported_rows(base_frame)
            self._update_preview(merged)
        else:
            self._update_preview(pd.DataFrame(list(self._imported_rows.values())))
        self._sync_imports_to_fabrication()
        summary_lines = [
            f"Imported workbook: {path.name}",
            f"New samples added: {stats['new_samples']}",
            f"Existing samples updated: {stats['updated_samples']}",
            "Imported rows are tagged as Source = Imported for the Source filter.",
        ]
        if stats["added_fields"]:
            summary_lines.append(f"Fields filled: {stats['added_fields']}")
        if stats["new_labels"]:
            summary_lines.append("New samples: " + ", ".join(stats["new_labels"][:8]))
        if stats["updated_labels"]:
            summary_lines.append("Updated samples: " + ", ".join(stats["updated_labels"][:8]))
        QtWidgets.QMessageBox.information(
            self,
            "Microwire Data Builder",
            "\n".join(summary_lines),
        )
        self.log(f"Imported {len(new_rows)} row(s) from {path.name}.")
        self._mark_dirty()

    def open_import_dialog(self) -> None:
        self._open_import_dialog()

    def _load_import_rows(
        self, path: Path, fabrication_index: FabricationIndex
    ) -> Dict[str, Dict[str, Any]]:
        if openpyxl is None:
            return {}
        try:
            workbook = openpyxl.load_workbook(path, read_only=True, data_only=True)
        except Exception:
            self.logger.exception("Failed to open import workbook %s", path)
            return {}
        sheet = workbook.active
        rows_iter = sheet.iter_rows(values_only=True)
        header_row = next(rows_iter, None)
        if not header_row:
            return {}
        mapped_headers: List[Optional[str]] = []
        seen: Dict[str, int] = {}
        for header in header_row:
            column = _map_import_header(header)
            if column is None:
                mapped_headers.append(None)
                continue
            count = seen.get(column, 0) + 1
            seen[column] = count
            if count > 1:
                column = f"{column} ({count})"
            mapped_headers.append(column)
        rows: Dict[str, Dict[str, Any]] = {}
        source_label = f"Imported ({path.name})"
        for row in rows_iter:
            record: Dict[str, Any] = {}
            for idx, value in enumerate(row):
                if idx >= len(mapped_headers):
                    break
                column = mapped_headers[idx]
                if not column:
                    continue
                record[column] = _normalise_import_value(value)
            if "Temperature (°C)" in record and CORE_TEMPERATURE_COLUMN not in record:
                record[CORE_TEMPERATURE_COLUMN] = record.pop("Temperature (°C)")
            composition = str(record.get("Composition") or "").strip()
            microwire = str(record.get("Microwire") or "").strip()
            if not composition or not microwire:
                continue
            normalised_wire = self._normalise_import_microwire(microwire)
            record["Composition"] = composition
            record["Microwire"] = normalised_wire or microwire
            import_key = _row_to_microwire_key(pd.Series(record))
            if not import_key:
                continue
            if not record.get("e/a"):
                ea_value = _compute_ea_from_composition(composition)
                if ea_value is not None:
                    record["e/a"] = ea_value
            record.setdefault("Data source", source_label)
            self._apply_fabrication_defaults(record, fabrication_index)
            rows[import_key] = record
        return rows

    def _normalise_import_microwire(self, microwire: str) -> Optional[str]:
        parts = _microwire_parts_from_label_safe(str(microwire))
        if parts is None:
            return None
        draw, piece, suffix = parts
        try:
            return _microwire_label(int(draw), int(piece), suffix)
        except Exception:
            return None

    @staticmethod
    def _is_missing_import_value(value: Any) -> bool:
        if value is None:
            return True
        if isinstance(value, str) and not value.strip():
            return True
        try:
            return bool(pd.isna(value))
        except Exception:
            return False

    @classmethod
    def _should_fill_import_value(cls, existing: Any, incoming: Any) -> bool:
        return cls._is_missing_import_value(existing) and not cls._is_missing_import_value(incoming)

    def _apply_fabrication_defaults(
        self, record: Dict[str, Any], fabrication_index: FabricationIndex
    ) -> None:
        composition = str(record.get("Composition") or "").strip()
        microwire = str(record.get("Microwire") or "").strip()
        if not composition or not microwire:
            return
        parts = _microwire_parts_from_label_safe(microwire)
        if parts is None:
            return
        draw_x, piece_y, _suffix = parts
        draw_info = fabrication_index.get_draw(composition, draw_x)
        piece_info = fabrication_index.get_piece(composition, draw_x, piece_y)

        def fill(column: str, value: object) -> None:
            if self._should_fill_import_value(record.get(column), value):
                record[column] = value

        fill("Length (m)", _value_for_output(piece_info, "length_m"))
        fill("Production datetime", _value_for_output(draw_info, "production_datetime"))
        fill("Mass (g)", _value_for_output(draw_info, "mass_g"))
        piece_resistance = _value_for_output(piece_info, "fabrication_resistance_ohm")
        draw_resistance = _value_for_output(draw_info, "fabrication_resistance_ohm")
        fill("Resistance (Ω)", piece_resistance if piece_resistance is not None else draw_resistance)
        fill(CORE_TEMPERATURE_COLUMN, _value_for_output(draw_info, "fabrication_temperature_c"))
        fill(
            GLASS_TEMPERATURE_COLUMN,
            _value_for_output(draw_info, "fabrication_glass_temperature_c"),
        )
        fill("Winding speed (m/min)", _value_for_output(draw_info, "winding_speed_m_per_min"))
        fill("Glass feeding (mm/min)", _value_for_output(draw_info, "glass_feed_mm_per_min"))
        fill("Underpressure", _value_for_output(draw_info, "underpressure"))
        pull_value = _value_for_output(piece_info, "glass_pull_off")
        if pull_value is None:
            pull_value = _value_for_output(draw_info, "glass_pull_off")
        fill(GLASS_PULL_COLUMN, pull_value)
        notes = _compose_notes(draw_info, piece_info)
        fill("Notes", notes)
        ea_value = record.get("e/a")
        if ea_value in (None, ""):
            ea_value = _compute_ea_from_composition(composition)
        fill(ESTIMATED_TRANSITION_COLUMN, _estimate_transition_temp_c(ea_value))

    def _merge_imported_rows(self, frame: pd.DataFrame) -> pd.DataFrame:
        if not self._imported_rows or not self._show_imported:
            return frame
        imported = pd.DataFrame(list(self._imported_rows.values()))
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return imported
        merged_frame = frame.copy()
        key_index: Dict[str, int] = {}
        for idx, row in merged_frame.iterrows():
            key = _row_to_microwire_key(row)
            if key and key not in key_index:
                key_index[key] = idx
        append_rows: List[Dict[str, Any]] = []
        for key, record in self._imported_rows.items():
            if key in key_index:
                row_idx = key_index[key]
                row = merged_frame.loc[row_idx]
                updated = False
                for column, value in record.items():
                    if column in {"Composition", "Microwire"}:
                        continue
                    if column not in merged_frame.columns:
                        merged_frame[column] = None
                    existing = row.get(column)
                    if self._should_fill_import_value(existing, value):
                        try:
                            merged_frame[column] = merged_frame[column].astype(object)
                        except Exception:
                            pass
                        merged_frame.at[row_idx, column] = value
                        updated = True
                if updated:
                    current_source = str(row.get("Data source") or "").strip()
                    merged_frame.at[row_idx, "Data source"] = _data_source_with_import(
                        current_source
                    )
            else:
                append_rows.append(record)
        if append_rows:
            merged_frame = pd.concat(
                [merged_frame, pd.DataFrame(append_rows)], ignore_index=True, sort=False
            )
        return merged_frame

    def _merge_imported_payload(self, incoming: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
        added_fields = 0
        new_samples = 0
        updated_samples = 0
        new_labels: List[str] = []
        updated_labels: List[str] = []
        for key, record in incoming.items():
            existing = self._imported_rows.get(key)
            if existing is None:
                self._imported_rows[key] = dict(record)
                new_samples += 1
                label = f"{record.get('Composition', '')} {record.get('Microwire', '')}".strip()
                if label:
                    new_labels.append(label)
                continue
            updated = False
            for column, value in record.items():
                if self._should_fill_import_value(existing.get(column), value):
                    existing[column] = value
                    added_fields += 1
                    updated = True
            if updated:
                updated_samples += 1
                label = f"{record.get('Composition', '')} {record.get('Microwire', '')}".strip()
                if label:
                    updated_labels.append(label)
        return {
            "new_samples": new_samples,
            "updated_samples": updated_samples,
            "added_fields": added_fields,
            "new_labels": new_labels,
            "updated_labels": updated_labels,
        }

    def set_show_imported(self, enabled: bool) -> None:
        self._show_imported = bool(enabled)
        base_frame = self._measured_preview_frame or self._raw_preview_frame
        if isinstance(base_frame, pd.DataFrame) and not base_frame.empty:
            merged = self._merge_imported_rows(base_frame)
            self._update_preview(merged)
        elif self._show_imported:
            self._update_preview(pd.DataFrame(list(self._imported_rows.values())))
        else:
            self._update_preview(pd.DataFrame())

    def set_show_oe_samples(self, enabled: bool) -> None:
        self._show_oe_samples = bool(enabled)
        if hasattr(self, "oe_samples_checkbox"):
            try:
                self.oe_samples_checkbox.blockSignals(True)
                self.oe_samples_checkbox.setChecked(self._show_oe_samples)
            finally:
                self.oe_samples_checkbox.blockSignals(False)
        self._refresh_preview_frame()

    def clear_imported_data(self) -> None:
        if not self._imported_rows and not self._imported_sources:
            return
        self._imported_rows = {}
        self._imported_sources = []
        base_frame = self._measured_preview_frame or self._raw_preview_frame
        if isinstance(base_frame, pd.DataFrame):
            self._update_preview(base_frame)
        else:
            self._update_preview(pd.DataFrame())

    @staticmethod
    def _row_is_oe_sample(row: pd.Series) -> bool:
        key = _row_to_microwire_key(row)
        if key:
            parsed = _microwire_key_from_string(key)
            if parsed is not None:
                suffix = str(parsed[3] or "").strip().lower()
                if suffix == "oe":
                    return True
        microwire = str(row.get("Microwire") or "").strip()
        parsed = _microwire_parts_from_label_safe(microwire)
        if parsed is None:
            return False
        suffix = str(parsed[2] or "").strip().lower()
        return suffix == "oe"
        self._mark_dirty()

    def imported_sources(self) -> List[str]:
        return list(self._imported_sources)

    def _mark_dirty(self) -> None:
        try:
            self.data_updated.emit()
        except Exception:
            pass

    def _sync_imports_to_fabrication(self) -> None:
        fabrication = self.sections.get("fabrication")
        if not isinstance(fabrication, FabricationSection):
            return
        if not self._imported_rows:
            return
        try:
            added = fabrication.apply_imported_samples(self._imported_rows.values())
        except Exception:
            self.logger.exception("Failed to sync imported samples into fabrication section")
            return
        if added:
            self.log(f"Added {added} imported sample(s) to Fabrication.")

    def _update_export_summary(self) -> None:
        output_dir = self._output_dir or str(Path.cwd())
        output_name = self._output_name or DEFAULT_OUTPUT_NAME
        formats: List[str] = []
        if self._export_csv:
            formats.append("CSV")
        if self._export_excel:
            formats.append("Excel")
        if self._export_html:
            formats.append("HTML")
        if self._export_word:
            formats.append("Word reports")
        if self._export_matplotlib:
            formats.append("Matplotlib")
        if self._export_origin:
            formats.append("Origin")
        if not formats:
            formats.append("No exports")
        selected_sections = [
            label for key, label in self._section_choices if self._section_states.get(key)
        ]
        section_summary = f"{len(selected_sections)}/{len(self._section_choices)} sections"
        self.export_summary_label.setText(
            f"{output_name} → {output_dir} | {', '.join(formats)} | {section_summary}"
        )

    def _choose_output_dir(self) -> None:
        start_dir = _dialog_start_directory(self._output_dir)
        directory = QtWidgets.QFileDialog.getExistingDirectory(
            self,
            "Select output directory",
            str(start_dir),
        )
        if directory:
            self._output_dir = directory
            self._update_export_summary()

    def _load_payload(self, section_key: str, name: str) -> Any:
        section = self.sections.get(section_key)
        if section is None:
            return None
        if _section_payload_enabled(section, name):
            return section.store.load_payload(name)
        try:
            return section.store.load_payload(name)
        except Exception:
            return None

    def _selected_sections(self) -> set[str]:
        return {key for key, enabled in self._section_states.items() if enabled}

    @staticmethod
    def _merge_fabrication_indexes(
        base_index: FabricationIndex,
        overlay_index: FabricationIndex,
    ) -> FabricationIndex:
        merged = FabricationIndex()
        for (composition, draw), payload in getattr(base_index, "draw_level", {}).items():
            merged.set_draw(str(composition), int(draw), dict(payload))
        for (composition, draw, piece), payload in getattr(base_index, "piece_level", {}).items():
            merged.set_piece(str(composition), int(draw), int(piece), dict(payload))
        for (composition, draw), payload in getattr(overlay_index, "draw_level", {}).items():
            merged.set_draw(str(composition), int(draw), dict(payload))
        for (composition, draw, piece), payload in getattr(overlay_index, "piece_level", {}).items():
            merged.set_piece(str(composition), int(draw), int(piece), dict(payload))
        return merged

    def _prepare_builder_inputs(
        self,
        selected: set[str],
        *,
        require_payloads: bool = True,
    ) -> Optional[
        tuple[
            FabricationIndex,
            List[MeasurementRecord],
            List[VsmHysteresisRecord],
            List[VsmTemperatureScanRecord],
            List[DmaIsoStressRecord],
            List[MiniDmaRecord],
            List[ShapeMemoryStressStrainRecord],
            Dict[str, Dict[str, Any]],
            List[FmrRecord],
            Dict[MicrowireKey, MicroscopeMeasurements],
            Dict[Tuple[str, int, Optional[int]], VideoMetricsSummary],
            Dict[MicrowireKey, StrainRecord],
            Dict[str, Dict[str, Any]],
            Dict[str, Dict[str, Any]],
            Dict[str, Dict[str, float]],
            Dict[str, Dict[str, float]],
            Dict[str, Dict[str, Any]],
            Dict[str, Dict[str, float]],
            Dict[str, Dict[str, Any]],
        ]
    ]:
        missing: list[str] = []

        def _mark_missing(label: str) -> None:
            if require_payloads:
                missing.append(label)
            else:
                self.log(f"Skipping {label} because no data were found.", level=logging.WARNING)

        fabrication_index = FabricationIndex()
        fabrication_payload = self._load_payload("fabrication", "fabrication_index")
        if isinstance(fabrication_payload, FabricationIndex):
            fabrication_index = fabrication_payload
        fabrication_section = self.sections.get("fabrication")
        fabrication_table = None
        if isinstance(fabrication_section, FabricationSection):
            if isinstance(fabrication_section.data.table, pd.DataFrame) and not fabrication_section.data.table.empty:
                fabrication_table = fabrication_section.data.table
            else:
                fabrication_table = fabrication_section.model.frame()
        table_index = self._fabrication_index_from_frame(fabrication_table)
        if table_index.draw_level or table_index.piece_level:
            fabrication_index = self._merge_fabrication_indexes(
                fabrication_index,
                table_index,
            )
        if "fabrication" in selected and not (fabrication_index.draw_level or fabrication_index.piece_level):
            _mark_missing("fabrication")

        annealing_records_payload = self._load_payload("annealing", "annealing_records")
        annealing_records: List[MeasurementRecord] = []
        if isinstance(annealing_records_payload, list):
            annealing_records = list(
                self._filter_hidden_records(annealing_records_payload, "annealing")
            )
        if not annealing_records:
            _mark_missing("annealing")
        self._cached_annealing_records = list(annealing_records)
        self._cached_annealing_groups = self._group_annealing_records(annealing_records)

        microscope_index: Dict[MicrowireKey, MicroscopeMeasurements] = {}
        overrides: Dict[str, Dict[str, float]] = {}
        show_other_ends = True
        if "microscope" in selected:
            payload = self._load_payload("microscope", "microscope_index")
            microscope_section = self.sections.get("microscope")
            if isinstance(microscope_section, MicroscopeSection):
                overrides = microscope_section.overrides
                table = microscope_section.data.table
                show_other_ends = bool(getattr(microscope_section, "_show_other_ends", True))
            else:
                table = None
            if isinstance(payload, dict) and payload:
                microscope_index = payload
                if isinstance(table, pd.DataFrame) and not table.empty:
                    table_index = self._build_microscope_index_from_table(table)
                    if table_index and self._microscope_payload_stale(payload, table_index):
                        self.logger.warning(
                            "Microscope saved payload is stale; using the visible table values and repairing the payload."
                        )
                        microscope_index = table_index
                        if isinstance(microscope_section, MicroscopeSection):
                            try:
                                microscope_section.store.save_payload("microscope_index", table_index)
                                payload_map = dict(microscope_section.data.extra.get("payloads", {}))
                                payload_map["microscope_index"] = "microscope_index"
                                microscope_section.data.extra["payloads"] = payload_map
                                microscope_section.store.save(microscope_section.data)
                            except Exception:
                                self.logger.exception("Failed to repair stale microscope payload")
            elif isinstance(table, pd.DataFrame) and not table.empty:
                microscope_index = self._build_microscope_index_from_table(table)
            else:
                _mark_missing("microscope")
            microscope_index = _filter_other_end_microscope_index(
                microscope_index,
                show_other_ends=show_other_ends,
            )

        video_index: Dict[Tuple[str, int, Optional[int]], VideoMetricsSummary] = {}
        video_payload = self._load_payload("videos", "video_index")
        if isinstance(video_payload, dict):
            video_index = video_payload
        video_overrides: Dict[str, Dict[str, Any]] = {}
        video_section = self.sections.get("videos")
        if isinstance(video_section, VideoSection):
            video_overrides = video_section.overrides_snapshot()
            if not video_index:
                video_index = video_section._load_video_index()
        if "videos" in selected and not video_index and not video_overrides:
            if require_payloads:
                self.log("Skipping videos because no data were found.", level=logging.WARNING)
            else:
                _mark_missing("videos")

        strain_records: Dict[MicrowireKey, StrainRecord] = {}
        if "strain" in selected:
            payload = self._load_payload("strain", "strain_records")
            if isinstance(payload, dict):
                strain_records = payload
            if not strain_records:
                section = self.sections.get("strain")
                if isinstance(section, StrainSection):
                    strain_records = section.records_snapshot()
            if not strain_records:
                _mark_missing("strain")

        strain_entries: Dict[str, Dict[str, Any]] = {}
        if "strain" in selected:
            section = self.sections.get("strain")
            if isinstance(section, StrainSection):
                strain_entries = section.entries_snapshot()

        vsm_hysteresis_records: List[VsmHysteresisRecord] = []
        if "vsm_hysteresis" in selected:
            payload = self._load_payload("vsm_hysteresis", "vsm_hysteresis_records")
            if isinstance(payload, list):
                vsm_hysteresis_records = list(
                    self._filter_hidden_records(payload, "vsm_hysteresis")
                )
            else:
                _mark_missing("VSM hysteresis")
        self._cached_vsm_hysteresis_records = list(vsm_hysteresis_records)
        self._cached_vsm_hysteresis_groups = _group_graph_records_by_key(vsm_hysteresis_records)

        vsm_temperature_records: List[VsmTemperatureScanRecord] = []
        if "vsm_temperature_scan" in selected:
            payload = self._load_payload("vsm_temperature_scan", "vsm_temperature_scan_records")
            if isinstance(payload, list):
                vsm_temperature_records = list(
                    self._filter_hidden_records(payload, "vsm_temperature_scan")
                )
            else:
                _mark_missing("VSM temperature scan")
        self._cached_vsm_temperature_records = list(vsm_temperature_records)
        self._cached_vsm_temperature_groups = _group_graph_records_by_key(vsm_temperature_records)

        dma_isostress_records: List[DmaIsoStressRecord] = []
        if "dma_iso_stress" in selected:
            payload = self._load_payload("dma_iso_stress", "dma_iso_stress_records")
            if isinstance(payload, list):
                dma_isostress_records = list(
                    self._filter_hidden_records(payload, "dma_iso_stress")
                )
            else:
                _mark_missing("DMA iso-stress")
        self._cached_dma_isostress_records = list(dma_isostress_records)
        self._cached_dma_isostress_groups = _group_graph_records_by_key(dma_isostress_records)

        mini_dma_records: List[MiniDmaRecord] = []
        mini_dma_transition_reviews: Dict[str, Dict[str, Any]] = {}
        if "mini_dma" in selected:
            payload = self._load_payload("mini_dma", "mini_dma_records")
            if isinstance(payload, list):
                mini_dma_records = list(payload)
                section = self.sections.get("mini_dma")
                if isinstance(section, MiniDmaSection):
                    mini_dma_transition_reviews = section.transition_reviews_snapshot()
                    mini_dma_records = section.records_with_reviewed_transitions(mini_dma_records)
            else:
                _mark_missing("Mini DMA")
        self._cached_mini_dma_records = list(mini_dma_records)
        self._cached_mini_dma_groups = _group_graph_records_by_key(mini_dma_records)

        shape_memory_stress_strain_records: List[ShapeMemoryStressStrainRecord] = []
        if "shape_memory_stress_strain" in selected:
            payload = self._load_payload(
                "shape_memory_stress_strain",
                "shape_memory_stress_strain_records",
            )
            if isinstance(payload, list):
                shape_memory_stress_strain_records = list(
                    self._filter_hidden_records(payload, "shape_memory_stress_strain")
                )
            else:
                _mark_missing("Manual stress/strain")
        self._cached_shape_memory_stress_strain_records = list(
            shape_memory_stress_strain_records
        )
        self._cached_shape_memory_stress_strain_groups = _group_graph_records_by_key(
            shape_memory_stress_strain_records
        )

        shape_memory_entries: Dict[str, Dict[str, Any]] = {}
        if "shape_memory_stress_strain" in selected:
            section = self.sections.get("shape_memory_stress_strain")
            if isinstance(section, ShapeMemoryStressStrainSection):
                shape_memory_entries = section.entries_snapshot()
                self._cached_shape_memory_record_entries = section.record_entries_snapshot()
            else:
                self._cached_shape_memory_record_entries = {}
        else:
            self._cached_shape_memory_record_entries = {}
        self._cached_shape_memory_entries = dict(shape_memory_entries)

        fmr_records: List[FmrRecord] = []
        if "fmr" in selected:
            payload = self._load_payload("fmr", "fmr_records")
            if isinstance(payload, list):
                fmr_records = list(self._filter_hidden_records(payload, "fmr"))
            else:
                _mark_missing("FMR")
        self._cached_fmr_records = list(fmr_records)
        self._cached_fmr_groups = _group_graph_records_by_key(fmr_records)

        current_density_entries: Dict[str, Dict[str, Any]] = {}
        if "current_density" in selected:
            current_section = self.sections.get("current_density")
            if isinstance(current_section, CurrentDensitySection):
                snapshot_provider = getattr(
                    current_section, "current_density_snapshot", None
                )
                if not callable(snapshot_provider):
                    self.logger.warning(
                        "Current density snapshot method is missing; skipping current density values."
                    )
                else:
                    try:
                        current_density_entries = snapshot_provider()
                    except Exception:
                        self.logger.exception("Failed to snapshot current density")
                    if not current_density_entries:
                        try:
                            current_section.refresh_data()
                        except Exception:
                            self.logger.exception("Failed to refresh current density data")
                        try:
                            current_density_entries = snapshot_provider()
                        except Exception:
                            self.logger.exception(
                                "Failed to snapshot current density after refresh"
                            )
            if not current_density_entries:
                _mark_missing("current density")

        phase_points: Dict[str, Dict[str, float]] = {}
        if "current_density" in selected:
            annealing_section = self.sections.get("annealing")
            if isinstance(annealing_section, AnnealingSection):
                current_section = self.sections.get("current_density")
                if isinstance(current_section, CurrentDensitySection):
                    phase_points = {
                        _microwire_key_to_str(key): values
                        for key, values in current_section._collect_phase_points().items()
                    }
        transition_points: Dict[str, Dict[str, Any]] = {}
        if "transition_temps" in selected:
            transition_section = self.sections.get("transition_temps")
            if isinstance(transition_section, TransitionTempsSection):
                transition_points = transition_section.transition_points_snapshot()
        if missing and require_payloads:
            QtWidgets.QMessageBox.warning(
                self,
                "Microwire Data Builder",
                "Process the following sections first: " + ", ".join(sorted(missing)),
            )
            return None

        return (
            fabrication_index,
            annealing_records,
            vsm_hysteresis_records,
            vsm_temperature_records,
            dma_isostress_records,
            mini_dma_records,
            shape_memory_stress_strain_records,
            shape_memory_entries,
            fmr_records,
            microscope_index,
            video_index,
            strain_records,
            strain_entries,
            current_density_entries,
            overrides,
            phase_points,
            transition_points,
            mini_dma_transition_reviews,
            video_overrides,
        )

    @staticmethod
    def _parse_microscope_key_from_row(row: pd.Series) -> Optional[MicrowireKey]:
        key_value = row.get("_key")
        if isinstance(key_value, str):
            parsed = _microwire_key_from_string(key_value)
            if parsed is not None:
                return parsed
        composition = str(row.get("Composition") or "").strip()
        microwire = str(row.get("Microwire") or "").strip()
        if not composition or not microwire:
            return None
        parsed = _microwire_parts_from_label_safe(microwire)
        if parsed is None:
            return None
        try:
            draw = int(parsed[0])
            piece = int(parsed[1])
            suffix = parsed[2]
        except (TypeError, ValueError):
            return None
        return (composition, draw, piece, suffix)

    @staticmethod
    def _parse_positive_float(value: object) -> Optional[float]:
        if value is None:
            return None
        if isinstance(value, (int, float)):
            numeric = float(value)
        else:
            text = str(value).strip().replace(",", ".")
            if not text:
                return None
            try:
                numeric = float(text)
            except ValueError:
                return None
        if not math.isfinite(numeric) or numeric <= 0:
            return None
        return numeric

    @staticmethod
    def _coerce_path(value: object) -> Optional[Path]:
        if value is None:
            return None
        if isinstance(value, Path):
            return value
        if isinstance(value, str):
            text = value.strip()
            if not text:
                return None
            try:
                return Path(text)
            except Exception:
                return None
        return None

    def _image_path_from_row(self, row: pd.Series, kind: str) -> Optional[Path]:
        candidates: List[Path] = []
        if kind == "core":
            image_column = MICROSCOPE_IMAGE_COLUMNS[0]
            mapped = "_core_image"
        else:
            image_column = MICROSCOPE_IMAGE_COLUMNS[1]
            mapped = "_glass_image"
        direct_path = self._coerce_path(row.get(image_column))
        if direct_path is not None:
            candidates.append(direct_path)
        mapped_path = self._coerce_path(row.get(mapped))
        if mapped_path is not None:
            candidates.append(mapped_path)
        images = row.get("_images")
        if isinstance(images, (list, tuple)):
            for entry in images:
                path = self._coerce_path(entry)
                if path is not None:
                    candidates.append(path)
                    break
        for candidate in candidates:
            if candidate is not None:
                return candidate
        return None

    def _build_microscope_index_from_table(
        self, table: pd.DataFrame
    ) -> Dict[MicrowireKey, MicroscopeMeasurements]:
        index: Dict[MicrowireKey, MicroscopeMeasurements] = {}
        for _, row in table.iterrows():
            key = self._parse_microscope_key_from_row(row)
            if key is None:
                continue
            measurements = index.setdefault(key, MicroscopeMeasurements())
            d_value = self._parse_positive_float(row.get(MICROSCOPE_D_COLUMN))
            if d_value is not None:
                d_path = self._image_path_from_row(row, "core")
                detection = MicroscopeDetection(
                    value=float(d_value),
                    image_path=d_path,
                    source="manual",
                )
                detection.category = "core"
                measurements.core.append(detection)
            else:
                d_path = self._image_path_from_row(row, "core")
                if d_path is not None:
                    measurements.add_placeholder("core", d_path)
            D_value = self._parse_positive_float(row.get(MICROSCOPE_CAP_D_COLUMN))
            if D_value is not None:
                D_path = self._image_path_from_row(row, "glass")
                detection = MicroscopeDetection(
                    value=float(D_value),
                    image_path=D_path,
                    source="manual",
                )
                detection.category = "glass"
                measurements.glass.append(detection)
            else:
                D_path = self._image_path_from_row(row, "glass")
                if D_path is not None:
                    measurements.add_placeholder("glass", D_path)
            brittle_value = str(row.get(BRITTLE_COLUMN) or "").strip().lower()
            if brittle_value == "brittle":
                measurements.brittle = True
        return index

    def _microscope_payload_stale(
        self,
        payload: Mapping[MicrowireKey, MicroscopeMeasurements],
        table_index: Mapping[MicrowireKey, MicroscopeMeasurements],
    ) -> bool:
        if set(payload.keys()) != set(table_index.keys()):
            return True
        for key, table_measurements in table_index.items():
            payload_measurements = payload.get(key)
            if payload_measurements is None:
                return True
            for getter in ("best_core", "best_glass"):
                table_value = getattr(table_measurements, getter)()
                payload_value = getattr(payload_measurements, getter)()
                if table_value is None:
                    continue
                if payload_value is None:
                    return True
                try:
                    if not math.isclose(float(table_value), float(payload_value), rel_tol=0.0, abs_tol=1e-9):
                        return True
                except (TypeError, ValueError):
                    return True
            for attr in ("core", "glass"):
                table_entries = getattr(table_measurements, attr, [])
                payload_entries = getattr(payload_measurements, attr, [])
                if table_entries and not payload_entries:
                    return True
        return False

    def _update_preview(self, frame: pd.DataFrame) -> None:
        previous_order = self._column_order or self._current_preview_column_order()
        if previous_order:
            self._column_order = list(previous_order)
        self._graph_pixmap_cache.clear()
        if isinstance(frame, pd.DataFrame):
            frame = self._expand_shape_memory_preview_rows(frame)
            frame = self._apply_column_universe(frame)
            frame = _with_source_label_column(frame)
            self._raw_preview_frame = frame.copy()
        else:
            self._raw_preview_frame = pd.DataFrame()
        self._refresh_preview_source_filter_options()
        self._refresh_preview_frame()

    def _column_universe(self) -> List[str]:
        universe: List[str] = []

        def add(column: str) -> None:
            if column and column not in universe:
                universe.append(column)

        for column in OUTPUT_COLUMNS:
            add(str(column))
        for column in MICROSCOPE_IMAGE_COLUMNS:
            add(str(column))
        for column in FIGURE_COLUMNS:
            add(str(column))
        for column in ORIGIN_FIGURE_COLUMNS:
            add(str(column))
        for column in (
            VSM_HYSTERESIS_COLUMN,
            VSM_TEMPERATURE_SCAN_COLUMN,
            DMA_ISOSTRESS_COLUMN,
        ):
            add(str(column))
        for column in CURRENT_DENSITY_COLUMNS:
            add(str(column))
        for column in TRANSITION_TEMP_COLUMNS:
            add(str(column))
        for column in getattr(StrainSection, "TABLE_COLUMNS", ()):
            add(str(column))
        return universe

    def _apply_column_universe(self, frame: pd.DataFrame) -> pd.DataFrame:
        frame = self._dedupe_frame_columns(frame)
        universe = self._column_universe()
        if not universe:
            return frame
        updated = frame.copy()
        for column in universe:
            if column not in updated.columns:
                updated[column] = None
        ordered = [column for column in universe if column in updated.columns]
        for column in updated.columns:
            if column not in ordered:
                ordered.append(column)
        return updated.loc[:, ordered]

    def _expand_shape_memory_preview_rows(self, frame: pd.DataFrame) -> pd.DataFrame:
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return frame
        groups = self._ensure_shape_memory_stress_strain_groups()
        section_row_map: Dict[str, List[pd.Series]] = {}
        section_standard_entry_map: Dict[str, Dict[str, Dict[str, Any]]] = {}
        section_fracture_entry_map: Dict[str, Dict[str, Dict[str, Any]]] = {}
        section = self.sections.get("shape_memory_stress_strain")
        if isinstance(section, ShapeMemoryStressStrainSection):
            section_frame = section.model.frame()
            if isinstance(section_frame, pd.DataFrame) and not section_frame.empty:
                for _, candidate_row in section_frame.iterrows():
                    section_key = _row_to_microwire_key(candidate_row)
                    if not section_key:
                        continue
                    section_row_map.setdefault(section_key, []).append(candidate_row.copy())
                    standard_source = str(
                        candidate_row.get(_SHAPE_MEMORY_STANDARD_SOURCE_COLUMN) or ""
                    ).strip()
                    if standard_source:
                        entry = {
                            column: candidate_row.get(column)
                            for column in _SHAPE_MEMORY_STANDARD_ENTRY_COLUMNS
                            if _shape_memory_has_value(candidate_row.get(column))
                        }
                        if entry:
                            section_standard_entry_map.setdefault(section_key, {})[
                                standard_source
                            ] = entry
                    fracture_source = str(
                        candidate_row.get(_SHAPE_MEMORY_FRACTURE_SOURCE_COLUMN) or ""
                    ).strip()
                    if fracture_source:
                        entry = {
                            column: candidate_row.get(column)
                            for column in _SHAPE_MEMORY_FRACTURE_ENTRY_COLUMNS
                            if _shape_memory_has_value(candidate_row.get(column))
                        }
                        if entry:
                            section_fracture_entry_map.setdefault(section_key, {})[
                                fracture_source
                            ] = entry

        def _diameter_from_row_payload(payload: Mapping[str, Any]) -> Optional[float]:
            for column in (MICROSCOPE_D_COLUMN, "d (µm)", "d (um)"):
                try:
                    value = payload.get(column)
                except Exception:
                    value = None
                try:
                    if value is not None:
                        numeric = float(value)
                        if math.isfinite(numeric) and numeric > 0:
                            return numeric
                except Exception:
                    continue
            return None

        def _current_from_source_or_label(source_text: str, label_value: object) -> Optional[float]:
            if source_text:
                current = _shape_memory_current_mA_from_record(
                    ShapeMemoryStressStrainRecord(path=Path(source_text), sample="", data=pd.DataFrame())
                )
                if current is not None:
                    return current
            if isinstance(label_value, (list, tuple, set)):
                for item in label_value:
                    current = _shape_memory_current_mA_from_text(item)
                    if current is not None:
                        return current
                return None
            return _shape_memory_current_mA_from_text(label_value)

        def _expanded_row_from_section_row(
            base_row: Mapping[str, Any],
            section_row: pd.Series,
            row_key: str,
            order: int,
        ) -> Optional[Dict[str, Any]]:
            payload = dict(base_row)
            section_payload = section_row.to_dict()
            for column in (
                SHAPE_MEMORY_STRESS_STRAIN_COLUMN,
                "_sources",
                _SHAPE_MEMORY_STANDARD_SOURCE_COLUMN,
                _SHAPE_MEMORY_FRACTURE_SOURCE_COLUMN,
            ):
                if column in section_payload:
                    payload[column] = section_payload.get(column)
            for column in _SHAPE_MEMORY_STANDARD_VALUE_COLUMNS + _SHAPE_MEMORY_FRACTURE_VALUE_COLUMNS:
                payload[column] = section_payload.get(column)
            diameter_um = (
                _diameter_from_row_payload(section_payload)
                or _diameter_from_row_payload(payload)
            )
            standard_source = str(section_payload.get(_SHAPE_MEMORY_STANDARD_SOURCE_COLUMN) or "").strip()
            fracture_source = str(section_payload.get(_SHAPE_MEMORY_FRACTURE_SOURCE_COLUMN) or "").strip()
            payload[SHAPE_MEMORY_CURRENT_COLUMN] = None
            payload[SHAPE_MEMORY_CURRENT_DENSITY_COLUMN] = None
            payload[SHAPE_MEMORY_FRACTURE_CURRENT_COLUMN] = None
            payload[SHAPE_MEMORY_FRACTURE_CURRENT_DENSITY_COLUMN] = None
            if _shape_memory_payload_has_values(payload, _SHAPE_MEMORY_STANDARD_VALUE_COLUMNS):
                standard_current = _current_from_source_or_label(
                    standard_source,
                    section_payload.get(SHAPE_MEMORY_STRESS_STRAIN_COLUMN),
                )
                if standard_current is not None:
                    payload[SHAPE_MEMORY_CURRENT_COLUMN] = standard_current
                    payload[SHAPE_MEMORY_CURRENT_DENSITY_COLUMN] = _current_density_from_diameter_um(
                        standard_current,
                        diameter_um,
                    )
            if _shape_memory_payload_has_values(payload, _SHAPE_MEMORY_FRACTURE_VALUE_COLUMNS):
                fracture_current = _current_from_source_or_label(
                    fracture_source,
                    section_payload.get(SHAPE_MEMORY_STRESS_STRAIN_COLUMN),
                )
                if fracture_current is not None:
                    payload[SHAPE_MEMORY_FRACTURE_CURRENT_COLUMN] = fracture_current
                    payload[SHAPE_MEMORY_FRACTURE_CURRENT_DENSITY_COLUMN] = _current_density_from_diameter_um(
                        fracture_current,
                        diameter_um,
                    )
            _clear_orphan_currents(payload)
            if not (
                _shape_memory_payload_has_values(payload, _SHAPE_MEMORY_STANDARD_VALUE_COLUMNS)
                or _shape_memory_payload_has_values(payload, _SHAPE_MEMORY_FRACTURE_VALUE_COLUMNS)
            ):
                return None
            payload[_SHAPE_MEMORY_GROUP_KEY_COLUMN] = row_key
            payload[_SHAPE_MEMORY_GROUP_ORDER_COLUMN] = order
            return payload

        def _clear_orphan_currents(payload: Dict[str, Any]) -> None:
            standard_has_values = _shape_memory_payload_has_values(
                payload,
                _SHAPE_MEMORY_STANDARD_VALUE_COLUMNS,
            )
            if not standard_has_values:
                payload[SHAPE_MEMORY_CURRENT_COLUMN] = None
                payload[SHAPE_MEMORY_CURRENT_DENSITY_COLUMN] = None
            fracture_has_values = _shape_memory_payload_has_values(
                payload,
                _SHAPE_MEMORY_FRACTURE_VALUE_COLUMNS,
            )
            if not fracture_has_values:
                payload[SHAPE_MEMORY_FRACTURE_CURRENT_COLUMN] = None
                payload[SHAPE_MEMORY_FRACTURE_CURRENT_DENSITY_COLUMN] = None

        expanded_rows: List[Dict[str, Any]] = []
        for idx, row in frame.iterrows():
            row_dict = dict(row)
            row_key = _row_to_microwire_key(pd.Series(row_dict))
            section_standard_entries = section_standard_entry_map.get(row_key or "", {})
            section_fracture_entries = section_fracture_entry_map.get(row_key or "", {})
            if not row_key:
                row_dict[_SHAPE_MEMORY_GROUP_KEY_COLUMN] = f"row-{idx}"
                row_dict[_SHAPE_MEMORY_GROUP_ORDER_COLUMN] = 0
                expanded_rows.append(row_dict)
                continue
            section_rows = section_row_map.get(row_key or "", [])
            if section_rows:
                appended = False
                for order, section_row in enumerate(section_rows):
                    payload = _expanded_row_from_section_row(row_dict, section_row, row_key, order)
                    if payload is None:
                        continue
                    expanded_rows.append(payload)
                    appended = True
                if appended:
                    continue
            records = list(groups.get(row_key, []))
            if not records:
                source_paths: List[Path] = []
                raw_sources = row_dict.get("_sources")
                if isinstance(raw_sources, (list, tuple, set)):
                    for entry in raw_sources:
                        try:
                            source_paths.append(Path(entry))
                        except Exception:
                            continue
                section_row: Optional[pd.Series] = None
                if not source_paths:
                    section = self.sections.get("shape_memory_stress_strain")
                    section_frame = (
                        section.model.frame()
                        if isinstance(section, ShapeMemoryStressStrainSection)
                        else pd.DataFrame()
                    )
                    if isinstance(section_frame, pd.DataFrame) and not section_frame.empty:
                        for _, candidate_row in section_frame.iterrows():
                            if _row_to_microwire_key(candidate_row) == row_key:
                                section_row = candidate_row
                                break
                    if section_row is not None:
                        candidate_sources = section_row.get("_sources")
                        if isinstance(candidate_sources, (list, tuple, set)):
                            for entry in candidate_sources:
                                try:
                                    source_paths.append(Path(entry))
                                except Exception:
                                    continue
                fallback_rows: List[Dict[str, Any]] = []
                sample_entry = self._cached_shape_memory_entries.get(row_key, {})
                standard_source = str(
                    (section_row.get(_SHAPE_MEMORY_STANDARD_SOURCE_COLUMN) if section_row is not None else row_dict.get(_SHAPE_MEMORY_STANDARD_SOURCE_COLUMN))
                    or ""
                ).strip()
                fracture_source = str(
                    (section_row.get(_SHAPE_MEMORY_FRACTURE_SOURCE_COLUMN) if section_row is not None else row_dict.get(_SHAPE_MEMORY_FRACTURE_SOURCE_COLUMN))
                    or ""
                ).strip()
                standard_source_count = sum(
                    1 for path in source_paths if "fracture" not in path.stem.casefold()
                )
                fracture_source_count = sum(
                    1 for path in source_paths if "fracture" in path.stem.casefold()
                )
                d_value = row_dict.get(MICROSCOPE_D_COLUMN)
                try:
                    diameter_um = float(d_value) if d_value is not None else None
                except Exception:
                    diameter_um = None
                for source_path in source_paths:
                    path_key = str(source_path)
                    entry = self._cached_shape_memory_record_entries.get(path_key, {})
                    current = _shape_memory_current_mA_from_record(
                        ShapeMemoryStressStrainRecord(path=source_path, sample="", data=pd.DataFrame())
                    )
                    is_fracture = "fracture" in source_path.stem.casefold()
                    new_row = dict(row_dict)
                    current_value = current
                    labels = [source_path.stem]
                    if labels:
                        new_row[SHAPE_MEMORY_STRESS_STRAIN_COLUMN] = labels
                    new_row[SHAPE_MEMORY_CURRENT_COLUMN] = None
                    new_row[SHAPE_MEMORY_CURRENT_DENSITY_COLUMN] = None
                    new_row[SHAPE_MEMORY_FRACTURE_CURRENT_COLUMN] = None
                    new_row[SHAPE_MEMORY_FRACTURE_CURRENT_DENSITY_COLUMN] = None
                    if is_fracture:
                        new_row[SHAPE_MEMORY_FRACTURE_CURRENT_COLUMN] = current_value
                        new_row[SHAPE_MEMORY_FRACTURE_CURRENT_DENSITY_COLUMN] = _current_density_from_diameter_um(
                            current_value,
                            diameter_um,
                        )
                    else:
                        new_row[SHAPE_MEMORY_CURRENT_COLUMN] = current_value
                        new_row[SHAPE_MEMORY_CURRENT_DENSITY_COLUMN] = _current_density_from_diameter_um(
                            current_value,
                            diameter_um,
                        )

                    standard_entry: Dict[str, Any] = {}
                    fracture_entry: Dict[str, Any] = {}
                    standard_current_confirmed = False
                    fracture_current_confirmed = False
                    if is_fracture:
                        for column in (
                            SHAPE_MEMORY_FRACTURE_LOAD_COLUMN,
                            SHAPE_MEMORY_FRACTURE_STRAIN_COLUMN,
                            SHAPE_MEMORY_FRACTURE_STRESS_COLUMN,
                        ):
                            if column in entry:
                                fracture_entry[column] = entry[column]
                        if fracture_entry:
                            fracture_current_confirmed = True
                        if not fracture_entry:
                            fracture_entry = dict(section_fracture_entries.get(path_key, {}))
                            fracture_current_confirmed = bool(fracture_entry)
                        if not fracture_entry and fracture_source and path_key == fracture_source:
                            for column in (
                                SHAPE_MEMORY_FRACTURE_LOAD_COLUMN,
                                SHAPE_MEMORY_FRACTURE_STRAIN_COLUMN,
                                SHAPE_MEMORY_FRACTURE_STRESS_COLUMN,
                            ):
                                if column in sample_entry:
                                    fracture_entry[column] = sample_entry[column]
                            if fracture_entry:
                                fracture_current_confirmed = True
                        elif not fracture_entry and not fracture_source and fracture_source_count == 1:
                            for column in (
                                SHAPE_MEMORY_FRACTURE_LOAD_COLUMN,
                                SHAPE_MEMORY_FRACTURE_STRAIN_COLUMN,
                                SHAPE_MEMORY_FRACTURE_STRESS_COLUMN,
                            ):
                                if column in sample_entry:
                                    fracture_entry[column] = sample_entry[column]
                    else:
                        for column in (
                            SHAPE_MEMORY_DISPLACEMENT_COLUMN,
                            SHAPE_MEMORY_LOAD_COLUMN,
                            SHAPE_MEMORY_STRAIN_COLUMN,
                            SHAPE_MEMORY_STRESS_COLUMN,
                        ):
                            if column in entry:
                                standard_entry[column] = entry[column]
                        if standard_entry:
                            standard_current_confirmed = True
                        if not standard_entry:
                            standard_entry = dict(section_standard_entries.get(path_key, {}))
                            standard_current_confirmed = bool(standard_entry)
                        if not standard_entry and standard_source and path_key == standard_source:
                            for column in (
                                SHAPE_MEMORY_DISPLACEMENT_COLUMN,
                                SHAPE_MEMORY_LOAD_COLUMN,
                                SHAPE_MEMORY_STRAIN_COLUMN,
                                SHAPE_MEMORY_STRESS_COLUMN,
                            ):
                                if column in sample_entry:
                                    standard_entry[column] = sample_entry[column]
                            if standard_entry:
                                standard_current_confirmed = True
                        elif not standard_entry and not standard_source and standard_source_count == 1:
                            for column in (
                                SHAPE_MEMORY_DISPLACEMENT_COLUMN,
                                SHAPE_MEMORY_LOAD_COLUMN,
                                SHAPE_MEMORY_STRAIN_COLUMN,
                                SHAPE_MEMORY_STRESS_COLUMN,
                            ):
                                if column in sample_entry:
                                    standard_entry[column] = sample_entry[column]

                    for column in (
                        SHAPE_MEMORY_DISPLACEMENT_COLUMN,
                        SHAPE_MEMORY_LOAD_COLUMN,
                        SHAPE_MEMORY_STRAIN_COLUMN,
                        SHAPE_MEMORY_STRESS_COLUMN,
                    ):
                        new_row[column] = standard_entry.get(column)
                    for column in (
                        SHAPE_MEMORY_FRACTURE_LOAD_COLUMN,
                        SHAPE_MEMORY_FRACTURE_STRAIN_COLUMN,
                        SHAPE_MEMORY_FRACTURE_STRESS_COLUMN,
                    ):
                        new_row[column] = fracture_entry.get(column)
                    if not standard_current_confirmed:
                        new_row[SHAPE_MEMORY_CURRENT_COLUMN] = None
                        new_row[SHAPE_MEMORY_CURRENT_DENSITY_COLUMN] = None
                    if not fracture_current_confirmed:
                        new_row[SHAPE_MEMORY_FRACTURE_CURRENT_COLUMN] = None
                        new_row[SHAPE_MEMORY_FRACTURE_CURRENT_DENSITY_COLUMN] = None
                    _clear_orphan_currents(new_row)
                    fallback_rows.append(new_row)

                if fallback_rows:
                    def _fallback_sort_key(payload: Dict[str, Any]) -> Tuple[int, float]:
                        value = payload.get(SHAPE_MEMORY_FRACTURE_CURRENT_COLUMN)
                        if value in (None, ""):
                            value = payload.get(SHAPE_MEMORY_CURRENT_COLUMN)
                        try:
                            numeric = float(value)
                        except Exception:
                            numeric = math.inf
                        return (0 if math.isfinite(numeric) else 1, numeric)

                    for order, payload in enumerate(sorted(fallback_rows, key=_fallback_sort_key)):
                        _clear_orphan_currents(payload)
                        if not (
                            _shape_memory_payload_has_values(payload, _SHAPE_MEMORY_STANDARD_VALUE_COLUMNS)
                            or _shape_memory_payload_has_values(payload, _SHAPE_MEMORY_FRACTURE_VALUE_COLUMNS)
                        ):
                            continue
                        payload[_SHAPE_MEMORY_GROUP_KEY_COLUMN] = row_key
                        payload[_SHAPE_MEMORY_GROUP_ORDER_COLUMN] = order
                        expanded_rows.append(payload)
                    continue

                row_dict[_SHAPE_MEMORY_GROUP_KEY_COLUMN] = row_key
                row_dict[_SHAPE_MEMORY_GROUP_ORDER_COLUMN] = 0
                expanded_rows.append(row_dict)
                continue

            by_current: Dict[Tuple[int, float], List[ShapeMemoryStressStrainRecord]] = {}
            for record in records:
                current = _shape_memory_current_mA_from_record(record)
                current_sort = float(current) if current is not None else math.inf
                by_current.setdefault((0 if current is not None else 1, current_sort), []).append(record)

            sample_entry = self._cached_shape_memory_entries.get(row_key, {})
            sorted_groups = sorted(by_current.items(), key=lambda item: item[0])
            d_value = row_dict.get(MICROSCOPE_D_COLUMN)
            try:
                diameter_um = float(d_value) if d_value is not None else None
            except Exception:
                diameter_um = None
            standard_count = sum(
                1 for record in records if not _shape_memory_is_fracture_record(record)
            )
            fracture_count = sum(
                1 for record in records if _shape_memory_is_fracture_record(record)
            )

            for order, ((_, current_sort), current_records) in enumerate(sorted_groups):
                current_value = None if math.isinf(current_sort) else current_sort
                current_labels = [
                    _record_label_for_display(record)
                    for record in current_records
                    if _record_label_for_display(record)
                ]
                new_row = dict(row_dict)
                new_row[SHAPE_MEMORY_CURRENT_COLUMN] = current_value
                new_row[SHAPE_MEMORY_CURRENT_DENSITY_COLUMN] = _current_density_from_diameter_um(
                    current_value,
                    diameter_um,
                )
                new_row[SHAPE_MEMORY_FRACTURE_CURRENT_COLUMN] = None
                new_row[SHAPE_MEMORY_FRACTURE_CURRENT_DENSITY_COLUMN] = None
                if current_labels:
                    new_row[SHAPE_MEMORY_STRESS_STRAIN_COLUMN] = list(dict.fromkeys(current_labels))

                standard_entry: Dict[str, Any] = {}
                fracture_entry: Dict[str, Any] = {}
                standard_current_confirmed = False
                fracture_current_confirmed = False
                has_fracture_record = False
                for record in current_records:
                    path_key = _record_path_key(record)
                    entry = (
                        self._cached_shape_memory_record_entries.get(path_key or "", {})
                        if path_key
                        else {}
                    )
                    if _shape_memory_is_fracture_record(record):
                        has_fracture_record = True
                        for column in (
                            SHAPE_MEMORY_FRACTURE_LOAD_COLUMN,
                            SHAPE_MEMORY_FRACTURE_STRAIN_COLUMN,
                            SHAPE_MEMORY_FRACTURE_STRESS_COLUMN,
                        ):
                            if column in entry and column not in fracture_entry:
                                fracture_entry[column] = entry[column]
                        if fracture_entry:
                            fracture_current_confirmed = True
                        if not fracture_entry and path_key:
                            source_entry = section_fracture_entries.get(path_key, {})
                            for column in (
                                SHAPE_MEMORY_FRACTURE_LOAD_COLUMN,
                                SHAPE_MEMORY_FRACTURE_STRAIN_COLUMN,
                                SHAPE_MEMORY_FRACTURE_STRESS_COLUMN,
                            ):
                                if column in source_entry and column not in fracture_entry:
                                    fracture_entry[column] = source_entry[column]
                            if fracture_entry:
                                fracture_current_confirmed = True
                        if not fracture_entry and not section_fracture_entries and fracture_count == 1:
                            for column in (
                                SHAPE_MEMORY_FRACTURE_LOAD_COLUMN,
                                SHAPE_MEMORY_FRACTURE_STRAIN_COLUMN,
                                SHAPE_MEMORY_FRACTURE_STRESS_COLUMN,
                            ):
                                if column in sample_entry and column not in fracture_entry:
                                    fracture_entry[column] = sample_entry[column]
                    else:
                        for column in (
                            SHAPE_MEMORY_DISPLACEMENT_COLUMN,
                            SHAPE_MEMORY_LOAD_COLUMN,
                            SHAPE_MEMORY_STRAIN_COLUMN,
                            SHAPE_MEMORY_STRESS_COLUMN,
                        ):
                            if column in entry and column not in standard_entry:
                                standard_entry[column] = entry[column]
                        if standard_entry:
                            standard_current_confirmed = True
                        if not standard_entry and path_key:
                            source_entry = section_standard_entries.get(path_key, {})
                            for column in (
                                SHAPE_MEMORY_DISPLACEMENT_COLUMN,
                                SHAPE_MEMORY_LOAD_COLUMN,
                                SHAPE_MEMORY_STRAIN_COLUMN,
                                SHAPE_MEMORY_STRESS_COLUMN,
                            ):
                                if column in source_entry and column not in standard_entry:
                                    standard_entry[column] = source_entry[column]
                            if standard_entry:
                                standard_current_confirmed = True
                        if not standard_entry and not section_standard_entries and standard_count == 1:
                            for column in (
                                SHAPE_MEMORY_DISPLACEMENT_COLUMN,
                                SHAPE_MEMORY_LOAD_COLUMN,
                                SHAPE_MEMORY_STRAIN_COLUMN,
                                SHAPE_MEMORY_STRESS_COLUMN,
                            ):
                                if column in sample_entry and column not in standard_entry:
                                    standard_entry[column] = sample_entry[column]

                if len(sorted_groups) == 1 and sample_entry:
                    for column in (
                        SHAPE_MEMORY_DISPLACEMENT_COLUMN,
                        SHAPE_MEMORY_LOAD_COLUMN,
                        SHAPE_MEMORY_STRAIN_COLUMN,
                        SHAPE_MEMORY_STRESS_COLUMN,
                    ):
                        if column not in standard_entry and column in sample_entry:
                            standard_entry[column] = sample_entry[column]
                    for column in (
                        SHAPE_MEMORY_FRACTURE_LOAD_COLUMN,
                        SHAPE_MEMORY_FRACTURE_STRAIN_COLUMN,
                        SHAPE_MEMORY_FRACTURE_STRESS_COLUMN,
                    ):
                        if column not in fracture_entry and column in sample_entry:
                            fracture_entry[column] = sample_entry[column]

                for column in (
                    SHAPE_MEMORY_DISPLACEMENT_COLUMN,
                    SHAPE_MEMORY_LOAD_COLUMN,
                    SHAPE_MEMORY_STRAIN_COLUMN,
                    SHAPE_MEMORY_STRESS_COLUMN,
                ):
                    new_row[column] = standard_entry.get(column)
                for column in (
                    SHAPE_MEMORY_FRACTURE_LOAD_COLUMN,
                    SHAPE_MEMORY_FRACTURE_STRAIN_COLUMN,
                    SHAPE_MEMORY_FRACTURE_STRESS_COLUMN,
                ):
                    new_row[column] = fracture_entry.get(column)
                if has_fracture_record and fracture_current_confirmed:
                    new_row[SHAPE_MEMORY_FRACTURE_CURRENT_COLUMN] = current_value
                    new_row[SHAPE_MEMORY_FRACTURE_CURRENT_DENSITY_COLUMN] = _current_density_from_diameter_um(
                        current_value,
                        diameter_um,
                    )
                if not standard_current_confirmed:
                    new_row[SHAPE_MEMORY_CURRENT_COLUMN] = None
                    new_row[SHAPE_MEMORY_CURRENT_DENSITY_COLUMN] = None

                _clear_orphan_currents(new_row)
                if not (
                    _shape_memory_payload_has_values(new_row, _SHAPE_MEMORY_STANDARD_VALUE_COLUMNS)
                    or _shape_memory_payload_has_values(new_row, _SHAPE_MEMORY_FRACTURE_VALUE_COLUMNS)
                ):
                    continue
                new_row[_SHAPE_MEMORY_GROUP_KEY_COLUMN] = row_key
                new_row[_SHAPE_MEMORY_GROUP_ORDER_COLUMN] = order
                expanded_rows.append(new_row)

        if not expanded_rows:
            return frame.copy()
        return pd.DataFrame(expanded_rows)

    def _refresh_preview_frame(self) -> None:
        started_s = time.perf_counter()
        loading = _builder_project_load_active()
        raw_frame = self._raw_preview_frame
        total_rows = 0
        if not isinstance(raw_frame, pd.DataFrame) or raw_frame.empty:
            display_frame = pd.DataFrame()
            self._preview_row_index_map = []
        else:
            working_frame = raw_frame
            row_map = list(range(len(raw_frame.index)))
            if not self._show_oe_samples:
                keep_positions = [
                    idx
                    for idx, (_, row) in enumerate(raw_frame.iterrows())
                    if not self._row_is_oe_sample(row)
                ]
                working_frame = raw_frame.iloc[keep_positions].reset_index(drop=True)
                row_map = keep_positions
            sorted_frame, sorted_row_map = self._apply_sort_spec(working_frame)
            row_map = [row_map[idx] for idx in sorted_row_map if 0 <= int(idx) < len(row_map)]
            sorted_frame, row_map = self._apply_source_filter(sorted_frame, row_map)
            selected_columns = self._resolve_selected_columns(sorted_frame.columns)
            display_frame = sorted_frame.loc[:, selected_columns] if selected_columns else sorted_frame.loc[:, []]
            total_rows = len(display_frame.index)
            display_frame, row_map = self._apply_search_filter(display_frame, row_map)
            self._preview_row_index_map = row_map
        self._rebuild_preview_background_cache(display_frame)
        self.preview_model.set_frame(display_frame)
        if self._column_order:
            try:
                self._apply_preview_column_order(self._column_order)
            except Exception:
                QtCore.QTimer.singleShot(
                    0,
                    lambda: self._apply_preview_column_order(self._column_order),
                )
        self.preview_table.setVisible(True)
        display_columns = (
            [str(column) for column in display_frame.columns]
            if isinstance(display_frame, pd.DataFrame)
            else []
        )
        show_graphs = any(
            column in self._inline_graph_columns for column in display_columns
        )
        try:
            if show_graphs:
                max_count = self._preview_graph_max_count(display_columns)
                spacing = 6
                icon_width = ANNEALING_GRAPH_WIDTH * max_count + spacing * (max_count - 1)
                self.preview_table.setIconSize(
                    QtCore.QSize(max(icon_width, ANNEALING_GRAPH_WIDTH), ANNEALING_GRAPH_HEIGHT)
                )
                header = self.preview_table.verticalHeader()
                if header is not None:
                    header.setDefaultSectionSize(ANNEALING_GRAPH_HEIGHT + 12)
            else:
                icon_extent = self.preview_table.style().pixelMetric(
                    QtWidgets.QStyle.PixelMetric.PM_SmallIconSize
                )
                if icon_extent <= 0:
                    icon_extent = 16
                self.preview_table.setIconSize(QtCore.QSize(icon_extent, icon_extent))
                header = self.preview_table.verticalHeader()
                if header is not None:
                    header.setDefaultSectionSize(self.preview_table.fontMetrics().height() + 8)
        except Exception:
            pass
        if not loading:
            try:
                resize_started_s = time.perf_counter()
                self.preview_table.resizeColumnsToContents()
                _log_builder_timing(
                    self.logger,
                    "assemble_preview_resize",
                    resize_started_s,
                    rows=len(display_frame.index) if isinstance(display_frame, pd.DataFrame) else 0,
                    columns=len(display_frame.columns) if isinstance(display_frame, pd.DataFrame) else 0,
                )
            except Exception:
                pass
        self._update_preview_graph_buttons()
        if not loading:
            self._update_graph_preview_panel()
        row_count = len(display_frame.index) if isinstance(display_frame, pd.DataFrame) else 0
        if row_count:
            if (self._preview_search_text or self._preview_source_filter_text != SOURCE_LABEL_ALL) and total_rows != row_count:
                self.status_label.setText(
                    f"Preview ready - {row_count} of {total_rows} row(s) shown."
                )
            else:
                self.status_label.setText(f"Preview ready - {row_count} row(s).")
        else:
            if (self._preview_search_text or self._preview_source_filter_text != SOURCE_LABEL_ALL) and total_rows:
                self.status_label.setText("No preview rows match the current search.")
            else:
                self.status_label.setText("Preview is empty.")
        if hasattr(self, "clear_sort_button"):
            self.clear_sort_button.setEnabled(bool(self._sort_spec))
        _log_builder_timing(
            self.logger,
            "assemble_preview_refresh",
            started_s,
            rows=row_count,
            columns=len(display_frame.columns) if isinstance(display_frame, pd.DataFrame) else 0,
            load=loading,
        )

    @staticmethod
    def _normalise_search_text(value: object) -> str:
        if value is None:
            return ""
        return str(value).strip()

    @staticmethod
    def _normalise_saved_column_name(value: object) -> str:
        text = str(value or "").strip()
        legacy_map = {
            "Temperature (°C)": CORE_TEMPERATURE_COLUMN,
            "Current (mA)": SHAPE_MEMORY_CURRENT_COLUMN,
            "Current density (A/mm^2)": SHAPE_MEMORY_CURRENT_DENSITY_COLUMN,
            "Fracture current (mA)": SHAPE_MEMORY_FRACTURE_CURRENT_COLUMN,
            "Fracture current density (A/mm^2)": SHAPE_MEMORY_FRACTURE_CURRENT_DENSITY_COLUMN,
            "Graph — other mA": ANNEALING_OTHER_GRAPH_COLUMN,
            "Shape memory stress/strain graphs": SHAPE_MEMORY_STRESS_STRAIN_COLUMN,
            "Shape memory stress/strain graphs (Origin)": SHAPE_MEMORY_STRESS_STRAIN_ORIGIN_COLUMN,
        }
        return legacy_map.get(text, text)

    def _handle_preview_search_changed(self, text: str) -> None:
        query = self._normalise_search_text(text)
        self._preview_search_text = query
        if hasattr(self, "search_clear_button"):
            self.search_clear_button.setEnabled(bool(query))
        self._refresh_preview_frame()

    def _clear_preview_search(self) -> None:
        if hasattr(self, "search_edit"):
            self.search_edit.clear()

    def _refresh_preview_source_filter_options(self) -> None:
        combo = getattr(self, "source_filter_combo", None)
        if not isinstance(combo, QtWidgets.QComboBox):
            return
        frame = self._raw_preview_frame
        labels: List[str] = []
        if isinstance(frame, pd.DataFrame) and not frame.empty:
            for _, row in frame.iterrows():
                for label in _source_labels_from_row(row):
                    if label and label not in labels:
                        labels.append(label)
        labels = sorted(labels, key=str.casefold)
        current = self._preview_source_filter_text or SOURCE_LABEL_ALL
        combo.blockSignals(True)
        try:
            combo.clear()
            combo.addItem(SOURCE_LABEL_ALL)
            for label in labels:
                combo.addItem(label)
            target = current if current in labels else SOURCE_LABEL_ALL
            combo.setCurrentText(target)
            combo.setEnabled(bool(labels))
            self._preview_source_filter_text = target
        finally:
            combo.blockSignals(False)

    def _handle_preview_source_filter_changed(self, text: str) -> None:
        selected = str(text or "").strip() or SOURCE_LABEL_ALL
        self._preview_source_filter_text = selected
        self._refresh_preview_frame()

    def _apply_source_filter(
        self,
        frame: pd.DataFrame,
        row_map: Sequence[int],
    ) -> Tuple[pd.DataFrame, List[int]]:
        selected = self._preview_source_filter_text
        if not selected or selected == SOURCE_LABEL_ALL:
            return frame, list(row_map)
        keep_rows: List[int] = []
        for idx, row in frame.iterrows():
            if selected in _source_labels_from_row(row):
                keep_rows.append(int(idx))
        if not keep_rows:
            return frame.iloc[0:0].copy(), []
        filtered = frame.iloc[keep_rows].reset_index(drop=True)
        mapped_rows = [int(row_map[idx]) for idx in keep_rows if idx < len(row_map)]
        return filtered, mapped_rows

    def _apply_search_filter(
        self,
        frame: pd.DataFrame,
        row_map: Sequence[int],
    ) -> Tuple[pd.DataFrame, List[int]]:
        query = self._preview_search_text
        if not query:
            return frame, list(row_map)
        lowered = query.casefold()
        keep_rows: List[int] = []
        for idx, row in frame.iterrows():
            for value in row.values:
                if value is None:
                    continue
                if isinstance(value, float) and math.isnan(value):
                    continue
                text = self._serialise_preview_value(value)
                if text is None:
                    continue
                if lowered in str(text).casefold():
                    keep_rows.append(int(idx))
                    break
        if not keep_rows:
            return frame.iloc[0:0].copy(), []
        filtered = frame.iloc[keep_rows].reset_index(drop=True)
        mapped_rows = [int(row_map[idx]) for idx in keep_rows if idx < len(row_map)]
        return filtered, mapped_rows

    def _preview_graph_max_count(self, columns: Sequence[str]) -> int:
        max_count = 1
        column_set = {str(column) for column in columns}
        if ANNEALING_OTHER_GRAPH_COLUMN in column_set:
            for records in self._ensure_annealing_groups().values():
                if not records:
                    continue
                _high_record, other_records = _select_anchor_and_other_records(records)
                max_count = max(max_count, len(other_records))
        if VSM_HYSTERESIS_COLUMN in column_set:
            for records in self._ensure_vsm_hysteresis_groups().values():
                max_count = max(max_count, len(_group_vsm_hysteresis_plot_groups(records)))
        if VSM_TEMPERATURE_SCAN_COLUMN in column_set:
            for records in self._ensure_vsm_temperature_groups().values():
                max_count = max(max_count, len(records))
        if DMA_ISOSTRESS_COLUMN in column_set:
            for records in self._ensure_dma_isostress_groups().values():
                max_count = max(max_count, len(records))
        if FMR_COLUMN in column_set:
            for records in self._ensure_fmr_groups().values():
                max_count = max(max_count, len(records))
        return max(max_count, 1)

    def _resolve_selected_columns(self, columns: Sequence[str]) -> List[str]:
        column_names = [str(column) for column in columns]
        if self._selected_columns is None:
            self._selected_columns = {
                column
                for column in column_names
                if column not in self._graph_columns and not column.startswith("_")
            }
        self._known_columns.update(column_names)
        self._selected_columns.update(self._mandatory_columns)
        self._sync_section_states_from_columns(self._selected_columns, column_names)
        return [column for column in column_names if column in self._selected_columns]

    def _apply_sort_spec(self, frame: pd.DataFrame) -> Tuple[pd.DataFrame, List[int]]:
        if (
            isinstance(frame, pd.DataFrame)
            and not frame.empty
            and _SHAPE_MEMORY_GROUP_KEY_COLUMN in frame.columns
            and _SHAPE_MEMORY_GROUP_ORDER_COLUMN in frame.columns
        ):
            indexed = frame.copy()
            indexed["_source_row_index"] = list(range(len(indexed.index)))

            sort_columns: List[str] = []
            ascending: List[bool] = []
            for column, is_ascending in self._sort_spec:
                if column in indexed.columns and column not in sort_columns:
                    sort_columns.append(column)
                    ascending.append(bool(is_ascending))
            for fallback_column in ("Microwire", "Composition"):
                if fallback_column in indexed.columns and fallback_column not in sort_columns:
                    sort_columns.append(fallback_column)
                    ascending.append(True)

            if sort_columns:
                row_sorted = indexed.sort_values(
                    by=sort_columns + [_SHAPE_MEMORY_GROUP_ORDER_COLUMN],
                    ascending=ascending + [True],
                    kind="mergesort",
                    key=lambda col: col.map(DataFrameModel._sort_value) if hasattr(col, "map") else col,
                )
            else:
                row_sorted = indexed.sort_values(
                    by=[_SHAPE_MEMORY_GROUP_ORDER_COLUMN],
                    ascending=[True],
                    kind="mergesort",
                )

            block_order: Dict[str, int] = {}
            for _, row in row_sorted.iterrows():
                key = str(row[_SHAPE_MEMORY_GROUP_KEY_COLUMN])
                if key not in block_order:
                    block_order[key] = len(block_order)

            indexed["_block_sort_index"] = indexed[_SHAPE_MEMORY_GROUP_KEY_COLUMN].map(
                lambda value: block_order.get(str(value), len(block_order))
            )
            within_group_columns = list(sort_columns)
            within_group_ascending = list(ascending)
            if _SHAPE_MEMORY_GROUP_ORDER_COLUMN not in within_group_columns:
                within_group_columns.append(_SHAPE_MEMORY_GROUP_ORDER_COLUMN)
                within_group_ascending.append(True)
            sorted_frame = indexed.sort_values(
                by=["_block_sort_index", *within_group_columns],
                ascending=[True, *within_group_ascending],
                kind="mergesort",
                key=lambda col: col.map(DataFrameModel._sort_value) if hasattr(col, "map") else col,
            ).reset_index(drop=True)
            row_map = [int(value) for value in sorted_frame["_source_row_index"].tolist()]
            sorted_frame = sorted_frame.drop(columns=["_source_row_index", "_block_sort_index"])
            return sorted_frame, row_map

        def _index_position(index: pd.Index, value: Any, fallback: int) -> int:
            try:
                return int(value)
            except Exception:
                pass
            try:
                return int(index.get_loc(value))
            except Exception:
                return fallback

        if not self._sort_spec:
            return frame.copy(), [
                _index_position(frame.index, idx, fallback)
                for fallback, idx in enumerate(frame.index)
            ]
        sort_columns: List[str] = []
        ascending: List[bool] = []
        for column, is_ascending in self._sort_spec:
            if column in frame.columns and column not in sort_columns:
                sort_columns.append(column)
                ascending.append(bool(is_ascending))
        for fallback_column in ("Microwire", "Composition"):
            if fallback_column in frame.columns and fallback_column not in sort_columns:
                sort_columns.append(fallback_column)
                ascending.append(True)
        if not sort_columns:
            return frame.copy(), [
                _index_position(frame.index, idx, fallback)
                for fallback, idx in enumerate(frame.index)
            ]
        try:
            sorted_frame = frame.sort_values(
                by=sort_columns,
                ascending=ascending,
                kind="mergesort",
                key=lambda col: col.map(DataFrameModel._sort_value) if hasattr(col, "map") else col,
            )
        except Exception:
            return frame.copy(), [
                _index_position(frame.index, idx, fallback)
                for fallback, idx in enumerate(frame.index)
            ]
        row_map = [
            _index_position(frame.index, idx, fallback)
            for fallback, idx in enumerate(sorted_frame.index)
        ]
        return sorted_frame.reset_index(drop=True), row_map

    def _record_signature(self, records: Sequence[object]) -> Tuple[str, ...]:
        signature: List[str] = []
        for record in records:
            path = getattr(record, "path", None)
            if isinstance(path, Path):
                signature.append(str(path))
                continue
            if isinstance(path, str) and path:
                signature.append(path)
                continue
            label = _record_label_for_display(record)
            if label:
                signature.append(label)
                continue
            sample = getattr(record, "sample", None)
            if isinstance(sample, str) and sample:
                signature.append(sample)
                continue
            signature.append(repr(record))
        return tuple(signature)

    def _combined_graph_pixmap(
        self,
        cache_key: Tuple[object, ...],
        items: Sequence[_GraphPreviewItem],
        *,
        stack_vertical: bool = False,
    ) -> Optional[QtGui.QPixmap]:
        cached = self._graph_pixmap_cache.get(cache_key)
        if cached is not None:
            return cached
        started_s = time.perf_counter()
        pixmaps = [item.pixmap for item in items if item.pixmap is not None]
        count = max(len(pixmaps), 1)
        spacing = 6
        if stack_vertical:
            combined = _combine_pixmaps_vertical(
                pixmaps,
                width_px=ANNEALING_GRAPH_WIDTH,
                height_px=ANNEALING_GRAPH_HEIGHT * count + spacing * (count - 1),
                spacing=spacing,
                scale_to_fit=False,
            )
        else:
            combined = _combine_pixmaps_side_by_side(
                pixmaps,
                width_px=ANNEALING_GRAPH_WIDTH * count + spacing * (count - 1),
                height_px=ANNEALING_GRAPH_HEIGHT,
                spacing=spacing,
                scale_to_fit=False,
            )
        if combined is not None:
            self._graph_pixmap_cache[cache_key] = combined
        _log_builder_timing(
            self.logger,
            "assemble_preview_pixmap_miss",
            started_s,
            key=cache_key[0] if cache_key else "",
            count=len(pixmaps),
        )
        return combined

    def _preview_decoration(
        self, row: pd.Series, column_label: str
    ) -> Optional[QtGui.QPixmap]:
        started_s = time.perf_counter()
        if column_label not in self._inline_graph_columns:
            return None
        key = _row_to_microwire_key(row)
        if not key:
            return None
        try:
            if column_label in FIGURE_COLUMNS:
                records = self._ensure_annealing_groups().get(key, [])
                if not records:
                    return None
                high_record, other_records = _select_anchor_and_other_records(records)
                if column_label == FIGURE_COLUMNS[0]:
                    target = high_record
                else:
                    target = None
                if target is not None:
                    diameter_um = _diameter_um_from_mapping(row.to_dict())
                    measurement_id = getattr(getattr(target, "metadata", None), "measurement_id", None)
                    cache_key = (
                        "annealing",
                        column_label,
                        measurement_id or str(getattr(target, "path", "")),
                    )
                    cached = self._graph_pixmap_cache.get(cache_key)
                    if cached is not None:
                        return cached
                    pixmap = _render_measurement_pixmap(
                        target,
                        self.logger,
                        width_px=ANNEALING_GRAPH_WIDTH,
                        height_px=ANNEALING_GRAPH_HEIGHT,
                        wire_diameter_um=diameter_um,
                    )
                    if pixmap is None:
                        return None
                    self._graph_pixmap_cache[cache_key] = pixmap
                    _log_builder_timing(
                        self.logger,
                        "assemble_preview_decoration_miss",
                        started_s,
                        column=column_label,
                    )
                    return pixmap
                if not other_records:
                    return None
                signature = tuple(
                    str(getattr(record, "path", "")) for record in other_records
                )
                cache_key = ("annealing_other", key, signature)
                cached = self._graph_pixmap_cache.get(cache_key)
                if cached is not None:
                    return cached
                pixmap_stack: List[QtGui.QPixmap] = []
                diameter_um = _diameter_um_from_mapping(row.to_dict())
                for record in other_records:
                    preview = _render_measurement_pixmap(
                        record,
                        self.logger,
                        width_px=ANNEALING_GRAPH_WIDTH,
                        height_px=ANNEALING_GRAPH_HEIGHT,
                        wire_diameter_um=diameter_um,
                    )
                    if preview is not None:
                        pixmap_stack.append(preview)
                combined = _combine_pixmaps_side_by_side(
                    pixmap_stack,
                    width_px=ANNEALING_GRAPH_WIDTH * max(len(pixmap_stack), 1)
                    + 6 * (max(len(pixmap_stack), 1) - 1),
                    height_px=ANNEALING_GRAPH_HEIGHT,
                    spacing=6,
                    scale_to_fit=False,
                )
                if combined is not None:
                    self._graph_pixmap_cache[cache_key] = combined
                _log_builder_timing(
                    self.logger,
                    "assemble_preview_decoration_miss",
                    started_s,
                    column=column_label,
                )
                return combined
            if column_label == VSM_HYSTERESIS_COLUMN:
                records = self._ensure_vsm_hysteresis_groups().get(key, [])
                if not records:
                    return None
                signature = self._record_signature(records)
                cache_key = (
                    "vsm_hysteresis",
                    key,
                    signature,
                    _load_vsm_hysteresis_angle_filter_mode(),
                    _load_vsm_hysteresis_preview_range_oe(),
                )
                items = _vsm_hysteresis_preview_items(
                    records,
                    self.logger,
                    width_px=ANNEALING_GRAPH_WIDTH,
                    height_px=ANNEALING_GRAPH_HEIGHT,
                )
                return self._combined_graph_pixmap(cache_key, items, stack_vertical=False)
            if column_label == VSM_TEMPERATURE_SCAN_COLUMN:
                records = self._ensure_vsm_temperature_groups().get(key, [])
                if not records:
                    return None
                signature = self._record_signature(records)
                cache_key = (
                    "vsm_temperature",
                    key,
                    signature,
                    _load_vsm_temperature_preview_mode(),
                )
                items = _vsm_temperature_preview_items(
                    records,
                    self.logger,
                    width_px=ANNEALING_GRAPH_WIDTH,
                    height_px=ANNEALING_GRAPH_HEIGHT,
                )
                return self._combined_graph_pixmap(cache_key, items, stack_vertical=False)
            if column_label == DMA_ISOSTRESS_COLUMN:
                records = self._ensure_dma_isostress_groups().get(key, [])
                if not records:
                    return None
                signature = self._record_signature(records)
                cache_key = ("dma_iso_stress", key, signature)
                items = _dma_iso_stress_preview_items(
                    records,
                    self.logger,
                    width_px=ANNEALING_GRAPH_WIDTH,
                    height_px=ANNEALING_GRAPH_HEIGHT,
                )
                return self._combined_graph_pixmap(cache_key, items, stack_vertical=False)
            if column_label == SHAPE_MEMORY_STRESS_STRAIN_COLUMN:
                records = self._ensure_shape_memory_stress_strain_groups().get(key, [])
                if not records:
                    return None
                signature = self._record_signature(records)
                cache_key = ("shape_memory_stress_strain", key, signature)
                items = _shape_memory_stress_strain_preview_items(
                    records,
                    self.logger,
                    width_px=ANNEALING_GRAPH_WIDTH,
                    height_px=ANNEALING_GRAPH_HEIGHT,
                )
                return self._combined_graph_pixmap(cache_key, items, stack_vertical=False)
            if column_label == FMR_COLUMN:
                records = self._ensure_fmr_groups().get(key, [])
                if not records:
                    return None
                signature = self._record_signature(records)
                cache_key = ("fmr", key, signature)
                items = _fmr_preview_items(
                    records,
                    self.logger,
                    width_px=ANNEALING_GRAPH_WIDTH,
                    height_px=ANNEALING_GRAPH_HEIGHT,
                )
                return self._combined_graph_pixmap(cache_key, items, stack_vertical=False)
        except Exception:
            self.logger.exception("Failed to render assemble graph preview")
            return None

    def _preview_background(
        self,
        row: pd.Series,
        column_label: str,
    ) -> Optional[QtGui.QBrush]:
        _ = column_label
        try:
            brush = self._preview_background_cache.get(row.name)
        except Exception:
            brush = None
        return brush

    def _rebuild_preview_background_cache(self, frame: pd.DataFrame) -> None:
        cache: Dict[Any, QtGui.QBrush] = {}
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            self._preview_background_cache = cache
            return
        group_index = 0
        previous_group: Optional[str] = None
        for row_label, row in frame.iterrows():
            current_group = "|".join(
                [
                    str(row.get("Composition") or "").strip(),
                    str(row.get("Microwire") or "").strip(),
                ]
            )
            if previous_group is None:
                previous_group = current_group
            elif current_group != previous_group:
                group_index += 1
                previous_group = current_group
            cache[row_label] = QtGui.QBrush(
                QtGui.QColor("#1a1a1a" if group_index % 2 == 0 else "#202733")
            )
        self._preview_background_cache = cache

    @staticmethod
    def _fabrication_index_from_frame(frame: Optional[pd.DataFrame]) -> FabricationIndex:
        index = FabricationIndex()
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return index

        def _is_missing(value: Any) -> bool:
            if value is None:
                return True
            if isinstance(value, str) and not value.strip():
                return True
            try:
                return bool(pd.isna(value))
            except Exception:
                return False

        def _assign_if_present(target: Dict[str, object], field: str, value: Any) -> None:
            if not _is_missing(value):
                target[field] = value

        for _, row in frame.iterrows():
            composition = str(row.get("Composition") or "").strip()
            if not composition or composition == "Imported data:":
                continue
            try:
                draw = int(row.get("Draw"))
                piece = int(row.get("Piece"))
            except (TypeError, ValueError):
                microwire = str(row.get("Microwire") or "").strip()
                parsed = _microwire_parts_from_label_safe(microwire)
                if parsed is None:
                    continue
                try:
                    draw = int(parsed[0])
                    piece = int(parsed[1])
                except (TypeError, ValueError):
                    continue

            piece_key = (composition, draw, piece)
            draw_key = (composition, draw)
            piece_data = dict(index.piece_level.get(piece_key, {}))
            draw_data = dict(index.draw_level.get(draw_key, {}))

            source_value: object = row.get("Data source") or "Manual"
            source_paths = row.get("_source_paths")
            if isinstance(source_paths, (list, tuple, set)):
                for candidate in source_paths:
                    if candidate:
                        source_value = candidate
                        break
            _assign_if_present(piece_data, "length_m", row.get("Length (m)"))
            _assign_if_present(piece_data, "piece_date", row.get("Piece date"))
            _assign_if_present(piece_data, "fabrication_resistance_ohm", row.get("Resistance (Ω)"))
            _assign_if_present(piece_data, "glass_pull_off", row.get(GLASS_PULL_COLUMN))
            _assign_if_present(piece_data, "notes", row.get("Notes"))
            _assign_if_present(piece_data, "_source_path", source_value)

            temperature_value = row.get(CORE_TEMPERATURE_COLUMN)
            if _is_missing(temperature_value):
                temperature_value = row.get("Temperature (°C)")
            _assign_if_present(draw_data, "fabrication_temperature_c", temperature_value)
            _assign_if_present(
                draw_data,
                "fabrication_glass_temperature_c",
                row.get(GLASS_TEMPERATURE_COLUMN),
            )
            _assign_if_present(draw_data, "mass_g", row.get("Mass (g)"))
            _assign_if_present(
                draw_data,
                "winding_speed_m_per_min",
                row.get("Winding speed (m/min)"),
            )
            _assign_if_present(
                draw_data,
                "glass_feed_mm_per_min",
                row.get("Glass feeding (mm/min)"),
            )
            _assign_if_present(draw_data, "underpressure", row.get("Underpressure"))
            _assign_if_present(
                draw_data,
                "production_datetime",
                row.get("Production datetime"),
            )
            _assign_if_present(draw_data, "fabrication_resistance_ohm", row.get("Resistance (Ω)"))
            _assign_if_present(draw_data, "notes", row.get("Notes"))
            _assign_if_present(draw_data, "_source_path", source_value)

            if piece_data:
                index.set_piece(composition, draw, piece, piece_data)
            if draw_data:
                index.set_draw(composition, draw, draw_data)
        return index

    def _group_annealing_records(
        self,
        records: Sequence[MeasurementRecord],
    ) -> Dict[str, List[MeasurementRecord]]:
        grouped: Dict[str, List[MeasurementRecord]] = {}
        for record in records:
            metadata = getattr(record, "metadata", None)
            if metadata is None:
                continue
            composition = getattr(metadata, "composition_token", None)
            draw = getattr(metadata, "draw_x", None)
            piece = getattr(metadata, "piece_y", None)
            if composition is None or draw is None or piece is None:
                continue
            suffix = None
            path = getattr(record, "path", None)
            if isinstance(path, Path):
                parsed_key = _microscope_key(path)
                if parsed_key is not None:
                    _, _, _, suffix = parsed_key
            try:
                key = _microwire_key_to_str((str(composition), int(draw), int(piece), suffix))
            except (TypeError, ValueError):
                continue
            grouped.setdefault(key, []).append(record)
        return grouped

    def _ensure_annealing_groups(self) -> Dict[str, List[MeasurementRecord]]:
        groups = self._cached_annealing_groups
        if not groups:
            payload = self._load_payload("annealing", "annealing_records")
            if isinstance(payload, list):
                records = self._filter_hidden_records(payload, "annealing")
                self._cached_annealing_records = list(records)
                self._cached_annealing_groups = self._group_annealing_records(records)
                groups = self._cached_annealing_groups
        return groups

    def _filter_hidden_records(
        self, records: Sequence[object], section_key: str
    ) -> List[object]:
        hidden = _hidden_paths_from_section(self.sections.get(section_key))
        if not hidden:
            return list(records)
        filtered: List[object] = []
        for record in records:
            path_key = _record_path_key(record)
            if path_key and path_key in hidden:
                continue
            filtered.append(record)
        return filtered

    def _ensure_vsm_hysteresis_groups(self) -> Dict[str, List[VsmHysteresisRecord]]:
        groups = self._cached_vsm_hysteresis_groups
        if not groups:
            payload = self._load_payload("vsm_hysteresis", "vsm_hysteresis_records")
            if isinstance(payload, list):
                records = self._filter_hidden_records(payload, "vsm_hysteresis")
                self._cached_vsm_hysteresis_records = list(records)
                self._cached_vsm_hysteresis_groups = _group_graph_records_by_key(records)
                groups = self._cached_vsm_hysteresis_groups
        return groups

